/** Feature-owned prompts and validation; session/tool ownership stays with the executor. */
export interface AgentWorkflowStep<T> {
  id: string;
  prompt(previous: T | undefined): string;
  before?(previous: T | undefined): void | Promise<void>;
  validate?(output: T, previous: T | undefined): void | Promise<void>;
}

export interface AgentWorkflow<T> {
  id: string;
  steps: readonly AgentWorkflowStep<T>[];
}

export interface AgentStepRequest {
  workflowId: string;
  stepId: string;
  prompt: string;
  signal?: AbortSignal;
}

/** Return only this turn's accepted submission. Honor signal for in-flight cancellation. */
export type AgentStepExecutor<T> = (request: AgentStepRequest) => Promise<T | undefined>;

export async function runAgentWorkflow<T>(
  workflow: AgentWorkflow<T>,
  execute: AgentStepExecutor<T>,
  options: { signal?: AbortSignal; onStepStart?(stepId: string): void } = {}
): Promise<T> {
  if (!workflow.id.trim() || !workflow.steps.length) throw new Error("An agent workflow needs an id and at least one step");
  const ids = new Set<string>();
  for (const step of workflow.steps) {
    if (!step.id.trim() || ids.has(step.id)) throw new Error(`Invalid or duplicate workflow step: ${step.id}`);
    ids.add(step.id);
  }

  let previous: T | undefined;
  for (const step of workflow.steps) {
    options.signal?.throwIfAborted();
    options.onStepStart?.(step.id);
    await step.before?.(previous);
    options.signal?.throwIfAborted();
    const output = await execute({
      workflowId: workflow.id, stepId: step.id, prompt: step.prompt(previous), signal: options.signal
    });
    options.signal?.throwIfAborted();
    if (output === undefined) throw new Error(`${workflow.id}/${step.id} finished without an accepted submission`);
    await step.validate?.(output, previous);
    options.signal?.throwIfAborted();
    previous = output;
  }
  return previous!;
}

import type { ProjectFileCompactionInput } from "../../domain/core/representations/projectCatalog";
import type { CoreContext } from './context';
import type { CorpusAccess } from "./corpus/corpusAccess";
import { DiagramRepository } from "./ports/diagramRepository";
import * as representationsOperations from './representations/service';

/** Project catalog reads and source-validated compaction writes. */
export class CoreApplication {
  private readonly context: CoreContext;
  constructor(readonly store: DiagramRepository, readonly corpus: CorpusAccess) { this.context = { store, corpus }; }

  async projectRepresentations(historyValidation: import('../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') {
    return representationsOperations.projectRepresentations(this.context, historyValidation);
  }

  async upsertProjectFileCompaction(input: ProjectFileCompactionInput) {
    return representationsOperations.upsertProjectFileCompaction(this.context, input);
  }
}

import type { CorpusAccess } from './corpus/corpusAccess';
import type { DiagramRepository } from './ports/diagramRepository';
export interface CoreContext { store: DiagramRepository; corpus: CorpusAccess; }

import type { BuiltInDomainProfileId, CorpusBinding, CorpusProvider } from "../../../domain/core/profiles/domainProfile";
import type { RepositoryLocation } from "./location";

export interface ReadableCorpusProvider extends CorpusProvider {
  readDocumentBytes(binding: CorpusBinding, path: string): Promise<Buffer>;
  readDocumentText(binding: CorpusBinding, path: string): Promise<string>;
  readDocumentLines(binding: CorpusBinding, path: string): Promise<string[]>;
}

export interface CorpusAccess {
  provider(binding: CorpusBinding): ReadableCorpusProvider;
  readDocumentLines(binding: CorpusBinding, path: string): Promise<string[]>;
  discover(inputPath: string, profile: BuiltInDomainProfileId): Promise<RepositoryLocation>;
}

import type { BuiltInDomainProfileId, CorpusBinding } from "../../../domain/core/profiles/domainProfile";

export interface RepositoryLocation {
  checkoutRoot: string;
  repositoryIdentity: string;
  gitRevision?: string;
  domainProfileId?: BuiltInDomainProfileId;
  corpus?: CorpusBinding;
}

/** Application failures are independent of their HTTP representation. */
export class ApplicationError extends Error {
  constructor(readonly code: 'conflict' | 'invalid-input' | 'binary-source' | 'lsp-disabled' | 'storage-unavailable', message: string) {
    super(message);
  }
}

import { type ProjectRecord } from "../../../domain/core/records/domain";
import type { RepositoryLocation } from '../corpus/location';
import { ProjectCatalogRepository } from "./projectCatalogRepository";

export interface DiagramRepository {
  readonly checkoutRoot: string;
  readonly storeRoot: string;
  readonly projectCatalogs: ProjectCatalogRepository;
  ensureProject(location: RepositoryLocation): Promise<ProjectRecord>;
  loadProject(): Promise<ProjectRecord | null>;
}

import { type ProjectProjectionRecord } from "../../../domain/core/diagrams/diagramProjection";
import { type SaveProjectDiagramInput } from "../../../domain/core/diagrams/projectDiagramCanvas";
import type { SaveProjectedTreeInput } from '../../../domain/core/representations/catalogCommands';
import type { ProjectCorpusCompactionCatalogRecord, ProjectFileCompactionInput, ProjectFileCompactionRecord, ProjectRepresentationCatalogRecord, ProjectRepresentationRecord } from "../../../domain/core/representations/projectCatalog";
export interface ProjectCatalogRepository {
  acceptCanvasChanges(projectId: string, input: import('../../../domain/core/representations/changeAcceptance').AcceptCanvasChangesInput): Promise<import('../../../domain/core/representations/changeAcceptance').ChangeSessionAcceptance>;
  readonly storeRoot: string;
  saveProjection(projectId: string, projection: ProjectProjectionRecord): Promise<{
    catalog: ProjectRepresentationCatalogRecord;
    projection: ProjectProjectionRecord;
  }>;
  saveProjectedTree(projectId: string, input: SaveProjectedTreeInput): Promise<{
    catalog: ProjectRepresentationCatalogRecord;
    representation: ProjectRepresentationRecord;
    projection: ProjectProjectionRecord;
  }>;
  saveMappingDiagram(projectId: string, input: SaveProjectDiagramInput): Promise<{
    catalog: ProjectRepresentationCatalogRecord;
    representation: ProjectRepresentationRecord;
  }>;
  loadCompactionCatalog(projectId: string): Promise<ProjectCorpusCompactionCatalogRecord>;
  saveCompactionCatalog(catalog: ProjectCorpusCompactionCatalogRecord): Promise<void>;
  upsertFileCompaction(projectId: string, input: ProjectFileCompactionInput): Promise<{
    catalog: ProjectCorpusCompactionCatalogRecord;
    compaction: ProjectFileCompactionRecord;
  }>;
  loadRepresentationCatalog(projectId: string, historyValidation?: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation): Promise<ProjectRepresentationCatalogRecord>;
  loadChangeSessionAcceptances(projectId: string): Promise<NonNullable<ProjectRepresentationCatalogRecord['changeSessionAcceptances']>>;
  saveRepresentationCatalog(catalog: ProjectRepresentationCatalogRecord): Promise<void>;
  archiveRepresentation(projectId: string, representationId: string): Promise<ProjectRepresentationCatalogRecord>;
}

import type { SaveProjectedTreeInput } from '../../../domain/core/representations/catalogCommands';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';

export class ProjectCatalogService {
  constructor(private readonly store: Pick<DiagramRepository, 'loadProject' | 'projectCatalogs'>) { }
  async saveProjection(input: SaveProjectedTreeInput) {
    const project = await this.store.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    return { project, ...await this.store.projectCatalogs.saveProjectedTree(project.id, input) };
  }
  async compactions() {
    const project = await this.store.loadProject();
    if (!project) throw new ApplicationError('conflict', 'project is not initialized');
    return this.store.projectCatalogs.loadCompactionCatalog(project.id);
  }
  async requireProject() {
    const project = await this.store.loadProject();
    if (!project) throw new ApplicationError('conflict', 'project is not initialized');
    return project;
  }
}

import type { ProjectFileCompactionInput } from "../../../domain/core/representations/projectCatalog";
import type { CoreContext } from '../context';
import { resolveDiagramSource } from '../source/diagramSource';

export async function projectRepresentations(context: CoreContext, historyValidation: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') {
  const project = await context.store.loadProject();
  return {
    project, catalog: project
      ? await context.store.projectCatalogs.loadRepresentationCatalog(project.id, historyValidation) : null
  };
}

export async function upsertProjectFileCompaction(context: CoreContext, input: ProjectFileCompactionInput) {
  const project = await context.store.loadProject();
  if (!project) throw new Error("project corpus is not initialized");
  const source = await resolveDiagramSource(context.store, {projectId: project.id, sourceId: input.sourceId}, context.corpus);
  input = { ...input, sourceId: source.binding().sourceId };
  if (input.makeActive !== false) {
    const documentLines = (await source.readText(input.path)).split(/\r?\n/);
    // Source coordinates count the final newline as the terminator of the last
    // source line, not as an additional empty line.
    const liveLines = documentLines.at(-1) === "" ? documentLines.slice(0, -1) : documentLines;
    const captured = liveLines.slice(input.startLine - 1, input.endLine);
    if (JSON.stringify(captured) !== JSON.stringify(input.originalLines)) {
      throw new Error(`active compaction snapshot is stale for ${input.path}`);
    }
    if (input.startLine === 1 && input.originalLines.length === input.endLine
      && liveLines.length !== input.endLine) {
      throw new Error(`active full-file compaction does not cover current ${input.path}`);
    }
  }
  return context.store.projectCatalogs.upsertFileCompaction(project.id, input);
}

import { diagramSource, validateDiagram, type Diagram, type DiagramSourceBinding } from '../../../domain/core/diagrams/diagram';
import { RevisionedDiagramService } from '../../../domain/core/diagrams/diagramService';
import { sceneFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { CorpusAccess } from '../corpus/corpusAccess';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';
export interface DiagramSourceReference { projectId: string; representationId?: string; revisionId?: string; contentId?: string; sourceId?: string }
/** Resolve a saved diagram/revision, or an unambiguous registered source. Never infer a repository from Project. */
export async function resolveDiagramSource(store: Pick<DiagramRepository,'loadProject'|'projectCatalogs'>, ref: DiagramSourceReference, corpus?: CorpusAccess, liveDiagram?: Diagram) {
  const project = await store.loadProject();
  if (!project || project.id !== ref.projectId) throw new ApplicationError('conflict','Diagram belongs to another project');
  const catalog = await store.projectCatalogs.loadRepresentationCatalog(project.id);
  let diagram: Diagram | undefined;
  const representation = ref.representationId ? catalog.representations[ref.representationId] : undefined;
  const revisionId = ref.revisionId ?? representation?.currentRevisionId;
  if (ref.representationId && (!representation || !revisionId || !representation.revisionIds.includes(revisionId))) throw new Error('Unknown diagram revision');
  if (liveDiagram) {
    validateDiagram(liveDiagram);
    if (ref.contentId && liveDiagram.id !== ref.contentId) throw new Error('Live diagram identity does not match selection');
    diagram = liveDiagram;
  } else if (ref.representationId) {
    const scene = sceneFromRevision(catalog.revisions[revisionId!]);
    const candidates = Object.values(scene.contents).filter(d => ref.contentId ? d.id === ref.contentId : !!d.sourceContext.binding);
    if (candidates.length !== 1) throw new Error('Select an individual diagram with contentId');
    diagram = candidates[0];
  } else {
    const bindings = new Map<string,DiagramSourceBinding>();
    const register = (binding: DiagramSourceBinding) => {
      const old = bindings.get(binding.sourceId);
      if (old && (old.corpus.root !== binding.corpus.root || old.corpus.kind !== binding.corpus.kind || old.repositoryIdentity !== binding.repositoryIdentity)) throw new Error('Conflicting diagram source identity');
      bindings.set(binding.sourceId,binding);
    };
    for (const revision of Object.values(catalog.revisions)) for (const d of Object.values(sceneFromRevision(revision).contents)) {
      const binding = d.sourceContext.binding;
      if (binding && (!ref.sourceId || binding.sourceId === ref.sourceId)) register(binding);
    }
    for (const binding of project.sources ?? []) {
      if (binding && (!ref.sourceId || binding.sourceId === ref.sourceId)) register(binding);
    }
    if (bindings.size !== 1) throw new Error('A valid diagram sourceId is required; the project has no single repository');
    diagram = new RevisionedDiagramService().create({id:'source-query',revision:0,ascii:'Source',source:[...bindings.values()][0]}).diagram;
  }
  if (ref.sourceId && diagram.sourceContext.binding?.sourceId !== ref.sourceId) throw new Error('Source does not belong to diagram');
  const query = diagramSource(diagram);
  const binding = () => {
    const result = query.context.binding;
    if (!result) throw new Error('This diagram has no source repository');
    return result;
  };
  return { ...query, diagram, binding,
    readText: (file: string) => { const source=binding(); if (!corpus) throw new Error('Source access unavailable'); return corpus.provider(source.corpus).readDocumentText(source.corpus,file); },
    listFiles: (directory: string) => { const source=binding(); if (!corpus) throw new Error('Source access unavailable'); return corpus.provider(source.corpus).listDirectory(source.corpus,directory); }
  };
}

import type { CorpusBinding } from '../../../domain/core/profiles/domainProfile';
import { type SourceDefinitions, type SourcePosition } from '../../../domain/core/source/sourceNavigation';

export interface LanguageService {
  definitions(binding: CorpusBinding, file: string, position: SourcePosition, sourceSha256: string, signal?: AbortSignal): Promise<SourceDefinitions>;
  dispose(): void;
}

import { createHash } from 'node:crypto';
import type { SourcePosition } from '../../../domain/core/source/sourceNavigation';
import type { CorpusAccess } from '../corpus/corpusAccess';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';
import { resolveDiagramSource, type DiagramSourceReference } from './diagramSource';
import type { LanguageService } from './languageService';

export class ProjectSourceService {
  constructor(
    private readonly projects: Pick<DiagramRepository, 'loadProject' | 'projectCatalogs'>,
    private readonly corpus: CorpusAccess,
    private readonly language?: LanguageService
  ) { }

  async files(projectId: string | null, directory: string, sourceId?: string) {
    const source = await resolveDiagramSource(this.projects, {projectId: projectId ?? '', sourceId}, this.corpus);
    return source.listFiles(directory);
  }

  ensureDefinitionsEnabled(): void {
    if (!this.language) throw new ApplicationError('lsp-disabled', 'Definition lookup is disabled. Start the server with --lsp to enable it.');
  }

  async definitions(input: DiagramSourceReference & { path: string; position: SourcePosition; sourceSha256: string }, signal: AbortSignal) {
    if (!this.language) throw new ApplicationError('lsp-disabled', 'Definition lookup is disabled. Start the server with --lsp to enable it.');
    const source = await resolveDiagramSource(this.projects, input, this.corpus);
    return this.language.definitions(source.binding().corpus, input.path, input.position, input.sourceSha256, signal);
  }

  async source(projectId: string | null, sourcePath: string | null, sourceId?: string) {
    if (!sourcePath) throw new ApplicationError('invalid-input', 'Source path is required');
    const resolved = await resolveDiagramSource(this.projects, {projectId: projectId ?? '', sourceId}, this.corpus);
    const source = await resolved.readText(sourcePath);
    if (source.includes('\0')) throw new ApplicationError('binary-source', 'This is a binary file. The source pane displays text files.');
    return {
      path: sourcePath, startLine: 1, lines: source.split(/\r?\n/),
      sourceSha256: createHash('sha256').update(source).digest('hex'), lspEnabled: Boolean(this.language)
    };
  }
}

import { randomUUID } from 'node:crypto';
import { AgentContext, type AgentContextSnapshot } from '../../../domain/core/agents/agentContext';

export interface AgentContextScope { workspaceInstanceId: string; documentId: string }
export interface AgentContextReceipt {
  agentContextId: string; contentHash: string; agentType: string; sourceSessionId: string; messageCount: number;
}
export class AgentContextError extends Error {
  constructor(readonly code: string, message: string) { super(message); }
}

/** Immutable uploads survive reader reconnects, bounded to this backend lifetime. */
export class AgentContextService {
  private records = new Map<string, { scope: string; context: AgentContext; receipt: AgentContextReceipt }>();
  private requests = new Map<string, string>();
  private bytes = 0;
  constructor(private readonly limits = { count: 100, bytes: 32 * 1024 * 1024 }) {}

  upload(scope: AgentContextScope, requestId: string, trajectory: unknown): AgentContextReceipt {
    const context = AgentContext.fromTrajectory(trajectory), scopeKey = this.scopeKey(scope);
    const key = JSON.stringify([scopeKey, requestId]);
    const previous = this.requests.get(key);
    if (previous) {
      const record = this.records.get(previous)!;
      if (record.context.contentHash !== context.contentHash)
        throw new AgentContextError('REQUEST_ID_CONFLICT', 'Upload request ID already identifies different context');
      return { ...record.receipt };
    }
    const snapshot = context.toSnapshot(), size = new TextEncoder().encode(JSON.stringify(snapshot)).byteLength;
    if (this.records.size >= this.limits.count || this.bytes + size > this.limits.bytes)
      throw new AgentContextError('AGENT_CONTEXT_CAPACITY', 'Agent context storage is full for this backend lifetime');
    const receipt = { agentContextId: `agent-context-${randomUUID()}`, contentHash: context.contentHash,
      agentType: snapshot.source.agentType, sourceSessionId: snapshot.source.sourceSessionId, messageCount: snapshot.messages.length };
    this.records.set(receipt.agentContextId, { scope: scopeKey, context, receipt });
    this.requests.set(key, receipt.agentContextId); this.bytes += size;
    return { ...receipt };
  }

  get(scope: AgentContextScope, agentContextId: string): AgentContextSnapshot {
    const record = this.records.get(agentContextId);
    if (!record || record.scope !== this.scopeKey(scope))
      throw new AgentContextError('AGENT_CONTEXT_NOT_FOUND', 'Context is unavailable for this workspace and document');
    return record.context.toSnapshot();
  }
  private scopeKey(scope: AgentContextScope) { return JSON.stringify([scope.workspaceInstanceId, scope.documentId]); }
}

import { AgentContext, type AgentContextSnapshot } from '../../../domain/core/agents/agentContext';
import { randomUUID } from 'node:crypto';
import { CanvasHistory } from '../../../domain/core/diagrams/canvasHistory';
import type { DiagramService, DiagramRevisionResult } from '../../../domain/core/diagrams/diagramService';
import type { LiveDocumentSnapshot } from '../../../domain/mapping/agent/contracts';
import type { DiagramEditRun, DiagramRevisionApplication, EditDiagramInput } from '../../../domain/mapping/agent/diagramEdit';
import { findBox } from '../../../domain/mapping/workspace/canvasDisplayNode';

export interface DiagramEditCanvasPort {
  snapshot(sessionId: string): Promise<LiveDocumentSnapshot>;
  apply(sessionId: string, input: DiagramRevisionApplication): Promise<{ version: number; unresolvedEdgeIds: string[] }>;
}
interface Run {
  agentContext?: AgentContextSnapshot;
  input: EditDiagramInput;
  signature: string;
  state: DiagramEditRun;
  abort: AbortController;
  revision?: DiagramRevisionResult;
  pending?: Promise<void>;
}

/** A request owns both generation and installation; retries never rerun the model. */
export class DiagramEditService {
  private runs = new Map<string, Run>();
  private requests = new Map<string, string>();
  constructor(private readonly diagrams: DiagramService, private readonly canvas: DiagramEditCanvasPort) {}

  start(input: EditDiagramInput, suppliedContext?: AgentContextSnapshot): DiagramEditRun {
    const agentContext = suppliedContext ? AgentContext.fromSnapshot(suppliedContext).toSnapshot() : undefined;
    if (input.agentContextId && !agentContext) throw Error('AGENT_CONTEXT_NOT_FOUND: resolve context before starting the edit');
    const key = JSON.stringify([input.sessionId, input.requestId]);
    const signature = JSON.stringify({ input, agentContextHash: agentContext?.contentHash });
    const existing = this.requests.get(key);
    if (existing) {
      const run = this.runs.get(existing)!;
      if (run.signature !== signature) throw Error('REQUEST_ID_CONFLICT: edit request differs');
      if (run.state.status === 'awaiting-acknowledgement' && !run.pending) this.launch(run, () => this.apply(run));
      return structuredClone(run.state);
    }
    if (this.runs.size >= 500) throw Error('Diagram edit run capacity reached; restart the backend');
    const run: Run = { agentContext, input: structuredClone(input), signature, abort: new AbortController(), state: {
      runId: `diagram-edit-${randomUUID()}`, status: 'generating', nodeId: input.nodeId, baseRevisionId: input.baseRevisionId
    } };
    this.runs.set(run.state.runId, run); this.requests.set(key, run.state.runId);
    this.launch(run, () => this.generate(run));
    return structuredClone(run.state);
  }
  get(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    return structuredClone(run.state);
  }
  cancel(id: string) {
    const run = this.runs.get(id); if (!run) throw Error('Diagram edit run not found');
    // Once application is dispatched its outcome can be unknown. Never call it cancelled.
    if (run.state.status === 'generating') {
      run.abort.abort(); run.state.status = 'cancelled'; run.state.message = 'Cancelled before application';
    }
    return structuredClone(run.state);
  }
  private launch(run: Run, work: () => Promise<void>) {
    run.pending = work().catch(error => {
      if (run.abort.signal.aborted && run.state.status !== 'applying') { run.state.status = 'cancelled'; return; }
      const message = error instanceof Error ? error.message : String(error);
      run.state.status = run.state.status === 'applying' && /CANVAS_TIMEOUT|CANVAS_UNAVAILABLE|PERSISTENCE_PENDING/.test(message)
        ? 'awaiting-acknowledgement' : message.includes('VERSION_CONFLICT') ? 'conflict' : 'failed';
      run.state.error = message;
    }).finally(() => { run.pending = undefined; });
  }
  private async generate(run: Run) {
    const { input, abort } = run;
    const snapshot = await this.canvas.snapshot(input.sessionId);
    abort.signal.throwIfAborted();
    if (snapshot.version !== input.expectedVersion) throw Error('VERSION_CONFLICT: read the canvas again');
    const box = input.nodeId.startsWith('grid:') && findBox(snapshot.document.scene.root, input.nodeId.slice(5));
    if (!box || box.kind !== 'diagram') throw Error('Expected diagram GridBox');
    const base = snapshot.document.scene.contents[box.contentId];
    if (base.revisionId !== input.baseRevisionId) throw Error('VERSION_CONFLICT: diagram base is no longer current');
    if (!snapshot.history) throw Error('Canvas history is required for diagram generation');
    // Validated portable history imports the exact browser-issued revision identities.
    new CanvasHistory(snapshot.document, snapshot.canvas, snapshot.history, 'current');
    const lines = base.content.ascii.split('\n');
    run.revision = await this.diagrams.generate({ input: { id: base.id, structureKind: base.content.structure.kind,
      source: base.sourceContext.binding, evidence: base.sourceContext.evidence },
      instruction: input.prompt, agentContext: run.agentContext, baseRevisionId: base.revisionId,
      context: { diagram: base, selection: { startLine: 1, endLine: lines.length, startColumn: 1,
        endColumn: Math.max(1, ...lines.map(line => line.length)) }, connections: snapshot.document.edges }
    }, { signal: abort.signal, onProgress: message => { if (run.state.status === 'generating') run.state.message = message; } });
    abort.signal.throwIfAborted();
    run.state.generated = { diagramId: run.revision.diagram.diagramId, revisionId: run.revision.revision.id,
      ascii: run.revision.diagram.content.ascii };
    await this.apply(run);
  }
  private async apply(run: Run) {
    run.state.status = 'applying'; delete run.state.error;
    const revision = run.revision!.revision, input = run.input;
    // The controller checks both versions at the mutation boundary, after generation.
    const result = await this.canvas.apply(input.sessionId, { requestId: run.state.runId,
      expectedVersion: input.expectedVersion, nodeId: input.nodeId, baseRevisionId: input.baseRevisionId, revision });
    run.state.result = { diagramId: revision.diagramId, previousRevisionId: input.baseRevisionId,
      revisionId: revision.id, documentVersion: result.version, unresolvedEdgeIds: result.unresolvedEdgeIds };
    run.state.status = 'completed'; run.state.message = 'Diagram revision installed and workspace persisted';
  }
  dispose() { for (const run of this.runs.values()) this.cancel(run.state.runId); }
}

import { AgentContextService } from './agentContextService';
import { randomUUID } from 'node:crypto';
import { selectionDelta } from '../../../domain/mapping/agent/liveCanvasStatus';
import type { CanvasDescriptor } from '../../../domain/mapping/agent/contracts';
import type { BoundSelection, LiveCanvasContext, LiveCanvasEvent, LiveSelection, LiveSelectionDelta } from '../../../domain/mapping/agent/liveCanvasStatus';

export class LiveCanvasError extends Error {
  constructor(readonly code: string, readonly status: number, message = code) { super(message); }
}
type Snapshot = LiveSelection & { receivedAt: string };
type Binding = { workspaceInstanceId: string; documentId: string; canvasEpoch: string;
  unavailable?: 'canvas.disconnected' | 'canvas.closed' | 'canvas.replaced'; notify: (event: LiveCanvasEvent) => void };

/** Ephemeral selection mirror. Never hydrates a document, exports history or writes storage. */
export class LiveCanvasService {
  private publishers = new Map<string, { owner: object; selections: Map<string, Snapshot>; notify: (event: LiveCanvasEvent) => void }>();
  private bindings = new Map<string, Binding>();
  constructor(private readonly listCanvases: () => CanvasDescriptor[],
    private readonly loadContext?: (workspaceInstanceId: string, documentId: string) => Promise<LiveCanvasContext>,
    private readonly agentContexts = new AgentContextService()) {}
  uploadAgentContext(connectionId: string, requestId: string, trajectory: unknown) {
    const binding = this.read(connectionId);
    return this.agentContexts.upload(binding, requestId, trajectory);
  }
  async contextForCanvas(workspaceInstanceId: string, documentId: string) {
    const publisher = this.publishers.get(workspaceInstanceId);
    const canvases = this.listCanvases();
    if (!publisher && canvases.length && !canvases.some(canvas => canvas.canvasId === workspaceInstanceId))
      throw new LiveCanvasError('CANVAS_INSTANCE_GONE', 410, 'The browser workspace instance is no longer available. Discover the current canvas ID and reconnect.');
    const selection = publisher?.selections.get(documentId);
    if (!selection) throw new LiveCanvasError('CANVAS_NOT_READY', 503, 'Canvas has not published a selection snapshot; retry attach');
    if (!this.loadContext) throw new LiveCanvasError('CONTEXT_UNAVAILABLE', 503, 'Canvas context is unavailable on this server');
    const context = await this.loadContext(workspaceInstanceId, documentId);
    if (this.publishers.get(workspaceInstanceId) !== publisher
      || publisher?.selections.get(documentId)?.canvasEpoch !== selection.canvasEpoch)
      throw new LiveCanvasError('CANVAS_REPLACED', 409, 'Canvas changed identity while reading context; reconnect');
    return context;
  }
  async context(connectionId: string) {
    const before = this.read(connectionId);
