export class MappingWorkspaceService {
  constructor(private readonly projects: Pick<DiagramRepository, 'loadProject'>, private readonly workspace: MappingWorkspaceRepository) { }
  async loadRecords(historyValidation: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    return this.workspace.loadRecords(project.id, historyValidation);
  }
  async applyBatch(input: WorkspaceBatch) {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    return this.workspace.applyBatch(project.id, input);
  }
  async load() {
    const project = await this.projects.loadProject();
    return project ? this.workspace.load(project.id) : null;
  }
  async save(input: unknown) {
    const project = await this.projects.loadProject();
    if (!project) throw new ApplicationError('invalid-input', 'Project is not initialized');
    await this.workspace.save(project.id, input);
    return { saved: true };
  }
}

import { z } from 'zod';
import { sha256 } from '../sha256';

export const AGENT_CONTEXT_MAX_BYTES = 2 * 1024 * 1024;
const id = z.string().min(1).max(200);
const text = z.object({ type: z.literal('text'), text: z.string().max(1_000_000) }).strict();
const toolCall = z.object({ type: z.literal('toolCall'), id, name: id, arguments: z.record(z.string(), z.json()) }).strict();
const timestamp = z.number().int().nonnegative().default(0);
export const agentContextMessageSchema = z.discriminatedUnion('role', [
  z.object({ role: z.literal('user'), content: z.array(text).min(1).max(1000), timestamp }).strict(),
  z.object({ role: z.literal('assistant'), content: z.array(z.union([text, toolCall])).min(1).max(1000), timestamp }).strict(),
  z.object({ role: z.literal('toolResult'), toolCallId: id, toolName: id,
    content: z.array(text).min(1).max(1000), isError: z.boolean().default(false), timestamp }).strict()
]);
export type AgentContextMessage = z.infer<typeof agentContextMessageSchema>;
const entrySchema = z.object({ id, parentId: id.nullable(), message: agentContextMessageSchema }).strict();
export const agentTrajectorySchema = z.object({
  agentType: z.string().regex(/^[a-z][a-z0-9_-]{0,63}$/), sourceSessionId: id,
  format: z.literal('messages-v1'), fromEntryId: id, throughEntryId: id,
  entries: z.array(entrySchema).min(1).max(2000)
}).strict();
export type AgentTrajectoryInput = z.input<typeof agentTrajectorySchema>;
const snapshotDataSchema = z.object({
  version: z.literal(1),
  source: agentTrajectorySchema.pick({ agentType: true, sourceSessionId: true, format: true }),
  range: agentTrajectorySchema.pick({ fromEntryId: true, throughEntryId: true }),
  messages: z.array(agentContextMessageSchema).min(1).max(2000)
}).strict();
export const agentContextSnapshotSchema = snapshotDataSchema.extend({ contentHash: z.string().regex(/^[a-f0-9]{64}$/) });
export type AgentContextSnapshot = z.infer<typeof agentContextSnapshotSchema>;

/** Canonical JSON also stabilizes tool arguments whose object key order differs. */
function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
  if (value !== null && typeof value === 'object') return `{${Object.keys(value).sort()
    .map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
  return JSON.stringify(value);
}
function bounded(input: unknown) {
  if (new TextEncoder().encode(JSON.stringify(input)).byteLength > AGENT_CONTEXT_MAX_BYTES)
    throw Error('AGENT_CONTEXT_TOO_LARGE: context exceeds 2 MiB');
}
function validateMessages(messages: AgentContextMessage[]) {
  const pending = new Map<string, string>(), seen = new Set<string>();
  for (const message of messages) {
    if (message.role === 'toolResult') {
      if (pending.get(message.toolCallId) !== message.toolName)
        throw Error('INVALID_AGENT_CONTEXT: orphan, duplicate or mismatched tool result');
      pending.delete(message.toolCallId);
    } else {
      if (pending.size) throw Error('INVALID_AGENT_CONTEXT: missing tool results before next message');
      if (message.role === 'assistant') for (const block of message.content) if (block.type === 'toolCall') {
        if (seen.has(block.id)) throw Error('INVALID_AGENT_CONTEXT: duplicate tool call ID');
        seen.add(block.id); pending.set(block.id, block.name);
      }
    }
  }
  if (pending.size) throw Error('INVALID_AGENT_CONTEXT: slice ends before tool results');
}

/** Captured trajectory value. All parsing/conversion lives here; no SDK or I/O dependency. */
export class AgentContext {
  readonly #snapshot: AgentContextSnapshot;
  private constructor(snapshot: AgentContextSnapshot) { this.#snapshot = structuredClone(snapshot); }
  get contentHash() { return this.#snapshot.contentHash; }

  static fromTrajectory(raw: unknown): AgentContext {
    bounded(raw);
    const input = agentTrajectorySchema.parse(raw);
    const entries = new Map(input.entries.map(entry => [entry.id, entry]));
    if (entries.size !== input.entries.length) throw Error('INVALID_AGENT_CONTEXT: duplicate entry ID');
    const selected: AgentContextMessage[] = [], visited = new Set<string>();
    let cursor: string | null = input.throughEntryId;
    while (cursor !== null) {
      if (visited.has(cursor)) throw Error('INVALID_AGENT_CONTEXT: cyclic trajectory');
      visited.add(cursor);
      const entry = entries.get(cursor);
      if (!entry) throw Error('INVALID_AGENT_CONTEXT: missing entry on selected branch');
      selected.push(entry.message);
      if (cursor === input.fromEntryId) break;
      cursor = entry.parentId;
    }
    if (cursor !== input.fromEntryId) throw Error('INVALID_AGENT_CONTEXT: range is not on one branch');
    const messages = selected.reverse();
    validateMessages(messages);
    const data = snapshotDataSchema.parse({ version: 1,
      source: { agentType: input.agentType, sourceSessionId: input.sourceSessionId, format: input.format },
      range: { fromEntryId: input.fromEntryId, throughEntryId: input.throughEntryId }, messages });
    return new AgentContext({ ...data, contentHash: sha256(canonical(data)) });
  }

  static fromSnapshot(raw: unknown): AgentContext {
    bounded(raw);
    const snapshot = agentContextSnapshotSchema.parse(raw);
    const { contentHash, ...data } = snapshot;
    if (contentHash !== sha256(canonical(data))) throw Error('INVALID_AGENT_CONTEXT: content hash mismatch');
    validateMessages(snapshot.messages);
    return new AgentContext(snapshot);
  }

  toSnapshot(): AgentContextSnapshot { return structuredClone(this.#snapshot); }

  toPiMessages() {
    return this.toSnapshot().messages.map(message => {
      if (message.role !== 'assistant') return message;
      // Synthetic provenance marks imported history; it never selects the run's model.
      return { ...message, api: 'openai-responses' as const, provider: 'agent-context', model: this.#snapshot.source.agentType,
        stopReason: message.content.some(block => block.type === 'toolCall') ? 'toolUse' as const : 'stop' as const,
        usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
          cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } } };
    });
  }
}

import { sha256 } from '../sha256';

/** Artifact identity deliberately remains limited to 7-bit ASCII. */
export function asciiSha256(value: string): string {
  if (!/^[\x00-\x7f]*$/.test(value)) throw new Error("artifact revision input must be 7-bit ASCII");
  return sha256(value);
}

import { parseDiagram } from './interpreter';

export interface AsciiTreeNode {
  line: number;
  branchColumn: number;
  textColumn: number;
  text: string;
  parentLine?: number;
  descendantLines: number[];
}

/** Compatibility projection of the shared spatial interpreter for existing tree consumers. */
export function parseAsciiTree(ascii: string, compatibility: 'ascii-tree-1' | 'ascii-tree-2' = 'ascii-tree-2'): AsciiTreeNode[] {
  const parsed = parseDiagram(ascii, { dialect: 'tree', compatibility,
    treeTolerance: 0, wireTolerance: 0, continuation: 'separate', repairs: 'none' });
  const lines = new Map(parsed.nodes.map(node => [node.id, node.spans[0].line]));
  const nodes = parsed.nodes.map((node): AsciiTreeNode => ({
    line: node.spans[0].line, branchColumn: node.branchColumn === undefined ? -1 : node.branchColumn - 1,
    textColumn: node.spans[0].column, text: node.label,
    ...(node.parentId ? { parentLine: lines.get(node.parentId) } : {}), descendantLines: []
  }));
  const byLine = new Map(nodes.map(node => [node.line, node]));
  for (const node of nodes) {
    let parent = node.parentLine === undefined ? undefined : byLine.get(node.parentLine);
    while (parent) {
      parent.descendantLines.push(node.line);
      parent = parent.parentLine === undefined ? undefined : byLine.get(parent.parentLine);
    }
  }
  return nodes;
}

export function asciiTreeLineage(ascii: string, line: number): AsciiTreeNode[] {
  const nodes = parseAsciiTree(ascii);
  const byLine = new Map(nodes.map((node) => [node.line, node]));
  const lineage: AsciiTreeNode[] = [];
  let node = byLine.get(line);
  while (node) {
    lineage.unshift(node);
    node = node.parentLine === undefined ? undefined : byLine.get(node.parentLine);
  }
  return lineage;
}

/** Return a node and all of its descendants in display (pre-order) order. */
export function asciiTreeSubtree(ascii: string, line: number): AsciiTreeNode[] {
  const nodes = parseAsciiTree(ascii);
  const root = nodes.find((node) => node.line === line);
  if (!root) return [];
  const descendantLines = new Set(root.descendantLines);
  return nodes.filter((node) => node.line === line || descendantLines.has(node.line));
}

export function hiddenAsciiTreeLines(
  ascii: string,
  collapsedNodeLines: ReadonlySet<number>
): Set<number> {
  const lines = ascii.replace(/\r\n?/g, "\n").split("\n");
  const nodes = parseAsciiTree(ascii);
  const hidden = new Set<number>();
  for (const node of nodes) {
    if (!collapsedNodeLines.has(node.line) || node.descendantLines.length === 0) continue;
    const nextPeer = nodes.find((candidate) => (
      candidate.line > node.line && candidate.branchColumn <= node.branchColumn
    ));
    const endLine = nextPeer ? nextPeer.line - 1 : lines.length;
    for (let line = node.line + 1; line <= endLine; line += 1) hidden.add(line);
  }
  return hidden;
}

import { deepFreeze } from '../immutability';
import { diagramRevisions } from './internal/revisionRegistry';
import { validateDiagram, type Diagram } from './diagram';
import { diagramContentNodes } from './diagramContentNodes';
import { correspondingNodes, DiagramRevisionEditor, type DiagramRevision } from './diagramRevisionEditor';
import type { LineGridScene } from './lineGrid';
import type { DiagramConnection, DiagramAnchor, ContentNodeAnchor } from './diagramConnection';
export interface ResolvedCanvasDocument { scene: LineGridScene; edges: DiagramConnection[]; jumps?: CanvasJump[]; sections: Readonly<Record<string, readonly {id: string; label: string; startLine: number; endLine: number; anchorToken: string}[]>> }
import { projectCanvasSnapshot, validateCanvasScene } from './projectDiagramCanvas';
import { validateConnections } from './diagramConnection';
import { validateCanvasJumps, type CanvasJump } from './canvasJump';

export type CanvasNodeAnchor = Omit<ContentNodeAnchor, 'revisionId'>;
export type CanvasConnection = Omit<DiagramConnection, 'source' | 'target'> & {
  source: CanvasNodeAnchor;
  target: CanvasNodeAnchor | Extract<DiagramAnchor, {kind: 'box'}>;
};
/** Canonical canvas state separates diagram bindings from composition. Jump spans retain their source revision for stale-link detection. */
export interface CanvasDocument {
  jumps?: CanvasJump[];
  scene: Pick<ResolvedCanvasDocument['scene'], 'root'>;
  edges: CanvasConnection[];
  sections: ResolvedCanvasDocument['sections'];
}
export interface StoredCanvasSnapshot {
  transactionId?: string;
  id: string;
  parentId?: string;
  document: CanvasDocument;
  diagramBindings: Record<string, string>;
  /** Personal view restoration is separate from canvas composition. */
  view: unknown;
  nodeOrigins: Record<string, string>;
  /** Legacy adapter only: preserve already-stale endpoints without guessing. */
  unresolvedAnchors?: Record<string, ContentNodeAnchor>;
}
export interface HistoryChanges {
  sequence: number;
  header: Omit<CanvasHistoryRecord, "snapshots" | "diagramRevisions">;
  snapshots: CanvasHistoryRecord["snapshots"];
  diagramRevisions: CanvasHistoryRecord["diagramRevisions"];
}
export interface CanvasHistoryRecord {
  schemaVersion: 1;
  contextId: string;
  baselineId: string;
  headId: string;
  past: string[];
  future: string[];
  snapshots: Record<string, StoredCanvasSnapshot>;
  diagramRevisions: Record<string, DiagramRevision>;
}
export type HistoryValidation = 'all' | 'current';
export function currentHistoryChanges(record: CanvasHistoryRecord, snapshotId = record.headId) {
  const snapshot = record.snapshots?.[snapshotId];
  if (!snapshot) throw Error('Unknown canvas checkpoint');
  return { revisions: [...new Set(Object.values(snapshot.diagramBindings))], snapshots: [snapshotId] };
}
const id = (kind: string) => `${kind}-${crypto.randomUUID()}`;
export function stateKey(value: unknown): string {
  return JSON.stringify(value, (_key, item) => item && typeof item === 'object' && !Array.isArray(item)
    ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
}
const equal = (a: unknown, b: unknown) => stateKey(a) === stateKey(b);

/** Shared by live controllers, MCP staging and persisted change-session copies. */
export class CanvasHistory {
  private record: CanvasHistoryRecord;
  private readonly validatedSnapshots = new Set<string>();
  private changes: { snapshots: CanvasHistoryRecord["snapshots"]; diagramRevisions: CanvasHistoryRecord["diagramRevisions"] }[] = [];
  readonly diagrams: Pick<DiagramRevisionEditor, 'resolve' | 'merge'>;
  constructor(document: ResolvedCanvasDocument, view: unknown, record?: CanvasHistoryRecord, validation: HistoryValidation = 'all') {
    if (record) {
      validateCanvasHistory(record, validation === 'current' ? currentHistoryChanges(record) : undefined);
      for (const revision of Object.values(record.diagramRevisions)) {
        if (validation === 'current') diagramRevisions.restore(revision); else diagramRevisions.register(revision);
      }
      for (const key of validation === 'current' ? [record.headId] : Object.keys(record.snapshots)) this.validatedSnapshots.add(key);
      this.record = structuredClone(record);
      if (!equal(this.document(), document)) throw new Error('Canvas history does not match document');
    } else {
      this.record = { schemaVersion: 1, contextId: id('context'), baselineId: '', headId: '', past: [], future: [], snapshots: {}, diagramRevisions: {} };
      this.append(document, view);
      this.record.baselineId = this.record.headId;
      this.record.past = [];
    }
    this.diagrams = new DiagramRevisionEditor(this.record.diagramRevisions, contextId => {
      if (contextId !== this.record.contextId) throw new Error('Unknown editing context');
      return this.head.diagramBindings;
    });
  }
  get headId() { return this.record.headId; }
  get contextId() { return this.record.contextId; }
  get head(): StoredCanvasSnapshot { return structuredClone(this.record.snapshots[this.record.headId]); }
  get canUndo() { return !!this.record.past.length; }
  get canRedo() { return !!this.record.future.length; }
  /** Trusted persistence adapter: records are immutable; only tables/navigation are copied. */
  persistenceChanges(since?: number): HistoryChanges {
    const { snapshots, diagramRevisions, ...header } = this.record;
    const updates = since === undefined ? { snapshots: { ...snapshots }, diagramRevisions: { ...diagramRevisions } }
      : this.changes.slice(since).reduce((out, change) => ({ snapshots: Object.assign(out.snapshots, change.snapshots),
        diagramRevisions: Object.assign(out.diagramRevisions, change.diagramRevisions) }), { snapshots: {}, diagramRevisions: {} });
    return { sequence: this.changes.length, header: { ...header, past: [...header.past], future: [...header.future] }, ...updates };
  }
  export(): CanvasHistoryRecord { return structuredClone(this.record); }
  fork(view: unknown = this.head.view): CanvasHistoryRecord {
    const record = this.export(), head = this.head;
    const baseline = { ...head, view: structuredClone(view), id: id('canvas-revision'), parentId: head.id, nodeOrigins: Object.fromEntries(
      Object.values(this.document().scene.contents).flatMap(diagram => diagramContentNodes(diagram.content).map(node => [node.id, node.id]))) };
    record.snapshots[baseline.id] = baseline;
    return { ...record, contextId: id('context'), headId: baseline.id, baselineId: baseline.id, past: [], future: [] };
  }
  /** Compatibility projection for existing rendering, source and MCP adapters. */
  document(snapshotId = this.record.headId): ResolvedCanvasDocument {
    this.validateCheckpoint(snapshotId);
    return documentFromHistory(this.record, snapshotId);
  }
  private validateCheckpoint(snapshotId: string) {
    if (this.validatedSnapshots.has(snapshotId)) return;
    validateCanvasHistory(this.record, currentHistoryChanges(this.record, snapshotId));
    this.validatedSnapshots.add(snapshotId);
  }

  append(document: ResolvedCanvasDocument, view: unknown, correspondence: ReadonlyMap<string, string> = new Map()): StoredCanvasSnapshot {
    projectCanvasSnapshot(document.scene);
    validateConnections(document.scene, document.edges);
    if (document.jumps) validateCanvasJumps(document.scene, document.jumps);
    const previous = this.record.snapshots[this.record.headId];
    const bindings: Record<string, string> = {}, additions: Record<string, DiagramRevision> = {}, origins: Record<string, string> = {};
    for (const [diagramId, diagram] of Object.entries(document.scene.contents)) {
      validateDiagram(diagram);
      const prior = previous && this.record.diagramRevisions[previous.diagramBindings[diagramId]];
      const same = prior && equal(prior.diagram, diagram);
      const map = prior ? new Map([...correspondingNodes(prior.diagram, diagram), ...correspondence]) : new Map<string, string>();
      const reverse = new Map([...map].map(([a, b]) => [b, a]));
      for (const node of diagramContentNodes(diagram.content)) {
        const old = same ? node.id : reverse.get(node.id);
        if (!previous) origins[node.id] = node.id;
        else if (old && previous.nodeOrigins[old]) origins[node.id] = previous.nodeOrigins[old];
      }
      const issued = diagramRevisions.assert(diagram);
      bindings[diagramId] = issued.id;
      const include = (revision: DiagramRevision) => {
        if (this.record.diagramRevisions[revision.id] || additions[revision.id]) return;
        if (revision.parentId) include(diagramRevisions.get(revision.parentId));
        additions[revision.id] = revision;
      };
      include(issued);
    }
    const unresolvedAnchors: Record<string, ContentNodeAnchor> = {};
    const revisions = { ...this.record.diagramRevisions, ...additions };
    const edges = document.edges.map(edge => ({ ...edge, source: encodeAnchor(edge.source, edge.id + ':source', document.scene, bindings, revisions, unresolvedAnchors) as CanvasNodeAnchor, target: encodeAnchor(edge.target, edge.id + ':target', document.scene, bindings, revisions, unresolvedAnchors) }));
    const snapshot: StoredCanvasSnapshot = { id: id('canvas-revision'), parentId: previous?.id,
      document: { scene: { root: structuredClone(document.scene.root) }, edges, sections: structuredClone(document.sections), ...(document.jumps ? { jumps: structuredClone(document.jumps) } : {}) },
      diagramBindings: bindings, unresolvedAnchors, view: structuredClone(view), nodeOrigins: origins };
    // Validation above must complete before any canonical state changes.
    Object.assign(this.record.diagramRevisions, additions);
    this.changes.push({ snapshots: {}, diagramRevisions: additions });
    this.record.snapshots[snapshot.id] = snapshot;
    this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
    if (previous) this.record.past.push(previous.id);
    this.record.headId = snapshot.id;
    this.record.future = [];
    return this.head;
  }
  navigationTransactionId(redo = false) {
    return this.record.snapshots[redo ? this.record.future.at(-1)! : this.record.headId]?.transactionId;
  }
  navigate(redo = false): StoredCanvasSnapshot | undefined {
    const target = (redo ? this.record.future : this.record.past).at(-1);
    if (!target) return;
    this.validateCheckpoint(target);
    (redo ? this.record.future : this.record.past).pop();
    (redo ? this.record.past : this.record.future).push(this.record.headId);
    this.record.headId = target;
    return this.head;
  }
  linkTransaction(transactionId: string) {
    const snapshot = { ...this.record.snapshots[this.record.headId], transactionId };
    this.record.snapshots[snapshot.id] = snapshot;
    this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
  }
  retireTransactions(ids: ReadonlySet<string>) {
    for (const prior of Object.values(this.record.snapshots)) if (prior.transactionId && ids.has(prior.transactionId)) {
      const { transactionId: _, ...snapshot } = prior;
      this.record.snapshots[snapshot.id] = snapshot;
      this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
    }
  }
  /** Publish a reviewed state as one checkpoint, retaining its exact diagram revision IDs. */
  adopt(proposed: CanvasHistoryRecord): void {
    validateCanvasHistory(proposed);
    for (const revision of Object.values(proposed.diagramRevisions)) diagramRevisions.register(revision);
    const added = Object.fromEntries(Object.entries(proposed.diagramRevisions).filter(([key]) => !this.record.diagramRevisions[key]));
    for (const [key, revision] of Object.entries(proposed.diagramRevisions)) {
      const existing = this.record.diagramRevisions[key];
      if (existing && !equal(existing, revision)) throw new Error('Diagram revision is immutable');
    }
    const snapshot = structuredClone({ ...proposed.snapshots[proposed.headId], id: id('canvas-revision'), parentId: this.record.headId });
    const next = { ...this.record, snapshots: { ...this.record.snapshots, [snapshot.id]: snapshot },
      diagramRevisions: { ...this.record.diagramRevisions, ...proposed.diagramRevisions },
      past: [...this.record.past, this.record.headId], future: [], headId: snapshot.id };
    validateCanvasHistory(next);
    // Keep the revision table object used by the internal resolver alive.
    Object.assign(this.record.diagramRevisions, structuredClone(proposed.diagramRevisions));
    this.record = { ...next, diagramRevisions: this.record.diagramRevisions };
    this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: Object.fromEntries(Object.keys(added).map(key => [key, this.record.diagramRevisions[key]])) });
  }
  reset(view?: unknown) {
    this.validateCheckpoint(this.record.baselineId);
    const baseline = this.record.snapshots[this.record.baselineId];
    const snapshot = structuredClone({ ...baseline, id: id('canvas-revision'), parentId: this.record.headId, view: view ?? baseline.view });
    this.record.snapshots[snapshot.id] = snapshot;
    this.changes.push({ snapshots: { [snapshot.id]: snapshot }, diagramRevisions: {} });
    this.record.past.push(this.record.headId);
    this.record.headId = snapshot.id;
    this.record.future = [];
    return this.head;
  }
}

export function validateCanvasHistory(value: CanvasHistoryRecord, changed?: { revisions: string[]; snapshots: string[] }): void {
  const validated = new Set<Diagram>();
  if (!value || value.schemaVersion !== 1 || typeof value.contextId !== 'string' || !value.contextId
    || !value.snapshots || !value.diagramRevisions || !Array.isArray(value.past) || !Array.isArray(value.future)) throw new Error('Invalid canvas history');
  for (const key of [value.headId, value.baselineId, ...value.past, ...value.future]) {
    if (typeof key !== 'string' || !Object.hasOwn(value.snapshots, key)) throw new Error('Unknown canvas history reference');
  }
  for (const [key, revision] of (changed ? changed.revisions.map(key => [key, value.diagramRevisions[key]] as const) : Object.entries(value.diagramRevisions))) {
    if (revision.diagram.revisionId !== key || revision.id !== key || revision.diagramId !== revision.diagram.diagramId || !revision.nodeRefs) throw new Error('Invalid diagram history identity');
    validateDiagram(revision.diagram);
    validated.add(revision.diagram);
    if (revision.parentId && (!Object.hasOwn(value.diagramRevisions, revision.parentId)
      || value.diagramRevisions[revision.parentId].diagramId !== revision.diagramId)) throw new Error('Invalid diagram revision parent');
    const refs = diagramContentNodes(revision.diagram.content).map(n => revision.nodeRefs[n.id]);
    if (refs.some(ref => typeof ref !== 'string' || !ref) || new Set(refs).size !== refs.length) throw new Error('Invalid logical node identities');
  }
  for (const [key, snapshot] of (changed ? changed.snapshots.map(key => [key, value.snapshots[key]] as const) : Object.entries(value.snapshots))) {
    if (snapshot.id !== key || !snapshot.document || !snapshot.view || !snapshot.nodeOrigins || !snapshot.diagramBindings
      || snapshot.parentId && !Object.hasOwn(value.snapshots, snapshot.parentId)) throw new Error('Invalid canvas checkpoint');
    if ('contents' in snapshot.document.scene) throw new Error('Canvas checkpoint must not embed diagrams');
    const contents: Record<string, Diagram> = {};
    for (const [diagramId, revisionId] of Object.entries(snapshot.diagramBindings)) {
      const revision = Object.hasOwn(value.diagramRevisions, revisionId) && value.diagramRevisions[revisionId];
      if (!revision || revision.diagram.id !== diagramId) throw new Error('Invalid diagram binding');
      contents[diagramId] = revision.diagram;
    }
    const scene = { root: snapshot.document.scene.root, contents };
    validateCanvasScene(scene, validated);
    if (snapshot.transactionId !== undefined && (typeof snapshot.transactionId !== 'string' || !snapshot.transactionId)) throw Error('Invalid transaction reference');
    if (snapshot.document.jumps) validateCanvasJumps(scene, snapshot.document.jumps);
    validateConnections(scene, documentFromHistory(value, key).edges);
  }
}

/** Materialize the legacy read model only at transport/rendering boundaries. */
export function documentFromHistory(record: CanvasHistoryRecord, snapshotId = record.headId): ResolvedCanvasDocument {
  const snapshot = record.snapshots[snapshotId];
  if (!snapshot) throw new Error('Unknown canvas checkpoint');
  const contents = Object.fromEntries(Object.entries(snapshot.diagramBindings).map(([diagramId, revisionId]) => [diagramId, record.diagramRevisions[revisionId].diagram]));
  const scene = { root: snapshot.document.scene.root, contents };
  const decode = (anchor: CanvasConnection['target'], key: string): DiagramAnchor => {
    if (anchor.kind === 'box') return anchor;
    if (snapshot.unresolvedAnchors?.[key]) return snapshot.unresolvedAnchors[key];
    const box = findOwner(scene.root, anchor.displayNodeId);
    const revision = box?.kind === 'diagram' && record.diagramRevisions[snapshot.diagramBindings[box.contentId]];
    const contentNodeId = revision && Object.entries(revision.nodeRefs).find(([, ref]) => ref === anchor.contentNodeId)?.[0];
    if (!revision || !contentNodeId) throw new Error('Unresolvable canonical anchor');
    return { ...anchor, contentNodeId, revisionId: revision.diagram.content.revisionId };
  };
  const result = structuredClone({ ...snapshot.document, scene, edges: snapshot.document.edges.map(edge => ({ ...edge,
    source: decode(edge.source, edge.id + ':source') as ContentNodeAnchor, target: decode(edge.target, edge.id + ':target') })) });
  Object.values(result.scene.contents).forEach(deepFreeze);
  return result;
}

function findOwner(root: LineGridScene['root'], displayNodeId: string): LineGridScene['root'] | undefined {
  if (`grid:${root.id}` === displayNodeId) return root;
  return root.kind === 'container' ? root.children.map(child => findOwner(child, displayNodeId)).find(Boolean) : undefined;
}
function encodeAnchor(anchor: DiagramAnchor, key: string, scene: LineGridScene, bindings: Record<string, string>,
  revisions: Record<string, DiagramRevision>, unresolved: Record<string, ContentNodeAnchor>): CanvasConnection['target'] {
  if (anchor.kind === 'box') return structuredClone(anchor);
  const box = findOwner(scene.root, anchor.displayNodeId);
  const revision = box?.kind === 'diagram' && revisions[bindings[box.contentId]];
  const ref = revision && revision.diagram.content.revisionId === anchor.revisionId && revision.nodeRefs[anchor.contentNodeId];
  const { revisionId: _, ...rest } = anchor;
  if (!ref) unresolved[key] = structuredClone(anchor);
  return { ...rest, contentNodeId: ref || `unresolved:${anchor.contentNodeId}` };
}

import { CanvasHistory, type CanvasHistoryRecord, type ResolvedCanvasDocument } from './canvasHistory';
import type { DiagramView } from './diagramRevisionEditor';
import { prepareCanvasTransfer, prepareTransferNavigation, transferBoundary, type CanvasTransfer, type TransferInput, type PreparedCanvasTransfer, type TransferState } from './canvasTransfer';


/** Runtime handle. Neither it nor the service belongs in a saved canvas. */
export interface CanvasEditingContext { readonly contextId: string }
export interface CanvasContextState {
  checkpointId: string;
  document: import('./canvasHistory').CanvasDocument;
  view: unknown;
  canUndo: boolean;
  canRedo: boolean;
}

/** Canvas controllers coordinate edits; this boundary owns history and its storage. */
export interface CanvasHistoryService {
  prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext): PreparedCanvasTransfer;
  transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo?: boolean): boolean;
  prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo?: boolean): { source: TransferState; destination: TransferState; transaction: CanvasTransfer };
  openContext(document: ResolvedCanvasDocument, view: unknown, history?: CanvasHistoryRecord): CanvasEditingContext;
  state(context: CanvasEditingContext): CanvasContextState;
  resolve(context: CanvasEditingContext, diagramId: string): DiagramView;
  document(context: CanvasEditingContext): ResolvedCanvasDocument;
  append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>): void;
  navigate(context: CanvasEditingContext, redo?: boolean): boolean;
  reset(context: CanvasEditingContext): void;
  /** Portable transport adapters; callers must not interpret diagram revision tables. */
  exportContext(context: CanvasEditingContext): CanvasHistoryRecord;
  persistenceChanges(context: CanvasEditingContext, since?: number): import("./canvasHistory").HistoryChanges;
  retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>): void;
  forkContext(context: CanvasEditingContext, view: unknown): CanvasHistoryRecord;
  adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord): void;
}

export class DefaultCanvasHistoryService implements CanvasHistoryService {
  constructor(private readonly validation: import('./canvasHistory').HistoryValidation = 'all') {}
  // Object handles isolate two viewers of the same persisted context, and allow GC on close.
  private readonly contexts = new WeakMap<CanvasEditingContext, CanvasHistory>();

  openContext(document: ResolvedCanvasDocument, view: unknown, record?: CanvasHistoryRecord): CanvasEditingContext {
    const history = new CanvasHistory(document, view, record, this.validation);
    const context = Object.freeze({ contextId: history.contextId });
    this.contexts.set(context, history);
    return context;
  }
  private history(context: CanvasEditingContext) {
    const history = this.contexts.get(context);
    if (!history) throw new Error('Unknown diagram editing context');
    return history;
  }
  state(context: CanvasEditingContext): CanvasContextState {
    const history = this.history(context), head = history.head;
    return { checkpointId: head.id, document: head.document, view: head.view, canUndo: history.canUndo, canRedo: history.canRedo };
  }
  resolve(context: CanvasEditingContext, diagramId: string) {
    const history = this.history(context);
    return history.diagrams.resolve(history.contextId, diagramId);
  }
  document(context: CanvasEditingContext) { return this.history(context).document(); }
  append(context: CanvasEditingContext, document: ResolvedCanvasDocument, view: unknown, correspondence?: ReadonlyMap<string, string>) {
    this.history(context).append(document, view, correspondence);
  }
  navigate(context: CanvasEditingContext, redo = false) {
    const linked = this.history(context).navigationTransactionId(redo);
    if (linked) throw Error('Use workspace undo/redo for a canvas transfer.');
    return !!this.history(context).navigate(redo);
  }
  prepareTransfer(context: CanvasEditingContext, input: TransferInput, destination?: CanvasEditingContext) {
    return prepareCanvasTransfer(this.history(context).export(), input, destination ? this.history(destination).export() : undefined);
  }
  transferBoundary(context: CanvasEditingContext, transaction: CanvasTransfer, canvasId: string, redo = false) {
    return transferBoundary({ headId: this.history(context).headId }, transaction, canvasId, redo);
  }
  prepareTransferNavigation(source: CanvasEditingContext, destination: CanvasEditingContext, transaction: CanvasTransfer, redo = false) {
    return prepareTransferNavigation(this.history(source).export(), this.history(destination).export(), transaction, redo);
  }
  reset(context: CanvasEditingContext) { this.history(context).reset(); }
  persistenceChanges(context: CanvasEditingContext, since?: number) { return this.history(context).persistenceChanges(since); }
  retireTransactions(context: CanvasEditingContext, ids: ReadonlySet<string>) { this.history(context).retireTransactions(ids); }
  exportContext(context: CanvasEditingContext) { return this.history(context).export(); }
  forkContext(context: CanvasEditingContext, view: unknown) { return this.history(context).fork(view); }
  adopt(context: CanvasEditingContext, proposed: CanvasHistoryRecord) { this.history(context).adopt(proposed); }
}

import { z } from 'zod';
import { diagramJumpSchema, validateDiagramJumps } from './diagramJump';
import { connectionBox } from './diagramConnection';
import type { LineGridScene } from './lineGrid';
export const canvasJumpSchema = diagramJumpSchema.extend({ sourceDisplayNodeId: z.string().min(1), label: z.string().optional() });
export type CanvasJump = z.infer<typeof canvasJumpSchema>;
export function validateCanvasJumps(scene: LineGridScene, input: unknown): CanvasJump[] {
  const jumps = z.array(canvasJumpSchema).max(4000).parse(input ?? []);
  if (new Set(jumps.map(jump => jump.id)).size !== jumps.length) throw Error('Duplicate canvas jump');
  for (const jump of jumps) {
    const box = connectionBox(scene, jump.sourceDisplayNodeId);
    if (box?.kind !== 'diagram') throw Error('Jump source diagram is missing');
    const { sourceDisplayNodeId, label, ...link } = jump;
    validateDiagramJumps(scene.contents[box.contentId].content, [link]);
  }
  return jumps;
}

import { placeTransferredGroup } from './canvasTransferPlacement';
import { z } from 'zod';
import { CanvasHistory, documentFromHistory, type CanvasHistoryRecord, type ResolvedCanvasDocument } from './canvasHistory';
import { rebaseDiagramJumps, type DiagramJumpTarget } from './diagramJump';
import { RevisionedDiagramService } from './diagramService';
import { diagramContentNodes } from './diagramContentNodes';
import { connectionBox, getArrowLabel, validateConnectionAnchor } from './diagramConnection';
import { flattenGrid, resolveScene, type GridBox, type LineGridScene } from './lineGrid';

import type { CanvasJump } from './canvasJump';
export const canvasTransferSchema = z.object({
  destinationCreated: z.boolean().optional(),
  id: z.string().min(1), mode: z.enum(['copy', 'move']), applied: z.boolean(), discarded: z.boolean().optional(),
  sourceId: z.string().min(1), destinationId: z.string().min(1),
  sourceBefore: z.string().min(1), sourceAfter: z.string().min(1),
  destinationBefore: z.string().min(1), destinationAfter: z.string().min(1)
}).strict();
export type CanvasTransfer = z.infer<typeof canvasTransferSchema>;
export interface TransferInput {
  mode: 'copy' | 'move'; sourceId: string; sourceAliases: string[]; destinationId: string;
  selectedIds: string[]; destinationView: unknown; sourceView?: unknown;
}
export interface TransferState { document: ResolvedCanvasDocument; history: CanvasHistoryRecord; view: unknown }
export interface PreparedCanvasTransfer { transaction: CanvasTransfer; source: TransferState; destination: TransferState; selectedIds: string[] }
const fresh = (kind: string) => `${kind}-${crypto.randomUUID()}`;
export const emptyCanvasDocument = (): ResolvedCanvasDocument => ({ scene: { contents: {}, root: { id: 'root', kind: 'container',
  position: { column: 0, row: 0 }, collapsed: false, layout: { collisionPolicy: 'push-right', gap: 3 }, children: [] } }, edges: [], sections: {} });
const state = (history: CanvasHistory): TransferState => ({ document: history.document(), history: history.export(), view: history.head.view });

/** Preparation operates on isolated histories. Publication belongs to the workspace transaction. */
export function prepareCanvasTransfer(record: CanvasHistoryRecord, input: TransferInput, destinationRecord?: CanvasHistoryRecord): PreparedCanvasTransfer {
  if (input.sourceId === input.destinationId) throw Error('Choose another canvas as the destination');
  const diagrams = new RevisionedDiagramService();
  const original = new CanvasHistory(documentFromHistory(record), {}, record), before = original.document();
  if (!input.selectedIds.length || new Set(input.selectedIds).size !== input.selectedIds.length) throw Error('Select one or more diagrams');
  const existing = destinationRecord ? documentFromHistory(destinationRecord) : emptyCanvasDocument();
  const destination = new CanvasHistory(existing, input.destinationView, destinationRecord);
  const existingIds = new Set<string>();
  const visitIds = (box: GridBox) => { existingIds.add(box.id); if (box.kind === 'container') box.children.forEach(visitIds); };
  visitIds(existing.scene.root);
  const selected = new Set(input.selectedIds);
  for (const id of selected) if (connectionBox(before.scene, id)?.kind !== 'diagram') throw Error('Selection must contain only diagrams');
  const expand = (box: GridBox): GridBox => box.kind === 'container' ? { ...box, collapsed: false, children: box.children.map(expand) } : box;
  const boxes = flattenGrid(resolveScene({ ...before.scene, root: expand(before.scene.root) })).filter(({ box }) => selected.has(`grid:${box.id}`));
  const minColumn = Math.min(...boxes.map(box => box.bounds.column)), minRow = Math.min(...boxes.map(box => box.bounds.row));
  const boxIds = new Map(boxes.map(({ box }) => [box.id, input.mode === 'copy' || existingIds.has(box.id) ? fresh('diagram') : box.id]));
  const contentIds = new Map<string, string>();
  const target = emptyCanvasDocument(), contents: Record<string, LineGridScene['contents'][string]> = {};
  const sections: Record<string, ResolvedCanvasDocument['sections'][string]> = {};
  const cloneContent = (id: string) => {
    if (!contentIds.has(id)) {
      const next = input.mode === 'copy' || Object.hasOwn(existing.scene.contents, id) ? fresh('diagram-content') : id;
      contentIds.set(id, next);
      const old = before.scene.contents[id];
      if (next === id) contents[next] = old;
      else {
        const created = diagrams.create({ id: next, revision: 0, ascii: old.content.ascii,
          structureKind: old.content.structure.kind, source: old.sourceContext.binding,
          mappings: old.sourceContext.mappings, evidence: old.sourceContext.evidence }).diagram;
        contents[next] = old.jumps ? diagrams.revise(created.revisionId,
          { kind: 'jumps', jumps: rebaseDiagramJumps(old.content, created.content, old.jumps) }).diagram : created;
      }
      if (before.sections[id]) sections[next] = structuredClone(before.sections[id]);
    }
    return contentIds.get(id)!;
  };
  const children = boxes.map(({ box, bounds }) => {
    if (box.kind !== 'diagram') throw Error('Expected diagram');
    return { ...structuredClone(box), id: boxIds.get(box.id)!, contentId: cloneContent(box.contentId),
      collapsedContentId: box.collapsedContentId ? cloneContent(box.collapsedContentId) : undefined,
      position: { column: bounds.column - minColumn, row: bounds.row - minRow } };
  });
  target.scene = { contents, root: { ...target.scene.root, kind: 'container', layout: { collisionPolicy: 'push-right', gap: 3 }, children } };
  target.sections = sections;
  const remapNode = (displayNodeId: string, nodeId: string) => {
    const box = connectionBox(before.scene, displayNodeId);
    if (box?.kind !== 'diagram') throw Error('Expected diagram node target');
    const old = diagramContentNodes(before.scene.contents[box.contentId].content).find(node => node.id === nodeId);
    if (!old) return nodeId; // Preserve explicitly stale links as stale.
    return diagramContentNodes(contents[contentIds.get(box.contentId)!].content)
      .find(node => node.line === old.line && node.startColumn === old.startColumn && node.endColumn === old.endColumn)?.id ?? nodeId;
  };
  const remapTarget = (jump: DiagramJumpTarget): DiagramJumpTarget => input.sourceAliases.includes(jump.representationId) && jump.displayNodeId && selected.has(jump.displayNodeId)
    ? { ...jump, representationId: input.destinationId, displayNodeId: `grid:${boxIds.get(jump.displayNodeId.slice(5))}`,
      ...(jump.contentNodeId ? { contentNodeId: remapNode(jump.displayNodeId, jump.contentNodeId) } : {}) } : jump;
  const remapJumps = (diagram: LineGridScene['contents'][string]) => diagram.jumps
    ? diagrams.revise(diagram.revisionId, { kind: 'jumps', jumps: diagram.jumps.map(jump => ({ ...jump, target: remapTarget(jump.target) })) }).diagram : diagram;
  for (const [id, diagram] of Object.entries(contents)) contents[id] = remapJumps(diagram);
  const targetJumps: CanvasJump[] = [], sourceJumps: CanvasJump[] = [];
  for (const jump of before.jumps ?? []) {
    if (selected.has(jump.sourceDisplayNodeId)) {
      const box = connectionBox(before.scene, jump.sourceDisplayNodeId)!;
      if (box.kind !== 'diagram') throw Error('Expected jump source diagram');
      const rebased = rebaseDiagramJumps(before.scene.contents[box.contentId].content, contents[contentIds.get(box.contentId)!].content, [jump])[0];
      targetJumps.push({ ...structuredClone(jump), ...rebased, id: fresh('jump'),
        sourceDisplayNodeId: `grid:${boxIds.get(jump.sourceDisplayNodeId.slice(5))}`, target: remapTarget(jump.target) });
    }
    if (input.mode === 'copy' || !selected.has(jump.sourceDisplayNodeId)) sourceJumps.push({ ...jump,
      target: input.mode === 'move' ? remapTarget(jump.target) : jump.target });
  }
  if (input.mode === 'copy') {
    const remapAnchor = <T extends typeof before.edges[number]['target']>(anchor: T): T => {
      const displayNodeId = `grid:${boxIds.get(anchor.displayNodeId.slice(5))}`;
      if (anchor.kind === 'box') return { ...anchor, displayNodeId };
      validateConnectionAnchor(before.scene, anchor);
      const box = connectionBox(before.scene, anchor.displayNodeId)!;
      if (box.kind !== 'diagram') throw Error('Expected diagram anchor');
      return { ...anchor, displayNodeId, contentNodeId: remapNode(anchor.displayNodeId, anchor.contentNodeId),
        revisionId: contents[contentIds.get(box.contentId)!].content.revisionId };
    };
    target.edges = before.edges.filter(edge => selected.has(edge.source.displayNodeId) && selected.has(edge.target.displayNodeId)).map(edge => ({
      ...structuredClone(edge), id: fresh('edge'), source: remapAnchor(edge.source), target: remapAnchor(edge.target) }));
  } else {
    for (const edge of before.edges) {
      validateConnectionAnchor(before.scene, edge.source); validateConnectionAnchor(before.scene, edge.target);
      const owner = connectionBox(before.scene, edge.source.displayNodeId)!;
      if (owner.kind !== 'diagram') throw Error('Edge source must be a diagram');
      const content = before.scene.contents[owner.contentId].content;
      const node = diagramContentNodes(content).find(node => node.id === edge.source.contentNodeId)!;
      const movedSource = selected.has(edge.source.displayNodeId), movedTarget = selected.has(edge.target.displayNodeId);
      const jump: CanvasJump = { id: fresh('jump'), label: getArrowLabel(edge.appearance).text || undefined,
        sourceDisplayNodeId: movedSource ? `grid:${boxIds.get(owner.id)}` : edge.source.displayNodeId,
        source: { revisionId: content.revisionId, contentHash: content.asciiSha256, contentNodeId: node.id,
          line: node.line, startColumn: node.startColumn, endColumn: node.endColumn },
        target: { representationId: movedTarget ? input.destinationId : input.sourceId,
          displayNodeId: movedTarget ? `grid:${boxIds.get(edge.target.displayNodeId.slice(5))}` : edge.target.displayNodeId,
          ...(edge.target.kind === 'content-node' ? { contentNodeId: edge.target.contentNodeId } : {}) } };
      if (movedSource) jump.source = rebaseDiagramJumps(content, contents[contentIds.get(owner.contentId)!].content, [jump])[0].source;
      if (movedTarget && jump.target.contentNodeId) jump.target.contentNodeId = remapNode(edge.target.displayNodeId, jump.target.contentNodeId);
      (movedSource ? targetJumps : sourceJumps).push(jump);
    }
    const remove = (box: GridBox): GridBox => box.kind === 'container'
      ? { ...box, children: box.children.filter(child => !selected.has(`grid:${child.id}`)).map(remove) } : box;
    const root = selected.has(`grid:${before.scene.root.id}`) ? emptyCanvasDocument().scene.root : remove(before.scene.root);
    const used = new Set<string>();
    const visit = (box: GridBox) => { if (box.collapsedContentId) used.add(box.collapsedContentId);
      if (box.kind === 'diagram') used.add(box.contentId); else box.children.forEach(visit); };
    visit(root);
    const source: ResolvedCanvasDocument = { ...before, edges: [], jumps: sourceJumps,
      sections: Object.fromEntries(Object.entries(before.sections).filter(([id]) => used.has(id))),
      scene: { root, contents: Object.fromEntries(Object.entries(before.scene.contents).filter(([id]) => used.has(id))) } };
    // Diagram-local links on remaining placements also follow moved targets.
    source.scene = { ...source.scene, contents: Object.fromEntries(Object.entries(source.scene.contents).map(([id, diagram]) =>
      [id, remapJumps(diagram)])) };
    original.append(source, input.sourceView ?? original.head.view);
  }
  target.jumps = targetJumps;
  if (destinationRecord) {
    const placement = placeTransferredGroup(existing.scene, target.scene);
    const root = existing.scene.root;
    const parent = root.kind === 'container' && !root.collapsed ? root : {
      id: fresh('group'), kind: 'container' as const, position: { column: 0, row: 0 }, collapsed: false,
      layout: { collisionPolicy: 'push-right' as const, gap: 3 }, children: [root]
    };
    const placed = children.map(child => ({ ...child, position: {
      column: child.position.column + placement.column - parent.position.column,
      row: child.position.row + placement.row - parent.position.row
    } }));
    const existingContents = Object.fromEntries(Object.entries(existing.scene.contents).map(([id, diagram]) => [id,
      input.mode === 'move' ? remapJumps(diagram) : diagram]));
    target.scene = { contents: { ...existingContents, ...contents }, root: { ...parent, children: [...parent.children, ...placed] } };
    target.edges = [...existing.edges, ...target.edges];
    target.jumps = [...(existing.jumps ?? []).map(jump => input.mode === 'move' ? { ...jump, target: remapTarget(jump.target) } : jump), ...targetJumps];
    target.sections = { ...existing.sections, ...sections };
  }
  const transaction: CanvasTransfer = { id: fresh('transfer'), mode: input.mode, applied: true, destinationCreated: !destinationRecord,
    sourceId: input.sourceId, destinationId: input.destinationId, sourceBefore: record.headId, sourceAfter: original.head.id,
    destinationBefore: destination.head.id, destinationAfter: '' };
  destination.append(target, input.destinationView); transaction.destinationAfter = destination.head.id;
  destination.linkTransaction(transaction.id);
  if (input.mode === 'move') original.linkTransaction(transaction.id);
  return { transaction, source: state(original), destination: state(destination), selectedIds: [...boxIds.values()].map(id => `grid:${id}`) };
}

export function transferBoundary(record: Pick<CanvasHistoryRecord, 'headId'>, transaction: CanvasTransfer, canvasId: string, redo = false) {
  if (transaction.discarded || transaction.applied === redo) return false;
  const expected = canvasId === transaction.sourceId ? redo ? transaction.sourceBefore : transaction.sourceAfter
    : canvasId === transaction.destinationId ? redo ? transaction.destinationBefore : transaction.destinationAfter : undefined;
  return record.headId === expected;
}
export function prepareTransferNavigation(sourceRecord: CanvasHistoryRecord, destinationRecord: CanvasHistoryRecord, transaction: CanvasTransfer, redo = false) {
  if (!transferBoundary(sourceRecord, transaction, transaction.sourceId, redo) || !transferBoundary(destinationRecord, transaction, transaction.destinationId, redo))
    throw Error('Undo newer edits in both participating canvases before undoing or redoing this transfer.');
  const source = new CanvasHistory(documentFromHistory(sourceRecord), {}, sourceRecord), destination = new CanvasHistory(documentFromHistory(destinationRecord), {}, destinationRecord);
  if (transaction.mode === 'move' && !source.navigate(redo)) throw Error('Source transfer checkpoint is unavailable');
  if (!destination.navigate(redo)) throw Error('Destination transfer checkpoint is unavailable');
  return { source: state(source), destination: state(destination), transaction: { ...transaction, applied: redo } };
}

import { boxesOverlap, flattenGrid, resolveScene, type GridBounds, type GridPoint, type LineGridScene } from './lineGrid';

export function diagramCenterOfMass(bounds: readonly GridBounds[]): GridPoint {
  const mass = bounds.reduce((sum, box) => sum + box.columns * box.rows, 0);
  if (!mass) return { column: 0, row: 0 };
  return {
    column: bounds.reduce((sum, b) => sum + (b.column + b.columns / 2) * b.columns * b.rows, 0) / mass,
    row: bounds.reduce((sum, b) => sum + (b.row + b.rows / 2) * b.columns * b.rows, 0) / mass
  };
}

/** Translate one intact group. Existing siblings are immutable obstacles, including container bounds. */
export function placeTransferredGroup(destination: LineGridScene, incoming: LineGridScene): GridPoint {
  const root = resolveScene(destination), group = resolveScene(incoming);
  const incomingBoxes = flattenGrid(group).filter(node => node.box.kind === 'diagram').map(node => node.bounds);
  const destinationBoxes = flattenGrid(root).filter(node => node.box.kind === 'diagram' || node.box.collapsed).map(node => node.bounds);
  const parent = root.box.kind === 'container' && !root.box.collapsed ? root : undefined;
  const origin = parent ? { column: root.bounds.column, row: root.bounds.row } : { column: 0, row: 0 };
  if (!destinationBoxes.length && !root.children.length && parent) return origin;
  const obstacles = parent ? root.children.map(node => node.bounds) : [root.bounds];
  const center = diagramCenterOfMass(destinationBoxes.length ? destinationBoxes : obstacles);
  const incomingCenter = diagramCenterOfMass(incomingBoxes);
  const row = Math.max(origin.row, Math.round(center.row - incomingCenter.row));
  const ideal = center.column - incomingCenter.column;
  const gap = parent?.box.kind === 'container' ? parent.box.layout.gap : 3;
  // A nearest feasible integer is either nearest to the ideal, or on an obstacle boundary.
  const candidates = new Set([origin.column, Math.floor(ideal), Math.ceil(ideal), ...obstacles.flatMap(box =>
    [box.column - group.bounds.columns - gap, box.column + box.columns + gap])]);
  const fits = [...candidates].filter(column => column >= origin.column && column + group.bounds.columns <= 20000
    && row + group.bounds.rows <= 20000 && !obstacles.some(obstacle => boxesOverlap({ ...group.bounds, column, row }, obstacle, gap)));
  fits.sort((a, b) => Math.abs(a - ideal) - Math.abs(b - ideal) || b - a);
  if (!fits.length) throw Error('No free horizontal space within the supported canvas size');
  return { column: fits[0], row };
}

import type { DeepReadonly } from '../immutability';
import { validateDiagramJumps, type DiagramJump } from './diagramJump';
import { buildDiagramContent, type DiagramContent } from './diagramContent';
import { validateDiagramLocalMappings } from './diagramMappings';
import { mappingsForSelection } from './diagramSelection';
import { asciiSha256 } from './asciiSha256';
import type { DiagramElementMapping } from '../records/domain';
import type { CorpusBinding, BuiltInDomainProfileId } from '../profiles/domainProfile';
import type { ProjectRepresentationEvidenceRecord } from '../representations/projectCatalog';

export interface DiagramSourceBinding {
  sourceId: string;
  repositoryIdentity: string;
  corpus: CorpusBinding;
  domainProfileId: BuiltInDomainProfileId;
}
export type DiagramSourceContext = DeepReadonly<{
  binding?: DiagramSourceBinding;
  contentHash: string;
  mappings: readonly DiagramElementMapping[];
  evidence: Record<string, ProjectRepresentationEvidenceRecord>;
}>;
/** Repository-independent diagram, shared by canvas, persistence, and agents. */
export interface Diagram {
  /** Stable service identity; id remains the local canvas content key. */
  readonly diagramId: string;
  readonly revisionId: string;
  readonly id: string;
  readonly revision: number;
  readonly content: DeepReadonly<DiagramContent>;
  readonly sourceContext: DeepReadonly<DiagramSourceContext>;
  readonly jumps?: DeepReadonly<DiagramJump[]>;
}
export interface DiagramInput {
  id: string; revision: number; ascii: string; structureKind?: 'diagram' | 'tree';
  mappings?: readonly DiagramElementMapping[];
  evidence?: DiagramSourceContext['evidence'];
  source?: DiagramSourceBinding;
  jumps?: readonly DiagramJump[];
}
export function validateSourceBinding(binding: DiagramSourceBinding): void {
  if (!binding || typeof binding.sourceId !== 'string' || !binding.sourceId || binding.sourceId.length > 200
    || typeof binding.repositoryIdentity !== 'string' || !binding.repositoryIdentity
    || !['source-code','document'].includes(binding.domainProfileId) || !binding.corpus
    || !['git-worktree','filesystem-documents'].includes(binding.corpus.kind)
    || typeof binding.corpus.root !== 'string' || !/^(?:\/|[A-Za-z]:[\\/])/.test(binding.corpus.root)
    || (binding.domainProfileId === 'source-code') !== (binding.corpus.kind === 'git-worktree')) throw new Error('Invalid diagram source binding');
}
export function validateDiagram(diagram: Diagram): void {
  if (diagram?.content && (!diagram.diagramId || !diagram.revisionId))
    throw new Error('Diagram storage migration required: saved diagrams lack service identities. Run the offline diagram identity migration before loading this store.');
  if (!diagram || typeof diagram.diagramId !== 'string' || !diagram.diagramId.startsWith('diagram-') || typeof diagram.revisionId !== 'string' || !diagram.revisionId.startsWith('diagram-revision-') || typeof diagram.id !== 'string' || !diagram.id || !Number.isInteger(diagram.revision) || diagram.revision < 0 || !diagram.content) throw new Error('Invalid diagram');
  if (['ascii','mappings','diagramContent','structureKind'].some(key => Object.hasOwn(diagram,key))) throw new Error('Diagram data must live in content and sourceContext');
  const { content, sourceContext: source } = diagram;
  const canonical = buildDiagramContent(content.ascii, `${diagram.id}:${diagram.revision}`, content.structure.kind, content.structure.kind === 'tree' ? content.structure.parserVersion : undefined);
  if (JSON.stringify(content) !== JSON.stringify(canonical)) throw new Error('Invalid diagram content revision or parsed structure');
  if (!source || !source.evidence || !Array.isArray(source.mappings) || source.contentHash !== asciiSha256(content.ascii)) throw new Error('Diagram source context does not match content');
  if (source.binding) validateSourceBinding(source.binding);
  validateDiagramJumps(content, diagram.jumps);
  validateDiagramLocalMappings(content.ascii, source.mappings);
  for (const [id, entry] of Object.entries(source.evidence)) {
    if (entry?.sourceId && source.binding && entry.sourceId !== source.binding.sourceId) throw new Error('Evidence belongs to another diagram source');
    if (!entry || entry.id !== id || typeof entry.label !== 'string' || !Array.isArray(entry.sourceRanges)) throw new Error('Invalid diagram evidence');
    for (const range of entry.sourceRanges) {
      if (!range || typeof range.id !== 'string' || typeof range.path !== 'string' || range.path.startsWith('/') || range.path.split(/[\\/]/).includes('..')
        || !Number.isInteger(range.startLine) || range.startLine < 1 || !Number.isInteger(range.endLine) || range.endLine < range.startLine
        || !Array.isArray(range.originalLines) || range.originalLines.length !== range.endLine - range.startLine + 1 || range.originalLines.some((line: unknown) => typeof line !== 'string')) throw new Error('Invalid diagram evidence range');
    }
  }
  for (const mapping of source.mappings) {
    const range = source.evidence[mapping.entityId]?.sourceRanges[mapping.sourceRangeIndex];
    if (!range || mapping.sourceRangeId && mapping.sourceRangeId !== range.id) throw new Error('Mapping references unknown diagram evidence');
  }
}
/** All mapping/evidence joins live here; callers receive derived, read-only results. */
export function diagramSource(diagram: Diagram) {
  return queryDiagramSourceContext(diagram.sourceContext);
}
export function queryDiagramSourceContext(context: DiagramSourceContext) {
  const evidenceFor = (mapping: DiagramElementMapping) => {
    const entity = context.evidence[mapping.entityId];
    const range = entity?.sourceRanges[mapping.sourceRangeIndex];
    return { mapping, entity, range, binding: context.binding };
  };
  return {
    context,
    mappings: () => context.mappings,
    forSelection: (rect: Parameters<typeof mappingsForSelection>[1]) => mappingsForSelection(context.mappings, rect).map(evidenceFor),
    entries: () => context.mappings.map(evidenceFor),
    search: (query: string) => {
      const q = query.toLowerCase();
      return context.mappings.map(evidenceFor).filter(({mapping,entity,range}) => [mapping.entityId,entity?.label,range?.path,range?.symbol].some(value=>value?.toLowerCase().includes(q)));
    }
  };
}
export function sourceBindingFromLocation(location: { checkoutRoot: string; repositoryIdentity: string; domainProfileId?: BuiltInDomainProfileId; corpus?: CorpusBinding; gitRevision?: string }): DiagramSourceBinding {
  const corpus = location.corpus ?? { kind: 'git-worktree' as const, root: location.checkoutRoot, ...(location.gitRevision ? {revision:location.gitRevision} : {}) };
  return { sourceId: `source-${asciiSha256(`${corpus.kind}:${corpus.root}`).slice(0,24)}`, repositoryIdentity: location.repositoryIdentity,
    corpus, domainProfileId: location.domainProfileId ?? 'source-code' };
}

export const MIN_DIAGRAM_CANVAS_SCALE = 0.25;
export const MAX_DIAGRAM_CANVAS_SCALE = 4;

export interface CanvasPoint {
  x: number;
  y: number;
}

export interface CanvasTransform {
  offset: CanvasPoint;
  scale: number;
}

export interface CanvasPinchGeometry {
  center: CanvasPoint;
  distance: number;
}

export interface CanvasPinch {
  startDistance: number;
  startScale: number;
  contentPoint: CanvasPoint;
}

export function clampDiagramCanvasScale(scale: number): number {
  return Math.min(MAX_DIAGRAM_CANVAS_SCALE, Math.max(MIN_DIAGRAM_CANVAS_SCALE, scale));
}

export function scaleCanvasTransform(
  transform: CanvasTransform,
  requestedScale: number,
  anchor: CanvasPoint
): CanvasTransform {
  const scale = clampDiagramCanvasScale(requestedScale);
  const ratio = scale / transform.scale;
  return {
    offset: {
      x: anchor.x - ratio * (anchor.x - transform.offset.x),
      y: anchor.y - ratio * (anchor.y - transform.offset.y)
    },
    scale
  };
}

export function canvasPinchGeometry(
  first: CanvasPoint,
  second: CanvasPoint
): CanvasPinchGeometry | null {
  const dx = second.x - first.x;
  const dy = second.y - first.y;
  const distance = Math.hypot(dx, dy);
  if (distance < 1) return null;
  return {
    center: {
      x: (first.x + second.x) / 2,
      y: (first.y + second.y) / 2
    },
    distance
  };
}

export function beginCanvasPinch(
  transform: CanvasTransform,
  geometry: CanvasPinchGeometry
): CanvasPinch {
  return {
    startDistance: geometry.distance,
    startScale: transform.scale,
    contentPoint: {
      x: (geometry.center.x - transform.offset.x) / transform.scale,
      y: (geometry.center.y - transform.offset.y) / transform.scale
    }
  };
}

export function updateCanvasPinch(
  pinch: CanvasPinch,
  geometry: CanvasPinchGeometry
): CanvasTransform {
  const scale = clampDiagramCanvasScale(
    pinch.startScale * (geometry.distance / pinch.startDistance)
  );
  return {
    offset: {
      x: geometry.center.x - pinch.contentPoint.x * scale,
      y: geometry.center.y - pinch.contentPoint.y * scale
    },
    scale
  };
}

export function centeredCanvasTransform(
  viewport: { width: number; height: number },
  content: { width: number; height: number },
  inset = 32
): CanvasTransform {
  return {
    offset: {
      x: content.width + inset * 2 <= viewport.width
        ? (viewport.width - content.width) / 2
        : inset,
      y: content.height + inset * 2 <= viewport.height
        ? (viewport.height - content.height) / 2
        : inset
    },
    scale: 1
  };
}

export function recenterCanvasTransform(
  transform: CanvasTransform,
  previousViewport: { width: number; height: number },
  nextViewport: { width: number; height: number }
): CanvasTransform {
  const contentAtCenter = {
    x: (previousViewport.width / 2 - transform.offset.x) / transform.scale,
    y: (previousViewport.height / 2 - transform.offset.y) / transform.scale
  };
  return {
    offset: {
      x: nextViewport.width / 2 - contentAtCenter.x * transform.scale,
      y: nextViewport.height / 2 - contentAtCenter.y * transform.scale
    },
    scale: transform.scale
  };
}
/** A transient navigation request, never part of persisted diagram content. */
export interface DiagramFocus {
  id: string; serial: number; contentNodeId?: string;
  search?: {
    displayNodeId: string; revisionId: string; asciiSha256: string; line: number;
    matches: { startColumn: number; endColumn: number }[];
  };
}

/** Clipboard layout for Mapping rectangle selections. */
export function formatAsciiWithCodeReferences(
  asciiSelections: readonly string[],
  codeReferences: readonly string[]
): string {
  return [
    asciiSelections.join("\n\n"),
    "Associated Code Entities:",
    ...new Set(codeReferences)
  ].join("\n");
}

import { z } from 'zod';
import type { GridBox, LineGridScene } from './lineGrid';
import { diagramContentNodes as connectionContentNodes } from './diagramContentNodes';
export { diagramContentNodes as connectionContentNodes } from './diagramContentNodes';

const id = z.string().min(1).max(500).refine(value => !['__proto__', 'constructor', 'prototype'].includes(value));
const offset = z.number().min(0).max(1).optional();
const side = z.enum(['auto', 'left', 'right', 'top', 'bottom']).default('auto');
export const contentNodeAnchorSchema = z.object({
  kind: z.literal('content-node'), displayNodeId: id, contentNodeId: id, revisionId: id, side, offset
}).strict();
export const boxAnchorSchema = z.object({ kind: z.literal('box'), displayNodeId: id, side, offset }).strict();
export const anchorSchema = z.discriminatedUnion('kind', [contentNodeAnchorSchema, boxAnchorSchema]);
export const arrowLabelSchema = z.object({
  text: z.string().max(120),
  /** Absolute canvas pixels: horizontal center and text baseline, before pan/zoom. */
  position: z.object({ x: z.number().finite(), y: z.number().finite() }).strict().optional()
}).strict();
export const arrowAppearanceSchema = z.object({
  color: z.string().regex(/^#[0-9a-fA-F]{6}$/).default('#88c0d0'),
  lineStyle: z.enum(['solid', 'dashed']).default('solid'),
  label: z.union([z.string().max(120), arrowLabelSchema]).default('')
}).strict();
export const diagramConnectionSchema = z.object({
  id, source: contentNodeAnchorSchema, target: anchorSchema,
  appearance: arrowAppearanceSchema
}).strict();
export type ContentNodeAnchor = z.infer<typeof contentNodeAnchorSchema>;
export type GridBoxAnchor = z.infer<typeof boxAnchorSchema>;
export type DiagramAnchor = ContentNodeAnchor | GridBoxAnchor;
export type DiagramConnection = z.infer<typeof diagramConnectionSchema>;
export type ArrowAppearance = DiagramConnection['appearance'];
export type ArrowLabel = z.infer<typeof arrowLabelSchema>;
export const defaultArrowAppearance: ArrowAppearance = { color: '#88c0d0', lineStyle: 'solid', label: '' };

/** Legacy saved edges and callers may still supply a plain string. */
export function getArrowLabel(appearance: ArrowAppearance): ArrowLabel {
  return typeof appearance.label === 'string' ? { text: appearance.label } : appearance.label;
}

export function connectionBox(scene: LineGridScene, displayNodeId: string): GridBox | undefined {
  if (!displayNodeId.startsWith('grid:')) return undefined;
  const find = (box: GridBox): GridBox | undefined => box.id === displayNodeId.slice(5) ? box
    : box.kind === 'container' ? box.children.map(find).find(Boolean) : undefined;
  return find(scene.root);
}

export function validateConnectionAnchor(scene: LineGridScene, anchor: DiagramAnchor, allowStale = false) {
  const box = connectionBox(scene, anchor.displayNodeId);
  if (!box) throw new Error('Connection requires an existing GridBox');
  if (anchor.kind === 'box') return;
  if (box.kind !== 'diagram') throw new Error('Content anchor requires a diagram');
  const content = scene.contents[box.contentId].content;
  if (allowStale && content.revisionId !== anchor.revisionId) return;
  if (content.revisionId !== anchor.revisionId || !connectionContentNodes(content).some(node => node.id === anchor.contentNodeId)) {
    throw new Error('STALE_CONTENT_NODE: choose a current connection endpoint');
  }
}

export function validateConnections(scene: LineGridScene, input: unknown): DiagramConnection[] {
  const edges = z.array(diagramConnectionSchema).max(2000).parse(input ?? []);
  const seen = new Set<string>();
  for (const edge of edges) {
    if (seen.has(edge.id)) throw new Error('Duplicate connection ID');
    seen.add(edge.id);
    validateConnectionAnchor(scene, edge.source, true);
    validateConnectionAnchor(scene, edge.target, true);
  }
  return edges;
}

/** Deletions remove incident edges. Changed content retains stale, explicitly repairable anchors. */
export function reconcileConnections(before: LineGridScene, after: LineGridScene, edges: readonly DiagramConnection[]): DiagramConnection[] {
  const update = <T extends DiagramAnchor>(anchor: T): T => {
    if (anchor.kind !== 'content-node') return anchor;
    const oldBox = connectionBox(before, anchor.displayNodeId), newBox = connectionBox(after, anchor.displayNodeId);
    if (oldBox?.kind !== 'diagram' || newBox?.kind !== 'diagram') return anchor;
    const oldContent = before.contents[oldBox.contentId].content, content = after.contents[newBox.contentId].content;
    if (oldContent.revisionId === content.revisionId || oldContent.revisionId !== anchor.revisionId
      || oldContent.ascii !== content.ascii || oldContent.structure.kind !== content.structure.kind) return anchor;
    const oldNode = connectionContentNodes(oldContent).find(node => node.id === anchor.contentNodeId);
    const node = oldNode && connectionContentNodes(content).find(node => node.line === oldNode.line && node.startColumn === oldNode.startColumn);
    return node ? { ...anchor, revisionId: content.revisionId, contentNodeId: node.id } : anchor;
  };
  return edges.filter(edge => connectionBox(after, edge.source.displayNodeId) && connectionBox(after, edge.target.displayNodeId))
    .map(edge => ({ ...edge, source: update(edge.source), target: update(edge.target) }));
}

import type { DeepReadonly } from '../immutability';
import { asciiSha256 } from './asciiSha256';
import { parseAsciiTree } from './asciiTree';

export type DiagramContentNode = DeepReadonly<{
  id: string; label: string; line: number; branchColumn: number; startColumn: number; endColumn: number;
  parentId?: string; childIds: string[]; foldRanges: { startLine: number; endLine: number }[];
}>;
export type DiagramContent = DeepReadonly<{
  revisionId: string; ascii: string; asciiSha256: string;
  structure: { kind: 'diagram' } | { kind: 'tree'; parserVersion: 'ascii-tree-1' | 'ascii-tree-2'; rootIds: string[]; nodes: Record<string, DiagramContentNode> };
}>;
export function buildDiagramContent(ascii: string, revisionId: string, kind: 'diagram' | 'tree' = 'diagram', parserVersion: 'ascii-tree-1' | 'ascii-tree-2' = 'ascii-tree-2'): DiagramContent {
  if (!['ascii-tree-1', 'ascii-tree-2'].includes(parserVersion)) throw new Error('Unknown tree parser version');
  if (!ascii.trim() || ascii.length > 20000 || /[^\x20-\x7e\n]/.test(ascii)) throw new Error('Diagram must contain 1–20000 printable ASCII characters with LF newlines');
  const content: DiagramContent = { revisionId, ascii, asciiSha256: asciiSha256(ascii), structure: { kind: 'diagram' } };
  if (kind === 'diagram') return content;
  const parsed = parseAsciiTree(ascii, parserVersion);
  const ids = new Map(parsed.map(node => [node.line, `${revisionId}:${content.asciiSha256}:line-${node.line}`]));
  const nodes: Record<string, DiagramContentNode> = {};
  for (const node of parsed) {
    const id = ids.get(node.line)!;
    const peer = parsed.find(next => next.line > node.line && next.branchColumn <= node.branchColumn);
    nodes[id] = { id, label: node.text, line: node.line, branchColumn: node.branchColumn, startColumn: node.textColumn,
      endColumn: node.textColumn + Math.max(1, node.text.length) - 1,
      parentId: node.parentLine === undefined ? undefined : ids.get(node.parentLine),
      childIds: parsed.filter(child => child.parentLine === node.line).map(child => ids.get(child.line)!),
      foldRanges: node.descendantLines.length ? [{ startLine: node.line + 1, endLine: peer ? peer.line - 1 : ascii.split('\n').length }] : [] };
  }
  return { ...content, structure: { kind: 'tree', parserVersion, rootIds: Object.values(nodes).filter(node => !node.parentId).map(node => node.id), nodes } };
}
export function visibleContentLines(content: DiagramContent, collapsedIds: readonly string[]): number[] {
  const hidden = new Set<number>();
  if (content.structure.kind === 'tree') for (const id of collapsedIds) {
    const node = content.structure.nodes[id];
    if (!node) throw new Error('STALE_CONTENT_NODE');
    for (const range of node.foldRanges) for (let line = range.startLine; line <= range.endLine; line++) hidden.add(line);
  }
  return content.ascii.split('\n').map((_, i) => i + 1).filter(line => !hidden.has(line));
}

export function contentTreeNodes(content: DiagramContent): import('./asciiTree').AsciiTreeNode[] {
  if (content.structure.kind !== 'tree') return [];
  const nodes = content.structure.nodes;
  return Object.values(nodes).map(node => ({ line: node.line, branchColumn: node.branchColumn, textColumn: node.startColumn, text: node.label,
    parentLine: node.parentId ? nodes[node.parentId]?.line : undefined,
    descendantLines: Object.values(nodes).filter(child => node.foldRanges.some(range => child.line >= range.startLine && child.line <= range.endLine)).map(child => child.line) }));
}

import { deepFreeze } from '../immutability';
import type { DiagramContent, DiagramContentNode } from './diagramContent';
import { parseDiagram } from './interpreter';

// A derived index lets existing unstructured diagrams expose anchors without rewriting their content.
const indexes = new WeakMap<DiagramContent, readonly DiagramContentNode[]>();
export function diagramContentNodes(content: DiagramContent): readonly DiagramContentNode[] {
  if (content.structure.kind === 'tree') return Object.values(content.structure.nodes);
  const cached = indexes.get(content);
  if (cached) return cached;
  const parsed = parseDiagram(content.ascii, { dialect: 'mixed', repairs: 'none', continuation: 'separate' });
  const scoped = (id: string) => `${content.revisionId}:${content.asciiSha256}:${id}`;
  const nodes = parsed.nodes.filter(node => node.spans.length).map(node => ({
    id: scoped(node.id), label: node.label, line: node.spans[0].line,
    branchColumn: node.branchColumn ?? node.spans[0].column,
    startColumn: node.spans[0].column, endColumn: node.spans[0].endColumn - 1,
    parentId: node.parentId ? scoped(node.parentId) : undefined,
    childIds: node.childIds.map(scoped), foldRanges: []
  }));
  deepFreeze(nodes);
  indexes.set(content, nodes);
  return nodes;
}

import { z } from 'zod';
import type { DiagramContent } from './diagramContent';
import { diagramContentNodes } from './diagramContentNodes';

const id = z.string().min(1).max(500);
/** Destinations use catalog IDs or persisted workspace document IDs, never agent session IDs. */
export const diagramJumpSchema = z.object({
  id,
  source: z.object({
    revisionId: id, contentHash: z.string().regex(/^[a-f0-9]{64}$/),
    line: z.number().int().positive(), startColumn: z.number().int().positive(), endColumn: z.number().int().positive(),
    contentNodeId: id.optional()
  }).strict(),
  target: z.object({
    representationId: id, displayNodeId: id.optional(), contentNodeId: id.optional()
  }).strict().refine(target => !target.contentNodeId || !!target.displayNodeId, 'A target node needs its display instance')
}).strict();
export type DiagramJump = z.infer<typeof diagramJumpSchema>;
export type DiagramJumpTarget = DiagramJump['target'];

/** Stale links are retained as metadata, but never attached to unrelated replacement text. */
export function activeDiagramJumps(content: DiagramContent, jumps: readonly DiagramJump[] = []): DiagramJump[] {
  const lines = content.ascii.split('\n');
  return jumps.filter(({ source }) => source.revisionId === content.revisionId && source.contentHash === content.asciiSha256
    && source.startColumn <= source.endColumn && source.endColumn <= (lines[source.line - 1]?.length ?? 0));
}

export function validateDiagramJumps(content: DiagramContent, input: unknown, allowStale = true): DiagramJump[] {
  const jumps = z.array(diagramJumpSchema).max(2000).parse(input ?? []);
  const seen = new Set<string>();
  for (const jump of jumps) {
    if (seen.has(jump.id)) throw new Error('Duplicate diagram jump ID');
    seen.add(jump.id);
    if (jump.source.endColumn < jump.source.startColumn) throw new Error('Invalid jump source range');
    const current = jump.source.revisionId === content.revisionId && jump.source.contentHash === content.asciiSha256;
    if (!current && allowStale) continue;
    if (!activeDiagramJumps(content, [jump]).length) throw new Error('STALE_JUMP_SOURCE');
    if (jump.source.contentNodeId) {
      const matches = diagramContentNodes(content).filter(node => node.line === jump.source.line
        && node.startColumn <= jump.source.startColumn && node.endColumn >= jump.source.endColumn);
      if (matches.length !== 1 || matches[0].id !== jump.source.contentNodeId) throw new Error('STALE_CONTENT_NODE');
    }
  }
  const active = activeDiagramJumps(content, jumps);
  for (let i = 0; i < active.length; i++) for (let j = i + 1; j < active.length; j++) {
    const a = active[i].source, b = active[j].source;
    if (a.line === b.line && a.startColumn <= b.endColumn && b.startColumn <= a.endColumn) throw new Error('Overlapping diagram jumps');
  }
  return jumps;
}

/** Identical text may acquire a new revision on replacement or individual-diagram export. */
export function rebaseDiagramJumps(before: DiagramContent, after: DiagramContent, jumps: readonly DiagramJump[] = []): DiagramJump[] {
  if (before.ascii !== after.ascii) return structuredClone([...jumps]);
  return jumps.map(jump => {
    if (!activeDiagramJumps(before, [jump]).length) return structuredClone(jump);
    const node = diagramContentNodes(after).filter(node => node.line === jump.source.line
      && node.startColumn <= jump.source.startColumn && node.endColumn >= jump.source.endColumn);
    const { contentNodeId: _old, ...source } = jump.source;
    return { ...jump, source: { ...source, revisionId: after.revisionId, contentHash: after.asciiSha256,
      ...(node.length === 1 ? { contentNodeId: node[0].id } : {}) } };
  });
}

import type { DiagramElementMapping } from "../records/domain";
export function validateDiagramLocalMappings(ascii: string, mappings: readonly DiagramElementMapping[]): void {
  if (mappings.length > 2000) throw new Error("Too many source mappings");
  const lines = ascii.split("\n");
  const ids = new Set<string>();
  for (const mapping of mappings) {
    if (!mapping || typeof mapping.id !== "string" || !mapping.id || ids.has(mapping.id)
      || typeof mapping.entityId !== "string"
      || !Number.isInteger(mapping.sourceRangeIndex) || mapping.sourceRangeIndex < 0
      || !Number.isInteger(mapping.line) || mapping.line < 1
      || !Number.isInteger(mapping.startColumn) || mapping.startColumn < 1
      || !Number.isInteger(mapping.endColumn) || mapping.endColumn < mapping.startColumn
      || !lines[mapping.line - 1] || mapping.endColumn > lines[mapping.line - 1].length
      || !lines[mapping.line - 1].slice(mapping.startColumn - 1, mapping.endColumn).trim()) {
      throw new Error("Invalid diagram-local source mapping");
    }
    ids.add(mapping.id);
  }
}

import { diagramRevisions as revisionRegistry } from './internal/revisionRegistry';
import { validateDiagram, type Diagram } from './diagram';
import { currentHistoryChanges, validateCanvasHistory, type CanvasHistoryRecord, type HistoryValidation } from './canvasHistory';
import type { DiagramRevision } from './diagramRevisionEditor';

export type DiagramRecordKind = 'diagram' | 'revision' | 'history';
/** Immutable, content-addressed records; the implementation supplies durable atomic writes. */
export interface DiagramRecordStore {
  put(kind: DiagramRecordKind, data: unknown): Promise<string>;
  get(kind: DiagramRecordKind, id: string): Promise<unknown>;
}
interface Reference { $diagramRecord: DiagramRecordKind; id: string }
interface StoredHistory {
  revisions: Record<string, Reference>;
  bindings: Record<string, Record<string, string>>;
}
const object = (value: unknown): value is Record<string, any> => !!value && typeof value === 'object' && !Array.isArray(value);
const isHistory = (value: Record<string, any>) => value.schemaVersion === 1 && typeof value.contextId === 'string'
  && value.snapshots && value.diagramRevisions && typeof value.headId === 'string';
// Captured evidence contains source text, never nested diagram records.
const isEvidence = (value: Record<string, any>) => typeof value.id === 'string' && typeof value.label === 'string'
  && typeof value.category === 'string' && Array.isArray(value.sourceRanges);
const isDiagram = (value: Record<string, any>) => typeof value.id === 'string' && Number.isInteger(value.revision)
  && value.content && typeof value.content.ascii === 'string' && value.sourceContext;

/** Avoid allocating a promise/object for every captured source line or unrelated UI field. */
function recordDetector(restoring: boolean) {
  const cache = new WeakMap<object, boolean>();
  const contains = (value: unknown): boolean => {
    if (!value || typeof value !== 'object') return false;
    if (cache.has(value)) return cache.get(value)!;
    if (object(value) && (restoring ? !!value.$diagramRecord || !!value.diagramHistory || isHistory(value) || isDiagram(value) : isHistory(value) || isDiagram(value))) return true;
    const result = Object.values(value).some(contains);
    cache.set(value, result);
    return result;
  };
  return contains;
}

/** Storage adapter only. Public transports/exports remain portable expanded documents. */
export async function persistDiagramData(value: unknown, store: DiagramRecordStore): Promise<unknown> {
  const contains = recordDetector(false);
  const reference = async (kind: DiagramRecordKind, data: unknown): Promise<Reference> => ({ $diagramRecord: kind, id: await store.put(kind, data) });
  const visit = async (value: unknown): Promise<unknown> => {
    if (!contains(value)) return value;
    if (Array.isArray(value)) return Promise.all(value.map(item => item && typeof item === 'object' ? visit(item) : item));
    if (!object(value) || isEvidence(value)) return value;
    if (isHistory(value)) {
      const history = value as CanvasHistoryRecord;
      validateCanvasHistory(history);
      const revisions = Object.fromEntries(await Promise.all(Object.entries(history.diagramRevisions).map(async ([id, revision]) =>
        [id, await reference('revision', { ...revision, diagram: await visit(revision.diagram) })])));
      const bindings = Object.fromEntries(Object.entries(history.snapshots).map(([id, snapshot]) => [id, snapshot.diagramBindings]));
      const { diagramRevisions: _, snapshots, ...rest } = history;
      return { ...rest, diagramHistory: await reference('history', { revisions, bindings }),
        snapshots: await visit(Object.fromEntries(Object.entries(snapshots).map(([id, snapshot]) => {
          const { diagramBindings: _, ...canvas } = snapshot;
          return [id, { ...canvas, diagramCheckpointId: id }];
        }))) };
    }
    if (isDiagram(value)) { validateDiagram(value as Diagram); return reference('diagram', value); }
    return Object.fromEntries(await Promise.all(Object.entries(value).map(async ([key, item]) => [key, !item || typeof item !== 'object' ? item : await visit(item)])));
  };
  return visit(value);
}

/** Restore current portable documents or their content-addressed storage representation. */
export async function restoreDiagramData(value: unknown, store: DiagramRecordStore, historyValidation: HistoryValidation = 'all'): Promise<unknown> {
  const contains = recordDetector(true);
  const hydrated = new Map<string, Promise<unknown>>();
  const records = new Map<string, Promise<unknown>>();
  const read = (ref: Reference) => {
    if (!['diagram', 'revision', 'history'].includes(ref.$diagramRecord) || !/^[a-f0-9]{64}$/.test(ref.id)) throw new Error('Invalid diagram record reference');
    const key = `${ref.$diagramRecord}:${ref.id}`;
    if (!records.has(key)) records.set(key, store.get(ref.$diagramRecord, ref.id));
    return records.get(key)!;
  };
  const visit = async (value: unknown, deferred = false): Promise<unknown> => {
    if (!contains(value)) return value;
    if (Array.isArray(value)) return Promise.all(value.map(item => item && typeof item === 'object' ? visit(item, deferred) : item));
    if (!object(value) || isEvidence(value)) return value;
    if (typeof value.$diagramRecord === 'string' && typeof value.id === 'string' && Object.keys(value).length === 2) {
      const ref = value as Reference;
      const key = `${ref.$diagramRecord}:${ref.id}`;
      if (!hydrated.has(key)) hydrated.set(key, (async () => {
        const restored = await visit(await read(ref), deferred);
        return restored;
      })());
      const restored = await hydrated.get(key);
      if (ref.$diagramRecord === 'diagram' && !deferred) validateDiagram(restored as Diagram);
      return structuredClone(restored);
    }
    if (typeof value.contextId === 'string' && value.snapshots && value.diagramHistory?.$diagramRecord === 'history') {
      const stored = await read(value.diagramHistory) as StoredHistory;
      const { diagramHistory: _, snapshots, ...rest } = value;
      const diagramRevisions = await visit(stored.revisions, historyValidation === 'current') as Record<string, DiagramRevision>;
      const restoredSnapshots = Object.fromEntries(await Promise.all(Object.entries(snapshots).map(async ([id, raw]) => {
        const { diagramCheckpointId, ...canvas } = raw as Record<string, unknown>;
        if (diagramCheckpointId !== id || !Object.hasOwn(stored.bindings, id)) throw new Error('Unknown diagram checkpoint');
        return [id, { ...await visit(canvas) as object, diagramBindings: stored.bindings[id] }];
      })));
      const history = { ...rest, snapshots: restoredSnapshots, diagramRevisions } as CanvasHistoryRecord;
      validateCanvasHistory(history, historyValidation === 'current' ? currentHistoryChanges(history) : undefined);
      for (const revision of Object.values(history.diagramRevisions)) {
        if (historyValidation === 'current') revisionRegistry.restore(revision); else revisionRegistry.register(revision);
      }
      return history;
    }
    if (isHistory(value)) {
      const history = value as CanvasHistoryRecord;
      validateCanvasHistory(history, historyValidation === 'current' ? currentHistoryChanges(history) : undefined);
      for (const revision of Object.values(history.diagramRevisions)) {
        if (historyValidation === 'current') revisionRegistry.restore(revision); else revisionRegistry.register(revision);
      }
      return structuredClone(history);
    }
    if (isDiagram(value)) { if (!deferred) validateDiagram(value as Diagram); return structuredClone(value); }
    return Object.fromEntries(await Promise.all(Object.entries(value).map(async ([key, item]) => [key, !item || typeof item !== 'object' ? item : await visit(item, deferred)])));
  };
  return visit(value);
}

export class DiagramPersistence {
  constructor(private readonly store: DiagramRecordStore) {}
  persist(value: unknown) { return persistDiagramData(value, this.store); }
  async restore<T>(value: unknown, historyValidation: HistoryValidation = 'all'): Promise<T> { return restoreDiagramData(value, this.store, historyValidation) as Promise<T>; }
}

import { validateCompactionProjection } from "../representations/compactionProjection";
import type { ProjectRepresentationCatalogRecord, ProjectRepresentationRevisionRecord } from "../representations/projectCatalog";
import { buildTreeRepresentationIndex, type TreeRepresentationIndex } from "../representations/representationIndex";

export interface ProjectProjectionRecord {
  id: string;
  projectId: string;
  name: string;
  sourceRepresentationId: string;
  sourceRevisionId: string;
  targetRepresentationId: string;
  targetRevisionId: string;
  match: "any";
  links: { sourceEvidenceIds: string[]; targetNodeIds: string[] }[];
  /** Immutable file-tree snapshots and exact row links from this call-tree revision. */
  compactionProjection?: import("../representations/compactionProjection").CompactionProjection;
}

export interface ProjectionSelectionResult {
  ascii: string;
  matchedSourceEvidenceIds: string[];
  unmatchedSourceEvidenceIds: string[];
  targetNodeIds: string[];
  visibleNodeIds: string[];
  /** Matched subtrees only, excluding ancestors added solely for display. */
  projectedNodeIds: string[];
  /** Array index is the zero-based rendered row; sourceLine is one-based in the target revision. */
  rows: { nodeId: string; sourceLine: number }[];
}

function record(value: unknown, label: string): asserts value is Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} must be an object`);
  }
}

function id(value: unknown, label: string): asserts value is string {
  if (typeof value !== "string" || !value.trim() || value !== value.trim()) {
    throw new Error(`${label} must be a nonempty string without surrounding whitespace`);
  }
  if (value === "__proto__" || value === "constructor" || value === "prototype") {
    throw new Error(`${label} contains a reserved identifier`);
  }
}

function ids(value: unknown, label: string, nonempty = true): asserts value is string[] {
  if (!Array.isArray(value) || (nonempty && value.length === 0)) {
    throw new Error(`${label} must be ${nonempty ? "a nonempty" : "an"} array`);
  }
  for (const entry of value) id(entry, `${label} entry`);
}

function validateShape(projection: ProjectProjectionRecord): void {
  record(projection, "projection");
  for (const key of ["id", "projectId", "sourceRepresentationId", "sourceRevisionId",
    "targetRepresentationId", "targetRevisionId"] as const) id(projection[key], key);
  if (typeof projection.name !== "string" || !projection.name.trim()) {
    throw new Error("projection name must be a nonempty string");
  }
  if (projection.match !== "any") throw new Error("projection match must be any");
  if (!Array.isArray(projection.links) || projection.links.length === 0) {
    throw new Error("projection links must be a nonempty array");
  }
  for (const link of projection.links) {
    record(link, "projection link");
    ids(link.sourceEvidenceIds, "sourceEvidenceIds");
    ids(link.targetNodeIds, "targetNodeIds");
  }
}

/**
 * Structural identity is scoped to the immutable Project revision, never row coordinates.
 * Conventional trees support a plain root with |, +--, \\--, and `-- connectors;
 * legacy arrow branches remain supported. Other semantic lines are standalone
 * roots, not implicit continuation children (matching the shared index grammar).
 */
export function buildProjectionTree(revision: ProjectRepresentationRevisionRecord): TreeRepresentationIndex {
  record(revision, "target revision");
  if (revision.representationKind !== "tree") throw new Error("projection target must be a tree");
  id(revision.id, "target revision id");
  id(revision.asciiSha256, "target ASCII hash");
  if (typeof revision.ascii !== "string") throw new Error("target ASCII must be a string");
  return buildTreeRepresentationIndex({
    revision: { artifactId: revision.id, asciiSha256: revision.asciiSha256 },
    ascii: revision.ascii,
    codeEntityMap: {

      artifactId: revision.id,
      asciiSha256: revision.asciiSha256,

      mappings: revision.mappings.map((mapping) => ({
        id: mapping.id,
        entityId: mapping.evidenceId,
        sourceRangeId: mapping.sourceRangeId,
        sourceRangeIndex: revision.evidence[mapping.evidenceId]?.sourceRanges
          .findIndex((range) => range.id === mapping.sourceRangeId) ?? -1,
        line: mapping.line,
        startColumn: mapping.startColumn,
        endColumn: mapping.endColumn
      }))
    }
  });
}

/** Reject cross-project, stale/foreign-revision, and unresolved mappings before persistence/use. */
export function validateProjection(
  projection: ProjectProjectionRecord,
  catalog: ProjectRepresentationCatalogRecord
): void {
  validateShape(projection);
  record(catalog, "representation catalog");
  if (catalog.projectId !== projection.projectId) throw new Error("projection must belong to the same project");
  record(catalog.representations, "catalog representations");
  record(catalog.revisions, "catalog revisions");
  for (const side of ["source", "target"] as const) {
    const representationId = projection[`${side}RepresentationId`];
    const revisionId = projection[`${side}RevisionId`];
    const representation = Object.hasOwn(catalog.representations, representationId)
      ? catalog.representations[representationId] : undefined;
    const revision = Object.hasOwn(catalog.revisions, revisionId) ? catalog.revisions[revisionId] : undefined;
    record(representation, `${side} representation`);
    record(revision, `${side} revision`);
    if (representation.id !== representationId || revision.id !== revisionId
      || representation.projectId !== projection.projectId || revision.projectId !== projection.projectId) {
      throw new Error(`${side} representation and revision must belong to the same project`);
    }
    if (revision.representationId !== representationId || !Array.isArray(representation.revisionIds)
      || !representation.revisionIds.includes(revisionId)) {
      throw new Error(`${side} revision is not owned by its representation`);
    }
    if (side === "target" && representation.representationKind !== "tree") {
      throw new Error("projection target representation must be a tree");
    }
  }
  const source = catalog.revisions[projection.sourceRevisionId];
  record(source.evidence, "source evidence");
  const target = buildProjectionTree(catalog.revisions[projection.targetRevisionId]);
  if (projection.compactionProjection) validateCompactionProjection(projection.compactionProjection, new Set(Object.keys(target.nodes)));
  for (const link of projection.links) {
    for (const evidenceId of link.sourceEvidenceIds) {
      if (!Object.hasOwn(source.evidence, evidenceId) || source.evidence[evidenceId]?.id !== evidenceId) {
        throw new Error(`unknown source evidence: ${evidenceId}`);
      }
    }
    for (const nodeId of link.targetNodeIds) {
      if (!Object.hasOwn(target.nodes, nodeId)) throw new Error(`unknown target node: ${nodeId}`);
    }
  }
}

/**
 * OR-match links, then include matched subtrees and their required ancestor paths.
 * Evidence lists retain selection order; node lists retain original target pre-order.
 * Every rendered row carries its original one-based source line; connectors are regenerated.
 */
export function projectSelection(
  projection: ProjectProjectionRecord,
  targetRevision: ProjectRepresentationRevisionRecord,
  selectedEvidenceIds: readonly string[]
): ProjectionSelectionResult {
  validateShape(projection);
  ids(selectedEvidenceIds, "selectedEvidenceIds", false);
  record(targetRevision, "target revision");
  if (targetRevision.id !== projection.targetRevisionId
    || targetRevision.representationId !== projection.targetRepresentationId
    || targetRevision.projectId !== projection.projectId) {
    throw new Error("projection target revision does not match its pinned revision");
  }
  const tree = buildProjectionTree(targetRevision);
  const selected = [...new Set(selectedEvidenceIds)];
  const selectedSet = new Set(selected);
  const matched = new Set<string>();
  const targets = new Set<string>();
  for (const link of projection.links) {
    for (const nodeId of link.targetNodeIds) {
      if (!Object.hasOwn(tree.nodes, nodeId)) throw new Error(`unknown target node: ${nodeId}`);
    }
    const matches = link.sourceEvidenceIds.filter((evidenceId) => selectedSet.has(evidenceId));
    if (!matches.length) continue;
    matches.forEach((evidenceId) => matched.add(evidenceId));
    link.targetNodeIds.forEach((nodeId) => targets.add(nodeId));
  }
  const visible = new Set<string>();
  const pending = [...targets];
  while (pending.length) {
    const nodeId = pending.pop()!;
    if (visible.has(nodeId)) continue;
    visible.add(nodeId);
    pending.push(...tree.nodes[nodeId].childIds);
  }
  const projected = new Set(visible);
  for (const nodeId of targets) {
    let parentId = tree.nodes[nodeId].parentId;
    while (parentId) {
      visible.add(parentId);
      parentId = tree.nodes[parentId].parentId;
    }
  }
  const lines: string[] = [];
  const rows: ProjectionSelectionResult["rows"] = [];
  const render = (nodeId: string, prefix: string, connector: string, childPrefix: string): void => {
    const node = tree.nodes[nodeId];
    lines.push(prefix + connector + node.text);
    rows.push({ nodeId, sourceLine: node.line });
    const children = node.childIds.filter((childId) => visible.has(childId));
    children.forEach((childId, index) => {
      const last = index === children.length - 1;
      render(childId, childPrefix, last ? "\\-- " : "+-- ", childPrefix + (last ? "    " : "|   "));
    });
  };
  tree.rootIds.filter((nodeId) => visible.has(nodeId)).forEach((nodeId) => render(nodeId, "", "", ""));
  const ordered = Object.values(tree.nodes).sort((left, right) => left.order - right.order);
  return {
    ascii: lines.join("\n"),
    matchedSourceEvidenceIds: selected.filter((evidenceId) => matched.has(evidenceId)),
    unmatchedSourceEvidenceIds: selected.filter((evidenceId) => !matched.has(evidenceId)),
    targetNodeIds: ordered.filter((node) => targets.has(node.id)).map((node) => node.id),
    visibleNodeIds: ordered.filter((node) => visible.has(node.id)).map((node) => node.id),
    projectedNodeIds: ordered.filter((node) => projected.has(node.id)).map((node) => node.id),
    rows
  };
}

import { validateDiagram, type Diagram, type DiagramInput } from './diagram';
import { constructDiagram } from './internal/constructDiagram';
import { patchDiagram } from './patchDiagram';
import { diagramContentNodes } from './diagramContentNodes';
import { activeDiagramJumps, rebaseDiagramJumps, validateDiagramJumps, type DiagramJump } from './diagramJump';

export type ContextId = string;
export type DiagramRevisionId = string;
export interface DiagramRevision {
  readonly id: DiagramRevisionId;
  readonly diagramId: string;
  readonly parentId?: DiagramRevisionId;
  /** Immutable diagram payload. Never returned by resolve(). */
  readonly diagram: Diagram;
  readonly nodeRefs: Readonly<Record<string, string>>;
}
export interface DiagramView {
  id: string;
  ascii: string;
  asciiSha256: string;
  structureKind: 'diagram' | 'tree';
  nodes: ReturnType<typeof diagramContentNodes>;
  sourceContext: Diagram['sourceContext'];
  jumps: { id: string; source: Omit<DiagramJump['source'], 'revisionId' | 'contentHash'>; target: DiagramJump['target'] }[];
}
export interface PreparedDiagramEdit {
  readonly diagram: Diagram;
  readonly nodeIds: ReadonlyMap<string, string>;
  lineAfter?: (line: number) => number | undefined;
}
export type DiagramEdit =
  | { kind: 'source-mappings'; expectedContentHash: string; mappings: NonNullable<DiagramInput['mappings']>; evidence: NonNullable<DiagramInput['evidence']>; source?: DiagramInput['source'] }
  | { kind: 'patch'; start: number; end: number; patch: string; mappings?: DiagramInput['mappings'] }
  | { kind: 'replace'; input: Omit<DiagramInput, 'id' | 'revision'> }
  | { kind: 'jumps'; jumps: DiagramJump[] };

/** Canonical content ownership; context bindings are supplied by canvas history. */
export interface DiagramRevisionOperations {
  resolve(contextId: ContextId, diagramId: string): DiagramView;
  prepareCreate(input: DiagramInput): PreparedDiagramEdit;
  prepareEdit(contextId: ContextId, diagramId: string, edit: DiagramEdit): PreparedDiagramEdit;
  merge(baseline: Readonly<Record<string, DiagramRevisionId>>, current: Readonly<Record<string, DiagramRevisionId>>,
    proposed: Readonly<Record<string, DiagramRevisionId>>): Record<string, DiagramRevisionId>;
}

export class DiagramRevisionEditor implements DiagramRevisionOperations {
  constructor(private readonly revisions: Record<string, DiagramRevision>,
    private readonly bindings: (contextId: ContextId) => Readonly<Record<string, DiagramRevisionId>>) {}

  private revision(contextId: ContextId, diagramId: string): DiagramRevision {
    const id = this.bindings(contextId)[diagramId], revision = id && this.revisions[id];
    if (!revision || revision.diagram.id !== diagramId) throw new Error(`Unknown diagram: ${diagramId}`);
    return revision;
  }
  resolve(contextId: ContextId, diagramId: string): DiagramView {
    const { diagram, nodeRefs } = this.revision(contextId, diagramId);
    const nodes = diagramContentNodes(diagram.content).map(node => ({ ...node, id: nodeRefs[node.id],
      parentId: node.parentId ? nodeRefs[node.parentId] : undefined, childIds: node.childIds.map(id => nodeRefs[id]) }));
    return structuredClone({ id: diagramId, ascii: diagram.content.ascii, asciiSha256: diagram.content.asciiSha256,
      structureKind: diagram.content.structure.kind, nodes, sourceContext: diagram.sourceContext,
      jumps: activeDiagramJumps(diagram.content, diagram.jumps).map(jump => {
        const { revisionId: _, contentHash: __, ...source } = jump.source;
        return { id: jump.id, source: { ...source, contentNodeId: source.contentNodeId ? nodeRefs[source.contentNodeId] : undefined }, target: jump.target };
      }) });
  }
  prepareCreate(input: DiagramInput): PreparedDiagramEdit {
    return { diagram: constructDiagram(input), nodeIds: new Map() };
  }
  prepareEdit(contextId: ContextId, diagramId: string, edit: DiagramEdit): PreparedDiagramEdit {
    const before = this.revision(contextId, diagramId).diagram;
    if (edit.kind === 'source-mappings') {
      if (edit.expectedContentHash !== before.content.asciiSha256) throw new Error('CONTENT_HASH_CONFLICT: read the diagram again');
      const diagram = { ...before, sourceContext: { ...before.sourceContext, mappings: structuredClone(edit.mappings), evidence: structuredClone(edit.evidence),
        ...(edit.source ? { binding: structuredClone(edit.source) } : {}) } };
      validateDiagram(diagram);
      return { diagram, nodeIds: correspondingNodes(before, diagram) };
    }
    if (edit.kind === 'patch') {
      const prepared = patchDiagram(before, edit.start, edit.end, edit.patch);
      if (edit.mappings) {
        const sourceContext = constructDiagram({ id: diagramId, revision: prepared.diagram.revision,
          ascii: prepared.diagram.content.ascii, structureKind: prepared.diagram.content.structure.kind,
          source: before.sourceContext.binding, evidence: before.sourceContext.evidence, mappings: edit.mappings }).sourceContext;
        return { ...prepared, diagram: { ...prepared.diagram, sourceContext } };
      }
      return prepared;
    }
    const diagram = edit.kind === 'jumps'
      ? { ...structuredClone(before), jumps: validateDiagramJumps(before.content, edit.jumps, false) }
      : constructDiagram({ ...edit.input, id: diagramId, revision: before.revision + 1 });
    const next = edit.kind === 'replace' && before.jumps ? { ...diagram, jumps: rebaseDiagramJumps(before.content, diagram.content, before.jumps) } : diagram;
    validateDiagram(next);
    return { diagram: next, nodeIds: correspondingNodes(before, next) };
  }
  /** Deliberately conservative until three-way merge is implemented. */
  merge(baseline: Readonly<Record<string, string>>, current: Readonly<Record<string, string>>, proposed: Readonly<Record<string, string>>) {
    for (const id of new Set([...Object.keys(baseline), ...Object.keys(current)])) {
      if (baseline[id] !== current[id]) throw new Error(`MERGE_REQUIRED: diagram ${id} advanced; automatic merge is not implemented`);
    }
    return { ...proposed };
  }
}

/** Exact identity only. Heuristic preview matches must never establish anchors. */
export function correspondingNodes(before: Diagram, after: Diagram): Map<string, string> {
  const result = new Map<string, string>();
  if (before.content.ascii !== after.content.ascii || before.content.structure.kind !== after.content.structure.kind) return result;
  const next = diagramContentNodes(after.content);
  for (const node of diagramContentNodes(before.content)) {
    const matches = next.filter(n => n.line === node.line && n.startColumn === node.startColumn && n.endColumn === node.endColumn && n.label === node.label);
    if (matches.length === 1) result.set(node.id, matches[0].id);
  }
  return result;
}

import { validateDiagram } from './diagram';
import { diagramContentNodes } from './diagramContentNodes';
import { correspondingNodes, type DiagramRevision } from './diagramRevisionEditor';
import { diagramRevisions } from './internal/revisionRegistry';

/** Internal transport boundary for a service-issued child revision, not a content-edit API. */
export function receiveDiagramRevision(baseRevisionId: string, revision: DiagramRevision) {
  const base = diagramRevisions.get(baseRevisionId);
  validateDiagram(revision.diagram);
  if (revision.id === base.id || revision.id !== revision.diagram.revisionId || revision.parentId !== base.id
    || revision.diagramId !== base.diagramId || revision.diagram.diagramId !== base.diagramId
    || revision.diagram.id !== base.diagram.id || revision.diagram.revision !== base.diagram.revision + 1)
    throw Error('Invalid generated diagram revision ancestry');
  const nodes = diagramContentNodes(revision.diagram.content);
  const refs = nodes.map(node => revision.nodeRefs?.[node.id]);
  if (!revision.nodeRefs || Object.keys(revision.nodeRefs).length !== nodes.length
    || refs.some(ref => typeof ref !== 'string' || !ref) || new Set(refs).size !== refs.length)
    throw Error('Invalid generated logical node identities');
  const nodeIds = correspondingNodes(base.diagram, revision.diagram);
  for (const [old, next] of nodeIds) if (base.nodeRefs[old] !== revision.nodeRefs[next])
    throw Error('Generated revision changed an unchanged logical node identity');
  return { diagram: diagramRevisions.register(revision).diagram, nodeIds };
}

import type { DiagramElementMapping, DiagramSelectionBounds } from "../records/domain";

export interface DiagramGridPoint {
  line: number;
  column: number;
}

export function normalizeDiagramSelection(
  anchor: DiagramGridPoint,
  focus: DiagramGridPoint
): DiagramSelectionBounds {
  return {
    startLine: Math.min(anchor.line, focus.line),
    endLine: Math.max(anchor.line, focus.line),
    startColumn: Math.min(anchor.column, focus.column),
    endColumn: Math.max(anchor.column, focus.column)
  };
}

export function mappingIntersectsSelection(
  mapping: DiagramElementMapping,
  selection: DiagramSelectionBounds
): boolean {
  return selection.startLine <= mapping.line
    && selection.endLine >= mapping.line
    && selection.startColumn <= mapping.endColumn
    && selection.endColumn >= mapping.startColumn;
}

export function mappingsForSelection(
  mappings: readonly DiagramElementMapping[],
  selection: DiagramSelectionBounds
): DiagramElementMapping[] {
  return mappings
    .filter((mapping) => mappingIntersectsSelection(mapping, selection))
    .sort((left, right) => (
      left.line - right.line
      || left.startColumn - right.startColumn
      || left.endColumn - right.endColumn
      || left.id.localeCompare(right.id)
    ));
}

/** Extracts the exact rectangular ASCII region, rebased to its left edge. */
export function asciiForSelection(
  ascii: string,
  selection: DiagramSelectionBounds
): string {
  const width = selection.endColumn - selection.startColumn + 1;
  return ascii
    .split("\n")
    .slice(selection.startLine - 1, selection.endLine)
    .map((line) => line.replace(/\r$/, "")
      .padEnd(selection.endColumn, " ")
      .slice(selection.startColumn - 1, selection.startColumn - 1 + width))
    .join("\n");
}

export function selectionContainsPoint(
  selection: DiagramSelectionBounds | null,
  line: number,
  column: number
): boolean {
  return Boolean(selection
    && line >= selection.startLine
    && line <= selection.endLine
    && column >= selection.startColumn
    && column <= selection.endColumn);
}

