  };
}
export interface GenerationOptions { signal?: AbortSignal; onProgress?: (message: string) => void }
export interface DiagramGenerator {
  generate(request: DiagramGenerationRequest, options: GenerationOptions): Promise<Omit<DiagramInput, 'id' | 'revision'>>;
}

/** Sole content writer. Local revisions are synchronous; durable adapters flush issued records before publishing canvases. */
export interface DiagramService {
  create(input: DiagramInput): DiagramRevisionResult;
  getRevision(revisionId: string): DiagramRevision;
  listRevisions(diagramId: string): readonly DiagramRevisionSummary[];
  revise(baseRevisionId: string, edit: DiagramEdit): DiagramRevisionResult;
  generate(request: DiagramGenerationRequest, options?: GenerationOptions): Promise<DiagramRevisionResult>;
}

export class RevisionedDiagramService implements DiagramService {
  constructor(private readonly generator?: DiagramGenerator) {}
  create(input: DiagramInput): DiagramRevisionResult {
    const prepared = new DiagramRevisionEditor({}, () => ({})).prepareCreate(input);
    return this.issue(prepared);
  }
  getRevision(revisionId: string) { return diagramRevisions.get(revisionId); }
  listRevisions(diagramId: string): readonly DiagramRevisionSummary[] {
    return Object.freeze(diagramRevisions.list(diagramId).map(({id, diagramId, parentId}) => Object.freeze({id, diagramId, parentId})));
  }
  revise(baseRevisionId: string, edit: DiagramEdit): DiagramRevisionResult {
    const base = this.getRevision(baseRevisionId);
    const prepared = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }))
      .prepareEdit('edit', base.diagram.id, edit);
    if (prepared.diagram === base.diagram) return { ...prepared, revision: base };
    return this.issue({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base);
  }
  private issue(prepared: PreparedDiagramEdit, base?: DiagramRevision): DiagramRevisionResult {
    const reverse = new Map([...prepared.nodeIds].map(([old, next]) => [next, old]));
    const record = diagramRevisions.register({ id: prepared.diagram.revisionId, diagramId: prepared.diagram.diagramId,
      ...(base ? { parentId: base.id } : {}), diagram: prepared.diagram,
      nodeRefs: Object.fromEntries(diagramContentNodes(prepared.diagram.content).map(node => {
        const old = reverse.get(node.id);
        return [node.id, old && base?.nodeRefs[old] || `node-${crypto.randomUUID()}`];
      })) });
    return { ...prepared, diagram: record.diagram, revision: record };
  }
  async generate(request: DiagramGenerationRequest, options: GenerationOptions = {}) {
    if (!this.generator) throw Error('Diagram generation is unavailable in this runtime');
    options.signal?.throwIfAborted();
    if (request.baseRevisionId && this.getRevision(request.baseRevisionId).diagram.id !== request.input.id)
      throw Error('Generation base belongs to another diagram');
    const generated = await this.generator.generate(structuredClone(request), options);
    options.signal?.throwIfAborted();
    return request.baseRevisionId
      ? this.revise(request.baseRevisionId, { kind: 'replace', input: generated })
      : this.create({ ...request.input, ...generated, id: request.input.id, revision: 0 });
  }
}

import { asciiSha256 } from './asciiSha256';
import type { DiagramContent } from './diagramContent';
import { diagramContentNodes } from './diagramContentNodes';
import { activeDiagramJumps, type DiagramJump } from './diagramJump';
import type { DiagramElementMapping } from '../records/domain';

export interface DiagramTextOwner {
  displayNodeId: string;
  contentNodeId?: string;
  revisionId?: string;
  sourceLine: number;
  /** Zero-based offset from source columns to composed columns. */
  columnOffset: number;
}
export interface DiagramTextRange {
  start: number; end: number; owner?: DiagramTextOwner;
  mapping?: DiagramElementMapping; jump?: DiagramJump;
}
export interface DiagramTextRun {
  jumps?: readonly DiagramJump[];
  start: number; end: number; text: string; owner?: DiagramTextOwner;
  mappings: readonly DiagramElementMapping[]; jump?: DiagramJump;
}
export interface DiagramTextRow { text: string; sourceLine?: number; runs: DiagramTextRun[] }

/** Each interval is emitted once, including overlaps between mappings and labels. */
export function textRow(text: string, ranges: readonly DiagramTextRange[], sourceLine?: number): DiagramTextRow {
  const valid = ranges.filter(range => range.start >= 0 && range.end <= text.length && range.end > range.start);
  const boundaries = [...new Set([0, text.length, ...valid.flatMap(range => [range.start, range.end])])].sort((a, b) => a - b);
  const runs: DiagramTextRun[] = [];
  for (let i = 0; i < boundaries.length - 1; i++) {
    const start = boundaries[i], end = boundaries[i + 1];
    const covering = valid.filter(range => range.start <= start && range.end >= end);
    const labels = covering.filter(range => range.owner?.contentNodeId);
    const base = covering.find(range => range.owner && !range.owner.contentNodeId)?.owner;
    const owner = labels.length === 1 ? labels[0].owner : base;
    const jumps = covering.flatMap(range => range.jump ? [range.jump] : []);
    runs.push({ start, end, text: text.slice(start, end), owner,
      mappings: covering.flatMap(range => range.mapping ? [range.mapping] : []),
      ...(jumps.length ? { jump: jumps[0], jumps } : {}) });
  }
  return { text, sourceLine, runs };
}

/** No loose/prose representation-index entries are promoted to structural nodes. */
export function diagramTextRanges(input: {
  ascii: string; content?: DiagramContent; displayNodeId: string;
  mappings?: readonly DiagramElementMapping[]; jumps?: readonly DiagramJump[];
}): Map<number, DiagramTextRange[]> {
  const lines = input.ascii.split('\n');
  const current = input.content?.ascii === input.ascii && input.content.asciiSha256 === asciiSha256(input.ascii)
    ? input.content : undefined;
  const result = new Map<number, DiagramTextRange[]>();
  lines.forEach((line, index) => result.set(index + 1, [{ start: 0, end: line.length,
    owner: { displayNodeId: input.displayNodeId, revisionId: current?.revisionId, sourceLine: index + 1, columnOffset: 0 } }]));
  const nodes = current ? diagramContentNodes(current).filter(node => node.startColumn >= 1
    && node.endColumn >= node.startColumn && node.endColumn <= (lines[node.line - 1]?.length ?? 0)
    && lines[node.line - 1].slice(node.startColumn - 1, node.endColumn) === node.label) : [];
  const unambiguous = nodes.filter(node => !nodes.some(other => other !== node && other.line === node.line
    && other.startColumn <= node.endColumn && other.endColumn >= node.startColumn));
  for (const node of unambiguous) result.get(node.line)!.push({ start: node.startColumn - 1, end: node.endColumn,
    owner: { displayNodeId: input.displayNodeId, contentNodeId: node.id, revisionId: current!.revisionId,
      sourceLine: node.line, columnOffset: 0 } });
  for (const mapping of input.mappings ?? []) result.get(mapping.line)?.push({ start: mapping.startColumn - 1, end: mapping.endColumn, mapping });
  for (const jump of current ? activeDiagramJumps(current, input.jumps) : []) result.get(jump.source.line)?.push({
    start: jump.source.startColumn - 1, end: jump.source.endColumn, jump });
  return result;
}

/** Whole-range containment, never label equality or mere overlap. */
export function mappingContentNodeId(content: DiagramContent, mapping: DiagramElementMapping): string | undefined {
  if (content.asciiSha256 !== asciiSha256(content.ascii) || mapping.startColumn < 1 || mapping.endColumn < mapping.startColumn) return;
  const nodes = diagramContentNodes(content).filter(node => node.line === mapping.line
    && node.startColumn <= mapping.startColumn && node.endColumn >= mapping.endColumn);
  return nodes.length === 1 ? nodes[0].id : undefined;
}

import { z } from 'zod';
import { buildDiagramContent } from './diagramContent';
import { validateDiagram, type Diagram } from './diagram';

export const generatedDiagramEditSchema = z.object({
  ascii: z.string().min(1).max(20000),
  structureKind: z.enum(['diagram', 'tree']),
  mappings: z.array(z.object({ id: z.string().min(1), entityId: z.string().min(1),
    sourceRangeIndex: z.number().int().nonnegative(), sourceRangeId: z.string().optional(),
    line: z.number().int().positive(), startColumn: z.number().int().positive(), endColumn: z.number().int().positive()
  }).strict()).max(2000)
}).strict();
export type GeneratedDiagramEdit = z.infer<typeof generatedDiagramEditSchema>;

/** Validate an agent candidate without issuing a revision for rejected submissions. */
export function validateGeneratedDiagramEdit(base: Diagram, raw: unknown): GeneratedDiagramEdit {
  const candidate = generatedDiagramEditSchema.parse(raw);
  if (!candidate.ascii.trim() || candidate.ascii.includes('\r') || candidate.ascii.includes('\t'))
    throw Error('Use nonempty ASCII with LF newlines and spaces, not tabs');
  const content = buildDiagramContent(candidate.ascii, `${base.id}:${base.revision + 1}`, candidate.structureKind);
  validateDiagram({ ...base, revision: base.revision + 1, content, jumps: undefined,
    sourceContext: { ...base.sourceContext, contentHash: content.asciiSha256, mappings: candidate.mappings } });
  return candidate;
}

import { buildDiagramContent } from '../diagramContent';
import { validateDiagram, type Diagram, type DiagramInput } from '../diagram';

/** Internal parser/factory. Only the revision service may issue diagrams. */
export function constructDiagram(input: DiagramInput): Diagram {
  const content = buildDiagramContent(input.ascii, `${input.id}:${input.revision}`, input.structureKind ?? 'diagram');
  const diagram: Diagram = { id: input.id, revision: input.revision, diagramId: `diagram-${crypto.randomUUID()}`, revisionId: `diagram-revision-${crypto.randomUUID()}`, content,
    ...(input.jumps ? { jumps: structuredClone(input.jumps) } : {}),
    sourceContext: { ...(input.source ? { binding: structuredClone(input.source) } : {}), contentHash: content.asciiSha256,
      mappings: structuredClone(input.mappings ?? []), evidence: structuredClone(input.evidence ?? {}) } };
  validateDiagram(diagram);
  return diagram;
}

import { deepFreeze } from '../../immutability';
import { validateDiagram, type Diagram } from '../diagram';
import type { DiagramRevision } from '../diagramRevisionEditor';
import { diagramContentNodes } from '../diagramContentNodes';

/** Runtime identity registry. Restored records enter only through validated storage/history adapters. */
class RevisionRegistry {
  private readonly records = new Map<string, DiagramRevision>();
  private readonly signatures = new Map<string, string>();
  private readonly pendingValidation = new Set<string>();
  register(record: DiagramRevision): DiagramRevision { return this.install(record, false); }
  /** Restored history keeps older revisions addressable without parsing them until accessed. */
  restore(record: DiagramRevision): DiagramRevision { return this.install(record, true); }
  private install(record: DiagramRevision, deferred: boolean): DiagramRevision {
    if (record.id !== record.diagram.revisionId || record.diagramId !== record.diagram.diagramId) throw Error('Invalid diagram revision identity');
    const signature = JSON.stringify(record);
    const prior = this.records.get(record.id);
    if (prior) {
      if (this.signatures.get(record.id) !== signature) throw Error('Diagram revision is immutable');
      if (!deferred) this.get(record.id);
      return prior;
    }
    if (!deferred) validateDiagram(record.diagram);
    const stored = deepFreeze(structuredClone(record));
    this.records.set(record.id, stored); this.signatures.set(record.id, signature);
    if (deferred) this.pendingValidation.add(record.id);
    return stored;
  }
  get(id: string): DiagramRevision {
    const record = this.records.get(id);
    if (!record) throw Error(`Unknown diagram revision: ${id}`);
    if (this.pendingValidation.has(id)) {
      validateDiagram(record.diagram);
      const refs = diagramContentNodes(record.diagram.content).map(node => record.nodeRefs?.[node.id]);
      if (!record.nodeRefs || refs.some(ref => typeof ref !== 'string' || !ref) || new Set(refs).size !== refs.length) throw Error('Invalid logical node identities');
      this.pendingValidation.delete(id);
    }
    return record;
  }
  assert(diagram: Diagram): DiagramRevision {
    const record = this.get(diagram.revisionId);
    if (record.diagram !== diagram && JSON.stringify(record.diagram) !== JSON.stringify(diagram))
      throw Error('Diagram content must be changed through DiagramService');
    return record;
  }
  list(diagramId: string) { return [...this.records.values()].filter(record => record.diagramId === diagramId); }
}
export const diagramRevisions = new RevisionRegistry();

import { normalizeSource } from './source';
import { DEFAULT_GLYPHS, recognize } from './recognizers';
import { interpretLayout } from './layout';
import { interpretTrees } from './trees';
import { interpretWires } from './wires';
import type { DiagramInterpretation, ParseOptions, Policy } from './types';

export type * from './types';
export { DEFAULT_GLYPHS, DEFAULT_RECOGNIZERS } from './recognizers';
export { sourceSpan } from './source';
export { renderCleaned } from './render';
export type { RenderedDiagram } from './render';

function policyFor(options: ParseOptions): Policy {
  const policy: Policy = { dialect: options.dialect ?? 'mixed', tabSize: options.tabSize ?? 4,
    treeTolerance: options.treeTolerance ?? 1, wireTolerance: options.wireTolerance ?? 2,
    continuation: options.continuation ?? 'auto', detachedLists: options.detachedLists ?? 'auto',
    repairs: options.repairs ?? 'conservative', maxChars: options.maxChars ?? 1_000_000,
    maxColumns: options.maxColumns ?? 100_000, maxCandidates: options.maxCandidates ?? 100_000,
    maxNodes: options.maxNodes ?? 10_000, maxMatchingCells: options.maxMatchingCells ?? 100_000,
    ...(options.compatibility ? { compatibility: options.compatibility } : {}) };
  for (const [key, choices] of Object.entries({ dialect: ['tree', 'graph', 'mixed', 'unknown'],
    continuation: ['auto', 'join', 'separate'], detachedLists: ['auto', 'include'], repairs: ['conservative', 'none'] })) {
    if (!choices.includes(String(policy[key as keyof Policy]))) throw new TypeError(`Invalid ${key}`);
  }
  if (policy.compatibility && (!['ascii-tree-1', 'ascii-tree-2'].includes(policy.compatibility) || policy.dialect !== 'tree')) throw new TypeError('Compatibility profile requires tree dialect');
  for (const [name, value] of Object.entries(policy)) if (typeof value === 'number' &&
    (!Number.isSafeInteger(value) || value < (name.endsWith('Tolerance') ? 0 : 1))) throw new RangeError(`Invalid ${name}`);
  return Object.freeze(policy);
}

/** Pure, synchronous parser shared by browser and server. No Python or runtime dependencies. */
export function parseDiagram(input: string, options: ParseOptions = {}): DiagramInterpretation {
  if (typeof input !== 'string') throw new TypeError('Diagram input must be a string');
  const policy = policyFor(options);
  if (input.length > policy.maxChars) throw new RangeError('Diagram exceeds maxChars');
  const diagnostics: DiagramInterpretation['diagnostics'] = [];
  const source = normalizeSource(input, policy, diagnostics);
  const glyphs = Object.freeze({ ...DEFAULT_GLYPHS, ...options.glyphs });
  const result: DiagramInterpretation = { parserVersion: 'spatial-diagram-1', source, policy, glyphs,
    candidates: recognize(source, policy, glyphs, options.recognizers ?? [], diagnostics),
    nodes: [], edges: [], regions: [], decisions: [], repairs: [], unresolved: [], diagnostics,
    lines: source.rows.map(row => ({ line: row.line, kind: row.kind, nodeIds: [] })) };
  const { labels, wires } = interpretLayout(result, glyphs);
  interpretTrees(result, labels, wires);
  interpretWires(result, labels, wires);
  return result;
}

/** An explanation contains actual decisions and evidence, never inferred confidence percentages. */
export function explainNode(result: DiagramInterpretation, nodeId: string) {
  const node = result.nodes.find(n => n.id === nodeId);
  if (!node) return undefined;
  const decisions = result.decisions.filter(d => node.decisionIds.includes(d.id) ||
    result.edges.some(e => (e.from === nodeId || e.to === nodeId) && e.decisionId === d.id));
  const repairIds = new Set(decisions.flatMap(d => d.repairIds));
  return { node, decisions, repairs: result.repairs.filter(r => repairIds.has(r.id)),
    unresolved: result.unresolved.filter(u => u.spans.some(s => node.spans.some(n => n.start < s.end && s.start < n.end)) ||
      u.alternatives.some(a => a.nodeIds?.includes(nodeId))) };
}

import { sourceSpan } from './source';
import type { Candidate, DiagramInterpretation, GlyphKind, Label, SourceSpan, WireCell } from './types';

export function decision(result: DiagramInterpretation, ruleId: string, reason: string,
  evidence: SourceSpan[], candidateIds: string[] = [], repairIds: string[] = []): string {
  const id = `decision-${result.decisions.length}`;
  result.decisions.push({ id, ruleId, reason, evidence, candidateIds, repairIds });
  return id;
}

export function unresolved(result: DiagramInterpretation, code: string, reason: string, spans: SourceSpan[],
  alternatives: DiagramInterpretation['unresolved'][number]['alternatives']): void {
  result.unresolved.push({ id: `unresolved-${result.unresolved.length}`, code, reason, spans, alternatives });
  result.diagnostics.push({ code, severity: 'warning', line: spans[0]?.line ?? 1, message: reason });
}

/** Choose structural roles before splitting labels; recognition never consumes source. */
export function interpretLayout(result: DiagramInterpretation, glyphs: Readonly<Record<string, GlyphKind>>):
  { labels: Label[]; wires: WireCell[] } {
  const { source, policy } = result;
  const labels: Label[] = [];
  const wires: WireCell[] = [];
  const byLine = new Map<number, Candidate[]>();
  for (const candidate of result.candidates) {
    if (!byLine.has(candidate.span.line)) byLine.set(candidate.span.line, []);
    byLine.get(candidate.span.line)!.push(candidate);
  }
  for (const row of source.rows) {
    if (row.kind !== 'content') continue;
    if (/^[ +\-_=─━═┌┐└┘┏┓┗┛╔╗╚╝╭╮╰╯┬┴┼]+$/.test(row.text) && row.text.trim().length >= 3) {
      result.lines[row.line - 1].kind = 'metadata'; continue;
    }
    const choices = byLine.get(row.line) ?? [];
    let prefixEnd = 0;
    while (prefixEnd < row.text.length && (row.text[prefixEnd] === ' ' || glyphs[row.text[prefixEnd]] === 'vertical')) prefixEnd++;
    const prefixOnly = (column: number) => column - 1 <= prefixEnd;
    const branches = choices.filter(c => {
      if (c.kind !== 'branch') return false;
      if (policy.dialect === 'graph' && ['horizontal', 'right'].includes(glyphs[row.text[c.span.column - 1]])) return false;
      if (prefixOnly(c.span.column)) return true;
      if (policy.dialect === 'tree') return false;
      let before = c.span.column - 2;
      while (before >= 0 && (row.text[before] === ' ' || glyphs[row.text[before]] === 'vertical')) before--;
      const localPrefix = row.text.slice(before + 1, c.span.column - 1);
      return localPrefix.includes('   ') || choices.some(other => other.kind === 'route' &&
        other.span.endColumn >= before + 2 && other.span.endColumn <= c.span.column);
    });
    const selected: Candidate[] = [];
    const uncertain: Candidate[] = [];
    const byColumn = new Map<number, Candidate[]>();
    for (const c of choices) {
      if (!byColumn.has(c.span.column)) byColumn.set(c.span.column, []);
      byColumn.get(c.span.column)!.push(c);
    }
    const branchesAt = new Map(branches.map(c => [c.span.column, c]));
    for (const [column, options] of byColumn) {
      if (selected.some(c => c.kind !== 'vertical' && column < c.span.endColumn) ||
        uncertain.some(c => column < c.span.endColumn)) continue;
      const branch = branchesAt.get(column);
      const route = options.filter(c => c.kind === 'route').sort((a, b) => b.span.endColumn - a.span.endColumn)[0];
      const applicable = options.filter(c => c.kind === 'route' && policy.dialect !== 'tree' || c.kind === 'branch' && branches.includes(c));
      const conflicting = (['branch', 'route'] as const).some(kind => new Set(applicable.filter(c => c.kind === kind)
        .map(c => `${c.span.endColumn}:${!!c.bullet}:${!!c.headed}`)).size > 1);
      if (conflicting) {
        uncertain.push(...applicable);
        unresolved(result, 'conflicting-recognizers', 'Recognizers disagree about this shape; registration order cannot settle it.',
          applicable.map(c => c.span), applicable.map(c => ({ description: `${c.ruleId}: ${c.kind} through column ${c.span.endColumn - 1}`,
            candidateIds: [c.id] })));
        continue;
      }
      if (branch && route && prefixOnly(column) && (policy.dialect === 'mixed' || policy.dialect === 'unknown')) {
        uncertain.push(branch, route);
        unresolved(result, 'ambiguous-connector', 'This marker can mean containment or a reference; select a diagram convention.',
          [route.span], [{ description: 'Containment branch', candidateIds: [branch.id] },
            { description: 'Reference wire', candidateIds: [route.id] }]);
        continue;
      }
      const chosen = policy.dialect === 'tree' ? branch : route ?? branch;
      if (chosen) {
        selected.push(chosen);
        decision(result, 'connector-convention', `${policy.dialect} convention selects ${chosen.kind}.`,
          [chosen.span], options.map(c => c.id));
        continue;
      }
      if (policy.dialect === 'tree') continue;
      const stroke = options.find(c => c.kind === 'vertical');
      if (!stroke) continue;
      const ch = row.text[column - 1];
      const guide = branches.some(c => c.span.column > column) && prefixOnly(column);
      if (guide) continue;
      const suffixPipes = [...row.text.slice(column - 1)].every(c => c === ' ' || glyphs[c] === 'vertical');
      const neighbors = [source.rows[row.line - 2], source.rows[row.line]].filter(other => other?.block === row.block);
      const supported = neighbors.some(other => {
        const near = other.text.slice(Math.max(0, column - 1 - policy.wireTolerance), column + policy.wireTolerance);
        return [...near].some(c => glyphs[c] === 'vertical' || glyphs[c] === 'joint' || glyphs[c] === 'down' || glyphs[c] === 'up');
      });
      if (prefixOnly(column) || ['up', 'down'].includes(glyphs[ch]) ||
        (suffixPipes && supported) || row.text.slice(Math.max(0, column - 4), column - 1) === '   ') selected.push(stroke);
    }
    // Graph runs own their cells; guide candidates remain visible in the evidence.
    for (const item of selected) {
      if (item.kind === 'branch') continue;
      for (let column = item.span.column; column < item.span.endColumn; column++) {
        const raw = row.text[column - 1];
        if (glyphs[raw]) wires.push({ line: row.line, column, raw, glyph: glyphs[raw],
          candidateId: item.id, span: sourceSpan(row, column, column + 1) });
      }
    }
    const selectedAt = new Map(selected.map(c => [c.span.column, c]));
    let pending: Candidate | undefined;
    let x = 0;
    const labelsBefore = labels.length;
    while (x < row.text.length) {
      const item = selectedAt.get(x + 1);
      if (item) {
        if (item.kind === 'branch') pending = item;
        x = item.span.endColumn - 1; continue;
      }
      if (row.text[x] === ' ' || (glyphs[row.text[x]] === 'vertical' && prefixOnly(x + 1))) { x++; continue; }
      const start = x;
      const closing: string[] = [];
      while (x < row.text.length) {
        const ch = row.text[x];
        if (!closing.length && x > start && selectedAt.has(x + 1)) break;
        if (!closing.length && policy.dialect !== 'tree' && row.text.startsWith('   ', x)) break;
        if ('[{('.includes(ch)) closing.push(({ '[': ']', '{': '}', '(': ')' } as Record<string, string>)[ch]);
        else if (closing.at(-1) === ch) closing.pop();
        x++;
      }
      const text = row.text.slice(start, x).trimEnd();
      if (text) {
        const span = sourceSpan(row, start + 1, start + text.length + 1);
        const guideEnd = pending ? pending.span.column - 1 : start;
        const guides: number[] = [];
        for (let col = 0; col < guideEnd; col++) if (glyphs[row.text[col]] === 'vertical') guides.push(col + 1);
        labels.push({ span, text, branch: pending, guides, block: row.block,
          column: span.column, anchor: pending?.span.column,
          uncertain: uncertain.some(c => c.span.column < span.endColumn && span.column < c.span.endColumn) });
      }
      pending = undefined;
      if (policy.dialect === 'tree') break;
      if (x === start) x++;
    }
    if (labels.length === labelsBefore) result.lines[row.line - 1].kind = 'drawing';
  }
  return { labels, wires };
}

import { sourceSpan } from './source';
import type { Candidate, Diagnostic, GlyphKind, Policy, RecognitionContext, Recognizer, SourceDocument } from './types';

export const DEFAULT_GLYPHS: Readonly<Record<string, GlyphKind>> = Object.freeze(Object.fromEntries(
  Object.entries({ horizontal: '-─━═╌╍┄┅┈┉–—_', vertical: '|│┃┆┊║¦╎╏:',
    joint: "+\\`'├└┝┞┟┠┡┢┣┗┖╠╚╟╙╰╘╞┌╭┐┘┬┴┼", left: '<←', right: '>→›',
    up: '^↑', down: 'v↓' }).flatMap(([kind, chars]) => [...chars].map(ch => [ch, kind as GlyphKind]))));

const branch: Recognizer = {
  id: 'branch-marker', starts: ['joint', 'vertical', 'horizontal', 'right', '↳', '↪', '➜', '➝', '➞'],
  recognize({ row, column, glyphs, policy }) {
    const start = column - 1;
    if (policy.compatibility) {
      const marker = policy.compatibility === 'ascii-tree-1'
        ? /^([+`\\]--(?:>)?)(?=\s+\S)/ : /^([+`\\|]--(?:>)?)(?=\s+\S)/;
