import type { Diagnostic, Policy, SourceDocument, SourceRow, SourceSpan } from './types';

const ANSI = /^(?:\x1b\[[0-?]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\))/;
const INVISIBLE = /[\ufeff\u200b\u200c\u200d]/;
