    for (const label of items) {
      const old = label.anchor;
      let anchor = old === undefined ? Math.min(label.column, base) - 1 : canonical.get(old)!;
      if (old !== undefined && anchor !== old) {
        const row = result.source.rows[label.span.line - 1];
        const delta = anchor - old;
        const newEnd = label.span.endColumn + delta;
        const crossed = delta < 0 ? row.text.slice(anchor - 1, old - 1) : row.text.slice(label.span.endColumn - 1, newEnd - 1);
        if (crossed.trim()) {
          unresolved(result, 'blocked-tree-repair', 'Aligning this branch would cross existing drawing content.', [label.span],
            [{ description: 'Keep the original indentation.' }]);
          anchor = old;
        }
      }
      const node = addNode(result, label, owner, 'tree-item');
      if (old !== undefined && anchor !== old) {
        const id = `repair-${result.repairs.length}`;
        result.repairs.push({ id, kind: 'tree-alignment', reason: 'A uniquely dominant nearby branch column establishes the alignment.',
          spans: [label.branch!.span], moves: [{ line: label.span.line, column: old, toColumn: anchor }], changesStructure: true });
        node.decisionIds.push(decision(result, 'tree-alignment', 'Explicit guides protect nested levels; the remaining drift matches the dominant column.',
          items.filter(l => l.anchor === anchor || l === label).map(l => l.span), [], [id]));
      }
      if (old !== undefined && ambiguous.has(old) && stack.length && old > stack.at(-1)!.anchor && old - stack.at(-1)!.anchor <= result.policy.treeTolerance) {
        unresolved(result, 'ambiguous-indentation', 'This indentation can be a child level or alignment drift.', [label.span],
          [{ description: 'Child of preceding item', nodeIds: [stack.at(-1)!.node.id] },
            { description: 'Sibling of preceding item', nodeIds: stack.at(-1)!.node.parentId ? [stack.at(-1)!.node.parentId!] : [] }]);
        stack.length = 0;
      }
      while (stack.length && stack.at(-1)!.anchor >= anchor) stack.pop();
      attach(result, node, stack.at(-1)?.node);
      stack.push({ anchor, node });
    }
  }
  result.nodes.sort((a, b) => a.spans[0].line - b.spans[0].line || a.spans[0].column - b.spans[0].column);
}

export function interpretTrees(result: DiagramInterpretation, labels: Label[], wires: WireCell[]): void {
  if (result.policy.dialect === 'tree') treeDocument(result, labels);
  else graphDocument(result, labels, wires);
}

/** Public coordinates are one-based; offsets and range ends are UTF-16, end-exclusive. */
export interface SourceSpan {
  line: number;
  column: number;
  endColumn: number;
  start: number;
  end: number;
}

export type Dialect = 'tree' | 'graph' | 'mixed' | 'unknown';
export interface ParseOptions {
  dialect?: Dialect;
  tabSize?: number;
  treeTolerance?: number;
  wireTolerance?: number;
  continuation?: 'auto' | 'join' | 'separate';
  detachedLists?: 'auto' | 'include';
  repairs?: 'conservative' | 'none';
  /** Preserve the app's historical arrow-tree headings and narrow branch grammar. */
  compatibility?: 'ascii-tree-1' | 'ascii-tree-2';
  maxChars?: number;
  maxColumns?: number;
  maxCandidates?: number;
  maxNodes?: number;
  maxMatchingCells?: number;
  recognizers?: readonly Recognizer[];
  glyphs?: Readonly<Record<string, GlyphKind>>;
}
export type Policy = Required<Omit<ParseOptions, 'recognizers' | 'glyphs' | 'compatibility'>> &
  Pick<ParseOptions, 'compatibility'>;
export type GlyphKind = 'horizontal' | 'vertical' | 'joint' | 'left' | 'right' | 'up' | 'down';

export interface SourceRow {
  readonly line: number;
  readonly text: string;
  readonly raw: string;
  readonly start: number;
  readonly block: number;
  readonly kind: 'content' | 'blank' | 'metadata' | 'outside';
  /** One original offset pair for every normalized UTF-16 column. */
  readonly offsets: readonly (readonly [number, number])[];
}
export interface SourceDocument {
  readonly original: string;
  readonly rows: readonly SourceRow[];
}
export interface Candidate {
  id: string;
  ruleId: string;
  kind: 'branch' | 'route' | 'vertical';
  span: SourceSpan;
  /** Branches may be bullets or carry a head; interpretation chooses their role. */
  bullet?: boolean;
  headed?: boolean;
}
export interface RecognitionContext {
  readonly source: SourceDocument;
  readonly row: SourceRow;
  readonly column: number;
  readonly glyphs: Readonly<Record<string, GlyphKind>>;
  readonly policy: Readonly<Policy>;
}
export interface Recognition {
  kind: Candidate['kind'];
  /** End-exclusive normalized column (one-based). */
  endColumn: number;
  bullet?: boolean;
  headed?: boolean;
}
export interface Recognizer {
  readonly id: string;
  /** Dispatch categories or literal characters. All applicable rules run. */
  readonly starts: readonly string[];
  recognize(context: RecognitionContext): readonly Recognition[];
}

export interface Decision {
  id: string;
  ruleId: string;
  reason: string;
  evidence: SourceSpan[];
  candidateIds: string[];
  repairIds: string[];
}
export interface Unresolved {
  id: string;
  code: string;
  reason: string;
  spans: SourceSpan[];
  alternatives: { description: string; candidateIds?: string[]; nodeIds?: string[] }[];
}
export interface Diagnostic {
  code: string;
  line: number;
  severity: 'info' | 'warning' | 'error';
  message: string;
}
export interface DiagramNode {
  id: string;
  kind: 'tree-item' | 'text';
  label: string;
  regionId: string;
  spans: SourceSpan[];
  branchColumn?: number;
  parentId?: string;
  childIds: string[];
  decisionIds: string[];
}
export interface DiagramEdge {
  id: string;
  kind: 'contains' | 'references';
  from: string;
  to: string;
  /** A head meeting a branch addresses the region, not that branch's item. */
  targetKind?: 'node' | 'region';
  decisionId: string;
  wireCells?: { line: number; column: number }[];
}
export interface Region {
  id: string;
  kind: 'tree' | 'text';
  nodeIds: string[];
  rootIds: string[];
}
export interface Repair {
  id: string;
  kind: 'tree-alignment' | 'wire-alignment';
  reason: string;
  spans: SourceSpan[];
  /** Describes logical geometry; original source is never rewritten. */
  moves: { line: number; column: number; toColumn: number }[];
  changesStructure: boolean;
}
export interface DiagramInterpretation {
  parserVersion: 'spatial-diagram-1';
  source: SourceDocument;
  policy: Policy;
  glyphs: Readonly<Record<string, GlyphKind>>;
  candidates: Candidate[];
  nodes: DiagramNode[];
  edges: DiagramEdge[];
  regions: Region[];
  decisions: Decision[];
  repairs: Repair[];
  unresolved: Unresolved[];
  diagnostics: Diagnostic[];
  /** Every original line remains addressable, including prose and unknown syntax. */
  lines: { line: number; kind: string; nodeIds: string[] }[];
}

/** Internal layout records keep interpretation geometry separate from source coordinates. */
export interface Label {
  span: SourceSpan;
  text: string;
  branch?: Candidate;
  guides: number[];
  block: number;
  column: number;
  anchor?: number;
  uncertain?: boolean;
  node?: DiagramNode;
}
export interface WireCell {
  line: number;
  column: number;
  glyph: GlyphKind;
  raw: string;
  candidateId: string;
  span: SourceSpan;
}

import { decision, unresolved } from './layout';
import type { DiagramInterpretation, Label, WireCell } from './types';

/** All matchings maximize track count, then minimize drift. Only forced pairs survive. */
export function matchTracks(above: number[], below: number[], tolerance: number, maxCells = 100_000):
  { pairs: [number, number][]; alternatives: [number, number][] } {
  const width = below.length + 1;
  const size = (above.length + 1) * width;
  if (size > maxCells) throw new RangeError('Wire matching exceeds maxMatchingCells');
  const reward = Math.min(above.length, below.length) * tolerance + 1;
  const f = new Float64Array(size);
  const b = new Float64Array(size);
  const at = (i: number, j: number) => i * width + j;
  const value = (i: number, j: number) => Math.abs(above[i] - below[j]) <= tolerance
    ? reward - Math.abs(above[i] - below[j]) : -Infinity;
  for (let i = 0; i < above.length; i++) for (let j = 0; j < below.length; j++) {
    f[at(i + 1, j + 1)] = Math.max(f[at(i, j + 1)], f[at(i + 1, j)], f[at(i, j)] + value(i, j));
  }
  for (let i = above.length - 1; i >= 0; i--) for (let j = below.length - 1; j >= 0; j--) {
    b[at(i, j)] = Math.max(b[at(i + 1, j)], b[at(i, j + 1)], b[at(i + 1, j + 1)] + value(i, j));
  }
  const best = b[0];
  const options: [number, number][] = [];
  const freeAbove = new Set<number>();
  const freeBelow = new Set<number>();
  for (let i = 0; i < above.length; i++) {
    for (let j = 0; j <= below.length; j++) if (f[at(i, j)] + b[at(i + 1, j)] === best) freeAbove.add(above[i]);
    for (let j = 0; j < below.length; j++) if (f[at(i, j)] + value(i, j) + b[at(i + 1, j + 1)] === best) options.push([above[i], below[j]]);
  }
  for (let j = 0; j < below.length; j++) for (let i = 0; i <= above.length; i++) {
    if (f[at(i, j)] + b[at(i, j + 1)] === best) freeBelow.add(below[j]);
  }
  const pairs = options.filter(([a, z]) => !freeAbove.has(a) && !freeBelow.has(z) &&
    options.filter(([x]) => x === a).length === 1 && options.filter(([, x]) => x === z).length === 1);
  return { pairs, alternatives: options.filter(pair => !pairs.includes(pair)) };
}

class Components {
  private parents = new Map<string, string>();
  add(key: string) { if (!this.parents.has(key)) this.parents.set(key, key); }
  root(key: string): string {
    this.add(key);
    let root = key;
    while (this.parents.get(root) !== root) root = this.parents.get(root)!;
    while (key !== root) { const next = this.parents.get(key)!; this.parents.set(key, root); key = next; }
    return root;
  }
  join(a: string, b: string) { this.parents.set(this.root(a), this.root(b)); }
}
const pos = (cell: Pick<WireCell, 'line' | 'column'>) => `${cell.line}:${cell.column}`;
const channel = (cell: WireCell, axis: 'h' | 'v') => `${pos(cell)}:${axis}`;
const vertical = (cell?: WireCell) => cell && ['joint', 'vertical', 'up', 'down'].includes(cell.glyph);
const horizontal = (cell?: WireCell) => cell && ['joint', 'horizontal', 'left', 'right'].includes(cell.glyph);

export function interpretWires(result: DiagramInterpretation, labels: Label[], input: WireCell[]): void {
  if (result.policy.dialect === 'tree') return;
  const cells = new Map(input.map(cell => [pos(cell), cell]));
  const connected = new Components();
  const entries: { key: string; cell: WireCell; axis: 'h' | 'v' }[] = [];
  const crossing = (cell: WireCell) => cell.glyph === 'vertical' &&
    horizontal(cells.get(`${cell.line}:${cell.column - 1}`)) && horizontal(cells.get(`${cell.line}:${cell.column + 1}`));
  const hasH = (cell?: WireCell) => cell && (horizontal(cell) || crossing(cell));
  for (const cell of cells.values()) {
    if (hasH(cell)) entries.push({ key: channel(cell, 'h'), cell, axis: 'h' });
    if (vertical(cell)) entries.push({ key: channel(cell, 'v'), cell, axis: 'v' });
    if (cell.glyph === 'joint') connected.join(channel(cell, 'h'), channel(cell, 'v'));
    const right = cells.get(`${cell.line}:${cell.column + 1}`);
    if (hasH(cell) && hasH(right) && cell.glyph !== 'right' && right!.glyph !== 'left') connected.join(channel(cell, 'h'), channel(right!, 'h'));
  }
  const byLine = new Map<number, WireCell[]>();
  for (const cell of cells.values()) if (vertical(cell)) byLine.set(cell.line, [...(byLine.get(cell.line) ?? []), cell]);
  const links: [WireCell, WireCell][] = [];
  for (const [line, row] of byLine) {
    if (result.source.rows[line - 1].block !== result.source.rows[line]?.block) continue;
    const above = row.filter(c => c.glyph !== 'down').sort((a, b) => a.column - b.column);
    const below = (byLine.get(line + 1) ?? []).filter(c => c.glyph !== 'up').sort((a, b) => a.column - b.column);
    const tolerance = result.policy.repairs === 'none' ? 0 : result.policy.wireTolerance;
    // Spatially disconnected bundles cannot affect each other's matching.
    const columns = [...new Set([...above, ...below].map(c => c.column))].sort((a, b) => a - b);
    const bundles: number[][] = [];
    for (const x of columns) {
      if (!bundles.length || x - bundles.at(-1)!.at(-1)! > tolerance) bundles.push([]);
      bundles.at(-1)!.push(x);
    }
    for (const bundle of bundles) {
      const xs = above.filter(c => bundle.includes(c.column));
      const ys = below.filter(c => bundle.includes(c.column));
      const matching = matchTracks(xs.map(c => c.column), ys.map(c => c.column), tolerance, result.policy.maxMatchingCells);
      for (const [x, y] of matching.pairs) links.push([xs.find(c => c.column === x)!, ys.find(c => c.column === y)!]);
      if (matching.alternatives.length) unresolved(result, 'ambiguous-wire-continuation',
        'Several equally good wire continuations exist; ambiguous tracks remain disconnected.', [...xs, ...ys].map(c => c.span),
        matching.alternatives.map(([x, y]) => ({ description: `Column ${x} continues at column ${y}.` })));
    }
  }
  // Repairs are evaluated as entire vertical runs, including corners and crossings.
  const runs = new Components();
  for (const [a, b] of links) runs.join(pos(a), pos(b));
  const grouped = new Map<string, WireCell[]>();
  for (const cell of cells.values()) if (vertical(cell)) {
    const key = runs.root(pos(cell)); grouped.set(key, [...(grouped.get(key) ?? []), cell]);
  }
  const blocked = new Set<string>();
  const repairFor = new Map<string, string>();
  const labelsByLine = new Map<number, Label[]>();
  for (const label of labels) if (label.node) labelsByLine.set(label.span.line, [...(labelsByLine.get(label.span.line) ?? []), label]);
  for (const [key, run] of grouped) {
    const target = Math.max(...run.map(c => c.column));
    if (run.every(c => c.column === target)) continue;
    const occupied = run.some(cell => {
      for (let column = cell.column + 1; column <= target; column++) {
        if ((labelsByLine.get(cell.line) ?? []).some(l => column >= (l.anchor ?? l.column) && column < l.span.endColumn)) return true;
        const other = cells.get(`${cell.line}:${column}`);
        if (other && !run.includes(other) && !(other.glyph === 'horizontal' && (cell.glyph === 'joint' || crossing(cell)))) return true;
      }
      return false;
    });
    if (occupied) {
      blocked.add(key);
      unresolved(result, 'blocked-wire-repair', 'Aligning this wire would cross text or another wire.', run.map(c => c.span),
        [{ description: 'Keep the original positions without inferring continuity across the drift.' }]);
    } else {
      const id = `repair-${result.repairs.length}`;
      result.repairs.push({ id, kind: 'wire-alignment', reason: 'A unique ordered track match connects this drifting wire.',
        spans: run.map(c => c.span), moves: run.filter(c => c.column !== target).map(c => ({ line: c.line, column: c.column, toColumn: target })), changesStructure: true });
      for (const cell of run) repairFor.set(pos(cell), id);
    }
  }
  for (const [a, b] of links) if (a.column === b.column || !blocked.has(runs.root(pos(a)))) connected.join(channel(a, 'v'), channel(b, 'v'));
  const groups = new Map<string, typeof entries>();
  for (const entry of entries) {
    const key = connected.root(entry.key); groups.set(key, [...(groups.get(key) ?? []), entry]);
  }
  const nodeById = new Map(result.nodes.map(n => [n.id, n]));
  const regionById = new Map(result.regions.map(r => [r.id, r]));
  for (const group of groups.values()) {
    const routeCells = [...new Map(group.map(e => [pos(e.cell), e.cell])).values()];
    const heads = routeCells.filter(c => ['left', 'right', 'up', 'down'].includes(c.glyph));
    if (!heads.length && !routeCells.some(c => c.glyph === 'horizontal')) continue;
    const keys = new Set(group.map(e => e.key));
    const sources = new Set<string>();
    for (const { cell, axis } of group) {
      const { line, column, glyph } = cell;
      if (['left', 'right', 'up', 'down'].includes(glyph)) continue;
      if (axis === 'h') {
        for (const label of labelsByLine.get(line) ?? []) {
          const end = label.span.endColumn;
          if (!keys.has(`${line}:${column - 1}:h`) && column - end >= 0 && column - end <= 2) sources.add(label.node!.id);
          if (!keys.has(`${line}:${column + 1}:h`) && label.column - column > 0 && label.column - column <= 2) sources.add(label.node!.id);
        }
        if (['`', '\\'].includes(cell.raw) && !keys.has(`${line}:${column - 1}:h`)) {
          const above = (labelsByLine.get(line - 1) ?? []).filter(l => l.anchor !== undefined && l.anchor < column && l.column <= column)
            .sort((a, b) => b.column - a.column);
          if (above.length) sources.add(above[0].node!.id);
        }
      } else if (glyph === 'vertical') {
        for (const direction of [-1, 1]) {
          const nearby = cells.get(`${line + direction}:${column}`);
          const inRoute = nearby && keys.has(channel(nearby, 'v'));
          if (!inRoute) {
            const touching = (labelsByLine.get(line + direction) ?? []).filter(l => l.column <= column && column < l.span.endColumn);
            if (touching.length === 1) sources.add(touching[0].node!.id);
          }
        }
      }
    }
    // A direct vertical head can have its source immediately above/below it.
    for (const head of heads) if (head.glyph === 'down' || head.glyph === 'up') {
      const fromLine = head.line + (head.glyph === 'down' ? -1 : 1);
      const touching = (labelsByLine.get(fromLine) ?? []).filter(l => l.column <= head.column && head.column < l.span.endColumn);
      if (touching.length === 1) sources.add(touching[0].node!.id);
    }
    if (!heads.length) {
      unresolved(result, 'unheaded-reference', 'A routed wire has no arrowhead; its direction remains unresolved.', routeCells.map(c => c.span),
        [{ description: 'Undirected or incomplete connector' }]); continue;
    }
    if (sources.size > 1) result.diagnostics.push({ code: 'shared-reference-bus', severity: 'info', line: routeCells[0].line,
      message: 'The joined bus connects each explicit source to each resolved arrowhead.' });
    for (const head of heads) {
      const targets = new Map<string, { id: string; kind: 'node' | 'region' }>();
      const line = head.line + (head.glyph === 'down' ? 1 : head.glyph === 'up' ? -1 : 0);
      for (const label of labelsByLine.get(line) ?? []) {
        const start = label.anchor ?? label.column;
        const end = label.span.endColumn;
        const tolerance = result.policy.wireTolerance;
        const found = head.glyph === 'right' ? start > head.column && start - head.column <= tolerance + 2
          : head.glyph === 'left' ? head.column >= end && head.column - end <= tolerance + 1
            : head.column >= start - tolerance && head.column < end + tolerance;
        if (!found) continue;
        const wholeTree = head.glyph === 'right' && label.anchor !== undefined;
        const target = wholeTree ? regionById.get(label.node!.regionId)!.rootIds[0] : label.node!.id;
        if (target) targets.set(target, { id: target, kind: wholeTree ? 'region' : 'node' });
      }
      if (targets.size !== 1 || !sources.size) {
        unresolved(result, 'unresolved-reference', `Arrow has ${sources.size} source(s) and ${targets.size} target candidate(s).`, [head.span],
          [...targets.values()].map(t => ({ description: `Possible target: ${nodeById.get(t.id)?.label}`, nodeIds: [t.id] })));
        continue;
      }
      const target = [...targets.values()][0];
      const repairs = [...new Set(routeCells.flatMap(c => repairFor.get(pos(c)) ?? []))];
      const id = decision(result, 'wire-connectivity', 'Connected wire channels reach one geometrically resolved target.',
        routeCells.map(c => c.span), [...new Set(routeCells.map(c => c.candidateId))], repairs);
      for (const source of [...sources].sort()) result.edges.push({ id: `reference-${result.edges.length}`, kind: 'references',
        from: source, to: target.id, targetKind: target.kind, decisionId: id,
        wireCells: routeCells.map(c => ({ line: c.line, column: c.column })).sort((a, b) => a.line - b.line || a.column - b.column) });
    }
  }
}

import type { DiagramElementMapping } from "../records/domain";

/** Grid coordinates are zero-based cells; right and bottom edges are exclusive. */
export interface GridPoint { column: number; row: number }
export interface GridSize { columns: number; rows: number }
export interface GridBounds extends GridPoint, GridSize {}

export type { Diagram } from './diagram';
import type { Diagram } from './diagram';

export type GridBox = {
  id: string;
  position: GridPoint;
  minimumSize?: GridSize;
  collapsed: boolean;
  collapsedContentId?: string;
} & (
  | { kind: "diagram"; contentId: string }
  | { kind: "container"; children: readonly GridBox[]; layout: { collisionPolicy: "push-right"; gap: number } }
);

export interface LineGridScene {
  contents: Readonly<Record<string, Diagram>>;
  root: GridBox;
}

export interface ResolvedGridBox {
  box: GridBox;
  /** Absolute scene coordinates. */
  bounds: GridBounds;
  contentId?: string;
  children: readonly ResolvedGridBox[];
}

// Bounds also limit accidental allocation when composing sparse text.
const MAX_EXTENT = 20000;
const MAX_CELLS = 4_000_000;

function integer(value: number, label: string): void {
  if (!Number.isInteger(value) || value < 0 || value > MAX_EXTENT) {
    throw new Error(`${label} must be an integer between 0 and ${MAX_EXTENT}`);
  }
}

export function measureContent(ascii: string): GridSize {
  if (/[^\x20-\x7e\n]/.test(ascii)) throw new Error("Grid content must be printable ASCII with LF newlines");
  const lines = ascii.split("\n");
  return { columns: Math.max(1, ...lines.map((line) => line.length)), rows: lines.length };
}

export function boxesOverlap(a: GridBounds, b: GridBounds, gap = 0): boolean {
  return a.row < b.row + b.rows && b.row < a.row + a.rows
    && a.column < b.column + b.columns + gap && b.column < a.column + a.columns + gap;
}

/** Measure without mutating input. Ancestor containment is not a collision. */
export function resolveScene(scene: LineGridScene): ResolvedGridBox {
  const ids = new Set<string>();
  function visit(box: GridBox, parent: GridPoint): ResolvedGridBox {
    if (ids.has(box.id)) throw new Error(`Duplicate GridBox id: ${box.id}`);
    ids.add(box.id);
    integer(box.position.column, "column");
    integer(box.position.row, "row");
    if (box.minimumSize) {
      integer(box.minimumSize.columns, "columns");
      integer(box.minimumSize.rows, "rows");
    }
    const origin = { column: parent.column + box.position.column, row: parent.row + box.position.row };
    integer(origin.column, "absolute column");
    integer(origin.row, "absolute row");
    if (box.kind === "container") integer(box.layout.gap, "gap");
    const contentId = box.collapsed ? box.collapsedContentId : box.kind === "diagram" ? box.contentId : undefined;
    if (box.collapsed && !contentId) throw new Error(`Collapsed box ${box.id} needs collapsed content`);
    let size: GridSize = { columns: 1, rows: 1 };
    if (contentId) {
      const content = scene.contents[contentId];
      if (!content) throw new Error(`Missing grid content: ${contentId}`);
      size = measureContent(content.content.ascii);
    }
    const children = box.kind === "container" && !box.collapsed
      ? box.children.map((child) => visit(child, origin)) : [];
    for (const child of children) {
      size.columns = Math.max(size.columns, child.bounds.column - origin.column + child.bounds.columns);
      size.rows = Math.max(size.rows, child.bounds.row - origin.row + child.bounds.rows);
    }
    // Reserved expanded space does not keep a collapsed box large.
    if (!box.collapsed && box.minimumSize) {
      size.columns = Math.max(size.columns, box.minimumSize.columns);
      size.rows = Math.max(size.rows, box.minimumSize.rows);
    }
    integer(origin.column + size.columns, "right edge");
    integer(origin.row + size.rows, "bottom edge");
    return { box, bounds: { ...origin, ...size }, contentId, children };
  }
  return visit(scene.root, { column: 0, row: 0 });
}

export function flattenGrid(root: ResolvedGridBox): ResolvedGridBox[] {
  return [root, ...root.children.flatMap(flattenGrid)];
}

export function findCollisions(scene: LineGridScene, parentId: string, bounds: GridBounds, excludeId?: string): string[] {
  const parent = flattenGrid(resolveScene(scene)).find((node) => node.box.id === parentId);
  if (!parent) throw new Error(`Unknown parent: ${parentId}`);
  return parent.children.filter((child) => child.box.id !== excludeId && boxesOverlap(child.bounds, bounds))
    .map((child) => child.box.id);
}

/** Immutable tree edit; use layoutScene afterward to commit the resulting positions. */
export function updateGridBox(scene: LineGridScene, id: string, update: (box: GridBox) => GridBox): LineGridScene {
  let found = false;
  function visit(box: GridBox): GridBox {
    if (box.id === id) { found = true; return update(box); }
    return box.kind === "container" ? { ...box, children: box.children.map(visit) } : box;
  }
  const root = visit(scene.root);
  if (!found) throw new Error(`Unknown GridBox: ${id}`);
  return { ...scene, root };
}

/**
 * Anchor the changed subtree at every ancestor. Settle other siblings in stable
 * spatial order, only moving right. Each settled box is an immutable obstacle,
 * so collision chains terminate without boxes repeatedly pushing each other.
 */
export function layoutScene(scene: LineGridScene, changedId: string): LineGridScene {
  function visit(box: GridBox): { box: GridBox; changed: boolean } {
    if (box.kind === "diagram") return { box, changed: box.id === changedId };
    const descendants = box.children.map(visit);
    let children = descendants.map((child) => child.box);
    const anchoredId = descendants.find((child) => child.changed)?.box.id;
    if (!box.collapsed) {
      const measure = (child: GridBox) => resolveScene({ ...scene, root: child }).bounds;
      const ordered = children.map((child, index) => ({ child, index })).sort((a, b) =>
        Number(b.child.id === anchoredId) - Number(a.child.id === anchoredId)
        || a.child.position.column - b.child.position.column
        || a.child.position.row - b.child.position.row || a.index - b.index);
      const settled: GridBounds[] = [];
      const replacements = new Map<string, GridBox>();
      for (const { child } of ordered) {
        const bounds = { ...measure(child) };
        let collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
        while (collisions.length) {
          bounds.column = Math.max(...collisions.map((other) => other.column + other.columns + box.layout.gap));
          collisions = settled.filter((other) => boxesOverlap(bounds, other, box.layout.gap));
        }
        settled.push(bounds);
        replacements.set(child.id, { ...child, position: { column: bounds.column, row: bounds.row } });
      }
      children = children.map((child) => replacements.get(child.id)!);
    }
    return { box: { ...box, children }, changed: box.id === changedId || descendants.some((child) => child.changed) };
  }
  const result = visit(scene.root);
  if (!result.changed) throw new Error(`Unknown GridBox: ${changedId}`);
  const next = { ...scene, root: result.box };
  // Check all final bounds before publishing a transaction.
  composeScene(next);
  return next;
}

export function composeScene(scene: LineGridScene, renderContent?: (content: Diagram, box: GridBox) => string): string {
  const root = resolveScene(scene);
  const width = root.bounds.column + root.bounds.columns;
  const height = root.bounds.row + root.bounds.rows;
  if (width * height > MAX_CELLS) throw new Error("Grid exceeds the supported canvas size");
  const rows = Array.from({ length: height }, () => "");
  function paint(node: ResolvedGridBox): void {
    for (let i = 0; i < node.children.length; i++) {
      for (let j = i + 1; j < node.children.length; j++) {
        if (boxesOverlap(node.children[i].bounds, node.children[j].bounds)) {
          throw new Error(`GridBox collision: ${node.children[i].box.id} and ${node.children[j].box.id}`);
        }
      }
    }
    if (node.contentId) {
      const content = scene.contents[node.contentId];
      (renderContent ? renderContent(content, node.box) : content.content.ascii).split("\n").forEach((line, index) => {
        const row = node.bounds.row + index;
        const start = node.bounds.column;
        const existing = rows[row].padEnd(start, " ");
        rows[row] = existing.slice(0, start) + line + existing.slice(start + line.length);
      });
    }
    node.children.forEach(paint);
  }
  paint(root);
  return rows.join("\n");
}

export function hitTest(scene: LineGridScene, point: GridPoint): { boxId: string; contentId?: string; local: GridPoint } | null {
  function visit(node: ResolvedGridBox): ReturnType<typeof hitTest> {
    const b = node.bounds;
    if (point.column < b.column || point.column >= b.column + b.columns
      || point.row < b.row || point.row >= b.row + b.rows) return null;
    for (const child of node.children) {
      const hit = visit(child);
      if (hit) return hit;
    }
    return { boxId: node.box.id, contentId: node.contentId,
      local: { column: point.column - b.column, row: point.row - b.row } };
  }
  return visit(resolveScene(scene));
}

export function projectMapping(bounds: GridBounds, mapping: DiagramElementMapping): GridBounds {
  return { column: bounds.column + mapping.startColumn - 1, row: bounds.row + mapping.line - 1,
    columns: mapping.endColumn - mapping.startColumn + 1, rows: 1 };
}

import { buildDiagramContent } from './diagramContent';
import { diagramContentNodes } from './diagramContentNodes';
