import { endpointKey, type EndpointBounds, type EndpointIdentity, type EndpointRect } from './endpointGeometry';
import { routeEdge, routePath } from './edgeRouting';
import { connectionBox, connectionContentNodes, getArrowLabel, type DiagramAnchor, type DiagramConnection } from '../../core/diagrams/diagramConnection';
import { flattenGrid, resolveScene, type GridBox, type LineGridScene } from '../../core/diagrams/lineGrid';
import { projectDiagramContent, type DiagramViews } from './diagramViewState';

export interface AnchorPoint { x: number; y: number; side: 'left' | 'right' | 'top' | 'bottom'; proxy: boolean }
export interface FloatingBoxArrow {
  kind: 'arrow'; id: string; edgeId: string;
  coordinateSpace: 'canvas'; position: { x: number; y: number }; bounds: { width: number; height: number };
  source?: AnchorPoint; target?: AnchorPoint; path?: string;
  label?: { text: string; position: { x: number; y: number } };
  status: 'resolved' | 'proxy' | 'stale' | 'pending' | 'blocked';
  geometrySource: 'measured' | 'estimated';
}
type Rect = { x: number; y: number; width: number; height: number; proxy: boolean };

function resolveEndpoint(scene: LineGridScene, views: DiagramViews | undefined, anchor: DiagramAnchor,
  cell: { width: number; height: number }): { identity: EndpointIdentity; rect: Rect } | undefined {
  const box = connectionBox(scene, anchor.displayNodeId);
  if (!box) return;
  const visible = flattenGrid(resolveScene(scene));
  const ancestry = (node: GridBox, path: GridBox[]): GridBox[] | undefined => node.id === box.id ? [...path, node]
    : node.kind === 'container' ? node.children.map(child => ancestry(child, [...path, node])).find(Boolean) : undefined;
  const path = ancestry(scene.root, [])!;
  const owner = [...path].reverse().map(parent => visible.find(item => item.box.id === parent.id)).find(Boolean)!;
  const rect: Rect = { x: owner.bounds.column * cell.width, y: owner.bounds.row * cell.height,
    width: owner.bounds.columns * cell.width, height: owner.bounds.rows * cell.height, proxy: owner.box.id !== box.id };
  const boxIdentity = { displayNodeId: `grid:${owner.box.id}` };
  if (anchor.kind === 'box') return { identity: boxIdentity, rect };
  if (box.kind !== 'diagram') return;
  const content = scene.contents[box.contentId].content;
  if (content.revisionId !== anchor.revisionId) return;
  const nodes = connectionContentNodes(content);
  let node = nodes.find(node => node.id === anchor.contentNodeId);
  if (!node) return;
  if (rect.proxy || box.collapsed) return { identity: boxIdentity, rect: { ...rect, proxy: true } };
  const projection = projectDiagramContent(content, views?.[anchor.displayNodeId]);
  while (projection.rowForLine(node.line) === undefined) {
    node = nodes.find(candidate => candidate.id === node!.parentId);
    if (!node) return;
    rect.proxy = true;
  }
  return { identity: { displayNodeId: anchor.displayNodeId, contentNodeId: node.id, revisionId: content.revisionId },
    rect: { x: rect.x + (node.startColumn - 1) * cell.width,
    y: rect.y + projection.rowForLine(node.line)! * cell.height,
    width: (node.endColumn - node.startColumn + 1) * cell.width, height: cell.height, proxy: rect.proxy } };
}
function point(rect: Rect, other: Rect, side: DiagramAnchor['side'], offset = 0.5): AnchorPoint {
  const dx = other.x + other.width / 2 - rect.x - rect.width / 2;
  const dy = other.y + other.height / 2 - rect.y - rect.height / 2;
  const resolved = side === 'auto' ? Math.abs(dx) >= Math.abs(dy) ? dx >= 0 ? 'right' : 'left' : dy >= 0 ? 'bottom' : 'top' : side;
  return { x: resolved === 'left' ? rect.x : resolved === 'right' ? rect.x + rect.width : rect.x + rect.width * offset,
    y: resolved === 'top' ? rect.y : resolved === 'bottom' ? rect.y + rect.height : rect.y + rect.height * offset,
    side: resolved, proxy: rect.proxy };
}
/** Route between fixed border sides, avoiding both endpoint interiors. */
export function arrowPath(source: AnchorPoint, target: AnchorPoint, obstacles: readonly EndpointRect[] = []): string | undefined {
  const points = routeEdge(source, target, obstacles);
  return points && routePath(points);
}
export function drawEdge(edge: DiagramConnection, scene: LineGridScene, views: DiagramViews | undefined,
  cell: { width: number; height: number }, bounds?: EndpointBounds): FloatingBoxArrow {
  const a = resolveEndpoint(scene, views, edge.source, cell), b = resolveEndpoint(scene, views, edge.target, cell);
  const base = { kind: 'arrow' as const, id: `edge:${edge.id}`, edgeId: edge.id, coordinateSpace: 'canvas' as const,
    geometrySource: bounds ? 'measured' as const : 'estimated' as const,
    position: { x: 0, y: 0 }, bounds: { width: 1, height: 1 } };
  if (!a || !b) return { ...base, status: 'stale' };
  const ar = bounds ? bounds[endpointKey(a.identity)] : a.rect, br = bounds ? bounds[endpointKey(b.identity)] : b.rect;
  if (!ar || !br) return { ...base, status: 'pending' };
  const sourceRect = { ...ar, proxy: a.rect.proxy }, targetRect = { ...br, proxy: b.rect.proxy };
  const source = point(sourceRect, targetRect, edge.source.side, edge.source.offset);
  const target = point(targetRect, sourceRect, edge.target.side, edge.target.offset);
  const points = routeEdge(source, target, [ar, br]);
  if (!points) return { ...base, source, target, status: 'blocked' };
  const xs = points.map(p => p.x), ys = points.map(p => p.y);
  const label = getArrowLabel(edge.appearance);
  return { ...base, source, target, path: routePath(points), status: a.rect.proxy || b.rect.proxy ? 'proxy' : 'resolved',
    label: { text: label.text, position: label.position ?? { x: (source.x + target.x) / 2, y: (source.y + target.y) / 2 - 8 } },
    position: { x: Math.min(...xs) - 6, y: Math.min(...ys) - 6 },
    bounds: { width: Math.max(...xs) - Math.min(...xs) + 12, height: Math.max(...ys) - Math.min(...ys) + 12 } };
}

import { composeScene, flattenGrid, resolveScene, type LineGridScene } from '../../core/diagrams/lineGrid';
import { diagramTextRanges, textRow, type DiagramTextRange } from '../../core/diagrams/diagramText';
import { projectDiagramContent, type DiagramViews } from './diagramViewState';
import type { CanvasJump } from '../../core/diagrams/canvasJump';

/** composeScene remains the authority for character placement and collision validation. */
export function diagramSceneText(scene: LineGridScene, views?: DiagramViews, jumps: readonly CanvasJump[] = []) {
  const boxes = new Map(flattenGrid(resolveScene(scene)).map(box => [box.box.id, box]));
  const ranges = new Map<number, DiagramTextRange[]>();
  const ascii = composeScene(scene, (diagram, box) => {
    const projection = projectDiagramContent(diagram.content, box.collapsed ? undefined : views?.[`grid:${box.id}`]);
    const local = diagramTextRanges({ ascii: diagram.content.ascii, content: diagram.content,
      displayNodeId: `grid:${box.id}`, mappings: diagram.sourceContext.mappings,
      jumps: [...(diagram.jumps ?? []), ...jumps.filter(jump => jump.sourceDisplayNodeId === `grid:${box.id}`)] });
    const { column, row } = boxes.get(box.id)!.bounds;
    projection.sourceLines.forEach((line, visibleRow) => {
      const target = row + visibleRow;
      ranges.set(target, [...(ranges.get(target) ?? []), ...(local.get(line) ?? []).map(range => ({ ...range,
        start: column + range.start, end: column + range.end,
        owner: range.owner ? { ...range.owner, columnOffset: column } : undefined }))]);
    });
    return projection.ascii;
  });
  return { ascii, rows: ascii.split('\n').map((line, row) => textRow(line, ranges.get(row) ?? [])) };
}

import { visibleContentLines, type DiagramContent } from '../../core/diagrams/diagramContent';
import type { Diagram, GridBox, LineGridScene } from '../../core/diagrams/lineGrid';
import type { MappingPocGridRect } from '../selection/mappingPoc';

/** Presentation of one diagram instance; never part of its source content. */
export interface DiagramViewState {
  contentRevisionId: string;
  collapsedContentNodeIds: string[];
}
export type DiagramViews = Record<string, DiagramViewState>;
export function resolveDiagramContent(diagram: Diagram): DiagramContent { return diagram.content; }
export function projectDiagramContent(content: DiagramContent, view?: DiagramViewState) {
  const collapsed = view?.contentRevisionId === content.revisionId ? view.collapsedContentNodeIds : [];
  const sourceLines = visibleContentLines(content, collapsed);
  const rows = content.ascii.split('\n');
  const rowByLine = new Map(sourceLines.map((line, row) => [line, row]));
  return {
    ascii: sourceLines.map(line => rows[line - 1]).join('\n'), sourceLines,
    rowForLine: (line: number) => rowByLine.get(line),
    lineForRow: (row: number) => sourceLines[row],
    /** Only exact, contiguous source regions can carry an editable selection. */
    rect: (rect: MappingPocGridRect): MappingPocGridRect | undefined => {
      const start = rowByLine.get(rect.startLine), end = rowByLine.get(rect.endLine);
      if (start === undefined || end === undefined || end - start !== rect.endLine - rect.startLine) return undefined;
      return { ...rect, startLine: start + 1, endLine: end + 1 };
    }
  };
}
export function diagramProjection(scene: LineGridScene, boxId: string, contentId: string, views?: DiagramViews) {
  return projectDiagramContent(resolveDiagramContent(scene.contents[contentId]), views?.[`grid:${boxId}`]);
}
/** Prune deleted owners and revision-scoped IDs on every document mutation. */
export function normalizeDiagramViews(scene: LineGridScene, views?: DiagramViews): DiagramViews | undefined {
  if (!views || !Object.keys(views).length) return views;
  const valid: DiagramViews = {};
  const visit = (box: GridBox) => {
    const key = `grid:${box.id}`, view = views[key];
    if (box.kind === 'container') { box.children.forEach(visit); return; }
    if (!view) return;
    const content = resolveDiagramContent(scene.contents[box.contentId]);
    if (content.revisionId !== view.contentRevisionId || content.structure.kind !== 'tree') return;
    const nodes = content.structure.nodes;
    const ids = view.collapsedContentNodeIds.filter(id => Object.hasOwn(nodes, id) && nodes[id].childIds.length);
    valid[key] = ids.length === view.collapsedContentNodeIds.length ? view : { ...view, collapsedContentNodeIds: ids };
  };
  visit(scene.root);
  return Object.keys(valid).length === Object.keys(views).length && Object.keys(valid).every(key => valid[key] === views[key]) ? views : valid;
}

