  return { newerRevision: false, document: { ...doc, document, history: historyFromRevision(latest),
    name: representation.name, savedName: representation.name, revisionId: latest.id,
    savedScene: JSON.stringify(document.scene), savedEdges: JSON.stringify(document.edges) } };
}

import { formatAsciiWithCodeReferences } from '../../core/diagrams/diagramClipboard';
import { asciiForSelection } from '../../core/diagrams/diagramSelection';
import type { Diagram } from '../../core/diagrams/lineGrid';
import type { MappingPocGridRect } from '../selection/mappingPoc';
import { diagramSelectionNodes } from './mappingDocument';

/** Exact payload of the canvas Copy ASCII + code refs action. No clipboard access. */
export function selectionClipboardText(diagram: Diagram, rect: MappingPocGridRect | null, selectedIds: readonly string[]): string | null {
  if (!rect) return null;
  const ids = new Set(selectedIds);
  const references = diagramSelectionNodes(diagram).filter(node => ids.has(node.id)).flatMap(node =>
    node.sourceRanges.map(range => `${node.label}: ${range.path}:${range.startLine}-${range.endLine}`));
  return formatAsciiWithCodeReferences([asciiForSelection(diagram.content.ascii, rect)], references);
}

import { canvasTransferSchema } from '../../core/diagrams/canvasTransfer';
import { CanvasHistory, currentHistoryChanges, documentFromHistory, validateCanvasHistory, type CanvasHistoryRecord, type HistoryChanges, type HistoryValidation } from '../../core/diagrams/canvasHistory';
import type { StorageChange } from '../../core/storage/storageService';
import { deserializeWorkspace } from './mappingWorkspaceCodec';
import type { MappingDocumentSnapshot, MappingWorkspaceSnapshot, MappingCanvasState } from './mappingWorkspace';

export type WorkspaceRecords = Record<string, unknown>;
export interface WorkspaceIndex { projectId: string; documentIds: string[]; activeDocumentId?: string; transfers: NonNullable<MappingWorkspaceSnapshot['transfers']> }
export interface WorkspaceBatch { requestId: string; expectedRevision: number; changes: StorageChange[] }
export interface WorkspaceRecordState { revision: number; records: WorkspaceRecords }
export const documentPrefix = (id: string) => `document/${encodeURIComponent(id)}/`;
export function historyChanges(id: string, history: HistoryChanges): StorageChange[] {
  const prefix = documentPrefix(id);
  return [
    { key: prefix + 'history', value: history.header },
    ...Object.entries(history.snapshots).map(([key, value]) => ({ key: prefix + 'checkpoint/' + key, value })),
    ...Object.entries(history.diagramRevisions).map(([key, value]) => ({ key: prefix + 'revision/' + key, value }))
  ];
}
export function documentRecords(doc: MappingDocumentSnapshot): WorkspaceRecords {
  const { document, canvas, history, viewport, savedName, savedScene, savedEdges, revisionId, ...metadata } = doc;
  const changes = new CanvasHistory(document, canvas, history).persistenceChanges();
  const prefix = documentPrefix(doc.representationId);
  return Object.fromEntries([
    ...historyChanges(doc.representationId, changes).map(change => [change.key, 'value' in change ? change.value : undefined]),
    [prefix + 'metadata', metadata], [prefix + 'baseline', { savedName, savedScene, savedEdges, revisionId }],
    [prefix + 'canvas', canvas], ...(viewport ? [[prefix + 'viewport', viewport]] : [])
  ]);
}
export function workspaceRecords(workspace: MappingWorkspaceSnapshot): WorkspaceRecords {
  return Object.assign({ workspace: { projectId: workspace.projectId, activeDocumentId: workspace.activeDocumentId,
    documentIds: workspace.documents.map(doc => doc.representationId), transfers: workspace.transfers ?? [] } satisfies WorkspaceIndex },
  ...workspace.documents.map(documentRecords));
}
export function recordHistory(records: WorkspaceRecords, id: string): CanvasHistoryRecord {
  const prefix = documentPrefix(id);
  return { ...records[prefix + 'history'] as HistoryChanges['header'],
    snapshots: Object.fromEntries(Object.entries(records).filter(([key]) => key.startsWith(prefix + 'checkpoint/')).map(([key, value]) => [key.slice((prefix + 'checkpoint/').length), value])),
    diagramRevisions: Object.fromEntries(Object.entries(records).filter(([key]) => key.startsWith(prefix + 'revision/')).map(([key, value]) => [key.slice((prefix + 'revision/').length), value]))
  } as CanvasHistoryRecord;
}
export function recordDocument(records: WorkspaceRecords, id: string): MappingDocumentSnapshot {
  const prefix = documentPrefix(id), history = recordHistory(records, id);
  return { ...records[prefix + 'metadata'] as object, ...records[prefix + 'baseline'] as object,
    representationId: id, document: documentFromHistory(history), history,
    canvas: records[prefix + 'canvas'] as MappingCanvasState,
    ...(records[prefix + 'viewport'] ? { viewport: records[prefix + 'viewport'] } : {}) } as MappingDocumentSnapshot;
}
export function recordsWorkspace(records: WorkspaceRecords): MappingWorkspaceSnapshot | null {
  const index = records.workspace as WorkspaceIndex | undefined;
  return index ? { schemaVersion: 3, projectId: index.projectId, activeDocumentId: index.activeDocumentId,
    transfers: index.transfers, documents: index.documentIds.map(id => recordDocument(records, id)) } : null;
}
/** Save projection, separate from full import validation. Called on the worker's copy. */
export function normalizeRecord(key: string, value: unknown): unknown {
  if (!key.endsWith('/canvas')) return value;
  const canvas = value as MappingCanvasState;
  for (const node of Object.values(canvas.display.nodes)) if (node.kind === 'conversation') {
    if (node.thread.pending && node.thread.context) node.thread.error = 'Reply interrupted by workspace reload. Retry to continue.';
    delete node.thread.progress; node.thread.pending = false;
  }
  for (const surface of Object.values(canvas.controls.surfaces)) if (surface.promptPhase === 'generating') {
    surface.promptPhase = 'error'; surface.statusMessage = 'Operation interrupted by workspace reload; review before retrying.';
  }
  return value;
}
/** Validate changed records and their references; previously accepted history is not reparsed. */
export function validateRecordUpdate(records: WorkspaceRecords, keys: string[], projectId: string, historyValidation: HistoryValidation = 'all'): void {
  const index = records.workspace as WorkspaceIndex;
  if (!index || index.projectId !== projectId || !Array.isArray(index.documentIds) || new Set(index.documentIds).size !== index.documentIds.length
    || index.documentIds.length > 100 || !Array.isArray(index.transfers)) throw Error('Invalid workspace index');
  if (index.documentIds.some(id => typeof id !== 'string' || !id || id.length > 200 || ['__proto__', 'constructor', 'prototype'].includes(id))) throw Error('Invalid canvas ID');
  if (index.activeDocumentId !== undefined && !index.documentIds.includes(index.activeDocumentId)) throw Error('Invalid active canvas');
  const prefixes = new Set(index.documentIds.map(id => documentPrefix(id)));
  for (const key of Object.keys(records)) {
    if (key !== 'workspace' && !prefixes.has(key.slice(0, key.indexOf('/', 'document/'.length) + 1))) throw Error('Record belongs to a removed canvas');
  }
  const affected = new Set<string>();
  for (const key of keys) {
    if (key === 'workspace') continue;
    const match = /^document\/([^/]+)\/(metadata|baseline|canvas|viewport|history|checkpoint\/[^/]+|revision\/[^/]+)$/.exec(key);
    if (!match) throw Error('Invalid workspace record key');
    const id = decodeURIComponent(match[1]);
    if (!id || match[1] !== encodeURIComponent(id) || ['__proto__', 'constructor', 'prototype'].includes(id)) throw Error('Invalid canvas ID');
    if (index.documentIds.includes(id)) affected.add(id);
    else if (Object.hasOwn(records, key)) throw Error('Record belongs to a removed canvas');
  }
  for (const id of index.documentIds) {
    const prefix = documentPrefix(id);
    if (!records[prefix + 'metadata'] || !records[prefix + 'baseline'] || !records[prefix + 'history'] || !records[prefix + 'canvas']) throw Error('Incomplete canvas');
  }
  for (const id of affected) {
    const prefix = documentPrefix(id), history = recordHistory(records, id);
    const removesHistory = keys.some(k => (k.startsWith(prefix + 'revision/') || k.startsWith(prefix + 'checkpoint/')) && !Object.hasOwn(records, k));
    validateCanvasHistory(history, historyValidation === 'current' ? currentHistoryChanges(history) : removesHistory ? undefined : {
      revisions: keys.filter(k => k.startsWith(prefix + 'revision/') && Object.hasOwn(records, k)).map(k => k.slice((prefix + 'revision/').length)),
      snapshots: keys.filter(k => k.startsWith(prefix + 'checkpoint/') && Object.hasOwn(records, k)).map(k => k.slice((prefix + 'checkpoint/').length))
    });
    // Current presentation/composition validation never includes accumulated history.
    const { history: _, ...doc } = recordDocument(records, id);
    deserializeWorkspace({ schemaVersion: 3, projectId, documents: [doc] });
  }
  // Cross-canvas transaction references are small and checked as one batch.
  if (new Set(index.transfers.map(tx => tx.id)).size !== index.transfers.length) throw Error('Duplicate transfer');
  for (const tx of index.transfers) {
    canvasTransferSchema.parse(tx);
    if (!index.documentIds.includes(tx.sourceId) || !index.documentIds.includes(tx.destinationId) || tx.sourceId === tx.destinationId) throw Error('Missing transfer participant');
    for (const [id, before, after] of [[tx.sourceId, tx.sourceBefore, tx.sourceAfter], [tx.destinationId, tx.destinationBefore, tx.destinationAfter]]) {
      if (!records[documentPrefix(id) + 'checkpoint/' + before] || !records[documentPrefix(id) + 'checkpoint/' + after]) throw Error('Missing transfer checkpoint');
    }
    const destination = records[documentPrefix(tx.destinationId) + 'checkpoint/' + tx.destinationAfter] as { transactionId?: string };
    const source = records[documentPrefix(tx.sourceId) + 'checkpoint/' + tx.sourceAfter] as { transactionId?: string };
    if (destination.transactionId !== tx.id || tx.mode === 'move' && source.transactionId !== tx.id) throw Error('Unlinked transfer');
  }
}

import type { AgentContext } from '../../../domain/core/agents/agentContext';
import { type Model } from "@earendil-works/pi-ai";
import { createAgentSession, SessionManager, type CreateAgentSessionOptions, ModelRuntime, type AgentSessionEvent } from "@earendil-works/pi-coding-agent";
import { DEFAULT_DIAGRAM_MODEL_ID, type AgentProgress } from "../../../domain/core/records/domain";
export function progressFor(event: AgentSessionEvent, model: string, sessionId: string): AgentProgress | undefined {
  const shared = { model, sessionId };
  if (event.type === "agent_start" || event.type === "turn_start" || event.type === "message_start") {
    return { ...shared, status: "generating", message: "agent is composing a structured result" };
  }
  if (event.type === "tool_execution_start") {
    if (["read", "grep", "find", "ls"].includes(event.toolName)) {
      return { ...shared, status: "reading-context", message: `inspecting source with ${event.toolName}` };
    }
    if (event.toolName.startsWith("submit_")) {
      return { ...shared, status: "validating", message: "validating structured submission" };
    }
  }
  return undefined;
}
export class PiAgentRuntime {

  protected modelRuntime?: Promise<ModelRuntime>;

  protected readonly sessions = new Set<{ abort(): Promise<void>; dispose(): void }>();

  protected async createSession(configuration: Omit<CreateAgentSessionOptions, 'sessionManager'>, context?: AgentContext) {
    const sessionManager = SessionManager.inMemory(configuration.cwd);
    for (const message of context?.toPiMessages() ?? []) sessionManager.appendMessage(message);
    const result = await createAgentSession({ ...configuration, sessionManager });
    this.sessions.add(result.session);
    return result;
  }

  protected runtime(): Promise<ModelRuntime> {
    this.modelRuntime ??= ModelRuntime.create({ allowModelNetwork: false });
    return this.modelRuntime;
  }

  protected async model(overrideModelId?: string): Promise<{
    runtime: ModelRuntime;
    model: Model<any>;
    provider: string;
    modelId: string;
  }> {
    const runtime = await this.runtime();
    const provider = "openai-codex";
    const modelId = overrideModelId || process.env.NEW_DIAGRAM_MODEL || DEFAULT_DIAGRAM_MODEL_ID;
    const model = runtime.getModel(provider, modelId);
    if (!model) throw new Error(`Pi model is unavailable: ${provider}/${modelId}`);
    if (!runtime.hasConfiguredAuth(provider)) {
      throw new Error(`Pi provider is not authenticated: ${provider}`);
    }
    return { runtime, model, provider, modelId };
  }
  dispose(): void {
    for (const session of this.sessions) { void session.abort(); session.dispose(); }
    this.sessions.clear();
  }
}

export interface ValidatedSubmissionOptions<T> {
  toolName: string;
  validate(candidate: T): Promise<string | undefined> | string | undefined;
  acceptedMessage(candidate: T): string;
  acceptedDetails?(candidate: T): Record<string, unknown>;
  correctionPrompt?: string;
}

export function createValidatedSubmission<T>(options: ValidatedSubmissionOptions<T>) {
  let accepted: T | undefined;

  return {
    promptGuideline: `Call ${options.toolName} with the final candidate. If it is rejected, correct the reported issues and call it again.`,

    get value(): T | undefined {
      return accepted;
    },

    async execute(_toolCallId: string, candidate: T) {
      const validationError = await options.validate(candidate);
      if (validationError) {
        const correction = options.correctionPrompt
          ? `${options.correctionPrompt} Then call ${options.toolName} again.`
          : `Correct the submission and call ${options.toolName} again.`;
        return {
          content: [{
            type: "text" as const,
            text: `Submission rejected: ${validationError}. ${correction}`
          }],
          details: { accepted: false },
          terminate: false
        };
      }

      accepted = candidate;
      return {
        content: [{ type: "text" as const, text: options.acceptedMessage(candidate) }],
        details: {
          accepted: true,
          ...options.acceptedDetails?.(candidate)
        },
        terminate: true
      };
    }
  };
}

import {
  lstat,
  readdir,
  readFile,
  realpath,
  stat
} from "node:fs/promises";
import path from "node:path";
import type { CorpusBinding, CorpusDirectoryListing, CorpusProvider } from "../../../domain/core/profiles/domainProfile";
import type { SourceRange } from "../../../domain/core/records/domain";

function relativeSegments(value: string, label: string): string[] {
  if (value.includes("\0") || value.includes("\\")) {
    throw new Error(`${label} path is invalid`);
  }
  if (path.posix.isAbsolute(value) || path.win32.isAbsolute(value)) {
    throw new Error(`${label} path must be relative`);
  }
  const segments = value === "" ? [] : value.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === "..")) {
    throw new Error(`${label} path is invalid`);
  }
  return segments;
}

async function canonicalBindingRoot(binding: CorpusBinding, expectedKind: CorpusBinding["kind"]): Promise<string> {
  if (binding.kind !== expectedKind) {
    throw new Error(`corpus provider ${expectedKind} cannot read ${binding.kind}`);
  }
  const root = await realpath(binding.root).catch(() => null);
  if (!root || !(await stat(root)).isDirectory()) {
    throw new Error(`corpus root is not a directory: ${path.resolve(binding.root)}`);
  }
  return root;
}

async function resolveWithoutSymlinks(
  root: string,
  relativePath: string,
  label: string
): Promise<string> {
  const segments = relativeSegments(relativePath, label);
  let resolved = root;
  for (const segment of segments) {
    resolved = path.join(resolved, segment);
    const info = await lstat(resolved).catch(() => null);
    if (!info) throw new Error(`unknown ${label} path: ${relativePath}`);
    if (info.isSymbolicLink()) {
      throw new Error(label === "corpus directory"
        ? "symbolic-link directories cannot be traversed"
        : "symbolic-link corpus file paths cannot be traversed");
    }
  }
  if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) {
    throw new Error(`${label} path escapes corpus root`);
  }
  return resolved;
}

class FilesystemCorpusProvider implements CorpusProvider {
  constructor(readonly kind: CorpusBinding["kind"]) { }

  async listDirectory(
    binding: CorpusBinding,
    directory: string
  ): Promise<CorpusDirectoryListing> {
    const root = await canonicalBindingRoot(binding, this.kind);
    const directoryPath = await resolveWithoutSymlinks(root, directory, "corpus directory");
    if (!(await stat(directoryPath)).isDirectory()) {
      throw new Error(`corpus path is not a directory: ${directory}`);
    }
    const entries = (await readdir(directoryPath, { withFileTypes: true }))
      .filter((entry) => entry.name !== ".git")
      .map((entry) => ({
        path: path.relative(root, path.join(directoryPath, entry.name)).split(path.sep).join("/"),
        name: entry.name,
        kind: entry.isDirectory() && !entry.isSymbolicLink()
          ? "directory" as const
          : "file" as const
      }))
      .sort((left, right) => (
        (left.kind === right.kind ? 0 : left.kind === "directory" ? -1 : 1)
        || left.name.localeCompare(right.name, undefined, { sensitivity: "base" })
        || left.path.localeCompare(right.path)
      ));
    return { directory: relativeSegments(directory, "corpus directory").join("/"), entries };
  }

  async readLines(binding: CorpusBinding, range: SourceRange): Promise<string[]> {
    if (!Number.isInteger(range.startLine) || !Number.isInteger(range.endLine)
      || range.startLine < 1 || range.endLine < range.startLine) {
      throw new Error(`invalid evidence range for ${range.path}`);
    }
    const lines = await this.readDocumentLines(binding, range.path);
    return lines.slice(range.startLine - 1, Math.min(range.endLine, lines.length));
  }

  async readDocumentLines(binding: CorpusBinding, relativePath: string): Promise<string[]> {
    return (await this.readDocumentText(binding, relativePath)).split(/\r?\n/);
  }

  async readDocumentText(binding: CorpusBinding, relativePath: string): Promise<string> {
    return (await this.readDocumentBytes(binding, relativePath)).toString("utf8");
  }

  async readDocumentBytes(binding: CorpusBinding, relativePath: string): Promise<Buffer> {
    const root = await canonicalBindingRoot(binding, this.kind);
    const filePath = await resolveWithoutSymlinks(root, relativePath, "corpus file");
    if (!(await stat(filePath)).isFile()) throw new Error(`corpus path is not a file: ${relativePath}`);
    return readFile(filePath);
  }
}

export type ReadableCorpusProvider = CorpusProvider & {
  readDocumentBytes(binding: CorpusBinding, relativePath: string): Promise<Buffer>;
  readDocumentText(binding: CorpusBinding, relativePath: string): Promise<string>;
  readDocumentLines(binding: CorpusBinding, relativePath: string): Promise<string[]>;
};

const providers: Record<CorpusBinding["kind"], ReadableCorpusProvider> = {
  "git-worktree": new FilesystemCorpusProvider("git-worktree"),
  "filesystem-documents": new FilesystemCorpusProvider("filesystem-documents")
};

export function corpusProvider(binding: CorpusBinding): ReadableCorpusProvider {
  return providers[binding.kind];
}

export async function readCorpusDocumentLines(
  binding: CorpusBinding,
  relativePath: string
): Promise<string[]> {
  return corpusProvider(binding).readDocumentLines(binding, relativePath);
}

import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { realpath } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { CancellationTokenSource, createMessageConnection, StreamMessageReader, StreamMessageWriter } from 'vscode-jsonrpc/node.js';
import type { CorpusBinding } from '../../../domain/core/profiles/domainProfile';
import { isRepositoryFilePath, supportsDefinitions, type SourceDefinitions, type SourceLocation, type SourcePosition } from '../../../domain/core/source/sourceNavigation';
import { corpusProvider } from '../corpus/corpus';
const require = createRequire(import.meta.url);
const liveSessions = new Set<LanguageSession>();
let signalHandlersInstalled = false;
function registerSession(session: LanguageSession) {
  liveSessions.add(session);
  if (signalHandlersInstalled) return;
  signalHandlersInstalled = true;
  for (const [signal, code] of [['SIGTERM', 143], ['SIGINT', 130]] as const) {
    process.once(signal, () => { for (const session of liveSessions) session.dispose(); process.exit(code); });
  }
}

class LanguageSession {
  private readonly child;
  private readonly rpc;
  private readonly ready: Promise<void>;
  private queue: Promise<unknown> = Promise.resolve();
  private idle?: ReturnType<typeof setTimeout>;
  dead = false;
  constructor(readonly root: string) {
    const cli = path.join(path.dirname(require.resolve('typescript-language-server/package.json')), 'lib/cli.mjs');
    this.child = spawn(process.execPath, [cli, '--stdio', '--log-level', '1'], { cwd: root, stdio: ['pipe', 'pipe', 'pipe'], detached: process.platform !== 'win32' });
    this.child.stderr.resume();
    this.rpc = createMessageConnection(new StreamMessageReader(this.child.stdout), new StreamMessageWriter(this.child.stdin));
    this.rpc.onRequest('workspace/configuration', (params: { items: unknown[] }) => params.items.map(() => ({})));
    this.rpc.onRequest('client/registerCapability', () => null);
    this.rpc.onRequest('workspace/applyEdit', () => ({ applied: false }));
    this.rpc.onError(() => this.dispose());
    this.child.on('error', () => this.dispose());
    this.child.on('exit', () => this.dispose());
    this.rpc.listen();
    registerSession(this);
    this.ready = this.bounded(async () => {
      const capabilities = await this.rpc.sendRequest<{ capabilities: { definitionProvider?: unknown; positionEncoding?: string } }>('initialize', {
        processId: process.pid, rootUri: pathToFileURL(root).href,
        capabilities: { general: { positionEncodings: ['utf-16'] }, textDocument: { definition: { linkSupport: true } } },
        workspaceFolders: [{ uri: pathToFileURL(root).href, name: path.basename(root) }],
        initializationOptions: { tsserver: { useSyntaxServer: 'never', path: require.resolve('typescript/lib/tsserver.js') } }
      });
      if (!capabilities.capabilities.definitionProvider || (capabilities.capabilities.positionEncoding && capabilities.capabilities.positionEncoding !== 'utf-16')) {
        throw new Error('Language server does not support UTF-16 definition lookup');
      }
      await this.rpc.sendNotification('initialized', {});
    });
    // Initialization may fail before the first queued request attaches.
    void this.ready.then(() => {
      this.scheduleIdle();
    }, () => this.dispose());
  }
  private scheduleIdle() {
    clearTimeout(this.idle);
    if (this.dead) return;
    this.idle = setTimeout(() => this.dispose(), 5 * 60_000);
    this.idle.unref();
  }
  private async bounded<T>(run: () => Promise<T>): Promise<T> {
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
      return await Promise.race([run(), new Promise<never>((_, reject) => {
        timer = setTimeout(() => { reject(new Error('Language server timed out; try again')); this.dispose(); }, 20000);
      })]);
    } finally { clearTimeout(timer); }
  }
  lookup(file: string, text: string, position: SourcePosition, signal?: AbortSignal): Promise<unknown> {
    const run = async () => {
      clearTimeout(this.idle);
      try {
        await this.ready;
        if (this.dead) throw new Error('Language server stopped; try again');
        signal?.throwIfAborted();
        const uri = pathToFileURL(path.join(this.root, file)).href;
        const cancellation = new CancellationTokenSource();
        const abort = () => cancellation.cancel();
        signal?.addEventListener('abort', abort, { once: true });
        try {
          await this.rpc.sendNotification('textDocument/didOpen', {
            textDocument: {
              uri, version: 1, text,
              languageId: /\.tsx$/i.test(file) ? 'typescriptreact' : /\.jsx$/i.test(file) ? 'javascriptreact' : /\.[cm]?ts$/i.test(file) ? 'typescript' : 'javascript'
            }
          });
          return await this.bounded(() => this.rpc.sendRequest('textDocument/definition', { textDocument: { uri }, position }, cancellation.token));
        } finally {
          signal?.removeEventListener('abort', abort);
          cancellation.dispose();
          if (!this.dead) await this.rpc.sendNotification('textDocument/didClose', { textDocument: { uri } });
        }
      } finally { this.scheduleIdle(); }
    };
    const result = this.queue.then(run);
    this.queue = result.catch(() => undefined);
    return result;
  }
  dispose() {
    if (this.dead) return;
    this.dead = true;
    liveSessions.delete(this);
    clearTimeout(this.idle);
    this.rpc.dispose();
    if (this.child.pid) {
      try { process.kill(process.platform === 'win32' ? this.child.pid : -this.child.pid, 'SIGTERM'); } catch { /* already exited */ }
    }
  }
}

/** One lazy TS/JS session per checkout, shared by every pane. */
export class ProjectLanguageService {
  private sessions = new Map<string, LanguageSession>();
  private disposed = false;
  private readonly exit = () => this.dispose();
  constructor() { process.once('exit', this.exit); }
  async definitions(binding: CorpusBinding, file: string, position: SourcePosition, sourceSha256: string, signal?: AbortSignal): Promise<SourceDefinitions> {
    if (this.disposed) throw new Error('Language service is stopped');
    signal?.throwIfAborted();
    if (!isRepositoryFilePath(file) || !supportsDefinitions(file)) throw new Error('Definitions are supported for TypeScript and JavaScript files');
    if (!position || !Number.isInteger(position.line) || position.line < 0 || !Number.isInteger(position.character) || position.character < 0) throw new Error('Invalid source position');
    const text = await corpusProvider(binding).readDocumentText(binding, file);
    if (createHash('sha256').update(text).digest('hex') !== sourceSha256) throw new Error('Source changed on disk. Reload the file before looking up definitions.');
    const line = text.split(/\r?\n/)[position.line];
    if (line === undefined || position.character > line.length) throw new Error('Source position is outside the file');
    const root = await realpath(binding.root);
    if (this.disposed) throw new Error('Language service is stopped');
    signal?.throwIfAborted();
    let session = this.sessions.get(root);
    if (!session || session.dead) { session = new LanguageSession(root); this.sessions.set(root, session); }
    const result = await session.lookup(file, text, position, signal);
    signal?.throwIfAborted();
    const locations: SourceLocation[] = [];
    let outsideRoot = 0;
    const seen = new Set<string>();
    for (const item of (Array.isArray(result) ? result : result ? [result] : []) as Array<{ uri?: string; targetUri?: string; range?: SourceLocation['range']; targetSelectionRange?: SourceLocation['range'] }>) {
      const uri = item.targetUri ?? item.uri;
      if (!uri?.startsWith('file:')) { outsideRoot++; continue; }
      const relative = path.relative(root, fileURLToPath(uri)).split(path.sep).join('/');
      if (!isRepositoryFilePath(relative)) { outsideRoot++; continue; }
      const location = { path: relative, range: item.targetSelectionRange ?? item.range };
      const key = JSON.stringify(location);
      if (!seen.has(key)) { seen.add(key); locations.push(location); }
    }
    return { locations, outsideRoot };
  }
  dispose() { this.disposed = true; for (const session of this.sessions.values()) session.dispose(); this.sessions.clear(); process.removeListener('exit', this.exit); }
}

import { DefaultCanvasHistoryService } from '../../../domain/core/diagrams/canvasHistoryService';
import { assertDiagramStorageFormat } from './diagramStorageFormat';
import path from 'node:path';
import type { AcceptCanvasChangesInput, ChangeSessionAcceptance } from '../../../domain/core/representations/changeAcceptance';
import { documentFromRevision, historyFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { ProjectProjectionRecord } from '../../../domain/core/diagrams/diagramProjection';
import type { SaveProjectDiagramInput } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { SaveProjectedTreeInput } from '../../../domain/core/representations/catalogCommands';
import type { ProjectRepresentationCatalogRecord } from '../../../domain/core/representations/projectCatalog';
import * as rules from '../../../domain/core/representations/catalogRules';
import { DiagramPersistence } from '../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from './diagramRevisionStore';
import { readJsonIfExists, writeJsonAtomic, emptyRepresentationCatalog, catalogEnvironment } from './catalogPersistence';

/** Canvas catalog owns composition/publication. DiagramService owns diagram persistence. */
export class CanvasCatalogStore {
  private readonly historyService = new DefaultCanvasHistoryService();
  constructor(readonly storeRoot: string,
    protected readonly diagramPersistence: DiagramPersistence = new DiagramPersistence(new DiagramRevisionStore(storeRoot))) {}

  private representationWrite: Promise<unknown> = Promise.resolve();
  private serialize<T>(write: () => Promise<T>): Promise<T> {
    const result = this.representationWrite.then(write);
    this.representationWrite = result.catch(() => undefined);
    return result;
  }

  saveProjection(projectId: string, projection: ProjectProjectionRecord) {
    return this.serialize(async () => {
      const catalog = await this.loadRepresentationCatalog(projectId);
      const result = rules.saveProjection(catalog, projectId, projection, catalogEnvironment());
      if (result.catalog !== catalog) await this.saveRepresentationCatalog(result.catalog);
      return result;
    });
  }

  /** Persist the generated tree and its relationship in one catalog write. */
  saveProjectedTree(projectId: string, input: SaveProjectedTreeInput) {
    return this.serialize(async () => {
      const catalog = await this.loadRepresentationCatalog(projectId);
      const result = rules.saveProjectedTree(catalog, projectId, input, catalogEnvironment());
      if (result.catalog !== catalog) await this.saveRepresentationCatalog(result.catalog);
      return result;
    });
  }

  saveMappingDiagram(projectId: string, input: SaveProjectDiagramInput) {
    return this.serialize(async () => {
      const catalog = await this.loadRepresentationCatalog(projectId);
      const result = rules.saveMappingDiagram(catalog, projectId, input, catalogEnvironment());
      if (result.catalog !== catalog) await this.saveRepresentationCatalog(result.catalog);
      return result;
    });
  }

  acceptCanvasChanges(projectId: string, input: AcceptCanvasChangesInput): Promise<ChangeSessionAcceptance> {
    return this.serialize(async () => {
      let catalog = await this.loadRepresentationCatalog(projectId);
      const prior = catalog.changeSessionAcceptances?.[input.changeSessionId];
      if (prior) {
        if (prior.requestId !== input.requestId || prior.sessionVersion !== input.sessionVersion)
          throw new Error('REQUEST_ID_CONFLICT: proposal already accepted');
        return prior;
      }
      if (!input.documents.length || new Set(input.documents.map(d => d.documentId)).size !== input.documents.length)
        throw new Error('Acceptance requires distinct changed documents');
      const targets = input.documents.flatMap(d => d.representationId ? [d.representationId] : []);
      if (new Set(targets).size !== targets.length) throw new Error('Duplicate acceptance target');
      const acceptance: ChangeSessionAcceptance = { changeSessionId: input.changeSessionId, sessionVersion: input.sessionVersion,
        requestId: input.requestId, acceptedAt: new Date().toISOString(), changeIds: [...input.changeIds], documents: [] };
      for (const doc of input.documents) {
        const current = doc.representationId ? catalog.representations[doc.representationId] : undefined;
        if (doc.representationId && (!current || current.status !== 'settled' || current.currentRevisionId !== doc.expectedRevisionId))
          throw new Error('VERSION_CONFLICT: original canvas changed; create a new proposal');
        const proposed = this.historyService.openContext(doc.document, doc.history.snapshots[doc.history.headId].view, doc.history);
        let history = this.historyService.forkContext(proposed, doc.history.snapshots[doc.history.headId].view);
        let before: ChangeSessionAcceptance['documents'][number]['before'] = null;
        if (current) {
          const revision = catalog.revisions[current.currentRevisionId], saved = historyFromRevision(revision);
          const context = this.historyService.openContext(documentFromRevision(revision), saved?.snapshots[saved.headId].view ?? {}, saved);
          before = { revisionId: revision.id, checkpointId: this.historyService.state(context).checkpointId };
          this.historyService.adopt(context, doc.history);
          history = this.historyService.exportContext(context);
        }
        const result = rules.saveMappingDiagram(catalog, projectId, { name: doc.name, representationId: doc.representationId,
          expectedRevisionId: doc.expectedRevisionId, scene: doc.document.scene, edges: doc.document.edges, history }, catalogEnvironment());
        catalog = result.catalog;
        acceptance.documents.push({ documentId: doc.documentId, representationId: result.representation.id, before,
          after: { revisionId: result.representation.currentRevisionId, checkpointId: history.headId }, proposedCheckpointId: doc.history.headId });
      }
      catalog = { ...catalog, changeSessionAcceptances: { ...catalog.changeSessionAcceptances, [input.changeSessionId]: acceptance } };
      // A failure before this write publishes none of the canvases. The receipt and
      // all new heads become visible in the same atomic catalog replacement.
      await this.saveRepresentationCatalog(catalog);
      return acceptance;
    });
  }

  private representationCatalogPath(): string {
    return path.join(this.storeRoot, 'canvases', 'catalog.json');
  }

  private async readStoredCatalog(projectId: string) {
    const raw = await readJsonIfExists<ProjectRepresentationCatalogRecord>(this.representationCatalogPath())
      ?? await readJsonIfExists<ProjectRepresentationCatalogRecord>(path.join(this.storeRoot, 'representations', 'catalog.json'));
    if (raw && raw.projectId !== projectId) throw new Error('representation catalog belongs to another Project');
    return raw;
  }

  /** Publication receipts contain no diagram references; listing proposals needs no restored catalog. */
  async loadChangeSessionAcceptances(projectId: string) {
    return (await this.readStoredCatalog(projectId))?.changeSessionAcceptances ?? {};
  }

  async loadRepresentationCatalog(projectId: string, historyValidation: import('../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all'): Promise<ProjectRepresentationCatalogRecord> {
    await assertDiagramStorageFormat(this.storeRoot);
    const raw = await this.readStoredCatalog(projectId);
    const stored = raw == null ? null : await this.diagramPersistence.restore<ProjectRepresentationCatalogRecord>(raw, historyValidation);
    if (!stored) return emptyRepresentationCatalog(projectId);
    if (stored.projectId !== projectId) {
      throw new Error("representation catalog belongs to another Project");
    }
    for (const revision of Object.values(stored.revisions)) if (revision.content?.kind !== 'canvas-history')
      throw new Error('Unsupported legacy diagram content: canvas history is required');
    return stored;
  }

  async saveRepresentationCatalog(catalog: ProjectRepresentationCatalogRecord): Promise<void> {
    await writeJsonAtomic(this.representationCatalogPath(), await this.diagramPersistence.persist(catalog));
  }

  archiveRepresentation(projectId: string, representationId: string) {
    return this.serialize(() => this.archiveRepresentationUnlocked(projectId, representationId));
  }

  private async archiveRepresentationUnlocked(
    projectId: string,
    representationId: string
  ): Promise<ProjectRepresentationCatalogRecord> {
    const catalog = await this.loadRepresentationCatalog(projectId);
    const result = rules.archiveRepresentation(catalog, projectId, representationId, catalogEnvironment());
    if (result !== catalog) await this.saveRepresentationCatalog(result);
    return result;
  }
}

import { createHash, randomUUID } from "node:crypto";
import {
  mkdir,
  readFile,
  rename,
  rm,
  writeFile
} from "node:fs/promises";
