    if (this.mappingPocSessions.size >= 12) {
      const oldest = [...this.mappingPocSessions.entries()]
        .sort((left, right) => left[1].lastUsedAt - right[1].lastUsedAt)[0];
      if (oldest) this.disposeMappingPocSession(oldest[0]);
