}
export async function startMappingMcpServer(baseUrl: string) { await createMappingMcpServer(baseUrl).connect(new StdioServerTransport()); }

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import type { CompactionSnapshot } from "../../../domain/core/representations/compactionProjection";
import type { FileCompactionRun } from "../../../domain/mapping/compaction/compactionRun";

import type { FileCompactionResult, FileCompactionStage } from "../../../domain/mapping/compaction/fileCompaction";
export type { FileCompactionRun } from "../../../domain/mapping/compaction/compactionRun";

export class FileCompactionStore {
  constructor(private readonly root: string) { }

  directory(id: string): string {
    if (!/^compaction-[0-9a-f-]{36}$/.test(id)) throw new Error("Invalid compaction run id");
    return path.join(this.root, "mapping", "compactions", id);
  }

  async create(run: FileCompactionRun, source: Buffer): Promise<void> {
    await mkdir(this.directory(run.id), { recursive: true });
    await writeFile(path.join(this.directory(run.id), "source.txt"), source, { flag: "wx" });
    await this.save(run);
  }

  async save(run: FileCompactionRun): Promise<void> {
    run.updatedAt = new Date().toISOString();
    const file = path.join(this.directory(run.id), "run.json");
    const temporary = `${file}.${randomUUID()}.tmp`;
    await writeFile(temporary, JSON.stringify(run, null, 2) + "\n");
    await rename(temporary, file);
  }

  async load(id: string): Promise<FileCompactionRun | null> {
    try { return JSON.parse(await readFile(path.join(this.directory(id), "run.json"), "utf8")); }
    catch (error) { if ((error as NodeJS.ErrnoException).code === "ENOENT") return null; throw error; }
  }

  artifacts(id: string): FileCompactionResult["artifacts"] {
    const base = path.relative(this.root, this.directory(id)).split(path.sep).join("/");
    return {
      compact: { text: `${base}/compact.txt`, mappings: `${base}/compact.json` },
      refine: { text: `${base}/refine.txt`, mappings: `${base}/refine.json` }
    };
  }

  async savePass(id: string, stage: FileCompactionStage, snapshot: CompactionSnapshot): Promise<void> {
    const directory = this.directory(id);
    await writeFile(path.join(directory, `${stage}.txt`), snapshot.ascii, { flag: "wx" });
    await writeFile(path.join(directory, `${stage}.json`), JSON.stringify({
      sourceFile: snapshot.sourceFile, sourceSha256: snapshot.sourceSha256,
      treeFile: `${stage}.txt`, mappings: snapshot.mappings
    }, null, 2) + "\n", { flag: "wx" });
  }
}

import { WorkspaceRecordStore } from './workspaceRecordStore';
import type { WorkspaceBatch } from '../../../../domain/mapping/workspace/workspaceRecords';
import { DiagramPersistence } from '../../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from '../../../core/persistence/diagramRevisionStore';
import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import type { MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import { deserializeWorkspace } from '../../../../domain/mapping/workspace/mappingWorkspaceCodec';
/** Separate from representation revisions: UI changes do not create diagram revisions. */
export class MappingWorkspaceStore {
  constructor(private readonly root: string, private readonly diagramPersistence: DiagramPersistence = new DiagramPersistence(new DiagramRevisionStore(root))) { this.records = new WorkspaceRecordStore(root); }
  private readonly records: WorkspaceRecordStore;
  loadRecords(projectId: string, historyValidation: import('../../../../domain/core/diagrams/canvasHistory').HistoryValidation = 'all') { return this.records.state(projectId, () => this.loadLegacy(projectId), historyValidation); }
  applyBatch(projectId: string, batch: WorkspaceBatch) { return this.records.apply(projectId, batch); }
  async load(projectId: string): Promise<MappingWorkspaceSnapshot | null> {
    return await this.records.load(projectId) ?? this.loadLegacy(projectId);
  }
  private async loadLegacy(projectId: string): Promise<MappingWorkspaceSnapshot | null> {
    let json: string;
    try { json = await readFile(path.join(this.root, 'mapping-workspace.json'), 'utf8'); }
    catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
    // A missing referenced diagram is corruption, not a missing workspace.
    const snapshot = deserializeWorkspace(await this.diagramPersistence.restore(JSON.parse(json)));
    if (snapshot.projectId !== projectId) throw new Error('Workspace belongs to another project');
    return snapshot;
  }

  async save(projectId: string, input: unknown): Promise<void> {
    const snapshot = deserializeWorkspace(input);
    if (snapshot.projectId !== projectId) throw new Error('Workspace belongs to another project');
    if (await this.records.replace(projectId, snapshot)) return;
    const json = JSON.stringify(await this.diagramPersistence.persist(snapshot));
    await mkdir(this.root, { recursive: true });
    const temp = path.join(this.root, `.mapping-workspace-${randomUUID()}.tmp`);
    try { await writeFile(temp, json, 'utf8'); await rename(temp, path.join(this.root, 'mapping-workspace.json')); }
    finally { await rm(temp, { force: true }); }
  }
}

import { createHash, randomUUID } from 'node:crypto';
import { assertDiagramStorageFormat } from '../../../core/persistence/diagramStorageFormat';
import { mkdir, readFile, rename, rm, open } from 'node:fs/promises';
import path from 'node:path';
import { ApplicationError } from '../../../../application/core/errors';
import { recordsWorkspace, validateRecordUpdate, workspaceRecords, type WorkspaceBatch, type WorkspaceRecords, type WorkspaceRecordState } from '../../../../domain/mapping/workspace/workspaceRecords';
import type { MappingWorkspaceSnapshot } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { HistoryValidation } from '../../../../domain/core/diagrams/canvasHistory';

interface Manifest { schemaVersion: 1; projectId: string; revision: number; records: Record<string, string>; receipts: Record<string, { hash: string; revision: number }> }
const queues = new Map<string, Promise<unknown>>();
const hash = (value: string) => createHash('sha256').update(value).digest('hex');
/** New records become reachable only through the final atomic manifest replacement. */
export class WorkspaceRecordStore {
  private cached?: { raw: string; manifest: Manifest; records: WorkspaceRecords; historyValidation: HistoryValidation };
  constructor(private readonly root: string) {}
  private get file() { return path.join(this.root, 'workspace-records.json'); }
  private serial<T>(run: () => Promise<T>): Promise<T> {
    const next = (queues.get(this.root) ?? Promise.resolve()).catch(() => {}).then(run);
    queues.set(this.root, next);
    void next.finally(() => { if (queues.get(this.root) === next) queues.delete(this.root); }).catch(() => {});
    return next;
  }
  private async read(projectId: string, historyValidation: HistoryValidation = 'all') {
    await assertDiagramStorageFormat(this.root);
    let raw: string;
    try { raw = await readFile(this.file, 'utf8'); } catch (e) { if ((e as NodeJS.ErrnoException).code === 'ENOENT') return undefined; throw e; }
    if (this.cached?.raw === raw) {
      if (this.cached.manifest.projectId !== projectId) throw Error('Workspace belongs to another project');
      if (historyValidation === 'all' && this.cached.historyValidation !== 'all') {
        if (Object.keys(this.cached.records).length) validateRecordUpdate(this.cached.records, Object.keys(this.cached.records), projectId);
        this.cached.historyValidation = 'all';
      }
      return this.cached;
    }
    const manifest = JSON.parse(raw) as Manifest;
    if (manifest.schemaVersion !== 1 || manifest.projectId !== projectId) throw Error('Workspace belongs to another project or has an invalid version');
    const records = Object.fromEntries(await Promise.all(Object.entries(manifest.records).map(async ([key, id]) => {
      if (!/^[a-f0-9]{64}$/.test(id)) throw Error('Invalid workspace record reference');
      const text = await readFile(path.join(this.root, 'workspace-records', id + '.json'), 'utf8');
      if (hash(text) !== id) throw Error('Workspace record integrity failure');
      return [key, JSON.parse(text)];
    })));
    if (Object.keys(records).length) validateRecordUpdate(records, Object.keys(records), projectId, historyValidation);
    return this.cached = { raw, manifest, records, historyValidation };
  }
  async load(projectId: string): Promise<MappingWorkspaceSnapshot | undefined> {
    const state = await this.read(projectId); return state ? recordsWorkspace(state.records)! : undefined;
  }
  async state(projectId: string, legacy: () => Promise<MappingWorkspaceSnapshot | null>, historyValidation: HistoryValidation = 'all'): Promise<WorkspaceRecordState> {
    return this.serial(async () => {
      let state = await this.read(projectId, historyValidation);
      if (!state) {
        const snapshot = await legacy();
        const records = snapshot ? workspaceRecords(snapshot) : {};
        state = await this.publish({ schemaVersion: 1, projectId, revision: 0, records: {}, receipts: {} }, records, Object.keys(records));
      }
      return { revision: state.manifest.revision, records: state.records };
    });
  }
  async replace(projectId: string, snapshot: MappingWorkspaceSnapshot): Promise<boolean> {
    return this.serial(async () => {
      const state = await this.read(projectId); if (!state) return false;
      const records = workspaceRecords(snapshot);
      await this.publish({ ...state.manifest, revision: state.manifest.revision + 1, records: {} }, records, Object.keys(records)); return true;
    });
  }
  async apply(projectId: string, input: WorkspaceBatch): Promise<{ revision: number }> {
    return this.serial(async () => {
      if (!input || typeof input.requestId !== 'string' || !/^[\w-]{1,150}$/.test(input.requestId) || !Number.isSafeInteger(input.expectedRevision)
        || !Array.isArray(input.changes) || input.changes.length > 100000) throw Error('Invalid workspace batch');
      const state = await this.read(projectId, 'current'); if (!state) throw Error('Initialize workspace storage first');
      const digest = hash(JSON.stringify(input)), receipt = Object.hasOwn(state.manifest.receipts, input.requestId) ? state.manifest.receipts[input.requestId] : undefined;
      if (receipt) {
        if (receipt.hash !== digest) throw new ApplicationError('conflict', 'REQUEST_ID_CONFLICT: different batch');
        return { revision: receipt.revision };
      }
      if (input.expectedRevision !== state.manifest.revision) throw new ApplicationError('conflict', 'VERSION_CONFLICT: workspace changed in another client; reload before saving');
      const records = { ...state.records }, keys: string[] = [], seen = new Set<string>();
      for (const change of input.changes) {
        if (!change || typeof change.key !== 'string' || change.key.length > 1000 || Object.keys(change).some(k => !['key', 'value', 'delete'].includes(k))
          || ('delete' in change ? change.delete !== true || 'value' in change : !('value' in change))) throw Error('Invalid record change');
        if (change.key !== 'workspace' && !/^document\//.test(change.key)) throw Error('Invalid workspace key');
        if (seen.has(change.key)) throw Error('Duplicate key in batch');
        seen.add(change.key); keys.push(change.key);
        if ('delete' in change) delete records[change.key]; else {
          const previous = records[change.key];
          if (previous && change.key.includes('/revision/') && JSON.stringify(previous) !== JSON.stringify(change.value)) throw Error('Immutable diagram revision changed');
          if (previous && change.key.includes('/checkpoint/')) {
            const { transactionId: _before, ...before } = previous as Record<string, unknown>;
            const { transactionId: _after, ...after } = change.value as Record<string, unknown>;
            if (JSON.stringify(before) !== JSON.stringify(after)) throw Error('Immutable canvas checkpoint changed');
          }
          records[change.key] = change.value;
        }
      }
      validateRecordUpdate(records, keys, projectId);
      const revision = state.manifest.revision + 1;
      try {
        await this.publish({ ...state.manifest, revision, records: { ...state.manifest.records },
          receipts: { ...state.manifest.receipts, [input.requestId]: { hash: digest, revision } } }, records, keys);
      } catch (error) {
        // Publication might have succeeded before a directory fsync or response
        // failed. The client must retry this ID to discover the durable receipt.
        throw new ApplicationError('storage-unavailable', error instanceof Error ? error.message : String(error));
      }
      return { revision };
    });
  }
  private async atomic(file: string, text: string) {
    await mkdir(path.dirname(file), { recursive: true });
    const temp = `${file}.${randomUUID()}.tmp`;
    try {
      const handle = await open(temp, 'wx');
      try { await handle.writeFile(text); await handle.sync(); } finally { await handle.close(); }
      await rename(temp, file);
      const dir = await open(path.dirname(file), 'r'); try { await dir.sync(); } finally { await dir.close(); }
    } finally { await rm(temp, { force: true }); }
  }
  private async publish(manifest: Manifest, records: WorkspaceRecords, keys: string[]) {
    // Serial writes bound descriptors and memory even during initial migration.
    for (const key of keys) {
      if (!Object.hasOwn(records, key)) { delete manifest.records[key]; continue; }
      const text = JSON.stringify(records[key]), id = hash(text);
      if (manifest.records[key] !== id) {
        const file = path.join(this.root, 'workspace-records', id + '.json');
        try { if (await readFile(file, 'utf8') !== text) throw Error('Workspace record integrity failure'); }
        catch (e) { if ((e as NodeJS.ErrnoException).code !== 'ENOENT') throw e; await this.atomic(file, text); }
        manifest.records[key] = id;
      }
    }
    const raw = JSON.stringify(manifest);
    await this.atomic(this.file, raw);
    return this.cached = { raw, manifest, records, historyValidation: 'current' };
  }
}

{
  "name": "@new-diagram/ui-test-framework",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "peerDependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  }
}

import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type ReactNode
} from "react";
import { createPortal } from "react-dom";
import "./styles.css";

type ToggleControl = {
  type: "toggle";
  label: string;
  description?: string;
  defaultValue: boolean;
};

type SelectControl<Value extends string = string> = {
  type: "select";
  label: string;
  description?: string;
  defaultValue: Value;
  options: readonly { value: Value; label: string }[];
};

type RangeControl = {
  type: "range";
  label: string;
  description?: string;
  defaultValue: number;
  min: number;
  max: number;
  step?: number;
};

type ColorControl = {
  type: "color";
  label: string;
  description?: string;
  defaultValue: string;
};

type UiTestControl = ToggleControl | SelectControl | RangeControl | ColorControl;
type UiTestControls = Record<string, UiTestControl>;
type ValueFor<Control extends UiTestControl> = Control extends ToggleControl
  ? boolean
  : Control extends SelectControl<infer Value>
    ? Value
    : Control extends RangeControl
      ? number
      : string;
type UiTestValues<Controls extends UiTestControls> = {
  [Key in keyof Controls]: ValueFor<Controls[Key]>;
};

function defaultsFor<Controls extends UiTestControls>(controls: Controls): UiTestValues<Controls> {
  return Object.fromEntries(
    Object.entries(controls).map(([id, control]) => [id, control.defaultValue])
  ) as UiTestValues<Controls>;
}

function validValue(control: UiTestControl, value: unknown): boolean {
  if (control.type === "toggle") return typeof value === "boolean";
  if (control.type === "select") {
    return typeof value === "string" && control.options.some((option) => option.value === value);
  }
  if (control.type === "range") {
    return typeof value === "number"
      && Number.isFinite(value)
      && value >= control.min
      && value <= control.max;
  }
  return typeof value === "string" && /^#[0-9a-f]{6}$/i.test(value);
}

export function normalizeStoredValues<Controls extends UiTestControls>(
  controls: Controls,
  stored: unknown
): UiTestValues<Controls> {
  const defaults = defaultsFor(controls);
  if (!stored || typeof stored !== "object" || Array.isArray(stored)) return defaults;
  const record = stored as Record<string, unknown>;
  return Object.fromEntries(Object.entries(controls).map(([id, control]) => [
    id,
    validValue(control, record[id]) ? record[id] : control.defaultValue
  ])) as UiTestValues<Controls>;
}

function readStoredValues<Controls extends UiTestControls>(
  controls: Controls,
  storageKey: string
): UiTestValues<Controls> {
  if (typeof window === "undefined") return defaultsFor(controls);
  try {
    const stored = window.localStorage.getItem(storageKey);
    return normalizeStoredValues(controls, stored ? JSON.parse(stored) : undefined);
  } catch {
    return defaultsFor(controls);
  }
}

function controlId(panelId: string, id: string): string {
  return `${panelId}-${id.replace(/[^a-zA-Z0-9_-]/g, "-")}`;
}

export function UiTestFramework<const Controls extends UiTestControls>(props: {
  id: string;
  controls: Controls;
  children: (values: UiTestValues<Controls>) => ReactNode;
  title?: string;
  persist?: boolean;
}) {
  const reactId = useId().replaceAll(":", "");
  const panelId = `ui-test-framework-${reactId}`;
  const storageKey = `ui-test-framework:${props.id}`;
  const persist = props.persist ?? true;
  const defaultValues = useMemo(() => defaultsFor(props.controls), [props.controls]);
  const [values, setValues] = useState<UiTestValues<Controls>>(() => (
    persist ? readStoredValues(props.controls, storageKey) : defaultValues
  ));
  const [open, setOpen] = useState(false);
  const dialRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLElement>(null);

  useEffect(() => {
    setValues((current) => normalizeStoredValues(props.controls, current));
  }, [props.controls]);

  useEffect(() => {
    if (!persist || typeof window === "undefined") return;
    try {
      window.localStorage.setItem(storageKey, JSON.stringify(values));
    } catch {
      // The tool remains usable when storage is unavailable or full.
    }
  }, [persist, storageKey, values]);

  useEffect(() => {
    if (!open) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      setOpen(false);
      requestAnimationFrame(() => dialRef.current?.focus());
    };
    const onPointerDown = (event: globalThis.PointerEvent) => {
      const target = event.target as Node | null;
      if (target && !panelRef.current?.contains(target) && !dialRef.current?.contains(target)) {
        setOpen(false);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("pointerdown", onPointerDown);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("pointerdown", onPointerDown);
    };
  }, [open]);

  const update = (id: keyof Controls, value: boolean | string | number) => {
    setValues((current) => ({ ...current, [id]: value }));
  };

  const controls = typeof document === "undefined" ? null : createPortal(
    <div className="ui-test-framework" data-ui-test-framework={props.id}>
      {open ? (
        <section
          ref={panelRef}
          id={panelId}
          className="ui-test-framework__panel"
          aria-label={props.title ?? "UI testing controls"}
        >
          <header>
            <div>
              <span>DEV TOOL</span>
              <strong>{props.title ?? "UI variants"}</strong>
            </div>
            <button
              type="button"
              onClick={() => setValues(defaultValues)}
              disabled={Object.entries(defaultValues).every(([id, value]) => values[id] === value)}
            >reset all</button>
          </header>
          <div className="ui-test-framework__controls">
            {Object.entries(props.controls).map(([id, control]) => {
              const inputId = controlId(panelId, id);
              const descriptionId = control.description ? `${inputId}-description` : undefined;
              const value = values[id];
              return (
                <div className="ui-test-framework__control" data-ui-test-control={id} key={id}>
                  <label htmlFor={inputId}>
                    <span>{control.label}</span>
                    {control.type === "range" ? <output>{String(value)}</output> : null}
                  </label>
                  {control.description ? <small id={descriptionId}>{control.description}</small> : null}
                  {control.type === "toggle" ? (
                    <input
                      id={inputId}
                      type="checkbox"
                      checked={Boolean(value)}
                      aria-describedby={descriptionId}
                      onChange={(event) => update(id, event.target.checked)}
                    />
                  ) : control.type === "select" ? (
                    <select
                      id={inputId}
                      value={String(value)}
                      aria-describedby={descriptionId}
                      onChange={(event) => update(id, event.target.value)}
                    >
                      {control.options.map((option) => (
                        <option value={option.value} key={option.value}>{option.label}</option>
                      ))}
                    </select>
                  ) : control.type === "range" ? (
                    <input
                      id={inputId}
                      type="range"
                      min={control.min}
                      max={control.max}
                      step={control.step ?? 1}
                      value={Number(value)}
                      aria-describedby={descriptionId}
                      onChange={(event) => update(id, Number(event.target.value))}
                    />
                  ) : (
                    <input
                      id={inputId}
                      type="color"
                      value={String(value)}
                      aria-describedby={descriptionId}
                      onChange={(event) => update(id, event.target.value)}
                    />
                  )}
                </div>
              );
            })}
          </div>
        </section>
      ) : null}
      <button
        ref={dialRef}
        type="button"
        className="ui-test-framework__dial"
        data-ui-test-dial="true"
        aria-label="Toggle UI testing controls"
        aria-controls={panelId}
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        <span aria-hidden="true">UI</span>
      </button>
    </div>,
    document.body
  );

  return <>{props.children(values)}{controls}</>;
}

.ui-test-framework {
  --ui-test-bg: #10151c;
  --ui-test-fg: #e6edf3;
  --ui-test-muted: #8b98a7;
  --ui-test-border: #475569;
  --ui-test-accent: #64d8e8;
  position: fixed;
  z-index: 1000;
  bottom: max(18px, env(safe-area-inset-bottom));
  left: max(18px, env(safe-area-inset-left));
  color: var(--ui-test-fg);
  font: 12px/1.35 ui-monospace, "SFMono-Regular", Menlo, Monaco, Consolas, monospace;
}

.ui-test-framework *, .ui-test-framework *::before, .ui-test-framework *::after { box-sizing: border-box; }

.ui-test-framework__dial {
  display: grid;
  width: 50px;
  height: 50px;
  border: 1px solid color-mix(in srgb, var(--ui-test-accent) 75%, white);
  border-radius: 50%;
  place-items: center;
  background: radial-gradient(circle at 35% 30%, #263747, var(--ui-test-bg) 68%);
  box-shadow: 0 8px 30px rgb(0 0 0 / 48%), inset 0 0 0 3px rgb(100 216 232 / 8%);
  color: var(--ui-test-accent);
  font: 800 11px/1 ui-monospace, monospace;
  letter-spacing: 0.08em;
  cursor: pointer;
}

.ui-test-framework__dial:hover,
.ui-test-framework__dial:focus-visible {
  outline: 2px solid var(--ui-test-accent);
  outline-offset: 3px;
  color: white;
  transform: translateY(-1px);
}

.ui-test-framework__panel {
  position: absolute;
  bottom: 62px;
  left: 0;
  width: min(320px, calc(100vw - 36px));
  max-height: min(560px, calc(100dvh - 100px));
  overflow: auto;
  border: 1px solid var(--ui-test-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--ui-test-bg) 96%, transparent);
  box-shadow: 0 18px 55px rgb(0 0 0 / 58%);
  backdrop-filter: blur(12px);
}

.ui-test-framework__panel > header {
  position: sticky;
  z-index: 1;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid rgb(148 163 184 / 18%);
  padding: 11px 12px;
  background: var(--ui-test-bg);
}

.ui-test-framework__panel > header div { display: grid; gap: 2px; }
.ui-test-framework__panel > header span { color: var(--ui-test-accent); font-size: 8px; letter-spacing: 0.16em; }
.ui-test-framework__panel > header strong { font-size: 12px; }
.ui-test-framework__panel > header button { border: 0; background: transparent; color: var(--ui-test-muted); font: inherit; cursor: pointer; }
.ui-test-framework__panel > header button:hover:not(:disabled) { color: var(--ui-test-accent); }
.ui-test-framework__panel > header button:disabled { opacity: 0.35; }
.ui-test-framework__controls { display: grid; gap: 1px; background: rgb(148 163 184 / 12%); }

.ui-test-framework__control {
  position: relative;
  display: grid;
  min-width: 0;
  gap: 7px;
  padding: 11px 12px;
  background: var(--ui-test-bg);
}

.ui-test-framework__control > label { display: flex; min-width: 0; align-items: center; justify-content: space-between; gap: 8px; }
.ui-test-framework__control > label span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ui-test-framework__control output { color: var(--ui-test-accent); font-size: 10px; }
.ui-test-framework__control small { color: var(--ui-test-muted); font-size: 9px; }
.ui-test-framework__control select { width: 100%; }
.ui-test-framework__control select,
.ui-test-framework__control input[type="color"] {
  min-height: 32px;
  border: 1px solid var(--ui-test-border);
  border-radius: 4px;
  padding: 4px 7px;
  background: #0a0f15;
  color: inherit;
  font: inherit;
}
.ui-test-framework__control input[type="range"] { width: 100%; accent-color: var(--ui-test-accent); }
.ui-test-framework__control input[type="checkbox"] { position: absolute; top: 10px; right: 12px; width: 30px; height: 18px; accent-color: var(--ui-test-accent); }
.ui-test-framework__control:has(input[type="checkbox"]) > label { padding-right: 38px; }
.ui-test-framework__control input:focus-visible,
.ui-test-framework__control select:focus-visible { outline: 2px solid var(--ui-test-accent); outline-offset: 2px; }

@media (max-width: 520px) {
  .ui-test-framework { bottom: 12px; left: 12px; }
  .ui-test-framework__panel { width: calc(100vw - 24px); }
}

import { useState } from 'react';
import { createMappingServices } from './services';
import { MappingPocPage } from "../features/mapping/MappingPage";

/** Every entry path opens the Mapping workspace, including old bookmarks. */
export function App() {
  const [services] = useState(createMappingServices);
  return <MappingPocPage services={services} />;
}

import { DefaultCanvasHistoryService } from '../../domain/core/diagrams/canvasHistoryService';
import { httpDiagramGenerator } from '../features/mapping/services/diagramGenerator';
import { WorkspaceStorage } from '../features/mapping/workspace/workspaceStorage';
import { RevisionedDiagramService } from '../../domain/core/diagrams/diagramService';
import { createHttpCodeRepoService } from '../shared/http/codeRepoService';
import type { MappingServices } from '../features/mapping/services/MappingServices';

export function createMappingServices(): MappingServices {
  return { canvasHistory: new DefaultCanvasHistoryService('current'), diagrams: new RevisionedDiagramService(httpDiagramGenerator), codeRepo: createHttpCodeRepoService(), workspaceStorage: new WorkspaceStorage() };
}

