import type { DiagramRevisionApplication } from '../../../../domain/mapping/agent/diagramEdit';
import type { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
import { validateConnectionAnchor } from '../../../../domain/core/diagrams/diagramConnection';

interface Applied { version: number; unresolvedEdgeIds: string[] }
interface Receipt { signature: string; result: Applied; pending?: Promise<Applied> }

/** Keep the mutation receipt before flushing: retry a failed write without editing twice. */
export class DiagramRevisionReceiver {
  private receipts = new Map<string, Receipt>();
  async apply(documentId: string, input: DiagramRevisionApplication, controller: MappingDocumentController, persist: () => Promise<void>) {
    const key = JSON.stringify([documentId, input.requestId]), signature = JSON.stringify(input);
    let receipt = this.receipts.get(key);
    if (receipt && receipt.signature !== signature) throw Error('REQUEST_ID_CONFLICT: revision application differs');
    if (!receipt) {
      if (this.receipts.size >= 2000) throw Error('Revision receipt capacity reached; reload the workspace');
      const result = controller.applyUpdate(input.expectedVersion, [{ method: 'diagram-revision-apply', nodeId: input.nodeId,
        expectedRevisionId: input.baseRevisionId, revision: input.revision }]);
      const document = controller.getSnapshot().document;
      const unresolvedEdgeIds = document.edges.filter(edge => {
        try { validateConnectionAnchor(document.scene, edge.source); validateConnectionAnchor(document.scene, edge.target); return false; }
        catch { return true; }
      }).map(edge => edge.id);
      receipt = { signature, result: { version: result.version, unresolvedEdgeIds } };
      this.receipts.set(key, receipt);
    }
    if (!receipt.pending) {
      const current = receipt;
      current.pending = Promise.resolve().then(persist).then(() => current.result).catch(error => {
        throw Error(`PERSISTENCE_PENDING: revision applied; retry the same request to flush: ${String(error)}`);
      }).finally(() => { current.pending = undefined; });
    }
    return receipt.pending!;
  }
}

import { selectedDiagramIds } from '../../../../domain/mapping/selection/selectionState';
import { selectionClipboardText } from '../../../../domain/mapping/workspace/selectionClipboard';
import { asciiForSelection } from '../../../../domain/core/diagrams/diagramSelection';
import { formatAsciiWithCodeReferences } from '../../../../domain/core/diagrams/diagramClipboard';
import type { Diagram, GridBox } from '../../../../domain/core/diagrams/lineGrid';
import { sameDiagramSelection, sameRegion, selectionDelta, type LiveRegion, type LiveSelection } from '../../../../domain/mapping/agent/liveCanvasStatus';
import type { MappingPocGridRect } from '../../../../domain/mapping/selection/mappingPoc';
import type { CanvasWorkspace } from '../workspace/canvasWorkspace';
import type { CanvasSession } from '../workspace/canvasSession';

/** Read completed regions only; pointer previews, pane geometry and history are not published. */
export function observeCanvasSelection(session: CanvasSession, documentId: string, changed: (snapshot: LiveSelection) => void) {
  const canvasEpoch = crypto.randomUUID();
  let sequence = 0, stopped = false, timer: ReturnType<typeof setTimeout> | undefined;
  let previous: LiveSelection | undefined;
  const cache = new Map<string, { diagram?: Diagram; rectKey: string; ids: readonly string[]; sourceAscii?: string; region: LiveRegion }>();
  const rectKey = (boxId: string, rect: MappingPocGridRect) => JSON.stringify([boxId, rect.startLine, rect.endLine, rect.startColumn, rect.endColumn]);
  const sample = () => {
    timer = undefined;
    if (stopped) return;
    const snapshot = session.controller.getSnapshot(), { selection } = snapshot.canvas;
    const boxes = new Map<string, string>();
    const visit = (box: GridBox) => {
      if (box.kind === 'container') box.children.forEach(visit);
      else boxes.set(box.id, box.contentId);
    };
    visit(snapshot.document.scene.root);
    const diagramIds = selectedDiagramIds(selection);
    const regions: LiveRegion[] = [];
    const add = (id: string, sourceBoxId: string, sourceContentId: string, rect: MappingPocGridRect,
      ids: readonly string[], sourceAscii?: string) => {
      const diagram = snapshot.document.scene.contents[sourceContentId];
      const stale = sourceAscii !== undefined && (!diagram || diagram.content.ascii !== sourceAscii || boxes.get(sourceBoxId) !== sourceContentId);
      const key = rectKey(sourceBoxId, rect), cached = cache.get(id);
      if (cached && cached.diagram === diagram && cached.rectKey === key && cached.ids === ids
        && cached.sourceAscii === sourceAscii && cached.region.stale === stale && cached.region.sourceContentId === sourceContentId) {
        regions.push(cached.region); return;
      }
      const text = stale ? formatAsciiWithCodeReferences([asciiForSelection(sourceAscii!, rect)], [])
        : diagram ? selectionClipboardText(diagram, rect, ids)! : '';
      const region = { id, sourceBoxId, sourceContentId, rect, text, stale };
      cache.set(id, { diagram, rectKey: key, ids, sourceAscii, region }); regions.push(region);
    };
    for (const item of selection.items) if (item.region) {
      const { sourceContentId, sourceAscii, rect, selectedIds } = item.region;
      add(item.id, item.displayNodeId.slice(5), sourceContentId, rect, selectedIds, sourceAscii);
    }
    const liveIds = new Set(regions.map(region => region.id));
    for (const id of cache.keys()) if (!liveIds.has(id)) cache.delete(id);
    const before = new Map(previous?.regions.map(region => [region.id, region]));
    if (previous && sameDiagramSelection(previous.diagramIds, diagramIds) && before.size === regions.length && regions.every(region => before.has(region.id) && sameRegion(before.get(region.id)!, region))) return;
    previous = { documentId, canvasEpoch, sequence: sequence++, documentVersion: snapshot.version, regions, diagramIds };
    changed(previous);
  };
  const unsubscribe = session.controller.subscribe(() => { timer ??= setTimeout(sample, 0); });
  sample();
  return { canvasEpoch, dispose() { stopped = true; clearTimeout(timer); unsubscribe(); } };
}

export interface LiveAgentStatus { connected: boolean; count: number }

/** One publisher socket per browser workspace; reconnects with current, bounded snapshots. */
export function publishLiveCanvasSelections(workspace: CanvasWorkspace, workspaceInstanceId: string, endpoint: string, onAgentStatus?: (status: LiveAgentStatus) => void) {
  let socket: WebSocket | undefined, ready = false, disposed = false;
  let reconnect: ReturnType<typeof setTimeout> | undefined, drainTimer: ReturnType<typeof setTimeout> | undefined;
  const entries = new Map<string, { session: CanvasSession; observer: ReturnType<typeof observeCanvasSelection> }>();
  const latest = new Map<string, LiveSelection>();
  const sent = new Map<string, LiveSelection>();
  const pending = new Map<string, LiveSelection | { documentId: string; canvasEpoch: string }>();
  const drain = () => {
    clearTimeout(drainTimer);
    drainTimer = undefined;
    if (!ready || socket?.readyState !== WebSocket.OPEN) return;
    for (const [id, value] of pending) {
      if (socket.bufferedAmount > 64 * 1024) { drainTimer = setTimeout(drain, 20); return; }
      if ('regions' in value) {
        const previous = sent.get(id);
        socket.send(JSON.stringify(previous?.canvasEpoch === value.canvasEpoch
          ? { type: 'selection.delta', ...selectionDelta(previous, value) }
          : { type: 'selection.snapshot', ...value }));
        sent.set(id, value);
      } else { socket.send(JSON.stringify({ type: 'remove', ...value })); sent.delete(id); }
      pending.delete(id);
    }
  };
  const refresh = () => {
    const drafts = workspace.store.getState().drafts;
    for (const [id, entry] of entries) if (!drafts[id] || drafts[id].hidden || drafts[id].session !== entry.session) {
      entry.observer.dispose(); entries.delete(id); latest.delete(id);
      pending.set(id, { documentId: id, canvasEpoch: entry.observer.canvasEpoch });
    }
    for (const [id, draft] of Object.entries(drafts)) if (!draft.hidden && !entries.has(id)) {
      const observer = observeCanvasSelection(draft.session, id, value => {
        latest.set(id, value); pending.set(id, value); drain();
      });
      entries.set(id, { session: draft.session, observer });
    }
    drain();
  };
  const unsubscribe = workspace.store.subscribe(refresh);
  refresh();
  const connect = () => {
    if (disposed) return;
    const ws = socket = new WebSocket(endpoint);
    ready = false;
    ws.onopen = () => ws.send(JSON.stringify({ type: 'publish', protocolVersion: 2, workspaceInstanceId }));
    ws.onmessage = event => {
      const message = JSON.parse(event.data);
      if (message.type === 'publisher.ready') {
        onAgentStatus?.({ connected: true, count: 0 });
        ready = true; sent.clear(); pending.clear(); latest.forEach((value, id) => pending.set(id, value)); drain();
      } else if (message.type === 'agents.changed') {
        onAgentStatus?.({ connected: true, count: message.count });
      } else if (message.type === 'error') ws.close(); // Registration may be racing this connection; retry with fresh state.
    };
    ws.onerror = () => ws.close();
    ws.onclose = () => {
      ready = false; clearTimeout(drainTimer);
      if (!disposed) onAgentStatus?.({ connected: false, count: 0 });
      if (!disposed) reconnect = setTimeout(connect, 1000);
    };
  };
  connect();
  return () => {
    disposed = true; ready = false; clearTimeout(reconnect); clearTimeout(drainTimer);
    unsubscribe(); entries.forEach(entry => entry.observer.dispose()); entries.clear(); pending.clear(); latest.clear();
    socket?.close();
  };
}

/** A stable tab ID is discovery metadata, never a command/publisher ownership key. */
interface IdentityEnvironment {
  read(): string | null;
  write(id: string): void;
  claim(id: string): Promise<boolean>;
  randomId(): string;
  pause(ms: number): Promise<void>;
}

const validId = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Exported separately so refresh/duplicate races can be tested without React. */
export async function acquireStableWorkspaceId(environment: IdentityEnvironment): Promise<string | undefined> {
  try {
    const saved = environment.read();
    if (saved && validId.test(saved)) {
      // A reload's old document may need a moment to release its browser lock.
      // A duplicated tab copied sessionStorage, but cannot acquire that lock.
      for (let attempt = 0; attempt < 6; attempt++) {
        if (await environment.claim(saved)) return saved;
        if (attempt < 5) await environment.pause(50);
      }
    }
    for (let attempt = 0; attempt < 3; attempt++) {
      const id = environment.randomId();
      if (!await environment.claim(id)) continue;
      environment.write(id);
      return id;
    }
  } catch {
    // Storage/locks can be disabled by the browser. Do not advertise an identity
    // whose reload stability and exclusive ownership we cannot establish.
  }
  return undefined;
}

type IdentityWindow = Window & {
  __mappingWorkspaceIdentities?: Map<string, Promise<string | undefined>>;
};

/** Window ownership outlives React remounts/HMR; browser teardown releases locks. */
export function browserStableWorkspaceId(baseUrl: string): Promise<string | undefined> {
  const owner = window as IdentityWindow;
  const key = `mapping.stable-workspace.v1:${baseUrl}`;
  const identities = owner.__mappingWorkspaceIdentities ??= new Map();
  const existing = identities.get(key);
  if (existing) return existing;
  const identity = acquireStableWorkspaceId({
    read: () => {
      if (!navigator.locks) throw new Error('Exclusive browser locks unavailable');
      return sessionStorage.getItem(key);
    },
    write: id => sessionStorage.setItem(key, id),
    randomId: () => crypto.randomUUID(),
    pause: ms => new Promise(resolve => setTimeout(resolve, ms)),
    claim: id => new Promise<boolean>((resolve, reject) => {
      void navigator.locks.request(`${key}:${id}`, { ifAvailable: true }, lock => {
        resolve(Boolean(lock));
        // No timeout/heartbeat: exclusivity lasts until this document is gone.
        return lock ? new Promise<void>(() => {}) : undefined;
      }).catch(reject);
    })
  });
  identities.set(key, identity);
  return identity;
}

import { publishLiveCanvasSelections, type LiveAgentStatus } from './liveCanvasPublisher';
import type { CanvasWorkspace } from '../workspace/canvasWorkspace';
import { useEffect, useRef, useState } from 'react';
import type { CanvasCommand, CanvasDescriptor } from '../../../../domain/mapping/agent/contracts';
import { apiFetch, errorFrom } from '../../../shared/http/http';
import { browserStableWorkspaceId } from './stableWorkspaceIdentity';

export function useAgentCanvasBridge(descriptor: Omit<CanvasDescriptor, 'canvasId' | 'stableWorkspaceId'>, handle: (command: CanvasCommand) => Promise<unknown>, workspace?: CanvasWorkspace) {
  const [agentStatus, setAgentStatus] = useState<LiveAgentStatus>({ connected: false, count: 0 });
  const [canvasId] = useState(() => crypto.randomUUID());
  const [identity, setIdentity] = useState<{ stableWorkspaceId?: string }>();
  useEffect(() => {
    let active = true;
    void browserStableWorkspaceId(import.meta.env.BASE_URL).then(stableWorkspaceId => {
      if (active) setIdentity({ stableWorkspaceId });
    });
    return () => { active = false; };
  }, []);
  const latest = useRef({ descriptor, handle }); latest.current = { descriptor, handle };
  const registration = identity && JSON.stringify({ ...descriptor, canvasId, ...identity });
  useEffect(() => {
    if (!registration) return;
    void apiFetch('/api/mapping/agent/canvases', { method: 'POST', headers: { 'content-type': 'application/json' }, body: registration }).catch(() => undefined);
  }, [registration]);
  useEffect(() => {
    if (!identity) return;
    const abort = new AbortController();
    let timer: ReturnType<typeof setTimeout> | undefined;
    const results = new Map<string, { value?: unknown; error?: string }>();
    const request = async (path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST') => {
      const response = await apiFetch(`/api/mapping/agent${path}`, { method, signal: abort.signal,
        ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }) });
      if (!response.ok) throw await errorFrom(response);
      return response.json();
    };
    const register = () => request('/canvases', { ...latest.current.descriptor, canvasId, ...identity });
    const run = async () => {
      try {
        await register();
        while (!abort.signal.aborted) {
          const commands: CanvasCommand[] = await request(`/canvases/${canvasId}/commands`);
          for (const command of commands) {
            let result = results.get(command.id);
            if (!result) {
              try { result = { value: await latest.current.handle(command) }; }
              catch (error) { result = { error: error instanceof Error ? error.message : String(error) }; }
              // Context is a fresh read and may be large; never retain it in the mutation receipt cache.
              if (command.method === 'context' && new TextEncoder().encode(JSON.stringify(result)).length > 64 * 1024 * 1024 - 1024)
                result = { error: 'CONTEXT_TOO_LARGE: canvas context exceeds the 64 MiB transport limit' };
              if (command.method !== 'context') results.set(command.id, result);
              if (results.size > 200) results.delete(results.keys().next().value!);
            }
            await request(`/canvases/${canvasId}/reply`, { commandId: command.id, ...result });
          }
          await register();
        }
      } catch {
        if (!abort.signal.aborted) timer = setTimeout(() => void run(), 1000);
      }
    };
    void run();
    const unregister = () => { void apiFetch(`/api/mapping/agent/canvases/${canvasId}`, { method: 'DELETE', keepalive: true }).catch(() => undefined); };
    // React cleanup does not run on page reload. Retire this ephemeral instance
    // promptly, without ever deleting a replacement that has the same stable ID.
    window.addEventListener('pagehide', unregister);
    return () => { abort.abort(); clearTimeout(timer); window.removeEventListener('pagehide', unregister); unregister(); };
  }, [canvasId, identity]);
  useEffect(() => {
    setAgentStatus({ connected: false, count: 0 });
    if (!workspace || !identity) return;
    const endpoint = new URL(`${import.meta.env.BASE_URL.replace(/\/$/, '')}/api/mapping/live`, location.href);
    endpoint.protocol = endpoint.protocol === 'https:' ? 'wss:' : 'ws:';
    return publishLiveCanvasSelections(workspace, canvasId, endpoint.href, setAgentStatus);
  }, [workspace, canvasId, identity]);
  return { canvasId, agentStatus };
}

import { apiFetch, errorFrom } from "../../shared/http/http";
import type { MappingPocPromptRequest, MappingPocPromptResult } from "../../../domain/mapping/selection/mappingPocPrompt";

export async function promptMappingPocSelection(
  request: MappingPocPromptRequest,
  onProgress: (message: string) => void,
  signal?: AbortSignal
): Promise<MappingPocPromptResult> {
  const response = await apiFetch("/api/mapping/prompt", {
    method: "POST", signal,
    headers: { "content-type": "application/json" },
    body: JSON.stringify(request)
  });
  if (!response.ok) throw await errorFrom(response);
  if (!response.body) throw new Error("diagram prompt response did not include a stream");
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let result: MappingPocPromptResult | undefined;
  const consume = (line: string) => {
    if (!line.trim()) return;
    const event = JSON.parse(line) as {
      type?: string;
      message?: string;
      error?: string;
      result?: MappingPocPromptResult;
    };
    if (event.type === "error") throw new Error(event.error || "diagram prompt failed");
    if (event.type === "progress" && event.message) onProgress(event.message);
    if (event.type === "result" && event.result) result = event.result;
  };
  while (true) {
    const { done, value } = await reader.read();
    buffer += decoder.decode(value, { stream: !done });
    const lines = buffer.split("\n");
    buffer = lines.pop() ?? "";
    for (const line of lines) consume(line);
    if (done) break;
  }
  if (buffer.trim()) consume(buffer);
  if (!result) throw new Error("diagram prompt stream ended without a patch result");
  return result;
}
export const localChatResponder: import("../../../domain/mapping/chat/localChat").LocalChatResponder = {
  async reply(request, options) {
    const response = await apiFetch("/api/mapping/chat", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(request),
      signal: options?.signal
    });
    if (!response.ok) throw await errorFrom(response);
    if (!response.body) throw new Error("Chat response did not include a stream");
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    let reply: string | undefined;
    const consume = (line: string) => {
      if (!line.trim()) return;
      const event = JSON.parse(line);
      if (event.type === "error") throw new Error(event.error || "Chat failed");
      if (event.type === "context") options?.onContext?.(event.sourceRanges);
      if (event.type === "progress") options?.onProgress?.(event.message);
      if (event.type === "result") reply = event.text;
    };
    try {
      while (true) {
        const { done, value } = await reader.read();
        buffer += decoder.decode(value, { stream: !done });
        const lines = buffer.split("\n");
        buffer = lines.pop() ?? "";
        for (const line of lines) consume(line);
        if (done) break;
      }
      consume(buffer);
      if (!reply?.trim()) throw new Error("Chat ended without an answer");
      return reply;
    } finally {
      await reader.cancel().catch(() => {});
      reader.releaseLock();
    }
  }
};

import { useEffect, useRef, useState, type RefObject } from 'react';
import { createPortal } from 'react-dom';
import type { GridPoint } from '../../../../domain/core/diagrams/lineGrid';

type Menu = { x: number; y: number; point: GridPoint; pending: boolean; error?: string; manual: boolean; text: string };

/** Transient UI only; insertion and undo remain owned by the diagram document. */
export function CanvasPasteMenu(props: {
  stageRef: RefObject<HTMLDivElement | null>;
  active: boolean;
  busy: boolean;
  toGrid: (x: number, y: number) => GridPoint | null;
  onPaste: (point: GridPoint, text: string) => void;
  selectionCount?: number;
  onTransfer?: (mode: 'copy' | 'move') => void;
  onCancelSelection?: () => void;
}) {
  const [menu, setMenu] = useState<Menu | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const current = useRef(props); current.current = props;
  const request = useRef(0);
  const pending = useRef(false);
  const dismiss = () => { request.current++; pending.current = false; setMenu(null); };

  useEffect(() => {
    if (!props.active || props.busy) { dismiss(); return; }
    const viewport = props.stageRef.current?.closest('[data-diagram-canvas]');
    if (!viewport) return;
    const open = (event: Event) => {
      if (!current.current.active || current.current.busy) return;
      const mouse = event as MouseEvent;
      if ((mouse.target as Element).closest('button, a, input, textarea, select, [contenteditable="true"], [data-diagram-canvas-static-ui], [data-mapping-static-ui], .mapping-floating-pane')) return;
      const point = current.current.toGrid(mouse.clientX, mouse.clientY);
      if (!point) return;
      mouse.preventDefault();
      dismiss();
      setMenu({ x: mouse.clientX, y: mouse.clientY, point, pending: false, manual: false, text: '' });
    };
    viewport.addEventListener('contextmenu', open);
    return () => { viewport.removeEventListener('contextmenu', open); request.current++; pending.current = false; };
  }, [props.active, props.busy, props.stageRef]);

  useEffect(() => {
    if (!menu) return;
    const outside = (event: PointerEvent) => { if (!menuRef.current?.contains(event.target as Node)) dismiss(); };
    const wheel = (event: WheelEvent) => { if (!menuRef.current?.contains(event.target as Node)) dismiss(); };
    const key = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); dismiss(); current.current.onCancelSelection?.(); }
    };
    window.addEventListener('pointerdown', outside, true);
    window.addEventListener('keydown', key, true);
    window.addEventListener('resize', dismiss);
    window.addEventListener('wheel', wheel);
    return () => {
      window.removeEventListener('pointerdown', outside, true);
      window.removeEventListener('keydown', key, true);
      window.removeEventListener('resize', dismiss);
      window.removeEventListener('wheel', wheel);
    };
  }, [Boolean(menu)]);

  useEffect(() => {
    if (menu) menuRef.current?.querySelector<HTMLElement>(menu.manual ? 'textarea' : 'button')?.focus();
  }, [Boolean(menu), menu?.manual]);

  if (!menu) return null;
  const paste = async (manual = false) => {
    if (pending.current) return;
    pending.current = true;
    const token = ++request.current;
    setMenu(value => value && { ...value, pending: true, error: undefined });
    try {
      if (!manual && !navigator.clipboard?.readText) throw new Error('Clipboard is unavailable. Paste your diagram below.');
      const text = manual ? menu.text : await navigator.clipboard.readText().catch(() => { throw new Error('Clipboard access failed. Paste your diagram below.'); });
      if (token !== request.current || !current.current.active || current.current.busy) return;
      current.current.onPaste(menu.point, text);
      dismiss();
    } catch (error) {
      if (token !== request.current) return;
      setMenu(value => value && { ...value, pending: false, manual: true,
        error: error instanceof Error ? error.message : 'Could not paste diagram.' });
    } finally { if (token === request.current) pending.current = false; }
  };
  return createPortal(
    <div ref={menuRef} className="canvas-paste-menu" role={menu.manual ? 'dialog' : 'menu'} aria-label="Canvas actions"
      data-diagram-canvas-static-ui data-mapping-static-ui
      style={{ left: Math.max(8, Math.min(menu.x, window.innerWidth - 328)), top: Math.max(8, Math.min(menu.y, window.innerHeight - (menu.manual ? 310 : props.selectionCount ? 135 : 60))) }}
      onContextMenu={event => {
        if (!(event.target as Element).closest('input, textarea, [contenteditable="true"]')) event.preventDefault();
      }}>
      {props.selectionCount && props.onTransfer ? <>
        <span>{props.selectionCount} diagrams selected</span>
        <button role="menuitem" onClick={() => { dismiss(); props.onTransfer?.('copy'); }}>Copy to canvas…</button>
        <button role="menuitem" onClick={() => { dismiss(); props.onTransfer?.('move'); }}>Move to canvas…</button>
      </> : menu.manual ? <form onSubmit={event => { event.preventDefault(); void paste(true); }}>
        <label>Paste ASCII diagram<textarea aria-label="ASCII diagram" rows={6} value={menu.text}
          onChange={event => setMenu(value => value && { ...value, text: event.target.value })} /></label>
        <button type="submit" disabled={menu.pending || !menu.text.trim()}>Paste sub-diagram here</button>
      </form> : <button role="menuitem" disabled={menu.pending} onClick={() => void paste()}>
        {menu.pending ? 'Reading clipboard…' : 'Paste sub-diagram here'}
      </button>}
      {menu.error && <p role="alert">{menu.error}</p>}
    </div>, document.body
  );
}

import { useEffect, useRef, useState, type RefObject } from 'react';
import { createPortal } from 'react-dom';
import type { CanvasMarqueeSelection, SelectionBounds } from '../../../../domain/mapping/selection/canvasSelection';

/** One gesture owner for region and whole-diagram selection. Preview never writes the document. */
export function CanvasSelectionLayer(props: { stageRef: RefObject<HTMLDivElement | null>; active: boolean;
  diagramIds: string[]; selected: string[];
  resolve: (bounds: SelectionBounds, promoted: string[]) => CanvasMarqueeSelection;
  onComplete: (selection: CanvasMarqueeSelection) => void;
  onSelectDiagram: (id: string, toggle: boolean) => void }) {
  const current = useRef(props); current.current = props;
  const [preview, setPreview] = useState<{ bounds: SelectionBounds; diagrams: SelectionBounds[] }>();
  useEffect(() => {
    const stage = props.stageRef.current, viewport = stage?.closest<HTMLElement>('[data-diagram-canvas]');
    if (!viewport || !props.active) { setPreview(undefined); return; }
    let drag: { x: number; y: number; pointerId: number; moved: boolean; promoted: string[] } | undefined;
    const boxes = () => [...stage!.querySelectorAll<HTMLElement>('[data-grid-box]')]
      .filter(el => current.current.diagramIds.includes(`grid:${el.dataset.gridBox}`))
      .map(el => ({ id: `grid:${el.dataset.gridBox}`, bounds: el.getBoundingClientRect() }));
    const ui = (event: MouseEvent) => {
      const target = event.target as Element;
      if (event.ctrlKey && target.closest('[data-diagram-jump-id]')) return false;
      return !!target.closest('button, a, input, textarea, select, [contenteditable=true], [data-mapping-static-ui], [data-diagram-canvas-static-ui], [data-display-node]');
    };
    const hit = (event: MouseEvent) => boxes().find(({ bounds: r }) => event.clientX >= r.left && event.clientX <= r.right && event.clientY >= r.top && event.clientY <= r.bottom);
    const doubleClick = (event: MouseEvent) => {
      const target = document.elementFromPoint(event.clientX, event.clientY);
      if (ui(event) || event.button !== 0 || (!(event.ctrlKey || event.metaKey) && target?.closest('[data-content-node-id]'))) return;
      const box = hit(event); if (!box) return;
      event.preventDefault(); event.stopPropagation(); window.getSelection()?.removeAllRanges();
      current.current.onSelectDiagram(box.id, event.ctrlKey || event.metaKey);
    };
    const down = (event: PointerEvent) => {
      if (event.button !== 0 || ui(event)) return;
      if (!event.ctrlKey || event.metaKey) return;
      event.preventDefault(); event.stopPropagation(); window.getSelection()?.removeAllRanges();
      stage!.focus({ preventScroll: true });
      drag = { x: event.clientX, y: event.clientY, pointerId: event.pointerId, moved: false, promoted: [...current.current.selected] };
      viewport.setPointerCapture(event.pointerId);
    };
    const sample = (event: PointerEvent) => {
      if (!drag || drag.pointerId !== event.pointerId) return;
      event.preventDefault(); event.stopPropagation();
      drag.moved ||= Math.hypot(event.clientX - drag.x, event.clientY - drag.y) > 4;
      const bounds = { left: Math.min(drag.x, event.clientX), top: Math.min(drag.y, event.clientY), right: Math.max(drag.x, event.clientX), bottom: Math.max(drag.y, event.clientY) };
      const selection = current.current.resolve(bounds, drag.promoted);
      // Promotion is sticky until pointer-up, even if the marquee subsequently shrinks.
      drag.promoted = selection.diagramIds;
      setPreview({ bounds, diagrams: boxes().filter(box => selection.diagramIds.includes(box.id)).map(box => box.bounds) });
      return selection;
    };
    const release = () => {
      const pointerId = drag?.pointerId; drag = undefined; setPreview(undefined);
      if (pointerId !== undefined && viewport.hasPointerCapture(pointerId)) viewport.releasePointerCapture(pointerId);
    };
    const up = (event: PointerEvent) => {
      if (!drag || drag.pointerId !== event.pointerId) return;
      const selection = sample(event), moved = drag.moved; release();
      if (moved && selection) current.current.onComplete(selection);
    };
    const key = (event: KeyboardEvent) => {
      if (!drag || event.key !== 'Escape') return;
      event.preventDefault(); event.stopImmediatePropagation(); release();
    };
    viewport.addEventListener('dblclick', doubleClick, true);
    viewport.addEventListener('pointerdown', down, true);
    viewport.addEventListener('pointermove', sample, true);
    viewport.addEventListener('pointerup', up, true);
    viewport.addEventListener('pointercancel', release, true);
    viewport.addEventListener('lostpointercapture', release, true);
    window.addEventListener('keydown', key, true);
    return () => {
      release();
      viewport.removeEventListener('dblclick', doubleClick, true); viewport.removeEventListener('pointerdown', down, true);
      viewport.removeEventListener('pointermove', sample, true); viewport.removeEventListener('pointerup', up, true);
      viewport.removeEventListener('pointercancel', release, true); viewport.removeEventListener('lostpointercapture', release, true);
      window.removeEventListener('keydown', key, true);
    };
  }, [props.stageRef, props.active]);
  return preview ? createPortal(<>
    <div className="diagram-selection-marquee" data-selection-preview aria-hidden="true" style={{ left: preview.bounds.left, top: preview.bounds.top,
      width: preview.bounds.right - preview.bounds.left, height: preview.bounds.bottom - preview.bounds.top }} />
    {preview.diagrams.map((bounds, i) => <div key={i} className="diagram-selection-marquee" data-diagram-selection-preview aria-hidden="true"
      style={{ left: bounds.left, top: bounds.top, width: bounds.right - bounds.left, height: bounds.bottom - bounds.top }} />)}
  </>, document.body) : null;
}

import { endpointKey } from '../../../../domain/mapping/workspace/endpointGeometry';
import type { CanvasDisplayNode } from '../../../../domain/mapping/workspace/canvasDisplayNode';
import { PanelConnector } from '../../../shared/diagrams/PanelConnector';
import { useEffect, useMemo, useState, type RefObject } from 'react';
import { createPortal } from 'react-dom';
import { connectionContentNodes, defaultArrowAppearance, getArrowLabel, type DiagramAnchor, type DiagramConnection } from '../../../../domain/core/diagrams/diagramConnection';
import { drawEdge, type FloatingBoxArrow } from '../../../../domain/mapping/workspace/connectionLayout';
import type { MappingDocumentController, ControllerSnapshot } from '../../../../domain/mapping/workspace/mappingDocumentController';
import './diagramConnections.css';

type Choice = { key: string; label: string; anchor: DiagramAnchor; rect?: { left: number; top: number; width: number; height: number } };
const keyFor = (anchor: DiagramAnchor) => JSON.stringify([anchor.displayNodeId, anchor.kind === 'box' ? null : anchor.contentNodeId]);
const sides = ['auto', 'left', 'right', 'top', 'bottom'] as const;

export function DiagramConnections({ controller, state, cell, displayNodes, svgRef, open, onOpen, onClose, disabled }: {
  displayNodes: CanvasDisplayNode[]; svgRef: RefObject<SVGSVGElement | null>;
  controller: MappingDocumentController; state: ControllerSnapshot; cell: { width: number; height: number };
  open: boolean; onOpen: () => void; onClose: () => void; disabled: boolean;
}) {
  const [selectedId, setSelectedId] = useState<string>();
  const [draft, setDraft] = useState<Partial<DiagramConnection>>({ appearance: { ...defaultArrowAppearance } });
  const [picking, setPicking] = useState<'source' | 'target'>();
  const [hover, setHover] = useState<DiagramAnchor>();
  const [error, setError] = useState('');
  const { document: doc, canvas } = state;
  const selected = doc.edges.find(edge => edge.id === selectedId);
  const choices = useMemo(() => {
    const measuredRect = (anchor: DiagramAnchor) => {
      const rect = state.endpointBounds?.[endpointKey(anchor)];
      return rect ? { left: rect.x, top: rect.y, width: rect.width, height: rect.height } : undefined;
    };
    const result: Choice[] = [];
    const visit = (box: typeof doc.scene.root) => {
      const displayNodeId = `grid:${box.id}`;
      if (box.id !== doc.scene.root.id) {
        const anchor: DiagramAnchor = { kind: 'box', displayNodeId, side: 'auto' };
        result.push({ key: keyFor(anchor), label: `${box.id} · whole box`, anchor,
          rect: measuredRect(anchor) });
      }
      if (box.kind === 'container') { box.children.forEach(visit); return; }
      const content = doc.scene.contents[box.contentId].content;
      for (const node of connectionContentNodes(content)) {
        const anchor: DiagramAnchor = { kind: 'content-node', displayNodeId, contentNodeId: node.id, revisionId: content.revisionId, side: 'auto' };
        result.push({ key: keyFor(anchor), label: `${box.id} · ${node.label} (line ${node.line})`, anchor,
          rect: measuredRect(anchor) });
      }
    };
    visit(doc.scene.root);
    return result;
  }, [doc.scene, state.endpointBounds]);
  useEffect(() => { if (!open || disabled) { setPicking(undefined); setHover(undefined); } }, [open, disabled]);
  useEffect(() => {
    if (!open) return;
    const escape = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.stopPropagation(); setPicking(undefined); setHover(undefined); onClose();
    };
    window.addEventListener('keydown', escape, true);
    return () => window.removeEventListener('keydown', escape, true);
  }, [open, onClose]);

  const edit = (edge: DiagramConnection) => { setSelectedId(edge.id); setDraft(structuredClone(edge)); setPicking(undefined); setError(''); onOpen(); };
  const create = () => { setSelectedId(undefined); setDraft({ appearance: { ...defaultArrowAppearance } }); setError(''); setPicking('source'); };
  const save = () => {
    try {
      if (!draft.source || !draft.target || !draft.appearance) throw new Error('Choose both endpoints');
      controller.transact(controller.getSnapshot().version, [{ method: selected ? 'edge-update' : 'edge-create',
        edge: { id: selected?.id ?? crypto.randomUUID(), source: draft.source, target: draft.target, appearance: draft.appearance } }]);
      setPicking(undefined); setSelectedId(undefined); setDraft({ appearance: { ...defaultArrowAppearance } }); setError('');
    } catch (error) { setError(error instanceof Error ? error.message : String(error)); }
  };
  const preview = draft.source && (hover ?? draft.target) && draft.appearance ? {
    id: 'preview', source: draft.source, target: hover ?? draft.target!, appearance: draft.appearance
  } : undefined;
  const arrowById = new Map(displayNodes.flatMap(node => node.layout === 'floating' && node.kind === 'arrow'
    && node.value.kind === 'arrow' ? [[node.value.edgeId, node.value] as const] : []));
  const arrows = doc.edges.flatMap(edge => {
    const arrow = arrowById.get(edge.id);
    return arrow ? [{ edge, arrow }] : [];
  });
  const previewArrow = preview && drawEdge(preview, doc.scene, canvas.diagramViews, cell, state.endpointBounds ?? {});
  const renderArrow = (edge: DiagramConnection, arrow: FloatingBoxArrow, preview = false) => {
    if (!arrow.path || !arrow.source || !arrow.target) return null;
    const label = getArrowLabel(edge.appearance).text || 'Connection';
    return <g key={preview ? 'preview' : edge.id} data-connection-id={preview ? undefined : edge.id} data-connection-status={arrow.status} data-geometry-source={arrow.geometrySource}
      style={{ color: edge.appearance.color, opacity: preview ? .55 : 1 }}>
      <PanelConnector path={arrow.path} target={arrow.target} selected={selectedId === edge.id}
        dashed={edge.appearance.lineStyle === 'dashed' || arrow.status === 'proxy'} />
      {arrow.status === 'proxy' && <circle cx={arrow.source.proxy ? arrow.source.x : arrow.target.x} cy={arrow.source.proxy ? arrow.source.y : arrow.target.y} r={4} fill="currentColor" />}
      {arrow.label?.text && <text x={arrow.label.position.x} y={arrow.label.position.y}
        textAnchor="middle" fill="currentColor">{arrow.label.text}</text>}
      {!preview && <path className="diagram-connection-hit" d={arrow.path} fill="none" stroke="transparent" strokeWidth={14}
        role="button" tabIndex={disabled ? -1 : 0} aria-label={`Edit connection: ${label}`} data-mapping-static-ui data-diagram-canvas-static-ui
        onClick={() => !disabled && edit(edge)} onKeyDown={event => {
          if (!disabled && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); event.stopPropagation(); edit(edge); }
        }}><title>{label}{arrow.status === 'proxy' ? ' · attached through collapsed content' : ''}</title></path>}
    </g>;
  };
  return <>
    <svg ref={svgRef} className="diagram-connections" aria-label="Diagram connections">
      {arrows.map(({ edge, arrow }) => renderArrow(edge, arrow))}
      {open && preview && previewArrow && renderArrow(preview, previewArrow, true)}
    </svg>
    {open && picking && !disabled && choices.filter(choice => choice.rect && (picking === 'target' || choice.anchor.kind === 'content-node')).map(choice => (
      <button key={choice.key} type="button" className={`diagram-anchor-target is-${choice.anchor.kind}`} style={choice.rect}
        data-mapping-static-ui data-diagram-canvas-static-ui data-connection-anchor={choice.key}
        aria-label={`Connect ${picking}: ${choice.label}`} title={choice.label}
        onPointerEnter={() => picking === 'target' && setHover(choice.anchor)} onPointerLeave={() => setHover(undefined)}
        onClick={() => {
          setDraft(current => ({ ...current, [picking]: choice.anchor }));
          setHover(undefined); setPicking(picking === 'source' ? 'target' : undefined);
        }} />
    ))}
    {open && createPortal(<aside className="diagram-connections-panel" role="dialog" aria-label="Connections"
      data-mapping-static-ui data-diagram-canvas-static-ui>
      <header><strong>Connections</strong><button type="button" aria-label="Close connections" onClick={onClose}>×</button></header>
      <button type="button" disabled={disabled} onClick={create}>New connection</button>
      <ul>{arrows.map(({ edge, arrow }) => <li key={edge.id}><button type="button" disabled={disabled} onClick={() => edit(edge)}>
        {getArrowLabel(edge.appearance).text || `${edge.source.displayNodeId.slice(5)} → ${edge.target.displayNodeId.slice(5)}`}
        {arrow.status === 'stale' ? ' · needs reattachment' : arrow.status === 'proxy' ? ' · folded endpoint' : arrow.status === 'pending' ? ' · waiting for layout' : arrow.status === 'blocked' ? ' · endpoint boxes block the route' : ''}
      </button></li>)}</ul>
      <form onSubmit={event => { event.preventDefault(); save(); }}>
        {(['source', 'target'] as const).map(end => {
          const anchor = draft[end];
          const options = choices.filter(choice => end === 'target' || choice.anchor.kind === 'content-node');
          const selectedKey = anchor && keyFor(anchor);
          return <fieldset key={end} disabled={disabled}><legend>{end === 'source' ? 'From node' : 'To node or box'}</legend>
            <select aria-label={`Connection ${end}`} value={selectedKey ?? ''} onChange={event => {
              const next = choices.find(choice => choice.key === event.target.value)?.anchor;
              setDraft(current => ({ ...current, [end]: next })); setPicking(undefined);
            }}>
              <option value="">Choose…</option>
              {selectedKey && !options.some(option => option.key === selectedKey) && <option value={selectedKey}>Stale endpoint — choose again</option>}
              {options.map(choice => <option key={choice.key} value={choice.key}>{choice.label}</option>)}
            </select>
            <button type="button" onClick={() => setPicking(end)}>Pick {end} on canvas</button>
            <label>Side <select aria-label={`${end} side`} value={anchor?.side ?? 'auto'} disabled={!anchor} onChange={event => setDraft(current => ({
              ...current, [end]: { ...current[end]!, side: event.target.value }
            }))}>{sides.map(side => <option key={side}>{side}</option>)}</select></label>
            <label>Position along side <input type="number" min={0} max={1} step={0.05}
              aria-label={`${end} side offset`} value={anchor?.offset ?? 0.5} disabled={!anchor}
              onChange={event => {
                const offset = event.target.valueAsNumber;
                if (Number.isFinite(offset) && offset >= 0 && offset <= 1) setDraft(current => ({ ...current, [end]: { ...current[end]!, offset } }));
              }} /></label>
          </fieldset>;
        })}
        <label>Label <input aria-label="Connection label" maxLength={120} value={draft.appearance ? getArrowLabel(draft.appearance).text : ''} disabled={disabled}
          onChange={event => setDraft(current => ({ ...current, appearance: { ...current.appearance!,
            label: { ...getArrowLabel(current.appearance!), text: event.target.value } } }))} /></label>
        <label>Color <input type="color" aria-label="Connection color" value={draft.appearance?.color ?? defaultArrowAppearance.color} disabled={disabled}
          onChange={event => setDraft(current => ({ ...current, appearance: { ...current.appearance!, color: event.target.value } }))} /></label>
        <label>Line <select aria-label="Connection line style" value={draft.appearance?.lineStyle ?? 'solid'} disabled={disabled}
          onChange={event => setDraft(current => ({ ...current, appearance: { ...current.appearance!, lineStyle: event.target.value as 'solid' | 'dashed' } }))}>
          <option value="solid">Solid</option><option value="dashed">Dashed</option>
        </select></label>
        <p role="status">{picking ? `Click a ${picking === 'source' ? 'source node' : 'destination node or box'}.` : 'Endpoints follow diagram movement and folding.'}</p>
        {error && <p role="alert">{error}</p>}
        <footer><button type="submit" disabled={disabled || !draft.source || !draft.target}>{selected ? 'Update connection' : 'Create connection'}</button>
          {selected && <button type="button" disabled={disabled} onClick={() => {
            try { controller.transact(controller.getSnapshot().version, [{ method: 'edge-remove', edgeId: selected.id }]); create(); setPicking(undefined); }
            catch (error) { setError(String(error)); }
          }}>Delete connection</button>}
        </footer>
      </form>
    </aside>, document.body)}
  </>;
}

