import { RevisionedDiagramService } from '../../../../domain/core/diagrams/diagramService';
import { measureContent, type GridPoint } from '../../../../domain/core/diagrams/lineGrid';
import { insertGridDiagram, type MappingGridDocument } from '../../../../domain/mapping/workspace/mappingGrid';

export function normalizePastedDiagram(text: string): string {
  let ascii = text.replace(/\r\n?/g, '\n');
  const fenced = ascii.match(/^\s*```[^\n]*\n([\s\S]*?)\n```\s*$/);
  if (fenced) ascii = fenced[1];
  if (!ascii.trim()) throw new Error('Clipboard contains no diagram text.');
  if (ascii.length > 20000) throw new Error('Diagram is too large (maximum 20,000 characters).');
  measureContent(ascii);
  return ascii;
}

export function pasteGridDiagram(document: MappingGridDocument, point: GridPoint, text: string, id: string): MappingGridDocument {
  const ascii = normalizePastedDiagram(text);
  return insertGridDiagram(document, document.scene.root.id, {
    id, kind: 'diagram', contentId: id, collapsed: false, position: point
  }, new RevisionedDiagramService().create({ id, revision: 0, ascii }).diagram);
}

import { useCallback, useLayoutEffect, useRef } from 'react';
import { endpointKey, type EndpointBounds, type EndpointIdentity, type EndpointRect } from '../../../../domain/mapping/workspace/endpointGeometry';
import type { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';

/** DOM measurements and SVG use the same origin/transform, retaining subpixel precision. */
export function measureEndpoint(element: Element, inverse: DOMMatrix): EndpointRect | undefined {
  if (!element.getClientRects().length) return;
  const rect = element.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const a = new DOMPoint(rect.left, rect.top).matrixTransform(inverse);
  const b = new DOMPoint(rect.right, rect.bottom).matrixTransform(inverse);
  return { x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), width: Math.abs(b.x - a.x), height: Math.abs(b.y - a.y) };
}

export function useEndpointGeometry(controller: { getSnapshot(): Pick<ReturnType<MappingDocumentController['getSnapshot']>, 'document' | 'canvas' | 'cell'>; configureEndpointBounds(bounds: EndpointBounds): void }, active: boolean) {
  const svgRef = useRef<SVGSVGElement>(null);
  const elements = useRef(new Map<string, Element>());
  const observer = useRef<ResizeObserver | null>(null);
  const frame = useRef<number | undefined>(undefined);
  const activeRef = useRef(active); activeRef.current = active;
  const measure = useCallback(() => {
    frame.current = undefined;
    const svg = svgRef.current;
    if (!activeRef.current || !svg?.getClientRects().length) { controller.configureEndpointBounds({}); return; }
    const matrix = svg.getScreenCTM();
    if (!matrix || !matrix.a || !matrix.d) return;
    const inverse = matrix.inverse();
    const bounds: Record<string, EndpointRect> = {};
    for (const [key, element] of elements.current) {
      const rect = measureEndpoint(element, inverse);
      if (rect) bounds[key] = rect;
    }
    controller.configureEndpointBounds(bounds as EndpointBounds);
  }, [controller]);
  const schedule = useCallback(() => {
    if (frame.current === undefined) frame.current = requestAnimationFrame(measure);
  }, [measure]);
  const registerEndpoint = useCallback((identity: EndpointIdentity, element: Element | null) => {
    const key = endpointKey(identity), previous = elements.current.get(key);
    if (previous === element) return;
    if (previous) observer.current?.unobserve(previous);
    if (element) { elements.current.set(key, element); observer.current?.observe(element); }
    else elements.current.delete(key);
    schedule();
  }, [schedule]);
  const endpointRefs = useRef(new Map<string, (element: Element | null) => void>());
  const refForEndpoint = useCallback((identity: EndpointIdentity) => {
    const key = endpointKey(identity);
    let callback = endpointRefs.current.get(key);
    if (!callback) {
      callback = element => registerEndpoint(identity, element);
      endpointRefs.current.set(key, callback);
    }
    return callback;
  }, [registerEndpoint]);
  useLayoutEffect(() => {
    observer.current = new ResizeObserver(schedule);
    for (const element of elements.current.values()) observer.current.observe(element);
    if (svgRef.current) observer.current.observe(svgRef.current);
    window.addEventListener('resize', schedule);
    document.fonts.addEventListener('loadingdone', schedule);
    return () => {
      observer.current?.disconnect(); observer.current = null;
      window.removeEventListener('resize', schedule);
      document.fonts.removeEventListener('loadingdone', schedule);
      if (frame.current !== undefined) cancelAnimationFrame(frame.current);
      frame.current = undefined;
    };
  }, [schedule]);
  // Movement/folding can relocate labels without resizing them. Selection controls
  // do neither, so they must not trigger a full-canvas DOM measurement.
  const { document: documentState, canvas, cell } = controller.getSnapshot();
  useLayoutEffect(() => {
    if (frame.current !== undefined) cancelAnimationFrame(frame.current);
    measure();
  }, [measure, active, documentState.scene, canvas.diagramViews, canvas.display, cell]);
  return { svgRef, registerEndpoint, refForEndpoint };
}

import { useEffect, useState } from 'react';
import { listChangeSessions, type DisplayModeChange } from './changeSessionApi';
import type { ChangeSessionSummary, DiagramChange } from '../../../../domain/mapping/changes/diagramChangeSession';
import './changeSessions.css';
const labels = { 1: 'Modify', 2: 'Add diagram', 3: 'New canvas', 4: 'Major update' };
export function ChangeBadge({ change }: { change: DiagramChange }) {
  return <span className={`change-type change-type-${change.type}`}>{change.reasons.length && change.type === 1 ? change.reasons.join('+') : change.type} {labels[change.type]}</span>;
}
export function ChangeSessionExplorer(props: { mode?: DisplayModeChange; onSelect: (mode: DisplayModeChange) => void }) {
  const [sessions, setSessions] = useState<ChangeSessionSummary[]>([]), [error, setError] = useState(''), [loading, setLoading] = useState(true);
  const [query, setQuery] = useState('');
  useEffect(() => {
    const abort = new AbortController(); let timer: ReturnType<typeof setTimeout>;
    const refresh = async () => {
      try { const result = await listChangeSessions(abort.signal); if (!abort.signal.aborted) { setSessions(result); setError(''); setLoading(false); } }
      catch (e) { if (!abort.signal.aborted) { setError(e instanceof Error ? e.message : String(e)); setLoading(false); } }
      finally { if (!abort.signal.aborted) timer = setTimeout(refresh, 2000); }
    };
    void refresh(); return () => { abort.abort(); clearTimeout(timer); };
  }, []);
  const select = (sessionId: string, documentId: string, changeId?: string) => props.onSelect({ kind: 'change-session', sessionId, documentId, changeId, serial: (props.mode?.serial ?? 0) + 1 });
  return <>
    <input type="search" aria-label="Filter change sessions" placeholder="Find changes…" value={query} onChange={e => setQuery(e.target.value)} />
    {error && <p role="alert">{error}</p>}
    {loading ? <p>Loading changes…</p> : !sessions.length && <p>No active change sessions.</p>}
    <nav aria-label="Diagram changes"><ul>{sessions.filter(s => `${s.title} ${s.changes.map(c => c.title).join(' ')}`.toLowerCase().includes(query.toLowerCase())).map(session =>
      <li key={session.id}><details open={props.mode?.sessionId === session.id || undefined}>
        <summary>{session.title} <small>{session.status} · {session.changes.length}</small></summary>
        <ul>{session.documents.filter(doc => session.changes.some(c => c.documentId === doc.id)).map(doc => <li key={doc.id}>
          <button onClick={() => select(session.id, doc.id)}>{doc.name}</button>
          <ul>{session.changes.filter(c => c.documentId === doc.id).map(change => <li key={change.id}>
            <button className={props.mode?.sessionId === session.id && props.mode.changeId === change.id ? 'is-active' : ''}
              data-change-id={change.id} onClick={() => select(session.id, doc.id, change.id)}>
              <span>{change.title}</span><ChangeBadge change={change} />
            </button>
          </li>)}</ul>
        </li>)}</ul>
        {!session.changes.length && <p>No edits yet.</p>}
      </details></li>)}</ul></nav>
  </>;
}

import { ChangePreviewState } from './changePreviewState';
import { useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ChangePreviewDocument, ChangeSessionPreview as Preview, DiagramChangeSession } from '../../../../domain/mapping/changes/diagramChangeSession';
