export function ChangeSessionPreview(props: { mode: DisplayModeChange; onSelect: (mode: DisplayModeChange) => void;
  onSearchDocument?: (document: SearchDocument) => void; searchFocus?: DiagramFocus;
  searchMatches?: readonly DiagramLineSearchResult[];
  onOpenAccepted: (session: Omit<DiagramChangeSession, 'receipts'>, documentId: string) => Promise<void> }) {
  const [loaded, setLoaded] = useState<{ session: Preview; diff: ReturnType<typeof diffChangeDocument> }>();
  const session = loaded?.session;
  const [error, setError] = useState('');
  const [accepting, setAccepting] = useState(false);
  const pendingAcceptance = useRef<{ sessionId: string; version: number; requestId: string } | undefined>(undefined);
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>, version: number | undefined;
    setLoaded(undefined); setError('');
    const worker = new Worker(new URL('./changePreview.worker.ts', import.meta.url), { type: 'module' });
    const refresh = () => {
      const endpoint = new URL(`/api/mapping/agent/change-sessions/${encodeURIComponent(props.mode.sessionId)}/preview`, location.href);
      endpoint.searchParams.set('documentId', props.mode.documentId);
      if (version !== undefined) endpoint.searchParams.set('version', String(version));
      worker.postMessage({ endpoint: endpoint.href });
    };
    worker.onmessage = ({ data }: MessageEvent<{ session?: Preview | null; diff?: ReturnType<typeof diffChangeDocument>; error?: string }>) => {
      if (data.error) setError(data.error);
      else if (data.session && data.diff) { version = data.session.version; setLoaded({ session: data.session, diff: data.diff }); setError(''); }
      if (data.session?.status !== 'accepted' && data.session?.status !== 'archived') timer = setTimeout(refresh, 2000);
    };
    worker.onerror = () => setError('Preview worker stopped. Reopen the proposal to retry.');
    refresh(); return () => { clearTimeout(timer); worker.terminate(); };
  }, [props.mode.sessionId, props.mode.documentId]);
  const doc = session?.document;
  useEffect(() => {
    if (doc && session?.id === props.mode.sessionId) props.onSearchDocument?.({
      id: `proposal:${session.id}:${doc.id}`, name: `${doc.name} (proposal)`, scope: 'proposal', document: doc.proposed.document
    });
  }, [doc, session?.id, props.mode.sessionId, props.onSearchDocument]);
  const change = session?.changes.find(c => c.id === props.mode.changeId);
  const diff = loaded?.diff;
  const modifiedDiagramIds = useMemo(() => new Set(session?.changes.flatMap(change =>
    change.documentId === doc?.id && change.type === 1 && change.nodeId ? [change.nodeId] : [])), [session, doc?.id]);
  const accept = async () => {
    if (!session || accepting) return;
    if (pendingAcceptance.current?.sessionId !== session.id || pendingAcceptance.current.version !== session.version)
      pendingAcceptance.current = { sessionId: session.id, version: session.version, requestId: crypto.randomUUID() };
    const request = pendingAcceptance.current;
    setAccepting(true); setError('');
    try {
      await acceptChangeSession(request.sessionId, request.version, request.requestId);
      const accepted = await readChangeSession(request.sessionId);
      await props.onOpenAccepted(accepted, props.mode.documentId);
    } catch (e) { setError(e instanceof Error ? e.message : String(e)); }
    finally { setAccepting(false); }
  };
  return <div className="change-session-preview" data-change-session={props.mode.sessionId}>
    {session && <div className="change-session-actions">
      <span>{session.status === 'accepted' ? 'Accepted — original review diff retained' : session.title}</span>
      {session.status === 'ready' && <button disabled={accepting} onClick={() => void accept()}>{accepting ? 'Accepting…' : 'Accept all changes'}</button>}
      {session.status === 'draft' && <span>Mark this proposal ready before accepting.</span>}
      {session.status === 'accepted' && <button onClick={() => void readChangeSession(session.id).then(full => props.onOpenAccepted(full, props.mode.documentId))
        .catch(e => setError(e instanceof Error ? e.message : String(e)))}>Open canvas</button>}
    </div>}
    {error && <p className="change-preview-message" role="alert">{error}</p>}
    {doc
      ? <PreviewCanvas key={`${session!.id}:${doc.id}:${doc.version}`} doc={doc}
          searchFocus={props.searchFocus}
          searchMatches={props.searchMatches}
          diff={diff!} modifiedDiagramIds={modifiedDiagramIds}
          focusId={change?.nodeId} serial={props.mode.serial} onJump={target => {
            const destination = session!.documents.find(d => d.representationId === target.representationId || d.id === target.representationId);
            if (!destination) { setError('Linked canvas is outside this change session'); return; }
            props.onSelect({ ...props.mode, documentId: destination.id, changeId: session!.changes.find(c => c.documentId === destination.id && c.nodeId === target.displayNodeId)?.id, serial: props.mode.serial + 1 });
          }} />
      : <p className="change-preview-message">{session ? 'Select a canvas in Changes.' : 'Loading preview…'}</p>}
  </div>;
}
function PreviewCanvas({ doc, focusId, serial, onJump, diff, modifiedDiagramIds, searchFocus, searchMatches }: { doc: ChangePreviewDocument; focusId?: string; serial: number; searchFocus?: DiagramFocus;
  searchMatches?: readonly DiagramLineSearchResult[];
  diff: ReturnType<typeof diffChangeDocument>; modifiedDiagramIds: ReadonlySet<string>;
  onJump: NonNullable<Parameters<typeof DiagramText>[0]['onJump']> }) {
  const controller = useMemo(() => {
    const state = structuredClone(doc.proposed);
    // Preview folds are local to this viewer; opening a change starts with visible content.
    const expand = (box: typeof state.document.scene.root): typeof box => box.kind === 'container'
      ? { ...box, collapsed: false, children: box.children.map(expand) } : { ...box, collapsed: false };
    state.document.scene.root = expand(state.document.scene.root); state.canvas.diagramViews = {};
    return new ChangePreviewState(state, doc.version);
  }, [doc.id, doc.version]);
  const state = useSyncExternalStore(controller.subscribe, controller.getSnapshot);
  useEffect(() => {
    if (!searchMatches?.length) return;
    controller.updateCanvas(current => {
      const revealed = revealSearchMatches(controller.getSnapshot().document.scene, current.diagramViews, searchMatches);
      return revealed.views === current.diagramViews ? current : { ...current, diagramViews: revealed.views };
    });
  }, [controller, searchMatches]);
  useEffect(() => {
    const result = searchFocus?.search;
    if (!result) return;
    controller.updateCanvas(current => {
      const view = current.diagramViews?.[result.displayNodeId];
      const content = controller.nodes().find(node => node.id === result.displayNodeId);
      if (!view || content?.layout !== 'grid' || content.content?.structure.kind !== 'tree'
        || content.content.revisionId !== result.revisionId || content.content.asciiSha256 !== result.asciiSha256) return current;
      const nodes = content.content.structure.nodes;
      return { ...current, diagramViews: { ...current.diagramViews, [result.displayNodeId]: { ...view,
        collapsedContentNodeIds: view.collapsedContentNodeIds.filter(id => !nodes[id]?.foldRanges.some(range => range.startLine <= result.line && range.endLine >= result.line)) } } };
    });
  }, [controller, searchFocus]);
  const geometry = useEndpointGeometry(controller, true);
  const [cell, setCell] = useState({ width: 8, height: 18.2 });
  const pre = useRef<HTMLPreElement>(null);
  useLayoutEffect(() => {
    const measure = () => {
      if (!pre.current) return;
      const style = getComputedStyle(pre.current), context = document.createElement('canvas').getContext('2d')!;
      context.font = style.font;
      const width = context.measureText('0000000000').width / 10, height = parseFloat(style.lineHeight);
      if (width > 0 && height > 0) setCell(old => old.width === width && old.height === height ? old : { width, height });
    };
    measure(); document.fonts.addEventListener('loadingdone', measure);
    return () => document.fonts.removeEventListener('loadingdone', measure);
  }, []);
  const scene = state.document.scene;
  const text = useMemo(() => changePreviewText(scene, state.canvas.diagramViews, diff.diagrams, modifiedDiagramIds, state.document.jumps),
    [scene, state.canvas.diagramViews, diff, modifiedDiagramIds, state.document.jumps]);
  const { resolved, boxes } = text;
  const nodes = controller.nodes();
  const controlNodes = nodes.map(node => {
    if (node.layout !== 'grid' || node.kind !== 'diagram') return node;
    const bounds = boxes.find(box => box.box.id === node.boxId)?.bounds, projection = text.projections.get(node.id);
    if (!bounds || !projection) return node;
    return { ...node, geometry: { ...node.geometry, bounds }, collapsible: { ...node.collapsible,
      subtrees: node.collapsible.subtrees.map(target => ({ ...target,
        visibleRow: projection.prefixRowForNode.get(target.contentNodeId) ?? projection.rowForLine.get(target.line),
        branchColumn: projection.columnForLine(target.line, target.branchColumn) })) } };
  });
  const focusBox = useMemo(() => searchFocus ?? (focusId?.startsWith('grid:') ? { id: focusId.slice(5), serial } : undefined), [focusId, serial, searchFocus]);
  return <DraggableDiagramCanvas enabled resetKey={doc.id} className="mapping-poc-canvas" leftInset={340}
    focusBox={focusBox}>
    <div className="change-preview-stage" style={{ position: 'relative', width: resolved.bounds.columns * cell.width, height: resolved.bounds.rows * cell.height }}>
      {(searchMatches?.length ? searchMatches : searchFocus?.search ? [searchFocus.search] : []).map(result => {
        const projection = text.projections.get(result.displayNodeId);
        const box = boxes.find(box => box.box.id === result.displayNodeId.slice(5));
        const focused = searchFocus?.search?.displayNodeId === result.displayNodeId && searchFocus.search.line === result.line;
        const row = projection?.rowForLine.get(result.line);
        return <SearchHighlight key={`${result.displayNodeId}:${result.line}`} result={result} focus={focused ? searchFocus : undefined} content={box?.box.kind === 'diagram' ? scene.contents[box.box.contentId].content : undefined}
          origin={box?.bounds} row={row} cell={cell} columnFor={column => {
            const run = row === undefined ? undefined : projection?.rows[row]?.runs.find(run => run.owner &&
              run.start - run.owner.columnOffset <= column && run.end - run.owner.columnOffset > column);
            return run?.owner ? column + run.owner.columnOffset : projection?.columnForLine(result.line, column) ?? column;
          }} />;
      })}
      <DiagramText ref={pre} className="mapping-poc-ascii" rows={text.rows} registerEndpoint={geometry.registerEndpoint} onJump={onJump}
        renderRun={run => (run as PreviewTextRun).diffStatus === 'removed'
          ? <span className="change-diff-removed" data-diff-status="removed">{run.text}</span>
          : (run as PreviewTextRun).diffVersion
          ? <span className="change-diff-modified" data-diff-status="modified" data-diff-version={(run as PreviewTextRun).diffVersion}>{run.text}</span>
          : run.text}
        nodeProps={owner => {
          if (!modifiedDiagramIds.has(owner.displayNodeId)) return;
          const side = diff.diagrams.get(owner.displayNodeId)?.proposed;
          const change = owner.contentNodeId ? side?.nodes.get(owner.contentNodeId) : undefined;
          const status = owner.contentNodeId ? change?.status : side?.lines.get(owner.sourceLine);
          if (!status && !change?.moved && !change?.containsChanges) return;
          return { className: [status && `change-diff-${status}`, change?.moved && 'change-diff-moved',
            change?.containsChanges && !status && !change.moved && 'change-diff-descendants'].filter(Boolean).join(' '),
            'data-diff-status': status, 'data-diff-moved': change?.moved || undefined, 'data-diff-descendants': change?.containsChanges || undefined,
            'data-diff-version': status === 'modified' ? 'current' : undefined,
            title: [status && `${status[0].toUpperCase()}${status.slice(1)}`, change?.moved && 'Moved or reparented',
              change?.containsChanges && 'Changes inside subtree'].filter(Boolean).join(' · ') };
        }} />
      {boxes.map(({ box, bounds }) => <div key={box.id} data-grid-box={box.id}
        ref={element => geometry.registerEndpoint({ displayNodeId: `grid:${box.id}` }, element)}
        className={`change-preview-box${focusId === `grid:${box.id}` ? ' is-change-target' : ''}`}
        style={{ left: bounds.column * cell.width, top: bounds.row * cell.height, width: bounds.columns * cell.width, height: bounds.rows * cell.height }} />)}
      <DiagramSubtreeControls nodes={controlNodes} visibleBoxIds={new Set(boxes.map(b => b.box.id))} cell={cell} disabled={false}
        onCollapse={(nodeId, contentNodeId, collapsed) => controller.collapse(nodeId, contentNodeId, collapsed)} />
      <svg className="diagram-connections" ref={geometry.svgRef} aria-label="Preview connections">
        {nodes.flatMap(node => {
          if (node.layout !== 'floating' || node.value.kind !== 'arrow') return [];
          const arrow = node.value, edge = state.document.edges.find(e => e.id === arrow.edgeId)!;
          if (!arrow.path || !arrow.target || !arrow.source) return [];
          return <g key={node.id} style={{ color: edge.appearance.color }} data-preview-edge={edge.id}>
            <PanelConnector path={arrow.path} target={arrow.target} dashed={edge.appearance.lineStyle === 'dashed' || arrow.status === 'proxy'} />
            {arrow.label?.text && <text fill={edge.appearance.color} textAnchor="middle"
              x={arrow.label.position.x} y={arrow.label.position.y}>{arrow.label.text}</text>}
          </g>;
        })}
      </svg>
    </div>
  </DraggableDiagramCanvas>;
}

import type { ChangeSessionPreview } from '../../../../domain/mapping/changes/diagramChangeSession';
import { diffChangeDocument } from '../../../../domain/mapping/changes/changeDocumentDiff';
self.onmessage = async ({ data }: MessageEvent<{ endpoint: string }>) => {
  try {
    const response = await fetch(data.endpoint, { cache: 'no-store' });
    const session = await response.json() as ChangeSessionPreview | null;
    if (!response.ok) throw Error((session as unknown as { error?: string })?.error ?? 'Could not load preview');
    const diff = session ? diffChangeDocument(session.document) : undefined;
    self.postMessage({ session, diff });
  } catch (error) { self.postMessage({ error: error instanceof Error ? error.message : String(error) }); }
};

import { deepFreeze } from '../../../../domain/core/immutability';
import { canvasDisplayNodes, findBox } from '../../../../domain/mapping/workspace/canvasDisplayNode';
import { equalEndpointBounds, type EndpointBounds } from '../../../../domain/mapping/workspace/endpointGeometry';
import type { ChangeDocumentState } from '../../../../domain/mapping/changes/diagramChangeSession';
import type { MappingCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';

/** Viewer-local folds and measurements. A preview never opens an editing context. */
export class ChangePreviewState {
  private snapshot: ChangeDocumentState & { cell?: { width: number; height: number }; endpointBounds?: EndpointBounds };
  private listeners = new Set<() => void>();
  constructor(state: ChangeDocumentState, private readonly version: number) { this.snapshot = structuredClone(state); deepFreeze(this.snapshot.document); }
  getSnapshot = () => this.snapshot;
  subscribe = (listener: () => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener); }; };
  nodes() { return canvasDisplayNodes(this.snapshot.document, this.snapshot.canvas, this.version, this.snapshot.cell, this.snapshot.endpointBounds); }
  updateCanvas(update: (canvas: MappingCanvasState) => MappingCanvasState) {
    const canvas = update(this.snapshot.canvas);
    if (canvas === this.snapshot.canvas) return;
    this.snapshot = { ...this.snapshot, canvas }; this.listeners.forEach(listener => listener());
  }
  configureEndpointBounds(endpointBounds: EndpointBounds) {
    if (equalEndpointBounds(this.snapshot.endpointBounds, endpointBounds)) return;
    this.snapshot = { ...this.snapshot, endpointBounds }; this.listeners.forEach(listener => listener());
  }
  collapse(nodeId: string, contentNodeId: string, collapsed: boolean) {
    const box = findBox(this.snapshot.document.scene.root, nodeId.replace(/^grid:/, ''));
    if (box?.kind !== 'diagram') throw Error('Expected diagram');
    const content = this.snapshot.document.scene.contents[box.contentId].content;
    if (content.structure.kind !== 'tree' || !content.structure.nodes[contentNodeId]) throw Error('STALE_CONTENT_NODE');
    this.updateCanvas(canvas => {
      const ids = new Set(canvas.diagramViews?.[nodeId]?.collapsedContentNodeIds ?? []);
      if (collapsed) ids.add(contentNodeId); else ids.delete(contentNodeId);
      return { ...canvas, diagramViews: { ...canvas.diagramViews, [nodeId]: { contentRevisionId: content.revisionId, collapsedContentNodeIds: [...ids] } } };
    });
  }
}

import type { CanvasJump } from '../../../../domain/core/diagrams/canvasJump';
import { composeScene, flattenGrid, layoutScene, measureContent, resolveScene, type GridBox, type LineGridScene } from '../../../../domain/core/diagrams/lineGrid';
import { diagramTextRanges, textRow, type DiagramTextRow, type DiagramTextRun } from '../../../../domain/core/diagrams/diagramText';
import { projectDiagramContent, type DiagramViews } from '../../../../domain/mapping/workspace/diagramViewState';
import type { DiagramContentDiff } from '../../../../domain/mapping/changes/diagramContentDiff';

export interface PreviewTextRun extends DiagramTextRun { diffVersion?: 'previous' | 'current'; diffStatus?: 'removed' }
export interface PreviewTextRow extends DiagramTextRow { runs: PreviewTextRun[] }
type Edit = { start: number; end: number; previous: string; current: string; contentNodeId?: string };

/** Display-only rows. Source content, IDs, jumps, mappings and provenance stay intact. */
export function changePreviewText(scene: LineGridScene, views: DiagramViews | undefined,
  diffs: ReadonlyMap<string, DiagramContentDiff>, modifiedDiagramIds: ReadonlySet<string>, jumps: readonly CanvasJump[] = []) {
  const projections = new Map<string, {
    rows: PreviewTextRow[]; ascii: string; rowForLine: Map<number, number>; prefixRowForNode: Map<string, number>;
    columnForLine: (line: number, column: number) => number;
  }>();
  for (const { box } of flattenGrid(resolveScene(scene))) {
    if (box.kind !== 'diagram') continue;
    const displayNodeId = `grid:${box.id}`, diagram = scene.contents[box.contentId], content = diagram.content;
    const visible = projectDiagramContent(content, views?.[displayNodeId]);
    const ranges = diagramTextRanges({ ascii: content.ascii, content, displayNodeId, mappings: diagram.sourceContext.mappings, jumps: [...(diagram.jumps ?? []), ...jumps.filter(jump => jump.sourceDisplayNodeId === displayNodeId)] });
    const source = content.ascii.split('\n'), edits = new Map<number, Edit[]>();
    if (modifiedDiagramIds.has(displayNodeId)) for (const modification of diffs.get(displayNodeId)?.modifications ?? []) {
      const selected = modification.proposed;
      const span = selected.contentNodeId
        ? ranges.get(selected.sourceLine)?.find(range => range.owner?.contentNodeId === selected.contentNodeId)
        : { start: 0, end: source[selected.sourceLine - 1]?.length ?? 0 };
      if (!span) continue;
      const edit = { start: span.start, end: span.end, previous: modification.original.text, current: modification.proposed.text, contentNodeId: selected.contentNodeId };
      const bucket = edits.get(selected.sourceLine);
      if (bucket) bucket.push(edit); else edits.set(selected.sourceLine, [edit]);
    }
    for (const bucket of edits.values()) bucket.sort((a, b) => a.start - b.start);
    const extraWidth = (edit: Edit) => 4 + Math.max(edit.previous.length, edit.current.length) - (edit.end - edit.start);
    const rows: PreviewTextRow[] = [], rowForLine = new Map<number, number>(), prefixRowForNode = new Map<string, number>();
    const view = views?.[displayNodeId];
    const collapsed = new Set(view?.contentRevisionId === content.revisionId ? view.collapsedContentNodeIds : []);
    const removals = modifiedDiagramIds.has(displayNodeId)
      ? (diffs.get(displayNodeId)?.removals ?? []).filter(removal => !removal.ancestorIds.some(id => collapsed.has(id))) : [];
    const pending = [...removals].sort((a, b) => a.beforeLine - b.beforeLine);
    const insertRemovals = (beforeLine: number) => {
      while (pending.length && pending[0].beforeLine <= beforeLine) {
        const { text, spans } = pending.shift()!;
        const runs: PreviewTextRun[] = [];
        let cursor = 0;
        for (const { start, end } of [...spans].sort((a, b) => a.start - b.start)) {
          if (start > cursor) runs.push({ start: cursor, end: start, text: text.slice(cursor, start), mappings: [] });
          runs.push({ start, end, text: text.slice(start, end), mappings: [], diffStatus: 'removed' });
          cursor = end;
        }
        if (cursor < text.length) runs.push({ start: cursor, end: text.length, text: text.slice(cursor), mappings: [] });
        rows.push({ text, runs });
      }
    };
    for (const line of visible.sourceLines) {
      insertRemovals(line);
      const original = textRow(source[line - 1], ranges.get(line) ?? [], line), changes = edits.get(line) ?? [];
      if (!changes.length) { rowForLine.set(line, rows.length); rows.push(original); continue; }
      const primary: PreviewTextRun[] = [], peer: PreviewTextRun[] = [];
      let offset = 0, cursor = 0;
      const copy = (start: number, end: number) => {
        for (const run of original.runs) {
          const from = Math.max(start, run.start), to = Math.min(end, run.end);
          if (from >= to) continue;
          primary.push({ ...run, start: from + offset, end: to + offset, text: run.text.slice(from - run.start, to - run.start),
            owner: run.owner ? { ...run.owner, columnOffset: run.owner.columnOffset + offset } : undefined });
        }
      };
      const literal = (runs: PreviewTextRun[], start: number, text: string, diffVersion?: PreviewTextRun['diffVersion']) => {
        if (text) runs.push({ start, end: start + text.length, text, mappings: [], diffVersion });
      };
      for (const edit of changes) {
        const start = edit.start + offset;
        // The tree branch and fold control introduce the pair on its first row.
        // The selected current label still owns its endpoint on the second row.
        if (edit.contentNodeId) prefixRowForNode.set(edit.contentNodeId, rows.length);
        const prefix = edit.contentNodeId
          ? original.text.slice(cursor, edit.start).match(/[ |]*[|+`\\]--(?:>)? *$/)?.[0] : undefined;
        if (prefix) {
          const prefixStart = edit.start - prefix.length;
          copy(cursor, prefixStart);
          literal(primary, prefixStart + offset, prefix.replace(/[|+`\\]--(?:>)?/, branch =>
            (branch[0] === '|' ? '|' : ' ') + ' '.repeat(branch.length - 1)));
          const end = peer.at(-1)?.end ?? 0;
          literal(peer, end, ' '.repeat(prefixStart + offset - end));
          literal(peer, prefixStart + offset, prefix);
        } else copy(cursor, edit.start);
        literal(primary, start, '[+] ', 'current');
        const peerStart = peer.at(-1)?.end ?? 0;
        literal(peer, peerStart, ' '.repeat(start - peerStart));
        literal(peer, start, `[-] ${edit.previous}`, 'previous');
        offset += 4;
        copy(edit.start, edit.end);
        const padding = extraWidth(edit) - 4;
        literal(primary, edit.end + offset, ' '.repeat(padding));
        offset += padding; cursor = edit.end;
      }
      copy(cursor, original.text.length);
      const mainRow = { text: primary.map(run => run.text).join(''), sourceLine: line, runs: primary };
      const peerRow = { text: peer.map(run => run.text).join(''), runs: peer };
      rowForLine.set(line, rows.length + 1);
      rows.push(peerRow, mainRow);
    }
    insertRemovals(Infinity);
    projections.set(displayNodeId, { rows, ascii: rows.map(row => row.text).join('\n'), rowForLine, prefixRowForNode,
      columnForLine: (line, column) => column + (edits.get(line) ?? []).filter(edit => edit.end <= column).reduce((sum, edit) => sum + extraWidth(edit), 0) });
  }

  // Reserve space and settle collisions on a temporary view of the grid. Content
  // remains the original parsed content; only this renderer's bounds are expanded.
  const resize = (box: GridBox): GridBox => {
    if (box.kind === 'container') return { ...box, children: box.children.map(resize) };
    const size = measureContent(projections.get(`grid:${box.id}`)!.ascii);
    return { ...box, minimumSize: { columns: Math.max(box.minimumSize?.columns ?? 0, size.columns), rows: Math.max(box.minimumSize?.rows ?? 0, size.rows) } };
  };
  const display = layoutScene({ ...scene, root: resize(scene.root) }, scene.root.id);
  const resolved = resolveScene(display), boxes = flattenGrid(resolved);
  const ascii = composeScene(display, (_diagram, box) => projections.get(`grid:${box.id}`)?.ascii ?? _diagram.content.ascii);
  const rows: PreviewTextRow[] = ascii.split('\n').map(text => ({ text, runs: [] }));
  for (const { box, bounds } of boxes) {
    if (box.kind !== 'diagram') continue;
    projections.get(`grid:${box.id}`)!.rows.forEach((row, i) => {
      rows[bounds.row + i].runs.push(...row.runs.map(run => ({ ...run, start: run.start + bounds.column, end: run.end + bounds.column,
        owner: run.owner ? { ...run.owner, columnOffset: run.owner.columnOffset + bounds.column } : undefined })));
    });
  }
  for (const row of rows) {
    const runs: PreviewTextRun[] = [];
    let end = 0;
    for (const run of row.runs.sort((a, b) => a.start - b.start)) {
      if (run.start > end) runs.push({ start: end, end: run.start, text: row.text.slice(end, run.start), mappings: [] });
      runs.push(run); end = run.end;
    }
    if (end < row.text.length) runs.push({ start: end, end: row.text.length, text: row.text.slice(end), mappings: [] });
    row.runs = runs;
  }
  return { rows, resolved, boxes, projections };
}

