import type { DiagramEditRun, EditDiagramInput } from '../../../../domain/mapping/agent/diagramEdit';
import { apiFetch, errorFrom } from '../../../shared/http/http';

export interface DiagramEditClient {
  capture(canvasId: string, documentId: string, nodeId: string): Promise<Pick<EditDiagramInput, 'sessionId' | 'expectedVersion' | 'baseRevisionId'>>;
  start(input: EditDiagramInput): Promise<DiagramEditRun>;
  status(runId: string): Promise<DiagramEditRun>;
  cancel(runId: string): Promise<DiagramEditRun>;
}
async function call<T>(name: string, input: unknown): Promise<T> {
  const response = await apiFetch(`/api/mapping/agent/tools/${name}`, { method: 'POST',
    headers: { 'content-type': 'application/json' }, body: JSON.stringify(input), signal: AbortSignal.timeout(65000) });
  if (!response.ok) throw await errorFrom(response);
  return response.json();
}
export function createDiagramEditClient(): DiagramEditClient {
  const attachments = new Map<string, Promise<string>>();
  return {
    async capture(canvasId, documentId, nodeId) {
      const key = JSON.stringify([canvasId, documentId]);
      let attachment = attachments.get(key);
      if (!attachment) {
        attachment = call<{ value: { sessionId: string } }>('exec', { requestId: crypto.randomUUID(),
          code: `return canvas.attach(${JSON.stringify({ canvasId, documentId })});` })
          .then(result => result.value.sessionId).catch(error => { attachments.delete(key); throw error; });
        attachments.set(key, attachment);
      }
      const sessionId = await attachment;
      try {
        const read = await call<{ version: number; node: { diagram?: { revisionId: string } } }>('diagram-search',
          { operation: 'read', sessionId, nodeId });
        if (!read.node.diagram) throw Error('The selected diagram is no longer available.');
        return { sessionId, expectedVersion: read.version, baseRevisionId: read.node.diagram.revisionId };
      } catch (error) { attachments.delete(key); throw error; }
    },
    start: input => call('edit-diagram', input),
    status: runId => call('edit-diagram-status', { runId }),
    cancel: runId => call('cancel-diagram-edit', { runId })
  };
}

import { createStore } from 'zustand/vanilla';
import type { DiagramEditRun, EditDiagramInput } from '../../../../domain/mapping/agent/diagramEdit';
import type { DiagramEditClient } from './diagramEditClient';

export interface DiagramEditTarget { canvasId: string; documentId: string; nodeId: string; label: string }
export interface DiagramEditEntry {
  target: DiagramEditTarget;
  prompt: string;
  pending: boolean;
  request?: EditDiagramInput;
  run?: DiagramEditRun;
  error?: string;
}
export const editTargetKey = (target: Pick<DiagramEditTarget, 'documentId' | 'nodeId'>) => JSON.stringify([target.documentId, target.nodeId]);
export const editUnsettled = (entry: DiagramEditEntry) => entry.pending || !!entry.request && (!entry.run
  || ['generating', 'applying', 'awaiting-acknowledgement'].includes(entry.run.status));

/** UI lifetime is independent of selection, panels and undo. Only the backend applies revisions. */
export class DiagramEditCoordinator {
  readonly store = createStore<{ entries: Record<string, DiagramEditEntry>; activeKey?: string }>(() => ({ entries: {} }));
  private timers = new Map<string, ReturnType<typeof setTimeout>>();
  private polling = new Set<string>();
  private stopped = false;
  constructor(private readonly client: DiagramEditClient, private readonly pollMs = 750) {}
  private entry(key: string) { return this.store.getState().entries[key]; }
  private patch(key: string, patch: Partial<DiagramEditEntry>) {
    if (this.stopped || !this.entry(key)) return;
    this.store.setState(state => ({ entries: { ...state.entries, [key]: { ...state.entries[key], ...patch } } }));
  }
  open(target: DiagramEditTarget) {
    const key = editTargetKey(target);
    this.store.setState(state => ({ activeKey: key, entries: { ...state.entries,
      [key]: state.entries[key] ?? { target: { ...target }, prompt: '', pending: false } } }));
  }
  show(key: string) { this.store.setState({ activeKey: key }); }
  close() {
    const key = this.store.getState().activeKey;
    if (key && !editUnsettled(this.entry(key))) this.dismiss(key);
    else this.store.setState({ activeKey: undefined });
  }
  dismiss(key: string) {
    const entry = this.entry(key);
    if (!entry || editUnsettled(entry)) return;
    clearTimeout(this.timers.get(key)); this.timers.delete(key);
    this.store.setState(state => {
      const entries = { ...state.entries }; delete entries[key];
      return { entries, activeKey: state.activeKey === key ? undefined : state.activeKey };
    });
  }
  setPrompt(key: string, prompt: string) {
    if (!editUnsettled(this.entry(key))) this.patch(key, { prompt });
  }
  private accept(key: string, run: DiagramEditRun) {
    this.patch(key, { run, error: undefined });
    this.schedule(key);
  }
  private schedule(key: string) {
    clearTimeout(this.timers.get(key)); this.timers.delete(key);
    if (this.stopped || !['generating', 'applying'].includes(this.entry(key)?.run?.status ?? '')) return;
    this.timers.set(key, setTimeout(() => { this.timers.delete(key); void this.refresh(key); }, this.pollMs));
  }
  async submit(key: string) {
    const entry = this.entry(key);
    if (editUnsettled(entry) || !entry.prompt.trim() || this.stopped) return;
    this.patch(key, { pending: true, error: undefined, run: undefined, request: undefined });
    try {
      const capture = await this.client.capture(entry.target.canvasId, entry.target.documentId, entry.target.nodeId);
      if (this.stopped) return;
      const request: EditDiagramInput = { ...capture, nodeId: entry.target.nodeId, prompt: entry.prompt.trim(), requestId: crypto.randomUUID() };
      // Retain the exact request before sending: a lost response must never start a second generation.
      this.patch(key, { request });
      this.accept(key, await this.client.start(request));
    } catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  async retry(key: string) {
    const entry = this.entry(key);
    if (entry.pending || this.stopped) return;
    if (!entry.request) return this.submit(key);
    if (entry.run && entry.run.status !== 'awaiting-acknowledgement') return this.refresh(key);
    this.patch(key, { pending: true, error: undefined });
    try { this.accept(key, await this.client.start(entry.request)); }
    catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  async refresh(key: string) {
    const run = this.entry(key)?.run;
    if (!run || this.polling.has(key) || this.stopped) return;
    this.polling.add(key);
    try {
      const next = await this.client.status(run.runId);
      // A cancel/retry response may already have moved this run forward while the read was in flight.
      if (this.entry(key)?.run === run) this.accept(key, next);
    } catch (error) { if (this.entry(key)?.run === run) this.patch(key, { error: `Could not refresh progress: ${String(error)}` }); }
    finally {
      this.polling.delete(key);
      if (this.entry(key)?.run !== run && !this.timers.has(key)) this.schedule(key);
    }
  }
  async cancel(key: string) {
    const entry = this.entry(key);
    if (entry.pending || entry.run?.status !== 'generating' || this.stopped) return;
    this.patch(key, { pending: true });
    try { this.accept(key, await this.client.cancel(entry.run.runId)); }
    catch (error) { this.patch(key, { error: String(error) }); }
    finally { this.patch(key, { pending: false }); }
  }
  dispose() {
    this.stopped = true;
    for (const timer of this.timers.values()) clearTimeout(timer);
    this.timers.clear();
  }
}

import { Fragment, useEffect, useRef, useState, useSyncExternalStore } from 'react';
import type { DiagramSearchService } from './diagramSearchService';
import type { DiagramLineSearchResult } from '../../../../domain/mapping/search/diagramSearch';
import { SearchQueryHistory } from './searchQueryHistory';
import './diagramSearch.css';

const preferenceKey = 'diagram-search-auto-select';
export function DiagramSearchPanel({ service, activeDocumentId, activeName, onReveal, onClear, onMatches }: {
  service: DiagramSearchService; activeDocumentId?: string; activeName?: string;
  onReveal: (result: DiagramLineSearchResult) => Promise<void>;
  onClear: () => void;
  onMatches: (results: readonly DiagramLineSearchResult[]) => void;
}) {
  const [opened, setOpened] = useState(false), [global, setGlobal] = useState(false);
  const [query, setQuery] = useState(''), [caseSensitive, setCaseSensitive] = useState(false);
  const [queryHistory] = useState(() => {
    try { return new SearchQueryHistory(localStorage); } catch { return new SearchQueryHistory(); }
  });
  const [autoSelect, setAutoSelect] = useState(() => {
    try { return localStorage.getItem(preferenceKey) !== 'false'; } catch { return true; }
  });
  const [selected, setSelected] = useState(0), [navigationError, setNavigationError] = useState('');
  const [focusSerial, setFocusSerial] = useState(0);
  const input = useRef<HTMLInputElement>(null), list = useRef<HTMLDivElement>(null);
  const previousFocus = useRef<HTMLElement | null>(null);
  const lastRevealed = useRef(-1);
  const searchTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const state = useSyncExternalStore(service.subscribe, service.getSnapshot);
  const open = (all: boolean) => {
    if (!opened) previousFocus.current = document.activeElement as HTMLElement;
    setGlobal(all); setOpened(true); setFocusSerial(value => value + 1);
  };
  const close = () => { setOpened(false); previousFocus.current?.focus(); };
  useEffect(() => {
    const key = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && !event.altKey && event.key.toLowerCase() === 'f') {
        event.preventDefault(); event.stopPropagation(); open(event.shiftKey);
      } else if (opened && event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
    };
    window.addEventListener('keydown', key, true);
    return () => window.removeEventListener('keydown', key, true);
  }, [opened]);
  useEffect(() => { if (opened) { input.current?.focus(); input.current?.select(); } }, [opened, focusSerial]);
  const scopeDocumentId = global ? undefined : activeDocumentId;
  useEffect(() => {
    service.cancel(); onClear(); setSelected(0); lastRevealed.current = -1; setNavigationError('');
    if (!query || (!global && !scopeDocumentId)) return;
    const timer = searchTimer.current = setTimeout(() => service.search({ text: query, caseSensitive,
      scope: global ? { kind: 'global' } : { kind: 'canvas', documentId: scopeDocumentId! } }), 120);
    return () => clearTimeout(timer);
  }, [service, global, scopeDocumentId, query, caseSensitive, onClear]);
  useEffect(() => {
    if (!autoSelect || !query || state.searching || state.error) { onMatches([]); return; }
    // Wait for a completed result set and a short typing pause before selecting.
    const timer = setTimeout(() => onMatches(state.results), 250);
    return () => clearTimeout(timer);
  }, [autoSelect, query, state.results, state.searching, state.error, onMatches]);
  const reveal = async (result: DiagramLineSearchResult, index: number) => {
    lastRevealed.current = index;
    setNavigationError('');
    try { await onReveal(result); }
    catch (error) { setNavigationError(error instanceof Error ? error.message : String(error)); }
  };
  const current = Math.min(selected, Math.max(0, state.results.length - 1));
  const changeQuery = (value: string) => { service.cancel(); onClear(); setQuery(value); };
  const runSearch = () => {
    if (!query.trim()) return;
    queryHistory.submit(query);
    clearTimeout(searchTimer.current);
    if (!global && !scopeDocumentId) return;
    setSelected(0); lastRevealed.current = -1; setNavigationError('');
    service.search({ text: query, caseSensitive, scope: global ? { kind: 'global' } : { kind: 'canvas', documentId: scopeDocumentId! } });
    input.current?.focus();
  };
  return <>
    {!opened && <button className="diagram-search-open" aria-label="Search diagrams" title="Find in canvas (Ctrl+F); find in project (Ctrl+Shift+F)" onClick={() => open(global)}>Search</button>}
    {opened && <section className="diagram-search-panel" role="search" aria-label="Diagram search" onKeyDown={event => {
      if (event.nativeEvent.isComposing) return;
      const inInput = event.target === input.current;
      const navigatingResults = event.target instanceof Element && !!event.target.closest('.diagram-search-results');
      if (inInput && (event.key === 'ArrowDown' || event.key === 'ArrowUp')) {
        event.preventDefault();
        const next = event.key === 'ArrowUp' ? queryHistory.previous(query) : queryHistory.next(query);
        if (next !== query) changeQuery(next);
      } else if (navigatingResults && (event.key === 'ArrowDown' || event.key === 'ArrowUp')) {
        event.preventDefault();
        const next = Math.max(0, Math.min(state.results.length - 1, current + (event.key === 'ArrowDown' ? 1 : -1)));
        setSelected(next); lastRevealed.current = -1; list.current?.querySelectorAll('button')[next]?.scrollIntoView({ block: 'nearest' });
      } else if (event.key === 'Enter' && inInput) {
        event.preventDefault();
        queryHistory.submit(query);
        if (!state.results[current] || state.searching) return;
        const next = lastRevealed.current === current ? (current + (event.shiftKey ? -1 : 1) + state.results.length) % state.results.length : current;
        setSelected(next); list.current?.querySelectorAll('button')[next]?.scrollIntoView({ block: 'nearest' });
        void reveal(state.results[next], next);
      }
    }}>
      <header><strong>Find in diagrams</strong><button aria-label="Close diagram search" onClick={close}>×</button></header>
      <div className="diagram-search-options">
        <label>Scope<select aria-label="Diagram search scope" value={global ? 'global' : 'canvas'} onChange={event => setGlobal(event.target.value === 'global')}>
          <option value="canvas">This canvas</option><option value="global">Entire project</option>
        </select></label>
        <label><input type="checkbox" checked={caseSensitive} onChange={event => setCaseSensitive(event.target.checked)} />Match case</label>
        <label><input type="checkbox" checked={autoSelect} onChange={event => {
          setAutoSelect(event.target.checked);
          try { localStorage.setItem(preferenceKey, String(event.target.checked)); } catch { /* Optional browser preference. */ }
        }} />Auto-select matches</label>
      </div>
      <div className="diagram-search-query">
        <input ref={input} type="search" aria-label="Search diagram text" aria-describedby="diagram-search-history-help" placeholder="Search diagram text…" value={query}
          onChange={event => { queryHistory.edited(); changeQuery(event.target.value); }} />
        <button type="button" aria-label="Run diagram search" disabled={!query.trim()} onClick={runSearch}>Search</button>
      </div>
      <small id="diagram-search-history-help">↑/↓ query history · Enter next result · Shift+Enter previous</small>
      <small>{global ? 'Current project diagrams · includes unsaved edits' : activeName ?? 'No active canvas'}</small>
      <p role="status">{state.error || navigationError || (!query ? 'Enter text to search.' : state.searching ? `Searching… ${state.results.length} lines` : `${state.results.length}${state.truncated ? '+' : ''} matching ${state.results.length === 1 ? 'line' : 'lines'}`)}
        {state.truncated && ' · Refine your search to see more.'}</p>
      <div ref={list} className="diagram-search-results" aria-label="Diagram search results">
        {state.results.map((result, i) => {
          const previous = state.results[i - 1];
          let cursor = 0;
          const pieces = result.matches.flatMap((match, j) => {
            const before = result.text.slice(cursor, match.startColumn - 1); cursor = match.endColumn;
            return [before, <mark key={j}>{result.text.slice(match.startColumn - 1, match.endColumn)}</mark>];
          });
          return <Fragment key={`${result.canvasDocumentId}:${result.displayNodeId}:${result.line}`}>
            {(previous?.canvasDocumentId !== result.canvasDocumentId || previous.displayNodeId !== result.displayNodeId) &&
              <h3>{result.canvasName}<span>{result.diagramName || result.diagramId}</span></h3>}
            <button className={i === current ? 'is-current' : ''} data-search-result-line={result.line}
              data-search-result-canvas={result.canvasDocumentId} data-search-result-node={result.displayNodeId}
              title={`${result.canvasName} · ${result.diagramName} · line ${result.line}`}
              aria-current={i === current ? 'true' : undefined}
              onClick={() => { setSelected(i); void reveal(result, i); }}>
              <span className="diagram-search-line-number">{result.line}</span><code>{pieces}{result.text.slice(cursor)}</code>
            </button>
          </Fragment>;
        })}
      </div>
    </section>}
  </>;
}

import type { DiagramContent } from '../../../../domain/core/diagrams/diagramContent';
import type { DiagramFocus } from '../../../../domain/core/diagrams/diagramCanvas';
export type { DiagramFocus } from '../../../../domain/core/diagrams/diagramCanvas';

export function SearchHighlight({ focus, result = focus?.search, content, row, columnFor, origin, cell }: {
  result?: DiagramFocus['search'];
  focus?: DiagramFocus; content?: DiagramContent; row?: number;
  columnFor?: (column: number) => number;
  origin?: { column: number; row: number }; cell: { width: number; height: number };
}) {
  if (!result || !origin || row === undefined || content?.revisionId !== result.revisionId || content.asciiSha256 !== result.asciiSha256) return null;
  return <>{result.matches.map((match, i) => {
    const left = columnFor?.(match.startColumn - 1) ?? match.startColumn - 1;
    const right = columnFor?.(match.endColumn - 1) ?? match.endColumn - 1;
    return <span key={i} className={`diagram-search-highlight${focus ? ' is-current' : ''}`} data-search-focus={focus?.serial} data-search-box={result.displayNodeId.slice(5)}
      data-search-line={result.line} aria-hidden="true" style={{ left: (origin.column + left) * cell.width,
        top: (origin.row + row) * cell.height, width: (right - left + 1) * cell.width, height: cell.height }} />;
  })}</>;
}

