import { DiagramSearchIndex, type SearchWorkerRequest, type SearchWorkerResponse } from '../../../../domain/mapping/search/diagramSearch';

const index = new DiagramSearchIndex();
let task = 0;
const send = (message: SearchWorkerResponse) => postMessage(message);
onmessage = async ({ data }: MessageEvent<SearchWorkerRequest>) => {
  const current = ++task;
  try {
    if (data.type === 'cancel') return;
    if (data.type === 'sync') { index.update(data.update); return; }
    if (data.generation !== index.generation) return;
    for (const batch of index.search(data.query)) {
      if (current !== task) return;
      send({ type: 'results', requestId: data.requestId, generation: data.generation, ...batch });
      if (!batch.done) await new Promise(resolve => setTimeout(resolve, 0));
    }
  } catch (error) { send({ type: 'error', message: error instanceof Error ? error.message : String(error) }); }
};

import type { DiagramContent } from '../../../../domain/core/diagrams/diagramContent';
import type { MappingGridDocument } from '../../../../domain/mapping/workspace/mappingGrid';
import type { DiagramLineSearchResult, SearchPlacement, SearchQuery, SearchWorkerRequest, SearchWorkerResponse } from '../../../../domain/mapping/search/diagramSearch';

export interface SearchDocument { id: string; name: string; scope: 'project' | 'proposal'; document: MappingGridDocument }
export interface SearchWorkerPort {
  postMessage(message: SearchWorkerRequest): void;
  onmessage: ((event: MessageEvent<SearchWorkerResponse>) => void) | null;
  onerror: ((event: ErrorEvent) => void) | null;
  terminate(): void;
}
export interface DiagramSearchState { results: DiagramLineSearchResult[]; searching: boolean; truncated: boolean; error?: string }
const emptyState = (): DiagramSearchState => ({ results: [], searching: false, truncated: false });

export class DiagramSearchService {
  private worker?: SearchWorkerPort;
  private contentKeys = new Set<string>();
  private placementSignature = '';
  private documents: readonly SearchDocument[] = [];
  private generation = 0;
  private requestId = 0;
  private query?: SearchQuery;
  private state = emptyState();
  private listeners = new Set<() => void>();
  constructor(private readonly createWorker: () => SearchWorkerPort) {}
  getSnapshot = () => this.state;
  subscribe = (listener: () => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener); }; };
  private publish(state: DiagramSearchState) { this.state = state; this.listeners.forEach(listener => listener()); }
  private connect() {
    if (this.worker) return this.worker;
    const worker = this.createWorker(); this.worker = worker;
    worker.onmessage = ({ data }) => {
      if (data.type === 'error') { this.publish({ ...this.state, searching: false, error: data.message }); return; }
      if (data.requestId !== this.requestId || data.generation !== this.generation) return;
      this.publish({ results: [...this.state.results, ...data.results], searching: !data.done, truncated: data.truncated });
    };
    worker.onerror = () => this.publish({ ...this.state, searching: false, error: 'Diagram search worker failed. Reopen the page to retry.' });
    return worker;
  }
  /** No history, source files, view geometry, or source evidence crosses this boundary. */
  sync(documents: readonly SearchDocument[]) {
    // Selection and camera updates must not walk every diagram or serialize its placements.
    if (documents.length === this.documents.length && documents.every((doc, i) => {
      const old = this.documents[i];
      return doc.id === old.id && doc.name === old.name && doc.scope === old.scope && doc.document.scene === old.document.scene;
    })) return;
    const contents = new Map<string, DiagramContent>(), placements: SearchPlacement[] = [];
    for (const doc of documents) {
      const visit = (box: MappingGridDocument['scene']['root']) => {
        if (box.kind === 'container') { box.children.forEach(visit); return; }
        const diagram = doc.document.scene.contents[box.contentId];
        if (!diagram) return;
        const content = diagram.content;
        const key = JSON.stringify([content.revisionId, content.asciiSha256, content.structure.kind,
          content.structure.kind === 'tree' ? content.structure.parserVersion : '']);
        contents.set(key, content);
        placements.push({ canvasDocumentId: doc.id, canvasName: doc.name, scope: doc.scope,
          displayNodeId: `grid:${box.id}`, diagramId: diagram.id, diagramName: content.ascii.split('\n', 1)[0], contentKey: key });
      };
      visit(doc.document.scene.root);
    }
    const signature = JSON.stringify(placements);
    if (signature === this.placementSignature) { this.documents = documents; return; }
    try {
      this.connect().postMessage({ type: 'sync', update: { generation: ++this.generation, placements,
        upsert: [...contents].filter(([key]) => !this.contentKeys.has(key)).map(([key, content]) => ({ key, content })),
        remove: [...this.contentKeys].filter(key => !contents.has(key)) } });
      this.contentKeys = new Set(contents.keys()); this.placementSignature = signature;
      this.documents = documents;
      if (this.query) this.search(this.query);
    } catch (error) { this.publish({ ...emptyState(), error: String(error) }); }
  }
  search(query: SearchQuery) {
    this.query = query; this.requestId++;
    if (!query.text) { this.worker?.postMessage({ type: 'cancel' }); this.publish(emptyState()); return; }
    this.publish({ ...emptyState(), searching: true });
    try { this.connect().postMessage({ type: 'search', query, requestId: this.requestId, generation: this.generation }); }
    catch (error) { this.publish({ ...emptyState(), error: String(error) }); }
  }
  cancel() { this.query = undefined; this.requestId++; this.worker?.postMessage({ type: 'cancel' }); this.publish(emptyState()); }
  dispose() { this.cancel(); this.worker?.terminate(); this.worker = undefined; this.contentKeys.clear(); this.placementSignature = ''; this.documents = []; }
}

import type { DiagramLineSearchResult } from '../../../../domain/mapping/search/diagramSearch';
import type { GridBox, LineGridScene } from '../../../../domain/core/diagrams/lineGrid';
import type { DiagramViews } from '../../../../domain/mapping/workspace/diagramViewState';

/** Reveal matching lines without changing content or moving the camera. */
export function revealSearchMatches(scene: LineGridScene, views: DiagramViews | undefined, matches: readonly DiagramLineSearchResult[]) {
  let nextViews = views;
  const byBox = new Map<string, DiagramLineSearchResult[]>();
  for (const match of matches) {
    const bucket = byBox.get(match.displayNodeId) ?? [];
    bucket.push(match); byBox.set(match.displayNodeId, bucket);
  }
  const visit = (box: GridBox): { box: GridBox; matched: boolean } => {
    if (box.kind === 'container') {
      const children = box.children.map(visit), matched = children.some(child => child.matched);
      return { matched, box: children.some((child, i) => child.box !== box.children[i]) || matched && box.collapsed
        ? { ...box, collapsed: matched ? false : box.collapsed, children: children.map(child => child.box) } : box };
    }
    const content = scene.contents[box.contentId]?.content;
    const hits = byBox.get(`grid:${box.id}`)?.filter(hit => hit.revisionId === content?.revisionId && hit.asciiSha256 === content.asciiSha256);
    if (!hits?.length || !content) return { box, matched: false };
    const view = views?.[`grid:${box.id}`];
    if (view && content.structure.kind === 'tree') {
      const nodes = content.structure.nodes;
      const collapsedContentNodeIds = view.collapsedContentNodeIds.filter(id => !nodes[id]?.foldRanges.some(range => hits.some(hit => hit.line >= range.startLine && hit.line <= range.endLine)));
      if (collapsedContentNodeIds.length !== view.collapsedContentNodeIds.length)
        nextViews = { ...nextViews, [`grid:${box.id}`]: { ...view, collapsedContentNodeIds } };
    }
    return { matched: true, box: box.collapsed ? { ...box, collapsed: false } : box };
  };
  const root = visit(scene.root).box;
  return { root, views: nextViews };
}

export const SEARCH_QUERY_HISTORY_KEY = 'diagram-search-queries';
const limit = 50;
type HistoryStorage = Pick<Storage, 'getItem' | 'setItem'>;

/** Submitted queries only. Browsing preserves the unfinished query at the end. */
export class SearchQueryHistory {
  private entries: string[] = [];
  private cursor = -1;
  private draft = '';
  constructor(private readonly storage?: HistoryStorage) {
    try {
      const saved: unknown = JSON.parse(storage?.getItem(SEARCH_QUERY_HISTORY_KEY) ?? '[]');
      if (Array.isArray(saved)) this.entries = [...new Set(saved.filter((query): query is string =>
        typeof query === 'string' && !!query.trim()))].slice(0, limit);
    } catch { /* History remains available in memory if browser storage is unavailable. */ }
  }
  submit(query: string) {
    if (!query.trim()) return;
    this.entries = [query, ...this.entries.filter(entry => entry !== query)].slice(0, limit);
    this.cursor = -1;
    try { this.storage?.setItem(SEARCH_QUERY_HISTORY_KEY, JSON.stringify(this.entries)); } catch { /* Keep in-memory history. */ }
  }
  edited() { this.cursor = -1; }
  previous(current: string): string {
    if (!this.entries.length) return current;
    if (this.cursor === -1) this.draft = current;
    this.cursor = Math.min(this.cursor + 1, this.entries.length - 1);
    return this.entries[this.cursor];
  }
  next(current: string): string {
    if (this.cursor === -1) return current;
    this.cursor--;
    return this.cursor === -1 ? this.draft : this.entries[this.cursor];
  }
}

