import type { DiagramGenerator } from '../../../../domain/core/diagrams/diagramService';
import { promptMappingPocSelection } from '../api';

export const httpDiagramGenerator: DiagramGenerator = {
  async generate(request, options) {
    const context = request.context;
    if (!context) throw new Error('Select diagram content before generating');
    const { diagram, selection, ...project } = context;
    const result = await promptMappingPocSelection({ ...project,
      clientSessionId: `generate-${crypto.randomUUID()}`, operation: 'generate',
      contentId: diagram.id, diagramAscii: diagram.content.ascii, diagramRevision: diagram.revision,
      sourceContext: diagram.sourceContext, mappings: [...diagram.sourceContext.mappings],
      selection, instruction: request.instruction
    }, options.onProgress ?? (() => {}), options.signal);
    return { ascii: result.diagramAscii, mappings: result.mappings ?? [],
      source: diagram.sourceContext.binding, evidence: diagram.sourceContext.evidence };
  }
};

import { memo, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import type { ProjectSourceFile } from '../../../shared/http/api';
import { useMappingServices } from '../services/MappingServices';
import { SourceCodeView } from '../../../shared/source/SourceCodeView';
import { RepositoryFileExplorer } from '../../../shared/source/RepositoryFileExplorer';
import { supportsDefinitions, type SourceLocation, type SourcePosition } from '../../../../domain/core/source/sourceNavigation';
import type { SourceCodePaneView } from './sourceCodePane';
import type { SourceCodePaneContent } from '../../../../domain/mapping/workspace/displayModel';
import { SourcePaneDocumentActiveContext, SourcePaneDocumentContext, SourcePaneViewStateContext } from './SourcePaneViewStateContext';

const presentation = { syntaxHighlighting: 'code', markdownRendering: 'source', wrap: false, sourceCompaction: true } as const;
const emptyEntries: { startLine: number; endLine: number }[] = [];
type Visit = SourceLocation & { scroll?: { top: number; left: number }; rangeIndex?: number };

/** Source navigation stays within the existing display pane and its projection ownership. */
export const SourceCodePane = memo(function SourceCodePane(props: {
  id: string; content: SourceCodePaneContent; initialLocation?: SourceLocation;
  onChange: (id: string, patch: Partial<SourceCodePaneView>) => void;
}) {
  const { content } = props;
  const { codeRepo } = useMappingServices();
  const viewState = useContext(SourcePaneViewStateContext);
  const documentId = useContext(SourcePaneDocumentContext);
  const active = useContext(SourcePaneDocumentActiveContext);
  const scrollState = useMemo(() => viewState?.bind(documentId, props.id, content.sourceFile, content.scroll, content.sourceId),
    [viewState, documentId, props.id, content.sourceFile, content.scroll, content.sourceId]);
  const onChange = useCallback((patch: Partial<SourceCodePaneView>) => props.onChange(props.id, patch), [props.id, props.onChange]);
  const file = content.files.find(file => file.sourceFile === content.sourceFile);
  const root = useRef<HTMLElement>(null);
  const [preview, setPreview] = useState<ProjectSourceFile | null>(null);
  const [error, setError] = useState('');
  const [attempt, setAttempt] = useState(0);
  const [revealRequestId, setRevealRequestId] = useState(0);
  const [navigation, setNavigation] = useState<{ visit: Visit; id: number } | undefined>(() => props.initialLocation ? { visit: props.initialLocation, id: 1 } : undefined);
  const [explorerOpen, setExplorerOpen] = useState(false);
  const [history, setHistory] = useState<{ back: Visit[]; forward: Visit[] }>({ back: [], forward: [] });
  const [definitionMessage, setDefinitionMessage] = useState('');
  const [definitions, setDefinitions] = useState<SourceLocation[]>([]);
  const definitionRequest = useRef<AbortController | undefined>(undefined);
  const entries = file?.ranges ?? emptyEntries;
  const compactedSource = file?.compactedSource;

  useEffect(() => {
    const controller = new AbortController();
    setPreview(null); setError('');
    void codeRepo.readFile({ projectId: content.projectId, sourceId: content.sourceId ?? '' }, content.sourceFile, { signal: controller.signal })
      .then(result => { if (!controller.signal.aborted) setPreview({ path: result.path, startLine: 1, lines: result.text.split('\n'), sourceSha256: result.sha256, lspEnabled: Boolean(result.lspEnabled) }); })
      .catch((error: unknown) => { if (!controller.signal.aborted) setError(error instanceof Error ? error.message : 'Could not load source file'); });
    return () => controller.abort();
  }, [codeRepo, content.projectId, content.sourceId, content.sourceFile, attempt]);
  useEffect(() => {
    definitionRequest.current?.abort(); setDefinitionMessage(''); setDefinitions([]);
    return () => definitionRequest.current?.abort();
  }, [content.projectId, content.sourceId, content.sourceFile, active]);

  const loaded = preview?.path === content.sourceFile ? preview : null;
  const stale = Boolean(file && loaded && loaded.sourceSha256 !== file.sourceSha256);
  const rangeIndex = Math.min(content.rangeIndex, Math.max(0, entries.length - 1));
  const target = entries[rangeIndex];
  const destination = navigation?.visit.path === content.sourceFile ? navigation.visit : undefined;
  const range = useMemo(() => ({ path: content.sourceFile, startLine: target?.startLine ?? 1,
    endLine: target?.endLine ?? 1, compactedSource: stale ? undefined : compactedSource }), [content.sourceFile, target, stale, compactedSource]);
  const capture = (): Visit => {
    const viewer = root.current?.querySelector<HTMLElement>('.source-code-viewer');
    return { path: content.sourceFile, rangeIndex: content.rangeIndex, range: destination?.range,
      scroll: viewer?.getClientRects().length ? { top: viewer.scrollTop, left: viewer.scrollLeft } : scrollState?.read() ?? content.scroll };
  };
  const navigate = (visit: Visit, direction?: 'back' | 'forward') => {
    definitionRequest.current?.abort(); setDefinitions([]); setDefinitionMessage('');
    const current = capture();
    setHistory(history => direction === 'back' ? { back: history.back.slice(0, -1), forward: [...history.forward, current] }
      : direction === 'forward' ? { back: [...history.back, current], forward: history.forward.slice(0, -1) }
      : { back: [...history.back.slice(-99), current], forward: [] });
    viewState?.resetPane(documentId, props.id);
    onChange({ sourceFile: visit.path, rangeIndex: visit.rangeIndex ?? 0, scroll: visit.scroll });
    setNavigation(current => ({ visit, id: (current?.id ?? 0) + 1 }));
  };
  const openFile = (path: string) => { if (path !== content.sourceFile) navigate({ path }); };
  const reveal = (index: number) => {
    viewState?.resetPane(documentId, props.id);
    setNavigation(undefined);
    onChange({ rangeIndex: index, scroll: undefined });
    setRevealRequestId(id => id + 1);
  };
  const lookup = async (position: SourcePosition) => {
    if (!loaded?.lspEnabled || !supportsDefinitions(content.sourceFile)) return;
    definitionRequest.current?.abort();
    const controller = new AbortController(); definitionRequest.current = controller;
    setDefinitionMessage('Finding definition…'); setDefinitions([]);
    try {
      const result = await codeRepo.definitions({ projectId: content.projectId, sourceId: content.sourceId ?? '' }, { path: content.sourceFile, position, sourceSha256: loaded.sourceSha256 }, { signal: controller.signal });
      if (controller.signal.aborted) return;
      if (result.locations.length === 1) navigate(result.locations[0]);
      else {
        setDefinitions(result.locations);
        setDefinitionMessage(result.locations.length ? 'Choose a definition:' : result.outsideRoot ? 'Definition is outside this repository.' : 'No definition found.');
      }
    } catch (error) { if (!controller.signal.aborted) setDefinitionMessage(error instanceof Error ? error.message : 'Definition lookup failed'); }
  };

  return <section ref={root} className="mapping-source-pane" data-projected-source={content.sourceFile} aria-label={`Source file ${content.sourceFile}`}>
    <div className="mapping-source-file-header">
      <button type="button" aria-label="Toggle repository files" aria-expanded={explorerOpen} onClick={() => setExplorerOpen(open => !open)}>{explorerOpen ? '▾' : '▸'} Files</button>
      <button type="button" aria-label="Back in source history" disabled={!history.back.length} onClick={() => navigate(history.back.at(-1)!, 'back')}>←</button>
      <button type="button" aria-label="Forward in source history" disabled={!history.forward.length} onClick={() => navigate(history.forward.at(-1)!, 'forward')}>→</button>
      <select aria-label="Projected source file" value={content.sourceFile} onChange={event => openFile(event.target.value)}>
        {!file && <option value={content.sourceFile}>{content.sourceFile}</option>}
        {content.files.map(file => <option key={file.sourceFile} value={file.sourceFile}>{file.sourceFile}</option>)}
      </select>
    </div>
    <div className="mapping-source-body">
      {explorerOpen && <RepositoryFileExplorer codeRepo={codeRepo} projectId={content.projectId} sourceId={content.sourceId} selected={content.sourceFile} onOpen={openFile} />}
      <div className="mapping-source-main">
        <div className="mapping-source-toolbar">
          <button type="button" aria-pressed={content.showCompactions} disabled={!loaded || stale || !file}
            onClick={() => onChange({ showCompactions: !content.showCompactions })}>Compact source</button>
          <span>{target ? `Lines ${target.startLine}–${target.endLine}` : 'No mapped ranges'}</span>
          <button type="button" aria-label="Previous mapped range" disabled={!loaded || stale || !entries.length} onClick={() => reveal((rangeIndex + entries.length - 1) % entries.length)}>↑</button>
          <button type="button" aria-label="Next mapped range" disabled={!loaded || stale || !entries.length} onClick={() => reveal((rangeIndex + 1) % entries.length)}>↓</button>
          <button type="button" aria-label="Reload source file" onClick={() => { definitionRequest.current?.abort(); setDefinitionMessage(''); setDefinitions([]); setAttempt(n => n + 1); }}>↻</button>
        </div>
        {loaded?.lspEnabled && supportsDefinitions(content.sourceFile) && <small className="source-navigation-hint">Ctrl/Cmd+click or F12: go to definition</small>}
        {definitionMessage && <div className="mapping-source-message" role="status">{definitionMessage}
          {definitions.map((location, index) => <button type="button" key={index} onClick={() => navigate(location)}>{location.path}:{(location.range?.start.line ?? 0) + 1}</button>)}
        </div>}
        {stale && <p className="mapping-source-message" role="status">This file has changed since the projection was created. Showing current source without range highlights or compaction folds. Update the projection to align them.</p>}
        {error ? <div className="mapping-source-message" role="alert"><p>{error}</p><button type="button" onClick={() => setAttempt(value => value + 1)}>Retry</button></div>
          : !loaded ? <p className="mapping-source-message" role="status">Loading source…</p>
          : <SourceCodeView key={`${content.projectId}:${content.sourceFile}:${navigation?.id ?? 0}`} preview={loaded}
            range={range} compacted={Boolean(file && !stale && content.showCompactions)} presentation={presentation} highlightedRanges={stale ? emptyEntries : entries} deferOffscreen
            targetLine={destination?.range ? destination.range.start.line + 1 : stale ? 1 : target?.startLine}
            navigationRange={destination?.range} revealRequestId={revealRequestId}
            onGoToDefinition={loaded.lspEnabled && supportsDefinitions(content.sourceFile) ? lookup : undefined}
            initialScrollPosition={content.scroll} scrollState={scrollState} active={active}
            onScrollPositionChange={scrollState ? undefined : scroll => onChange({ scroll })} />}
      </div>
    </div>
  </section>;
});

import { createContext } from 'react';
import type { SourcePaneViewState } from './sourcePaneViewState';

export const SourcePaneViewStateContext = createContext<SourcePaneViewState | null>(null);
export const SourcePaneDocumentContext = createContext('');
export const SourcePaneDocumentActiveContext = createContext(true);

import { isRepositoryFilePath } from '../../../../domain/core/source/sourceNavigation';
import { type DisplayState, type SourceCodePaneContent } from '../../../../domain/mapping/workspace/displayModel';

export type SourceCodePaneView = Pick<SourceCodePaneContent, 'sourceId' | 'sourceFile' | 'showCompactions' | 'rangeIndex' | 'scroll'>;

export function updateSourceCodePane(state: DisplayState, id: string, patch: Partial<SourceCodePaneView>): DisplayState {
  const node = state.nodes[id];
  if (node?.kind !== 'projection' || node.content.kind !== 'source-code') return state;
  const content = { ...node.content, ...patch };
  if (!isRepositoryFilePath(content.sourceFile)) return state;
  if (content.sourceId === node.content.sourceId && content.sourceFile === node.content.sourceFile && content.rangeIndex === node.content.rangeIndex
    && content.showCompactions === node.content.showCompactions
    && content.scroll?.top === node.content.scroll?.top && content.scroll?.left === node.content.scroll?.left) return state;
  return { ...state, nodes: { ...state.nodes, [id]: { ...node, title: content.sourceFile, content } } };
}

import type { DisplayState, ProjectedPane } from '../../../../domain/mapping/workspace/displayModel';
import type { CanvasTransform } from '../../../../domain/core/diagrams/diagramCanvas';
import type { ScrollPosition, SourceScrollState } from '../../../shared/source/sourceScrollState';
interface Entry {
  sourceId?: string;
  sourceFile: string;
  position: ScrollPosition;
  read?: () => ScrollPosition | undefined;
  owner?: symbol;
}

function ownsViewport(content: ProjectedPane['content'], entry: Entry): content is Extract<ProjectedPane['content'], { kind: 'code-panel' | 'source-code' }> {
  if (content.kind === 'code-panel') return entry.sourceFile === '@code-panel';
  return content.kind === 'source-code' && content.sourceFile === entry.sourceFile && content.sourceId === entry.sourceId;
}

/** Live viewport state is sampled at snapshot time, never published into the React display tree. */
export class SourcePaneViewState {
  private readonly listeners = new Set<(documentId: string) => void>();
  private readonly timers = new Map<string, ReturnType<typeof setTimeout>>();
  get pending() { return this.timers.size > 0; }
  subscribe(listener: (documentId: string) => void) { this.listeners.add(listener); return () => { this.listeners.delete(listener); }; }
  private changed(id: string) {
    if (this.timers.has(id)) return;
    this.timers.set(id, setTimeout(() => { this.timers.delete(id); this.listeners.forEach(fn => fn(id)); }, 250));
  }
  flush() { for (const [id, timer] of this.timers) { clearTimeout(timer); this.listeners.forEach(fn => fn(id)); } this.timers.clear(); }
  dispose() { for (const timer of this.timers.values()) clearTimeout(timer); this.timers.clear(); this.listeners.clear(); }
  private readonly entries = new Map<string, Map<string, Entry>>();
  private readonly cameras = new Map<string, CanvasTransform>();
  private readonly captures = new Map<string, { input: DisplayState; output: DisplayState }>();

  bind(documentId: string, paneId: string, sourceFile: string, fallback?: ScrollPosition, sourceId?: string): SourceScrollState {
    const owner = Symbol();
    const current = () => {
      const entry = this.entries.get(documentId)?.get(paneId);
      return entry?.sourceFile === sourceFile && entry.sourceId === sourceId ? entry : undefined;
    };
    return {
      read: () => current()?.position ?? fallback,
      connect: read => {
        let panes = this.entries.get(documentId);
        if (!panes) this.entries.set(documentId, panes = new Map());
        const entry: Entry = { sourceFile, sourceId, position: read() ?? current()?.position ?? fallback ?? { top: 0, left: 0 }, read, owner };
        panes.set(paneId, entry);
        return () => {
          // A reset or a newly mounted viewer takes ownership before an old cleanup may run.
          if (current() !== entry) return;
          entry.position = read() ?? entry.position;
          delete entry.read;
          delete entry.owner;
        };
      },
      write: position => {
        const entry = current();
        if (entry?.owner === owner) { entry.position = position; this.changed(documentId); }
      }
    };
  }

  resetPane(documentId: string, paneId: string) {
    this.entries.get(documentId)?.delete(paneId);
    this.captures.delete(documentId);
  }

  prune(documentId: string, display: DisplayState) {
    const panes = this.entries.get(documentId);
    if (!panes) return;
    for (const [id, entry] of panes) {
      const node = display.nodes[id];
      if (node?.kind !== 'projection' || !ownsViewport(node.content, entry)) panes.delete(id);
    }
  }

  captureDisplay(documentId: string, display: DisplayState): DisplayState {
    const panes = this.entries.get(documentId);
    if (!panes?.size) return display;
    const previous = this.captures.get(documentId);
    const base = previous?.input === display ? previous.output : display;
    let nodes = base.nodes;
    for (const [id, entry] of panes) {
      const node = nodes[id];
      if (node?.kind !== 'projection' || !ownsViewport(node.content, entry)) continue;
      const scroll = entry.read?.() ?? entry.position;
      if (node.content.scroll?.top === scroll.top && node.content.scroll?.left === scroll.left) continue;
      if (nodes === base.nodes) nodes = { ...nodes };
      nodes[id] = { ...node, content: { ...node.content, scroll: { ...scroll } } };
    }
    const output = nodes === base.nodes ? base : { ...display, nodes };
    this.captures.set(documentId, { input: display, output });
    return output;
  }

  setCamera(documentId: string, camera: CanvasTransform) { this.cameras.set(documentId, camera); this.changed(documentId); }
  captureCamera(documentId: string, fallback?: CanvasTransform) { return this.cameras.get(documentId) ?? fallback; }
}

import { useEffect, useId, useState, type ReactNode } from "react";
export function FloatingPane(props: { children: ReactNode; highlighted?: boolean }) {
  const [minimized, setMinimized] = useState(false);
  const contentId = useId();
  useEffect(() => { if (props.highlighted) setMinimized(false); }, [props.highlighted]);
  return <aside className={`mapping-floating-pane${minimized ? " is-minimized" : ""}${props.highlighted ? " is-transfer-target" : ""}`} aria-label="Project diagram explorer" data-diagram-canvas-static-ui>
    <button type="button" disabled={props.highlighted} className="mapping-explorer-toggle" aria-label={minimized ? "Restore explorer" : "Minimize explorer"}
      title={minimized ? "Restore explorer" : "Minimize explorer"} aria-expanded={!minimized} aria-controls={contentId}
      onClick={() => setMinimized(value => !value)}>
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
        {minimized ? <><rect x="2.5" y="2.5" width="11" height="11" rx="1" /><path d="M6 3v10" /></> : <path d="M3 11.5h10" />}
      </svg>
      {minimized && <span>Explorer</span>}
    </button>
    <div id={contentId} className="mapping-floating-pane-content" hidden={minimized}>{props.children}</div>
  </aside>;
}

import { ChangeSessionExplorer } from '../changes/ChangeSessionExplorer';
import type { DisplayModeChange } from '../changes/changeSessionApi';
import { useEffect, useRef, useState } from "react";
import type { GridBox, LineGridScene } from "../../../../domain/core/diagrams/lineGrid";
import type { ProjectRepresentationRecord } from "../../../../domain/core/representations/projectCatalog";
export function MappingDiagramExplorer(props: {
  transfer?: { mode: 'copy' | 'move'; count: number; sourceId: string; busy: boolean; error?: string; progress?: string; onCancel: () => void; onNew: (name: string) => void };
  explorerTab: 'diagrams'|'changes'; onTabChange: (tab: 'diagrams'|'changes') => void;
  changeMode?: DisplayModeChange; onChangeSelect: (mode: DisplayModeChange) => void;
  projectName: string; diagrams: Pick<ProjectRepresentationRecord, 'id' | 'name'>[]; activeId?: string;
  scene?: LineGridScene; dirtyIds: string[]; onOpen: (id: string) => void; onFocus: (boxId: string) => void;
  onDelete: (id: string) => void; deletingId?: string; deleteDisabled: boolean; busyIds: string[];
}) {
  const [query, setQuery] = useState("");
  const [newCanvas, setNewCanvas] = useState(false);
  const [name, setName] = useState('New canvas');
  const picker = useRef<HTMLDivElement>(null);
  useEffect(() => {
    setNewCanvas(false); setName('New canvas');
    if (props.transfer) { setQuery(''); picker.current?.focus(); picker.current?.scrollIntoView({ block: 'nearest' }); }
  }, [props.transfer?.mode, props.transfer?.sourceId]);
  const boxTree = (box: GridBox) => <li key={box.id}>
    <button type="button" onClick={() => props.onFocus(box.id)} data-explorer-box={box.id}>
      {box.kind === "container" ? "▸ " : "· "}{box.kind === "diagram"
        ? props.scene?.contents[box.contentId]?.content.ascii.split("\n")[0].slice(0, 60) || box.id : "Group"}
    </button>
    {box.kind === "container" && <ul>{box.children.map(boxTree)}</ul>}
  </li>;
  return <>
    <header><strong>{props.projectName}</strong><span>PROJECT DIAGRAMS</span></header>
    <div className="mapping-explorer-tabs" role="tablist" aria-label="Explorer mode">
      {(['diagrams','changes'] as const).map(tab => <button disabled={!!props.transfer} key={tab} role="tab" aria-selected={props.explorerTab === tab} onClick={() => props.onTabChange(tab)}>{tab === 'diagrams' ? 'Diagrams' : 'Changes'}</button>)}
    </div>
    {props.explorerTab === 'changes' ? <ChangeSessionExplorer mode={props.changeMode} onSelect={props.onChangeSelect} /> : <>
    {props.transfer && <div ref={picker} tabIndex={-1} className="mapping-transfer-picker" aria-label="Choose destination canvas" aria-busy={props.transfer.busy}>
      <h2>{props.transfer.mode === 'copy' ? 'Copy' : 'Move'} {props.transfer.count} {props.transfer.count === 1 ? 'diagram' : 'diagrams'}</h2>
      <p role="status">{props.transfer.busy ? props.transfer.progress : newCanvas ? 'Name the new canvas, then confirm below.' : 'Choose an existing canvas below, or create a new one.'}</p>
      {props.transfer.error && <p className="mapping-transfer-error" role="alert">{props.transfer.error} Your selection is preserved. Retry below or cancel.</p>}
      {newCanvas ? <form onSubmit={event => { event.preventDefault(); if (name.trim() && !props.transfer!.busy) props.transfer!.onNew(name.trim()); }}>
        <label>New canvas name<input autoFocus aria-label="Transfer canvas name" value={name} maxLength={120} disabled={props.transfer.busy} onChange={event => setName(event.target.value)} /></label>
        <button type="submit" disabled={props.transfer.busy || !name.trim()}>{props.transfer.busy ? 'Saving…' : `${props.transfer.mode === 'copy' ? 'Copy' : 'Move'} diagrams to new canvas`}</button>
      </form> : <button type="button" disabled={props.transfer.busy} onClick={() => setNewCanvas(true)}>New canvas…</button>}
      <button type="button" disabled={props.transfer.busy} onClick={props.transfer.onCancel}>Cancel</button>
      {!props.transfer.busy && <p className="mapping-transfer-hint">Esc cancels and clears the selection.</p>}
    </div>}
    <input type="search" aria-label="Filter diagrams" placeholder="Find a diagram…" value={query} onChange={(event) => setQuery(event.target.value)} />
    <nav aria-label="Project diagrams"><ul>{props.diagrams.filter((diagram) => diagram.name.toLowerCase().includes(query.toLowerCase())).map((diagram) =>
      <li key={diagram.id}>
        <div className="mapping-explorer-row">
          <button type="button" className={diagram.id === props.activeId ? "is-active" : ""}
            disabled={Boolean(props.deletingId) || !!props.transfer && (props.transfer.busy || diagram.id === props.transfer.sourceId || props.busyIds.includes(diagram.id))}
            aria-current={diagram.id === props.activeId ? "page" : undefined} data-project-diagram={diagram.id} onClick={() => props.onOpen(diagram.id)}>
            {diagram.name}{props.transfer && diagram.id === props.transfer.sourceId ? " (source)" : ""}{props.dirtyIds.includes(diagram.id) ? " *" : ""}
          </button>
          {!props.transfer && <button type="button" className="mapping-explorer-delete" aria-label={`Delete diagram ${diagram.name}`}
            title={`Delete ${diagram.name}`} disabled={props.deleteDisabled || props.busyIds.includes(diagram.id)}
            onClick={() => props.onDelete(diagram.id)}>{props.deletingId === diagram.id ? "…" : "×"}</button>}
        </div>
        {!props.transfer && diagram.id === props.activeId && props.scene && <ul>{props.scene.root.kind === "container"
          ? props.scene.root.children.map(boxTree) : boxTree(props.scene.root)}</ul>}
      </li>
    )}</ul></nav>
    {!props.diagrams.length && <p>No project diagrams yet. Create one with New.</p>}
    </>}
  </>;
}

export function MappingSubmenu(props: {
  projectName: string; name: string; status: string; canSave: boolean;
  onNameChange: (name: string) => void; onNew: () => void; onSave: () => void;
