}

import type { CanvasHistoryService } from '../../../../domain/core/diagrams/canvasHistoryService';
import { createStore, type StoreApi } from 'zustand/vanilla';

import { MappingDocumentController, type ControllerSnapshot } from '../../../../domain/mapping/workspace/mappingDocumentController';
import type { MappingGridDocument } from '../../../../domain/mapping/workspace/mappingGrid';
import type { MappingCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { CanvasHistoryRecord } from '../../../../domain/core/diagrams/canvasHistory';
import { stateKey } from '../../../../domain/core/diagrams/canvasHistory';
import type { DiagramService } from '../../../../domain/core/diagrams/diagramService';

/** Consumers can select and subscribe; mutations stay behind session commands. */
export function readable<T>(store: StoreApi<T>): Pick<StoreApi<T>, 'getState' | 'getInitialState' | 'subscribe'> {
  return { getState: store.getState, getInitialState: store.getInitialState, subscribe: store.subscribe };
}

export interface SavedDocumentState { name: string; savedName: string; savedScene: string; savedEdges?: string }
export interface DocumentStatus { isDirty: boolean; sceneDirty: boolean; canUndo: boolean; canRedo: boolean }

/** Domain state remains owned by the controller. Stores publish immutable references,
 * never a second editable document. Pointer previews have no route to the controller. */
export class CanvasSession {
  readonly controller: MappingDocumentController;
  readonly document;
  private readonly documentState;
  readonly presentation;
  private readonly presentationState;
  readonly selection;
  private readonly selectionState;
  readonly controls;
  private readonly controlsState;
  readonly geometry;
  private readonly geometryState;
  readonly status;
  private readonly statusState;
  private baseline: SavedDocumentState;
  private savedSceneKey: string;
  private savedEdgesKey: string;
  private scene: MappingGridDocument['scene'];
  private edges: MappingGridDocument['edges'];
  private sceneKey: string;
  private edgesKey: string;
  private unsubscribe: () => void;
  private commitListeners = new Set<() => void>();

  constructor(input: SavedDocumentState & { document: MappingGridDocument; canvas: MappingCanvasState; history?: CanvasHistoryRecord }, diagrams?: DiagramService, history?: CanvasHistoryService) {
    this.baseline = { name: input.name, savedName: input.savedName, savedScene: input.savedScene, savedEdges: input.savedEdges };
    this.controller = new MappingDocumentController(input.document, input.canvas, 0, undefined, {}, input.history, diagrams, history);
    const snapshot = this.controller.getSnapshot();
    this.scene = snapshot.document.scene; this.edges = snapshot.document.edges;
    this.sceneKey = stateKey(this.scene); this.edgesKey = stateKey(this.edges);
    this.savedSceneKey = stateKey(JSON.parse(input.savedScene)); this.savedEdgesKey = stateKey(JSON.parse(input.savedEdges ?? '[]'));
    this.documentState = createStore(() => ({ document: snapshot.document }));
    this.presentationState = createStore(() => ({ display: snapshot.canvas.display, diagramViews: snapshot.canvas.diagramViews }));
    this.selectionState = createStore(() => snapshot.canvas.selection);
    this.controlsState = createStore(() => snapshot.canvas.controls);
    this.geometryState = createStore(() => this.geometryOf(snapshot));
    this.statusState = createStore(() => this.statusOf(snapshot));
    this.document = readable(this.documentState);
    this.presentation = readable(this.presentationState);
    this.selection = readable(this.selectionState);
    this.controls = readable(this.controlsState);
    this.geometry = readable(this.geometryState);
    this.status = readable(this.statusState);
    let previous = snapshot;
    this.unsubscribe = this.controller.subscribe(() => {
      const next = this.controller.getSnapshot();
      if (next.document.scene !== this.scene) { this.scene = next.document.scene; this.sceneKey = stateKey(this.scene); }
      if (next.document.edges !== this.edges) { this.edges = next.document.edges; this.edgesKey = stateKey(this.edges); }
      // Publish all controller changes synchronously; React observes one completed transaction.
      if (next.canvas.display !== previous.canvas.display || next.canvas.diagramViews !== previous.canvas.diagramViews)
        this.presentationState.setState({ display: next.canvas.display, diagramViews: next.canvas.diagramViews });
      if (next.canvas.selection !== previous.canvas.selection) this.selectionState.setState(next.canvas.selection, true);
      if (next.canvas.controls !== previous.canvas.controls) this.controlsState.setState(next.canvas.controls, true);
      if (next.endpointBounds !== previous.endpointBounds || next.cell !== previous.cell || next.version !== previous.version)
        this.geometryState.setState(this.geometryOf(next));
      this.publishStatus(next);
      if (next.document !== previous.document) this.documentState.setState({ document: next.document });
      const committed = next.canvasRevisionId !== previous.canvasRevisionId;
      previous = next;
      if (committed) this.commitListeners.forEach(listener => listener());
    });
  }
  private geometryOf(s: ControllerSnapshot) { return { endpointBounds: s.endpointBounds, cell: s.cell, version: s.version }; }
  private statusOf(s: ControllerSnapshot): DocumentStatus {
    const sceneDirty = this.sceneKey !== this.savedSceneKey;
    return { sceneDirty, isDirty: sceneDirty || this.edgesKey !== this.savedEdgesKey || this.baseline.name !== this.baseline.savedName,
      canUndo: s.canUndo, canRedo: s.canRedo };
  }
  private publishStatus(s = this.controller.getSnapshot()) {
    const next = this.statusOf(s), prior = this.status.getState();
    if (Object.keys(next).some(key => next[key as keyof DocumentStatus] !== prior[key as keyof DocumentStatus])) this.statusState.setState(next);
  }
  /** A save acknowledgement names the captured baseline, not whatever is current now. */
  updateBaseline(input: SavedDocumentState) {
    if (input.savedScene !== this.baseline.savedScene) this.savedSceneKey = stateKey(JSON.parse(input.savedScene));
    if (input.savedEdges !== this.baseline.savedEdges) this.savedEdgesKey = stateKey(JSON.parse(input.savedEdges ?? '[]'));
    this.baseline = { name: input.name, savedName: input.savedName, savedScene: input.savedScene, savedEdges: input.savedEdges };
    this.publishStatus();
  }
  onCommit(listener: () => void) { this.commitListeners.add(listener); return () => { this.commitListeners.delete(listener); }; }
  dispose() { this.unsubscribe(); this.commitListeners.clear(); }
}

import { DefaultCanvasHistoryService, type CanvasHistoryService } from '../../../../domain/core/diagrams/canvasHistoryService';
import { createStore } from 'zustand/vanilla';
import type { CanvasTransform } from '../../../../domain/core/diagrams/diagramCanvas';
import type { DiagramService } from '../../../../domain/core/diagrams/diagramService';
import type { MappingDocumentController } from '../../../../domain/mapping/workspace/mappingDocumentController';
import { initialCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
import type { DisplayState } from '../../../../domain/mapping/workspace/displayModel';
import type { DiagramFocus } from '../search/SearchHighlight';
import { CanvasSession, readable, type SavedDocumentState } from './canvasSession';

export interface DraftMetadata extends SavedDocumentState {
  hidden?: boolean; newerRevision?: boolean; reloadKey?: string; representationId?: string;
  revisionId: string; busy: boolean; viewport?: CanvasTransform; focusBox?: DiagramFocus;
}
export interface CanvasDraft extends DraftMetadata { session: CanvasSession }
export type CanvasDraftSeed = DraftMetadata & Pick<ConstructorParameters<typeof CanvasSession>[0], 'document' | 'canvas' | 'history'>;
type DraftInput = CanvasDraft | CanvasDraftSeed;
type Drafts = Record<string, CanvasDraft>;

/** Registry owns session lifetimes. Page state contains metadata and stable handles only. */
export class CanvasWorkspace {
  private readonly storeState = createStore(() => ({ drafts: {} as Drafts }));
  readonly controllers = new Map<string, MappingDocumentController>();
  private readonly changesState = createStore(() => ({ version: 0 }));
  private readonly dirtyScenesState = createStore(() => ({ ids: [] as string[] }));
  readonly store = readable(this.storeState);
  readonly changes = readable(this.changesState);
  readonly dirtyScenes = readable(this.dirtyScenesState);
  private subscriptions = new Map<string, (() => void)[]>();
  constructor(private readonly diagrams?: DiagramService, private readonly history: CanvasHistoryService = new DefaultCanvasHistoryService()) {}
  private persistenceListeners = new Set<(ids: string[]) => void>();
  onPersist(listener: (ids: string[]) => void) { this.persistenceListeners.add(listener); return () => { this.persistenceListeners.delete(listener); }; }
  private persist(ids: string[]) { this.persistenceListeners.forEach(listener => listener(ids)); }
  private changed = () => this.changesState.setState(s => ({ version: s.version + 1 }));
  private refreshDirty = () => {
    const ids = Object.entries(this.store.getState().drafts).filter(([, d]) => d.session.status.getState().sceneDirty).map(([id]) => id);
    const prior = this.dirtyScenes.getState().ids;
    if (ids.length !== prior.length || ids.some((id, i) => id !== prior[i])) this.dirtyScenesState.setState({ ids });
  };
  copyDocument(input: { documentId: string; name: string; expectedVersion?: number; display?: DisplayState; viewport?: CanvasTransform }) {
    const source = this.store.getState().drafts[input.documentId];
    if (!source || source.hidden) throw new Error('DOCUMENT_UNAVAILABLE');
    if (source.busy) throw new Error('DOCUMENT_BUSY');
    const name = input.name.trim();
    if (!name || name.length > 120) throw new Error('Expected a canvas name between 1 and 120 characters');
    const controller = source.session.controller, snapshot = controller.getSnapshot();
    if (input.expectedVersion !== undefined && input.expectedVersion !== snapshot.version) throw new Error('VERSION_CONFLICT: read the source canvas again');
    const canvas = structuredClone({ ...snapshot.canvas, display: input.display ?? snapshot.canvas.display, selection: { items: [] }, controls: initialCanvasState().controls });
    // A copied conversation retains its messages, but has no running request.
    for (const node of Object.values(canvas.display.nodes)) if (node.kind === 'conversation') node.thread.pending = false;
    const documentId = `draft-${crypto.randomUUID()}`;
    this.setDrafts(current => ({ ...current, [documentId]: {
      name, savedName: '', revisionId: '', busy: false, document: snapshot.document, canvas,
      history: controller.forkHistory(canvas), viewport: structuredClone(input.viewport ?? source.viewport),
      savedScene: JSON.stringify(snapshot.document.scene), savedEdges: JSON.stringify(snapshot.document.edges)
    } }));
    return { documentId };
  }
  setDrafts = (value: Record<string, DraftInput> | ((current: Drafts) => Record<string, DraftInput>)) => {
    const prior = this.store.getState().drafts;
    const input = typeof value === 'function' ? value(prior) : value;
    if (input === prior) return;
    const next: Drafts = {};
    let persist = false;
    const changedIds = new Set<string>();
    for (const [id, item] of Object.entries(input)) {
      if (item === prior[id]) { next[id] = prior[id]; continue; }
      if ('document' in item) {
        const { document, canvas, history, ...metadata } = item;
        next[id] = { ...metadata, session: new CanvasSession({ ...metadata, document, canvas, history }, this.diagrams, this.history) };
      } else next[id] = item;
      next[id].session.updateBaseline(next[id]);
      const old = prior[id];
      if (!old || next[id].session !== old.session || ['name', 'savedName', 'savedScene', 'savedEdges', 'revisionId', 'representationId', 'hidden'].some(key =>
        old[key as keyof DraftMetadata] !== next[id][key as keyof DraftMetadata])) { persist = true; changedIds.add(id); }
    }
    for (const [id, old] of Object.entries(prior)) if (next[id]?.session !== old.session) {
      this.subscriptions.get(id)?.forEach(unsubscribe => unsubscribe()); this.subscriptions.delete(id);
      this.controllers.delete(id); old.session.dispose(); persist = true; changedIds.add(id);
    }
    for (const [id, draft] of Object.entries(next)) if (!this.subscriptions.has(id)) {
      const session = draft.session;
      this.controllers.set(id, session.controller);
      this.subscriptions.set(id, [session.onCommit(() => { this.changed(); this.persist([id]); }), session.status.subscribe(this.refreshDirty), session.document.subscribe(() => {
        // Document consumers (search/explorer) get a new entry; presentation/interaction never enter this path.
        const current = this.store.getState().drafts;
        if (current[id]?.session === session) this.storeState.setState({ drafts: { ...current, [id]: { ...current[id] } } });
      })]);
    }
    this.storeState.setState({ drafts: next });
    this.refreshDirty();
    if (persist) { this.changed(); this.persist([...changedIds]); }
  };
  dispose() { this.subscriptions.forEach(list => list.forEach(off => off())); this.persistenceListeners.clear(); Object.values(this.store.getState().drafts).forEach(d => d.session.dispose()); }
}

import type { ProjectRepresentationsSnapshot } from "../../../shared/http/api";
import { apiFetch, errorFrom } from "../../../shared/http/http";
