/** Vite adapter: mount HTTP routes and translate transport errors. */
export function diagramApi(
  projectRoot: string,
  diagramsDirectory = ".diagrams",
  configuredDomainProfileId: BuiltInDomainProfileId | undefined = isBuiltInDomainProfileId(
    process.env.NEW_DIAGRAM_DOMAIN
  ) ? process.env.NEW_DIAGRAM_DOMAIN : undefined,
  mappingPocSourceRoot = projectRoot,
  options: { lspEnabled?: boolean } = {}
): Plugin {
  const backend = createBackend(projectRoot, diagramsDirectory,
    configuredDomainProfileId, mappingPocSourceRoot, options);
  const { routes } = backend;
  const middleware: Connect.NextHandleFunction = async (request, response, next) => {
    const url = new URL(request.url ?? "/", "http://localhost");
    if (!url.pathname.startsWith("/api/") && !url.pathname.startsWith("/internal/mapping/")) {
      next();
      return;
    }
    const namespace = url.pathname.split("/")[2];
    if (!url.pathname.startsWith("/api/") || !Object.hasOwn(routes, namespace)) {
      return sendJson(response, 404, { error: "API route not found" });
    }
    try {
      await routes[namespace as keyof typeof routes](request, response, url);
    } catch (error) {
      const message = error instanceof Error ? error.message : "request failed";
      if (response.headersSent) {
        sendEvent(response, { type: "error", error: message });
        if (!response.destroyed && !response.writableEnded) response.end();
      } else {
        const status = error instanceof RequestTooLarge ? 413 : error instanceof ProjectDiagramConflict ? 409 : error instanceof ApplicationError
          ? { conflict: 409, 'invalid-input': 400, 'binary-source': 415, 'lsp-disabled': 503, 'storage-unavailable': 503 }[error.code] : 400;
        sendJson(response, status, { ...(error instanceof ApplicationError && error.code === 'lsp-disabled' ? { code: 'LSP_DISABLED' } : {}), error: message });
      }
    }
  };
  const attach = (server: ViteDevServer | PreviewServer) => {
    server.middlewares.use(middleware);
    const disposeSockets = server.httpServer ? attachLiveCanvasSockets(server.httpServer, backend.liveCanvas) : undefined;
    server.httpServer?.once("close", () => {
      disposeSockets?.(); backend.dispose();
    });
  };
  return { name: "new-diagram-api", configureServer: attach, configurePreviewServer: attach };
}

import type { ServerResponse } from "node:http";
import type { Connect } from "vite";
const MAX_REQUEST_BYTES = 10 * 1024 * 1024;
export class RequestTooLarge extends Error {}

export function sendJson(response: ServerResponse, status: number, payload: unknown): void {
  response.statusCode = status;
  response.setHeader("content-type", "application/json; charset=utf-8");
  response.end(JSON.stringify(payload));
}

export function sendEvent(response: ServerResponse, payload: unknown): void {
  if (!response.destroyed && !response.writableEnded) {
    response.write(`${JSON.stringify(payload)}\n`);
  }
}

export function readBody(request: Connect.IncomingMessage, maxBytes = MAX_REQUEST_BYTES): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let body = "";
    let bytes = 0;
    let exceeded = false;
    request.setEncoding("utf8");
    request.on("data", (chunk: string) => {
      if (exceeded) return;
      bytes += Buffer.byteLength(chunk);
      if (bytes > maxBytes) {
        exceeded = true; body = '';
        reject(new RequestTooLarge(`Request exceeds the ${Math.round(maxBytes / 1024 / 1024)} MB save limit`));
        return; // Drain the request so the client receives a useful HTTP error.
      }
      body += chunk;
    });
    request.on("end", () => {
      if (exceeded) return;
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch {
        reject(new Error("request body is not valid JSON"));
      }
    });
    request.on("error", reject);
  });
}

import type { ServerResponse } from "node:http";
import type { Connect } from "vite";
import type { CoreApplication } from "../../../../application/core/application";
import type { ProjectCatalogService } from '../../../../application/core/representations/projectCatalogService';
import type { ProjectSourceService } from '../../../../application/core/source/projectSource';
import { type SaveProjectedTreeInput } from "../../../../domain/core/representations/catalogCommands";
import { readBody, sendJson } from "../../http/http";

export function createCoreRoutes({ application, source, catalog }: {
  source: ProjectSourceService;
  catalog: ProjectCatalogService;
  application: CoreApplication;
}) {
  return async (request: Connect.IncomingMessage, response: ServerResponse, url: URL): Promise<void> => {
    if (url.pathname === '/api/core/project/files') {
      if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
      return sendJson(response, 200, await source.files(url.searchParams.get('projectId'), url.searchParams.get('path') ?? '', url.searchParams.get('sourceId') ?? undefined));
    }
    if (url.pathname === '/api/core/project/definitions') {
      if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
      source.ensureDefinitionsEnabled();
      const body = await readBody(request) as Parameters<ProjectSourceService['definitions']>[0];
      const controller = new AbortController();
      const abort = () => { if (!response.writableEnded) controller.abort(); };
      response.once('close', abort);
      try {
        const result = await source.definitions(body, controller.signal);
        if (!response.destroyed) return sendJson(response, 200, result);
      } finally { response.removeListener('close', abort); }
      return;
    }
    if (url.pathname === '/api/core/project/source') {
      if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
      return sendJson(response, 200, await source.source(url.searchParams.get('projectId'), url.searchParams.get('path'), url.searchParams.get('sourceId') ?? undefined));
    }
    if (url.pathname === '/api/core/project/projections') {
      if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
      return sendJson(response, 200, await catalog.saveProjection(await readBody(request) as SaveProjectedTreeInput));
    }
    if (url.pathname === "/api/core/project/corpus-compactions") {
      await catalog.requireProject();
      if (request.method === "GET") return sendJson(response, 200, await catalog.compactions());
      if (request.method !== "POST") return sendJson(response, 405, { error: "method not allowed" });
      const body = await readBody(request);
      return sendJson(response, 201, await application.upsertProjectFileCompaction(
        body as import("../../../../domain/core/representations/projectCatalog").ProjectFileCompactionInput
      ));
    }

    if (url.pathname === "/api/core/project/representations") {
      if (request.method !== "GET") return sendJson(response, 405, { error: "method not allowed" });
      return sendJson(response, 200, await application.projectRepresentations(url.searchParams.get('history') === 'current' ? 'current' : 'all'));
    }

    return sendJson(response, 404, { error: "API route not found" });
  };
}

import type { ServerResponse } from 'node:http';
import type { Connect } from 'vite';
import { z } from 'zod';
import type { AgentDiagrammingSessionService } from '../../../../application/mapping/agent/sessionService';
import { agentToolSchemas, type AgentToolName } from '../../../../domain/mapping/agent/contracts';
import { readBody, sendJson } from '../../http/http';
const registration = z.object({ canvasId: z.string().uuid(), stableWorkspaceId: z.string().uuid().optional(), projectId: z.string().optional(), documents: z.array(z.object({ documentId: z.string().min(1), name: z.string(), representationId: z.string().optional() })).max(100) }).strict();
export async function handleAgentRoutes(request: Connect.IncomingMessage, response: ServerResponse, url: URL, service: AgentDiagrammingSessionService) {
  const path = url.pathname.slice('/api/mapping/agent'.length);
  try {
    if (path === '/change-sessions' && request.method === 'GET') return sendJson(response, 200, await service.changes?.list() ?? []);
    const preview = path.match(/^\/change-sessions\/([^/]+)\/preview$/);
    if (preview && request.method === 'GET' && service.changes) {
      const documentId = url.searchParams.get('documentId'); if (!documentId) throw Error('documentId is required');
      const version = url.searchParams.has('version') ? Number(url.searchParams.get('version')) : undefined;
      if (version !== undefined && (!Number.isSafeInteger(version) || version < 0)) throw Error('Invalid session version');
      response.setHeader('cache-control', 'no-store');
      return sendJson(response, 200, await service.changes.preview(decodeURIComponent(preview[1]), documentId, version));
    }
    const changeSession = path.match(/^\/change-sessions\/([^/]+)$/);
    if (changeSession && request.method === 'GET' && service.changes) {
      const { receipts, ...session } = await service.changes.get(decodeURIComponent(changeSession[1]));
      return sendJson(response, 200, session);
    }
    if (path === '/canvases') {
      if (request.method === 'GET') return sendJson(response, 200, service.bridge.list());
      if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
      service.bridge.register(registration.parse(await readBody(request))); return sendJson(response, 200, { registered: true });
    }
    const canvas = path.match(/^\/canvases\/([^/]+)(?:\/(commands|reply))?$/);
    if (canvas) {
      const id = decodeURIComponent(canvas[1]);
      if (!canvas[2] && request.method === 'DELETE') { service.bridge.unregister(id); return sendJson(response, 200, {}); }
      if (canvas[2] === 'commands' && request.method === 'GET') return sendJson(response, 200, await service.bridge.poll(id));
      if (canvas[2] === 'reply' && request.method === 'POST') {
        const body = z.object({ commandId: z.string(), value: z.unknown().optional(), error: z.string().optional() }).parse(await readBody(request, 64 * 1024 * 1024));
        service.bridge.reply(id, body.commandId, body); return sendJson(response, 200, {});
      }
      return sendJson(response, 405, { error: 'method not allowed' });
    }
    const tool = path.match(/^\/tools\/([^/]+)$/);
    if (tool && request.method === 'POST' && Object.hasOwn(agentToolSchemas, tool[1])) return sendJson(response, 200, await service.call(tool[1] as AgentToolName, await readBody(request)));
    return sendJson(response, 404, { error: 'Unknown agent endpoint' });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return sendJson(response, message.includes('VERSION_CONFLICT') || message.includes('REQUEST_ID_CONFLICT') || message.includes('CONTENT_HASH_CONFLICT') ? 409 : message.includes('UNAVAILABLE') ? 503 : 400, { error: message });
  }
}

import type { ServerResponse } from "node:http";
import type { Connect } from "vite";
import type { LocalChatService } from '../../../../../application/mapping/chat/chatService';
import { readBody, sendEvent, sendJson } from "../../../http/http";

export async function handleLocalChat(request: Connect.IncomingMessage, response: ServerResponse, chat: LocalChatService): Promise<void> {
  if (request.method !== "POST") return sendJson(response, 405, { error: "method not allowed" });
  const prepared = await chat.prepare(await readBody(request));
  const { sourceRanges } = prepared;
  if (response.destroyed) return;
  const controller = new AbortController();
  const onClose = () => { if (!response.writableEnded) controller.abort(); };
  response.on("close", onClose);
  try {
    response.statusCode = 200;
    response.setHeader("content-type", "application/x-ndjson; charset=utf-8");
    response.setHeader("cache-control", "no-cache, no-transform");
    response.flushHeaders();
    sendEvent(response, { type: "context", sourceRanges });
    const text = await chat.reply(prepared, {
      signal: controller.signal,
      onProgress: (message) => sendEvent(response, { type: "progress", message })
    });
    sendEvent(response, { type: "result", text });
    response.end();
  } finally {
    response.off("close", onClose);
  }
}

import type { ServerResponse } from "node:http";
import type { Connect } from "vite";
import type { FileCompactionService } from "../../../../../application/mapping/compaction/fileCompactionService";
import { readBody, sendEvent, sendJson } from "../../../http/http";

export async function handleFileCompaction(request: Connect.IncomingMessage, response: ServerResponse,
  url: URL, service: FileCompactionService): Promise<void> {
  if (url.pathname !== "/api/mapping/compactions") {
    if (request.method !== "GET") return sendJson(response, 405, { error: "method not allowed" });
    const run = await service.get(url.pathname.slice("/api/mapping/compactions/".length));
    return sendJson(response, run ? 200 : 404, run ?? { error: "Compaction run not found" });
  }
  if (request.method !== "POST") return sendJson(response, 405, { error: "method not allowed" });
  const input = await readBody(request);
  const controller = new AbortController();
  const onClose = () => { if (!response.writableEnded) controller.abort(new Error("Compaction request cancelled")); };
  response.on("close", onClose);
  try {
    const prepared = await service.prepare(input);
    if (response.destroyed) return;
    controller.signal.throwIfAborted();
    response.statusCode = 200;
    response.setHeader("content-type", "application/x-ndjson; charset=utf-8");
    response.setHeader("cache-control", "no-cache, no-transform");
    response.flushHeaders();
    await service.run(prepared, { signal: controller.signal, onEvent: (event) => sendEvent(response, event) });
    response.end();
  } finally {
    response.off("close", onClose);
  }
}

import { AgentContextError } from '../../../../application/mapping/agent/agentContextService';
import type { IncomingMessage } from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocket, WebSocketServer } from 'ws';
import { LiveCanvasError, type LiveCanvasService } from '../../../../application/mapping/agent/liveCanvasService';
import { liveCanvasMessageSchema, type LiveCanvasEvent } from '../../../../domain/mapping/agent/liveCanvasStatus';
import { sendJson } from '../../http/http';
import type { Connect } from 'vite';
import type { ServerResponse } from 'node:http';

export function readLiveSelection(request: Connect.IncomingMessage, response: ServerResponse, connectionId: string, service: LiveCanvasService) {
  response.setHeader('cache-control', 'private, no-cache');
  if (request.method !== 'GET') return sendJson(response, 405, { error: 'method not allowed' });
  try {
    const selection = service.read(connectionId);
    response.setHeader('X-Canvas-Epoch', selection.canvasEpoch);
    response.setHeader('X-Selection-Sequence', String(selection.sequence));
    response.setHeader('X-Document-Version', String(selection.documentVersion));
    response.setHeader('X-Selection-Received-At', selection.receivedAt);
    const etag = `"${selection.connectionId}:${selection.sequence}"`;
    response.setHeader('etag', etag);
    const matches = request.headers['if-none-match']?.split(',').some(tag => tag.trim().replace(/^W\//, '') === etag || tag.trim() === '*');
    if (matches) { response.statusCode = 304; response.end(); return; }
    sendJson(response, 200, selection);
  } catch (error) {
    if (!(error instanceof LiveCanvasError)) throw error;
    sendJson(response, error.status, { code: error.code, error: error.message });
  }
}

/** One endpoint; the first frame either attaches an external reader or registers a browser publisher. */
type UpgradeListener = (request: IncomingMessage, socket: Duplex, head: Buffer) => void;
interface UpgradeServer {
  on(event: 'upgrade', listener: UpgradeListener): unknown;
  off(event: 'upgrade', listener: UpgradeListener): unknown;
}

export function attachLiveCanvasSockets(server: UpgradeServer, service: LiveCanvasService) {
  const sockets = new WebSocketServer({ noServer: true, maxPayload: 8 * 1024 * 1024, perMessageDeflate: false });
  const alive = new Set<WebSocket>();
  sockets.on('connection', ws => {
    alive.add(ws);
    let workspaceInstanceId: string | undefined, connectionId: string | undefined;
    let contextPending = false, attaching = false, contextAllowance = 0;
    const send = (event: LiveCanvasEvent) => {
      if (ws.readyState !== WebSocket.OPEN) return;
      // Deltas cannot be dropped/coalesced independently. Bound the transport queue
      // and force slow readers to reconnect for an authoritative snapshot instead.
      if (ws.bufferedAmount > 64 * 1024 + contextAllowance) { ws.close(1013, 'Reader too slow; reconnect for snapshot'); return; }
      const encoded = JSON.stringify(event);
      const hasContext = event.type === 'context.snapshot' || event.type === 'attached' && event.context !== undefined;
      if (hasContext) {
        const bytes = Buffer.byteLength(encoded);
        if (bytes > 64 * 1024 * 1024) { ws.close(1009, 'Canvas context exceeds 64 MiB transport limit'); return; }
        contextAllowance += bytes;
        ws.send(encoded, () => { contextAllowance -= bytes; });
      } else ws.send(encoded);
    };
    let handshake = setTimeout(() => { if (!connectionId && !workspaceInstanceId) ws.close(1008, 'Attach required'); }, 10_000);
    ws.on('pong', () => alive.add(ws));
    ws.on('error', () => ws.terminate());
    ws.on('message', async (raw, binary) => {
      let requestId: string | undefined;
      try {
        if (binary) throw new LiveCanvasError('INVALID_MESSAGE', 400, 'Expected a JSON text frame');
        const decoded: unknown = JSON.parse(raw.toString());
        if (decoded && typeof decoded === 'object' && 'requestId' in decoded
          && typeof decoded.requestId === 'string' && decoded.requestId.length <= 200) requestId = decoded.requestId;
        const message = liveCanvasMessageSchema.parse(decoded);
        if (message.type === 'attach' || message.type === 'publish') {
          if (connectionId || workspaceInstanceId || attaching) throw new LiveCanvasError('ALREADY_ATTACHED', 409, 'Open another socket to bind another canvas');
          if (message.type === 'attach') {
            attaching = true;
            let context;
            try {
              if (message.includeContext) {
                clearTimeout(handshake);
                handshake = setTimeout(() => ws.close(1008, 'Canvas context timed out'), 30_000);
                context = await service.contextForCanvas(message.workspaceInstanceId, message.documentId);
              }
            } finally { attaching = false; }
            if (ws.readyState !== WebSocket.OPEN) return;
            const initial = service.attach(message.workspaceInstanceId, message.documentId, send);
            connectionId = initial.connectionId;
            send({ type: 'attached', ...initial, ...(context ? { context } : {}) });
          } else {
            service.publish(ws, message.workspaceInstanceId, send);
            workspaceInstanceId = message.workspaceInstanceId;
            send({ type: 'publisher.ready', protocolVersion: 2 });
          }
          clearTimeout(handshake);
        } else if (message.type === 'agent-context.upload') {
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          const { type: _, requestId: uploadRequestId, ...trajectory } = message;
          send({ type: 'agent-context.uploaded', requestId: uploadRequestId, connectionId,
            ...service.uploadAgentContext(connectionId, uploadRequestId, trajectory) });
        } else if (message.type === 'context.get') {
          requestId = message.requestId;
          if (!connectionId) throw new LiveCanvasError('READER_REQUIRED', 403);
          if (contextPending || contextAllowance > 0) throw new LiveCanvasError('CONTEXT_BUSY', 409, 'Wait for the pending context request');
          contextPending = true;
          try { send({ type: 'context.snapshot', requestId, ...await service.context(connectionId) }); }
          finally { contextPending = false; }
        } else {
          if (!workspaceInstanceId) throw new LiveCanvasError('PUBLISHER_REQUIRED', 403);
          if (message.type === 'remove') service.remove(ws, workspaceInstanceId, message.documentId, message.canvasEpoch);
          else {
            const { type: _, ...selection } = message;
            service.update(ws, workspaceInstanceId, selection);
          }
        }
      } catch (error) {
        send({ type: 'error', ...(requestId ? { requestId } : {}), code: error instanceof LiveCanvasError || error instanceof AgentContextError ? error.code : 'INVALID_MESSAGE',
          error: error instanceof Error ? error.message : String(error) });
      }
    });
    ws.on('close', () => {
      clearTimeout(handshake); alive.delete(ws);
      if (connectionId) service.detach(connectionId);
      if (workspaceInstanceId) service.disconnect(ws, workspaceInstanceId);
    });
  });
  const upgrade: UpgradeListener = (request, socket, head) => {
    if (new URL(request.url ?? '/', 'http://localhost').pathname !== '/api/mapping/live') return;
    // Native clients may omit Origin. Browser clients must belong to this app's origin.
    let allowed = !request.headers.origin;
    try { allowed ||= new URL(request.headers.origin!).host === request.headers.host; } catch { /* invalid origin */ }
    if (!allowed || sockets.clients.size >= 1024) {
      socket.end(`HTTP/1.1 ${allowed ? '503 Service Unavailable' : '403 Forbidden'}\r\nConnection: close\r\n\r\n`); return;
    }
    sockets.handleUpgrade(request, socket, head, ws => sockets.emit('connection', ws, request));
  };
  server.on('upgrade', upgrade);
  const heartbeat = setInterval(() => {
    for (const ws of sockets.clients) {
      if (!alive.delete(ws)) ws.terminate(); else ws.ping();
    }
  }, 15_000);
  heartbeat.unref();
  return () => {
    clearInterval(heartbeat); server.off('upgrade', upgrade);
    for (const ws of sockets.clients) ws.terminate();
    sockets.close();
  };
}

import type { LiveCanvasService } from '../../../../application/mapping/agent/liveCanvasService';
import { readLiveSelection } from './liveCanvasRoutes';
import type { WorkspaceBatch } from '../../../../domain/mapping/workspace/workspaceRecords';
import type { AgentDiagrammingSessionService } from '../../../../application/mapping/agent/sessionService';
import { handleAgentRoutes } from './agentRoutes';

import type { ServerResponse } from 'node:http';
import type { Connect } from 'vite';
import type { LocalChatService } from '../../../../application/mapping/chat/chatService';
import type { FileCompactionService } from '../../../../application/mapping/compaction/fileCompactionService';
import type { MappingDiagramService } from '../../../../application/mapping/diagrams/diagramService';
import type { SelectionService } from '../../../../application/mapping/selection/selectionService';
import type { MappingWorkspaceService } from '../../../../application/mapping/workspace/workspaceService';
import type { SaveProjectDiagramInput } from '../../../../domain/core/diagrams/projectDiagramCanvas';
import { readBody, sendEvent, sendJson } from '../../http/http';
import { handleLocalChat } from './chat/localChatRoutes';
import { handleFileCompaction } from './compaction/fileCompactionRoutes';

export function createMappingRoutes({ selection, diagrams, workspace, chat, compactionService, agent, liveCanvas }: {
  agent?: AgentDiagrammingSessionService; liveCanvas?: LiveCanvasService;
  selection: SelectionService; diagrams: MappingDiagramService; workspace: MappingWorkspaceService;
  chat: LocalChatService; compactionService: FileCompactionService;
}) {
  return async (request: Connect.IncomingMessage, response: ServerResponse, url: URL): Promise<void> => {
    const selectionRead = url.pathname.match(/^\/api\/mapping\/live\/connections\/([^/]+)\/selection$/);
    if (selectionRead && liveCanvas) return readLiveSelection(request, response, decodeURIComponent(selectionRead[1]), liveCanvas);
    if (url.pathname.startsWith('/api/mapping/agent/') && agent) return handleAgentRoutes(request, response, url, agent);
    if (url.pathname === '/api/mapping/compactions' || url.pathname.startsWith('/api/mapping/compactions/')) {
      return handleFileCompaction(request, response, url, compactionService);
    }
    if (url.pathname === '/api/mapping/workspace/records') {
      if (request.method === 'GET') return sendJson(response, 200, await workspace.loadRecords(url.searchParams.get('history') === 'current' ? 'current' : 'all'));
      if (request.method === 'POST') return sendJson(response, 200, await workspace.applyBatch(await readBody(request, 64 * 1024 * 1024) as WorkspaceBatch));
      return sendJson(response, 405, { error: 'method not allowed' });
    }
    if (url.pathname === '/api/mapping/workspace') {
      if (request.method === 'GET') return sendJson(response, 200, await workspace.load());
      if (request.method !== 'PUT') return sendJson(response, 405, { error: 'method not allowed' });
      // Workspace saves include revision histories and captured source evidence.
      return sendJson(response, 200, await workspace.save(await readBody(request, 64 * 1024 * 1024)));
    }
    if (url.pathname === '/api/mapping/chat') return handleLocalChat(request, response, chat);
    if (url.pathname === '/api/mapping/diagrams') {
      if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
      return sendJson(response, 200, await diagrams.save(await readBody(request) as SaveProjectDiagramInput));
    }
    const diagram = url.pathname.match(/^\/api\/mapping\/diagrams\/([^/]+)$/);
    if (diagram) {
      if (request.method !== 'DELETE') return sendJson(response, 405, { error: 'method not allowed' });
      return sendJson(response, 200, await diagrams.delete(decodeURIComponent(diagram[1])));
    }
    if (url.pathname === '/api/mapping/prompt') {
      if (request.method !== 'POST') return sendJson(response, 405, { error: 'method not allowed' });
      const input = await selection.prepare(await readBody(request) as Record<string, unknown>);
      response.statusCode = 200;
      response.setHeader('content-type', 'application/x-ndjson; charset=utf-8');
      response.setHeader('cache-control', 'no-cache, no-transform');
      response.flushHeaders();
      const result = await selection.run(input, event => sendEvent(response, { type: 'progress', ...event }));
      sendEvent(response, { type: 'result', result });
      response.end();
      return;
    }
    return sendJson(response, 404, { error: 'API route not found' });
  };
}

import { Fragment, useEffect, useRef, useState, type ComponentPropsWithRef, type ReactNode, type HTMLAttributes } from 'react';
import type { DiagramTextRow, DiagramTextRun, DiagramTextOwner } from '../../../domain/core/diagrams/diagramText';
import type { DiagramJumpTarget } from '../../../domain/core/diagrams/diagramJump';
import './diagramText.css';

type Props = Omit<ComponentPropsWithRef<'pre'>, 'children'> & {
  rows: readonly DiagramTextRow[];
  registerEndpoint?: (identity: Pick<DiagramTextOwner, 'displayNodeId' | 'contentNodeId' | 'revisionId'>, element: Element | null) => void;
  onJump?: (target: DiagramJumpTarget) => void;
  renderRun?: (run: DiagramTextRun) => ReactNode;
  rowProps?: (row: DiagramTextRow) => HTMLAttributes<HTMLSpanElement>;
  /** Optional display-only decoration; never changes source text or endpoint identity. */
  nodeProps?: (owner: DiagramTextOwner) => HTMLAttributes<HTMLSpanElement> | undefined;
};

/** Shared JSX for both viewers. Controllers retain gestures, folding, and source actions. */
export function DiagramText({ rows, onJump, renderRun, rowProps, nodeProps, registerEndpoint, ...pre }: Props) {
  return <pre {...pre}>{rows.map((row, index) => {
    // Keep one outline around a label even when source mappings split its text.
    const groups: DiagramTextRun[][] = [];
    for (const run of row.runs) {
      const previous = groups.at(-1)?.[0];
      if (previous?.owner?.contentNodeId && previous.owner.contentNodeId === run.owner?.contentNodeId
        && previous.owner.displayNodeId === run.owner.displayNodeId) groups.at(-1)!.push(run);
      else groups.push([run]);
    }
    return <span key={index} className="ascii-line" {...rowProps?.(row)}>{groups.map(group => {
      const first = group[0], owner = first.owner;
      const decoration = owner ? nodeProps?.(owner) : undefined;
      const pieces: DiagramTextRun[][] = [];
      for (const run of group) {
        if (run.jump && pieces.at(-1)?.[0].jump?.id === run.jump.id && pieces.at(-1)?.[0].jumps?.map(j => j.id).join(',') === run.jumps?.map(j => j.id).join(',')) pieces.at(-1)!.push(run);
        else pieces.push([run]);
      }
      const contents = pieces.map(piece => {
        const run = piece[0];
        return <Fragment key={run.start}>{run.jump && onJump
          ? <JumpChoices run={run} onJump={onJump} text={piece.map(item => item.text).join('')} />
          : piece.map(item => <Fragment key={item.start}>{renderRun ? renderRun(item) : item.text}</Fragment>)}</Fragment>;
      });
      return <span key={first.start}
        {...decoration}
        ref={owner?.contentNodeId && registerEndpoint ? element => registerEndpoint({ displayNodeId: owner.displayNodeId,
          contentNodeId: owner.contentNodeId, revisionId: owner.revisionId }, element) : undefined}
        className={[owner?.contentNodeId ? 'diagram-content-node' : '', decoration?.className].filter(Boolean).join(' ') || undefined}
        data-display-node-id={owner?.displayNodeId} data-content-node-id={owner?.contentNodeId}
        data-content-revision={owner?.revisionId} data-source-line={owner?.sourceLine}
        data-source-start-column={owner ? first.start - owner.columnOffset + 1 : undefined}
        data-source-end-column={owner ? group.at(-1)!.end - owner.columnOffset : undefined}
        data-node-mapping-ids={owner?.contentNodeId ? [...new Set(group.flatMap(run => run.mappings)
          .filter(mapping => mapping.line === owner.sourceLine && mapping.startColumn >= first.start - owner.columnOffset + 1
            && mapping.endColumn <= group.at(-1)!.end - owner.columnOffset).map(mapping => mapping.id))].join(' ') || undefined : undefined}
        data-mapping-ids={group.flatMap(run => run.mappings.map(mapping => mapping.id)).filter((id, i, ids) => ids.indexOf(id) === i).join(' ') || undefined}
      >{contents}</span>;
    })}{index < rows.length - 1 ? '\n' : null}</span>;
  })}</pre>;
}

function JumpChoices({ run, onJump, text }: { run: DiagramTextRun; text: string; onJump: (target: DiagramJumpTarget) => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    if (!open) return;
    const outside = (event: PointerEvent) => { if (!ref.current?.contains(event.target as Node)) setOpen(false); };
    window.addEventListener('pointerdown', outside, true);
    return () => window.removeEventListener('pointerdown', outside, true);
  }, [open]);
  const jumps = run.jumps ?? [run.jump!];
  return <span ref={ref} className="diagram-jump-container" onKeyDown={event => { if (event.key === 'Escape') { event.stopPropagation(); setOpen(false); } }}>
    <button type="button" className="diagram-jump" data-diagram-jump-id={run.jump!.id} data-mapping-static-ui data-diagram-canvas-static-ui
      onPointerDown={event => { if (!event.ctrlKey) event.stopPropagation(); }}
      onClick={event => { if (event.ctrlKey || event.metaKey) return; event.stopPropagation();
        if (jumps.length === 1) onJump(jumps[0].target); else setOpen(value => !value); }}
      title={jumps.length === 1 ? 'Open linked diagram' : `Choose from ${jumps.length} linked diagrams`}>{text}</button>
    {open && <span className="diagram-jump-choices" role="menu" aria-label="Linked diagrams" data-mapping-static-ui data-diagram-canvas-static-ui>
      {jumps.map((jump, i) => <button key={jump.id} type="button" role="menuitem" onClick={event => { event.stopPropagation(); setOpen(false); onJump(jump.target); }}>
        {(jump as { label?: string }).label || `Destination ${i + 1}: ${jump.target.displayNodeId ?? jump.target.representationId}`}
      </button>)}
    </span>}
  </span>;
}

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode
} from "react";
import {
  beginCanvasPinch,
  canvasPinchGeometry,
  centeredCanvasTransform,
  recenterCanvasTransform,
  scaleCanvasTransform,
  updateCanvasPinch,
  type CanvasPinch,
  type CanvasPoint,
  type CanvasTransform
} from "../../../domain/core/diagrams/diagramCanvas";
import type { DiagramFocus } from '../../../domain/core/diagrams/diagramCanvas';

const ZOOM_SENSITIVITY = 0.0015;
const PAN_KEY_STEP = 32;
const ZOOM_KEY_FACTOR = 1.2;
const TRANSITION_MS = 160;

interface ActivePan {
  pointerId: number;
  start: CanvasPoint;
  base: CanvasPoint;
}

function localPoint(element: HTMLElement, clientX: number, clientY: number): CanvasPoint {
  const bounds = element.getBoundingClientRect();
  return { x: clientX - bounds.left, y: clientY - bounds.top };
}

function isInteractiveTarget(target: EventTarget | null): boolean {
  return target instanceof Element && Boolean(target.closest(
    "button, a, input, textarea, select, [contenteditable='true'], [data-diagram-canvas-static-ui]"
  ));
}

export function DraggableDiagramCanvas(props: {
  children: ReactNode;
  enabled: boolean;
  resetKey: string;
  className?: string;
  leftInset?: number;
  focusBox?: DiagramFocus;
  initialTransform?: CanvasTransform;
  onTransformChange?: (transform: CanvasTransform) => void;
}) {
  const transformChange = useRef(props.onTransformChange); transformChange.current = props.onTransformChange;
  const initialTransform = useRef(props.initialTransform);
  const focusBox = useRef(props.focusBox); focusBox.current = props.focusBox;
  const initialFocusPending = useRef(false);
  const viewportRef = useRef<HTMLDivElement>(null);
  const surfaceRef = useRef<HTMLDivElement>(null);
  const zoomOutputRef = useRef<HTMLOutputElement>(null);
  const transformRef = useRef<CanvasTransform>({ offset: { x: 0, y: 0 }, scale: 1 });
  const viewportSizeRef = useRef({ width: 0, height: 0 });
  const pointersRef = useRef(new Map<number, CanvasPoint>());
  const panRef = useRef<ActivePan | null>(null);
  const pinchRef = useRef<CanvasPinch | null>(null);

  const applyTransform = useCallback((transform: CanvasTransform, animate = false) => {
    transformRef.current = transform;
    transformChange.current?.(transform);
    const surface = surfaceRef.current;
    if (surface) {
      surface.style.transition = animate ? `transform ${TRANSITION_MS}ms ease` : "none";
      surface.style.transform = `translate3d(${transform.offset.x}px, ${transform.offset.y}px, 0) scale(${transform.scale})`;
    }
    const zoomOutput = zoomOutputRef.current;
    const zoomLabel = `${Math.round(transform.scale * 100)}%`;
    // Setting output.value replaces its text node, even if the zoom is unchanged.
    // Panning must not invalidate document layout on every pointer movement.
    if (zoomOutput && zoomOutput.value !== zoomLabel) {
      zoomOutput.value = zoomLabel;
    }
  }, []);

  const endGesture = useCallback(() => {
    panRef.current = null;
    pinchRef.current = null;
    viewportRef.current?.classList.remove("is-dragging");
  }, []);

  const resetCanvas = useCallback((animate = true) => {
    const viewport = viewportRef.current;
    const surface = surfaceRef.current;
    if (!viewport || !surface || !props.enabled) return;
    const viewportSize = { width: viewport.clientWidth, height: viewport.clientHeight };
    if (viewportSize.width <= 0 || viewportSize.height <= 0) return;
    viewportSizeRef.current = viewportSize;
    const inset = Math.min(props.leftInset ?? 0, viewportSize.width / 2);
    const centered = centeredCanvasTransform({ ...viewportSize, width: viewportSize.width - inset }, {
      width: surface.offsetWidth,
      height: surface.offsetHeight
    });
    applyTransform({ ...centered, offset: { ...centered.offset, x: centered.offset.x + inset } }, animate);
  }, [applyTransform, props.enabled, props.leftInset]);

  useLayoutEffect(() => {
    pointersRef.current.clear();
    endGesture();
    const surface = surfaceRef.current;
    if (!surface) return undefined;
    if (!props.enabled) {
      initialFocusPending.current = false;
      surface.style.visibility = "";
      surface.style.transition = "none";
      surface.style.transform = "";
      transformRef.current = { offset: { x: 0, y: 0 }, scale: 1 };
      return undefined;
    }
    // A newly opened target needs the children's measured layout before focus.
    // Keep the origin/default center offscreen until that initial focus is ready.
    initialFocusPending.current = Boolean(focusBox.current);
    if (initialFocusPending.current) {
      surface.style.visibility = "hidden";
      if (initialTransform.current) applyTransform(initialTransform.current);
      return undefined;
    }
    const frame = requestAnimationFrame(() => initialTransform.current ? applyTransform(initialTransform.current) : resetCanvas(false));
    return () => cancelAnimationFrame(frame);
  }, [applyTransform, endGesture, props.enabled, props.resetKey, resetCanvas]);

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport || !props.enabled || typeof ResizeObserver === "undefined") return undefined;
    viewportSizeRef.current = { width: viewport.clientWidth, height: viewport.clientHeight };
    const observer = new ResizeObserver(() => {
      const previous = viewportSizeRef.current;
      const next = { width: viewport.clientWidth, height: viewport.clientHeight };
      // Sidebar navigation hides mounted diagrams. Keep their last visible geometry.
      if (next.width <= 0 || next.height <= 0) return;
      viewportSizeRef.current = next;
      if (previous.width <= 0 || previous.height <= 0
        || (previous.width === next.width && previous.height === next.height)) return;
      applyTransform(recenterCanvasTransform(transformRef.current, previous, next));
    });
    observer.observe(viewport);
    return () => observer.disconnect();
  }, [applyTransform, props.enabled]);

  useLayoutEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport || !props.enabled) return undefined;
    const onWheel = (event: globalThis.WheelEvent) => {
      if (!event.ctrlKey && !event.metaKey) return;
      event.preventDefault();
      event.stopPropagation();
      const anchor = localPoint(viewport, event.clientX, event.clientY);
      applyTransform(scaleCanvasTransform(
        transformRef.current,
        transformRef.current.scale * Math.exp(-event.deltaY * ZOOM_SENSITIVITY),
        anchor
      ));
    };
    viewport.addEventListener("wheel", onWheel, { passive: false });
    return () => viewport.removeEventListener("wheel", onWheel);
  }, [applyTransform, props.enabled]);

  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport || !props.enabled) return;
    let suppressAuxClick = false;
    const onMiddleDown = (event: globalThis.PointerEvent) => {
      if (event.button !== 1) return;
      suppressAuxClick = false;
      if (event.defaultPrevented) return;
      const bounds = viewport.getBoundingClientRect();
      if (bounds.width <= 0 || bounds.height <= 0 || event.clientX < bounds.left
        || event.clientX >= bounds.right || event.clientY < bounds.top || event.clientY >= bounds.bottom) return;
      // Capture before pane controls, including floating siblings, can claim the gesture.
      event.preventDefault();
      event.stopPropagation();
      suppressAuxClick = true;
      window.getSelection()?.removeAllRanges();
      viewport.setPointerCapture(event.pointerId);
      const point = localPoint(viewport, event.clientX, event.clientY);
      pointersRef.current.clear();
      pointersRef.current.set(event.pointerId, point);
      pinchRef.current = null;
      panRef.current = { pointerId: event.pointerId, start: point, base: { ...transformRef.current.offset } };
      viewport.classList.add("is-dragging");
    };
    const onAuxClick = (event: MouseEvent) => {
      if (event.button !== 1 || !suppressAuxClick) return;
      suppressAuxClick = false;
      event.preventDefault();
      event.stopPropagation();
    };
    const onBlur = () => {
      for (const pointerId of pointersRef.current.keys()) {
        if (viewport.hasPointerCapture(pointerId)) viewport.releasePointerCapture(pointerId);
      }
      pointersRef.current.clear();
      endGesture();
    };
    document.addEventListener("pointerdown", onMiddleDown, true);
    document.addEventListener("auxclick", onAuxClick, true);
    window.addEventListener("blur", onBlur);
    return () => {
      document.removeEventListener("pointerdown", onMiddleDown, true);
      document.removeEventListener("auxclick", onAuxClick, true);
      window.removeEventListener("blur", onBlur);
    };
  }, [props.enabled, endGesture]);

  useEffect(() => {
    if (!props.enabled) return;
    if (!props.focusBox) {
      if (initialFocusPending.current) {
        initialFocusPending.current = false;
        resetCanvas(false);
        if (surfaceRef.current) surfaceRef.current.style.visibility = "";
      }
      return;
    }
    let innerFrame = 0;
    const frame = requestAnimationFrame(() => { innerFrame = requestAnimationFrame(() => {
      const viewport = viewportRef.current;
      const surface = surfaceRef.current;
      surfaceRef.current?.querySelectorAll('[data-jump-focus]').forEach(element => element.removeAttribute('data-jump-focus'));
      const label = props.focusBox?.contentNodeId && Array.from(surfaceRef.current?.querySelectorAll<HTMLElement>('.diagram-content-node') ?? [])
        .find(element => element.dataset.contentNodeId === props.focusBox?.contentNodeId && element.dataset.displayNodeId === `grid:${props.focusBox?.id}`);
      if (label) label.setAttribute('data-jump-focus', '');
      const searchLine = props.focusBox?.search && Array.from(surfaceRef.current?.querySelectorAll<HTMLElement>('[data-search-focus]') ?? [])
        .find(element => element.dataset.searchBox === props.focusBox?.id && element.dataset.searchFocus === String(props.focusBox?.serial));
      const target = searchLine || label || Array.from(surfaceRef.current?.querySelectorAll<HTMLElement>("[data-grid-box]") ?? [])
        .find((element) => element.dataset.gridBox === props.focusBox?.id);
      const initial = initialFocusPending.current;
      initialFocusPending.current = false;
      if (!viewport || !target) {
        if (initial) resetCanvas(false);
        if (surface) surface.style.visibility = "";
        return;
      }
      const bounds = viewport.getBoundingClientRect();
      const box = target.getBoundingClientRect();
      const inset = Math.min(props.leftInset ?? 0, bounds.width / 2);
      const current = transformRef.current;
      applyTransform({ ...current, offset: { x: current.offset.x + (bounds.width + inset) / 2 - (box.left - bounds.left + box.width / 2),
        y: current.offset.y + Math.min(bounds.height / 2, box.height / 2 + 80) - (box.top - bounds.top + box.height / 2) } }, !initial);
      if (surface) surface.style.visibility = "";
    }); });
    return () => { cancelAnimationFrame(frame); cancelAnimationFrame(innerFrame); };
  }, [props.enabled, props.resetKey, props.focusBox, props.leftInset, applyTransform, resetCanvas]);

  const beginPinch = (points: Map<number, CanvasPoint>) => {
    const [first, second] = [...points.values()];
    if (!first || !second) return false;
    const geometry = canvasPinchGeometry(first, second);
    if (!geometry) return false;
    pinchRef.current = beginCanvasPinch(transformRef.current, geometry);
    panRef.current = null;
    return true;
  };

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!props.enabled || event.button !== 0 || isInteractiveTarget(event.target)) return;
    if (event.pointerType !== "touch" && (event.ctrlKey || event.metaKey || event.shiftKey)) return;
    window.getSelection()?.removeAllRanges();
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    const point = localPoint(event.currentTarget, event.clientX, event.clientY);
    pointersRef.current.set(event.pointerId, point);
    event.currentTarget.classList.add("is-dragging");
    if (pointersRef.current.size >= 2 && beginPinch(pointersRef.current)) return;
    panRef.current = {
      pointerId: event.pointerId,
      start: point,
      base: { ...transformRef.current.offset }
    };
  };

  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    if (!pointersRef.current.has(event.pointerId)) return;
    event.preventDefault();
    const point = localPoint(event.currentTarget, event.clientX, event.clientY);
    pointersRef.current.set(event.pointerId, point);
    if (pinchRef.current && pointersRef.current.size >= 2) {
      const [first, second] = [...pointersRef.current.values()];
      const geometry = first && second ? canvasPinchGeometry(first, second) : null;
      if (geometry) applyTransform(updateCanvasPinch(pinchRef.current, geometry));
      return;
    }
    const pan = panRef.current;
    if (!pan || pan.pointerId !== event.pointerId) return;
    applyTransform({
      offset: {
        x: pan.base.x + point.x - pan.start.x,
        y: pan.base.y + point.y - pan.start.y
      },
      scale: transformRef.current.scale
    });
  };

  const finishPointer = (event: PointerEvent<HTMLDivElement>) => {
    if (!pointersRef.current.has(event.pointerId)) return;
    pointersRef.current.delete(event.pointerId);
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    if (pinchRef.current) {
      pinchRef.current = null;
      const remaining = [...pointersRef.current.entries()][0];
      if (remaining) {
        panRef.current = {
          pointerId: remaining[0],
          start: remaining[1],
          base: { ...transformRef.current.offset }
        };
        return;
      }
    }
    if (panRef.current?.pointerId === event.pointerId) panRef.current = null;
    if (pointersRef.current.size === 0) endGesture();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (!props.enabled || event.target !== event.currentTarget) return;
    let next: CanvasTransform | null = null;
    if (event.key === "ArrowLeft" || event.key === "ArrowRight"
      || event.key === "ArrowUp" || event.key === "ArrowDown") {
      next = {
        ...transformRef.current,
        offset: {
          x: transformRef.current.offset.x
            + (event.key === "ArrowLeft" ? -PAN_KEY_STEP : event.key === "ArrowRight" ? PAN_KEY_STEP : 0),
          y: transformRef.current.offset.y
            + (event.key === "ArrowUp" ? -PAN_KEY_STEP : event.key === "ArrowDown" ? PAN_KEY_STEP : 0)
        }
      };
    } else if (event.key === "+" || event.key === "=") {
      next = scaleCanvasTransform(
        transformRef.current,
        transformRef.current.scale * ZOOM_KEY_FACTOR,
        { x: event.currentTarget.clientWidth / 2, y: event.currentTarget.clientHeight / 2 }
      );
    } else if (event.key === "-") {
      next = scaleCanvasTransform(
        transformRef.current,
        transformRef.current.scale / ZOOM_KEY_FACTOR,
        { x: event.currentTarget.clientWidth / 2, y: event.currentTarget.clientHeight / 2 }
      );
    } else if (event.key === "0") {
      event.preventDefault();
      resetCanvas();
      return;
    }
    if (!next) return;
    event.preventDefault();
    applyTransform(next);
  };

  return (
    <div
      ref={viewportRef}
      className={`${props.className ?? ""} diagram-canvas${props.enabled ? " is-enabled" : ""}`.trim()}
      data-diagram-canvas
      tabIndex={props.enabled ? 0 : undefined}
      aria-label={props.enabled ? "Draggable diagram canvas" : undefined}
      aria-keyshortcuts={props.enabled ? "ArrowLeft ArrowRight ArrowUp ArrowDown + - 0" : undefined}
      title={props.enabled ? "Drag to pan · Ctrl-drag to select · Ctrl/Cmd-wheel to zoom · Shift-drag to select text" : undefined}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={finishPointer}
      onPointerCancel={finishPointer}
      onLostPointerCapture={finishPointer}
      onKeyDown={onKeyDown}
    >
      <div ref={surfaceRef} className="diagram-canvas__surface">
        {props.children}
      </div>
      {props.enabled ? (
        <div className="diagram-canvas__controls" data-diagram-canvas-static-ui>
          <output ref={zoomOutputRef} aria-label="Diagram zoom">100%</output>
          <button type="button" onClick={() => resetCanvas()} title="Reset zoom and center diagram">
            center
          </button>
        </div>
      ) : null}
    </div>
  );
}

import type { SVGProps } from 'react';

/** Existing panel connector appearance, shared with anchored diagram edges. */
export function PanelConnector(props: {
  path: string; target: { x: number; y: number; side: 'left' | 'right' | 'top' | 'bottom' };
  selected?: boolean; dashed?: boolean;
} & Pick<SVGProps<SVGGElement>, 'className'>) {
  const { x, y, side } = props.target;
  const dx = side === 'left' ? -1 : side === 'right' ? 1 : 0;
  const dy = side === 'top' ? -1 : side === 'bottom' ? 1 : 0;
  const head = `M${x + dx * 5 - dy * 3} ${y + dy * 5 + dx * 3} L${x} ${y} L${x + dx * 5 + dy * 3} ${y + dy * 5 - dx * 3}`;
  return <g className={props.className} fill="none" stroke="currentColor" strokeWidth={props.selected ? 2 : 1}>
    <path d={props.path} strokeDasharray={props.dashed ? '6 4' : undefined} />
    <path d={head} />
  </g>;
}

