.diagram-content-node:hover, .diagram-content-node.is-selected { outline: 1px solid var(--accent-cyan); outline-offset: 0; }
.diagram-content-node[data-jump-focus] { outline: 1px solid var(--accent-yellow); }
.diagram-jump { display: inline; border: 0; border-radius: 0; padding: 0; margin: 0; background: transparent; color: var(--accent-cyan); font: inherit; letter-spacing: inherit; line-height: inherit; white-space: pre; vertical-align: baseline; cursor: pointer; }
.diagram-jump:hover, .diagram-jump:focus-visible { outline: 1px solid currentColor; outline-offset: 0; }

.diagram-mapping-choices { position: fixed; z-index: 100; display: grid; max-width: 280px; max-height: 170px; overflow: auto; border: 1px solid var(--gutter); background: #141920; padding: 4px; }
.diagram-mapping-choices button { border: 0; background: transparent; color: var(--accent-cyan); text-align: left; padding: 5px; cursor: pointer; }
.diagram-jump-container { position: relative; }
.diagram-jump-choices { position: absolute; z-index: 40; top: 100%; left: 0; display: flex; flex-direction: column; min-width: 220px; padding: 6px; border: 1px solid var(--gutter); background: #141920; white-space: normal; }
.diagram-jump-choices button { font: 12px var(--font-mono); padding: 8px; text-align: left; color: var(--fg); background: #141920; border: 0; cursor: pointer; }
