import type { ProjectCorpusCompactionCatalogRecord, ProjectFileCompactionInput, ProjectRepresentationCatalogRecord } from "../../../domain/core/representations/projectCatalog";
import { apiFetch, errorFrom } from "./http";

export async function fetchProjectCorpusCompactions(): Promise<ProjectCorpusCompactionCatalogRecord> {
  const response = await apiFetch("/api/core/project/corpus-compactions", { cache: "no-store" });
  if (!response.ok) throw await errorFrom(response);
  return response.json() as Promise<ProjectCorpusCompactionCatalogRecord>;
}

export async function upsertProjectFileCompaction(
  input: ProjectFileCompactionInput
): Promise<{ catalog: ProjectCorpusCompactionCatalogRecord; compaction: import("../../../domain/core/representations/projectCatalog").ProjectFileCompactionRecord }> {
  const response = await apiFetch("/api/core/project/corpus-compactions", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(input)
  });
  if (!response.ok) throw await errorFrom(response);
  return response.json() as Promise<{ catalog: ProjectCorpusCompactionCatalogRecord; compaction: import("../../../domain/core/representations/projectCatalog").ProjectFileCompactionRecord }>;
}

export interface ProjectRepresentationsSnapshot {
  project: import("../../../domain/core/records/domain").ProjectRecord | null;
  catalog: ProjectRepresentationCatalogRecord | null;
}

export async function loadProjectRepresentations(historyValidation: 'all' | 'current' = 'all'): Promise<ProjectRepresentationsSnapshot> {
  const response = await apiFetch("/api/core/project/representations" + (historyValidation === 'current' ? '?history=current' : ''), { cache: "no-store" });
  if (!response.ok) throw await errorFrom(response);
  return response.json() as Promise<ProjectRepresentationsSnapshot>;
}

export interface SourceSnippet {
  path: string;
  startLine: number;
  lines: string[];
}

export interface ProjectSourceFile extends SourceSnippet {
  sourceSha256: string;
  lspEnabled: boolean;
}

export async function fetchProjectSourceFile(projectId: string, path: string, signal?: AbortSignal, sourceId?: string): Promise<ProjectSourceFile> {
  const params = new URLSearchParams({ projectId, path, ...(sourceId ? {sourceId} : {}) });
  const response = await apiFetch(`/api/core/project/source?${params}`, { cache: "no-store", signal });
  if (!response.ok) throw await errorFrom(response);
  return response.json();
}

export async function fetchProjectDirectory(projectId: string, path: string, signal?: AbortSignal, sourceId?: string): Promise<import('../../../domain/core/records/domain').RepositoryDirectoryListing> {
  const response = await apiFetch(`/api/core/project/files?${new URLSearchParams({ projectId, path, ...(sourceId ? {sourceId} : {}) })}`, { signal });
  if (!response.ok) throw await errorFrom(response);
  return response.json();
}
export async function fetchSourceDefinitions(projectId: string, path: string, position: import('../../../domain/core/source/sourceNavigation').SourcePosition, sourceSha256: string, signal?: AbortSignal, sourceId?: string): Promise<import('../../../domain/core/source/sourceNavigation').SourceDefinitions> {
  const response = await apiFetch('/api/core/project/definitions', { method: 'POST', signal,
    headers: { 'content-type': 'application/json' }, body: JSON.stringify({ projectId, path, position, sourceSha256, sourceId }) });
  if (!response.ok) throw await errorFrom(response);
  return response.json();
}

import type { CodeRepoService } from '../../../domain/core/source/codeRepoService';
import { fetchProjectDirectory, fetchProjectSourceFile, fetchSourceDefinitions } from './api';
const unsupported = async (): Promise<never> => { throw new Error('This repository operation is not supported yet'); };
export function createHttpCodeRepoService(): CodeRepoService {
  return {
    available: true,
    async readFile(repo, path, options) {
      const file = await fetchProjectSourceFile(repo.projectId, path, options?.signal, repo.sourceId || undefined);
      return { path: file.path, text: file.lines.join('\n'), sha256: file.sourceSha256, lspEnabled: file.lspEnabled };
    },
    async listDirectory(repo, path, options) {
      return (await fetchProjectDirectory(repo.projectId, path, options?.signal, repo.sourceId || undefined)).entries;
    },
    definitions: (repo, anchor, options) => fetchSourceDefinitions(repo.projectId, anchor.path, anchor.position,
      anchor.sourceSha256, options?.signal, repo.sourceId || undefined),
    search: unsupported,
    git: { resolveCommit: unsupported, listCommits: unsupported, changedFiles: unsupported, diff: unsupported, readFileAt: unsupported },
  };
}

const basePath = import.meta.env.BASE_URL.replace(/\/$/, "");
export function apiFetch(path: string, init?: RequestInit): Promise<Response> {
  return fetch(`${basePath}${path}`, init);
}
export async function errorFrom(response: Response): Promise<Error> {
  const payload = await response.json().catch(() => ({})) as { error?: string };
  return new Error(payload.error || `request failed with ${response.status}`);
}

import { useEffect, useState } from "react";
import { renderTerminalMarkdownFragment } from "./render";

/** Embedded Markdown with shared parsing and code highlighting. Raw HTML stays escaped. */
export function TerminalMarkdownContent(props: { source: string; className?: string; onRendered?: () => void }) {
  const [rendered, setRendered] = useState<{ source: string; html: string }>();
  useEffect(() => {
    let cancelled = false;
    void renderTerminalMarkdownFragment(props.source).then((html) => {
      if (!cancelled) setRendered({ source: props.source, html });
    }).catch(() => { /* Keep the escaped text fallback if rendering fails. */ });
    return () => { cancelled = true; };
  }, [props.source]);
  const ready = rendered?.source === props.source;
  useEffect(() => { if (ready) props.onRendered?.(); }, [ready, rendered, props.onRendered]);
  return ready
    ? <div className={props.className} data-rendered-markdown dangerouslySetInnerHTML={{ __html: rendered.html }} />
    : <div className={props.className}><p>{props.source}</p></div>;
}

import type { Token } from "markdown-it";

export const TERMINAL_MARKDOWN_OPEN_FILE_MESSAGE = "new-diagram:open-repository-file";
export const TERMINAL_MARKDOWN_REVEAL_LINE_MESSAGE = "new-diagram:reveal-markdown-line";
export const TERMINAL_MARKDOWN_ACTIVE_SECTION_MESSAGE = "new-diagram:active-markdown-section";

export function decorateMarkdownLinks(tokens: Token[], documentPath: string): void {
  for (const token of tokens) {
    if (token.type === "link_open") decorateLink(token, documentPath);
    if (token.children) decorateMarkdownLinks(token.children, documentPath);
  }
}

function decorateLink(token: Token, documentPath: string): void {
  const href = token.attrGet("href");
  if (href === null || href === undefined) return;
  const target = String(href);
  if (!target || target.startsWith("#")) return;

  const externalUrl = absoluteHttpUrl(target);
  if (externalUrl) {
    token.attrSet("href", externalUrl);
    token.attrSet("target", "_blank");
    token.attrSet("rel", "noopener noreferrer");
    token.attrJoin("class", "external-ref");
    return;
  }

  const repositoryPath = resolveRepositoryReference(documentPath, target);
  if (!repositoryPath) {
    token.attrSet("href", "#");
    token.attrSet("aria-disabled", "true");
    return;
  }
  token.attrSet("href", `#repository:${encodeURIComponent(repositoryPath)}`);
  token.attrSet("data-repository-path", repositoryPath);
  token.attrJoin("class", "repository-ref");
}

export function resolveRepositoryReference(documentPath: string, target: string): string | null {
  if (!documentPath || !target || target.includes("\0") || target.includes("\\")) return null;
  const withoutFragment = target.split(/[?#]/, 1)[0];
  if (!withoutFragment || withoutFragment.startsWith("/") || /^[a-z][a-z\d+.-]*:/i.test(withoutFragment)) {
    return null;
  }
  const segments = documentPath.split("/").slice(0, -1);
  for (const segment of withoutFragment.split("/")) {
    if (!segment || segment === ".") continue;
    if (segment === "..") {
      if (segments.length === 0) return null;
      segments.pop();
    } else {
      segments.push(segment);
    }
  }
  return segments.length > 0 ? segments.join("/") : null;
}

function absoluteHttpUrl(value: string): string | null {
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:" ? url.href : null;
  } catch {
    return null;
  }
}

export function terminalRepositoryLinkController(): string {
  return `<script>
(() => {
  document.addEventListener('click', (event) => {
    const link = event.target instanceof Element
      ? event.target.closest('[data-repository-path]')
      : null;
    if (!link) return;
    event.preventDefault();
    parent.postMessage({
      type: '${TERMINAL_MARKDOWN_OPEN_FILE_MESSAGE}',
      path: link.getAttribute('data-repository-path')
    }, '*');
  });
  window.addEventListener('message', (event) => {
    if (event.source !== parent
      || !event.data
      || event.data.type !== '${TERMINAL_MARKDOWN_REVEAL_LINE_MESSAGE}'
      || !Number.isInteger(event.data.line)
      || event.data.line < 1) return;
    const line = event.data.line;
    const selectionStart = Number.isInteger(event.data.startLine) ? event.data.startLine : line;
    const selectionEnd = Number.isInteger(event.data.endLine) ? event.data.endLine : selectionStart;
    const candidates = [...document.querySelectorAll('[data-source-start-line]')]
      .map((element) => ({
        element,
        start: Number(element.getAttribute('data-source-start-line')),
        end: Number(element.getAttribute('data-source-end-line'))
      }))
      .filter(({ start, end }) => Number.isFinite(start) && Number.isFinite(end));
    document.querySelectorAll('.is-source-selection').forEach((element) => {
      element.classList.remove('is-source-selection');
    });
    const intersecting = candidates.filter(({ start, end }) => (
      start <= selectionEnd && selectionStart <= end
    ));
    const leafBlocks = intersecting.filter(({ element }) => ![...element.children].some((child) => (
      child.matches('[data-source-start-line]')
      && Number(child.getAttribute('data-source-start-line')) <= selectionEnd
      && selectionStart <= Number(child.getAttribute('data-source-end-line'))
    )));
    leafBlocks.forEach(({ element }) => element.classList.add('is-source-selection'));
    const containing = candidates
      .filter(({ start, end }) => start <= line && line <= end)
      .sort((left, right) => (left.end - left.start) - (right.end - right.start));
    const preceding = candidates
      .filter(({ start }) => start <= line)
      .sort((left, right) => right.start - left.start);
    const following = candidates
      .filter(({ start }) => start > line)
      .sort((left, right) => left.start - right.start);
    const target = containing[0] ?? preceding[0] ?? following[0];
    const behavior = event.data.behavior === 'smooth'
      && !matchMedia('(prefers-reduced-motion: reduce)').matches
      ? 'smooth'
      : 'auto';
    target?.element.scrollIntoView({ block: 'start', behavior });
  });

  let sectionFrame = 0;
  const reportActiveSection = () => {
    sectionFrame = 0;
    const headings = [...document.querySelectorAll('h2[id], h3[id], h4[id]')];
    if (headings.length === 0) return;
    const threshold = Math.max(24, innerHeight * 0.12);
    const preceding = headings.filter((heading) => heading.getBoundingClientRect().top <= threshold);
    const active = preceding.at(-1) ?? headings[0];
    parent.postMessage({
      type: '${TERMINAL_MARKDOWN_ACTIVE_SECTION_MESSAGE}',
      id: active.id,
      line: Number(active.getAttribute('data-source-start-line')),
      scrollTop: scrollY
    }, '*');
  };
  addEventListener('scroll', () => {
    if (!sectionFrame) sectionFrame = requestAnimationFrame(reportActiveSection);
  }, { passive: true });
  addEventListener('load', reportActiveSection, { once: true });
  requestAnimationFrame(reportActiveSection);
})();
</script>`;
}

import MarkdownIt from "markdown-it";
