export function parseTerminalMarkdownOutline(source: string): TerminalMarkdownOutline {
  const { title, markdown } = splitDocument(source);
  const tokens = markdownRenderer.parse(markdown, {});
  const headings = decorateTerminalMarkdownHeadings(tokens);
  const documentEndLine = source.replace(/\r\n?/g, "\n").split("\n").length;
  return {
    title,
    sections: headings.map((heading, index) => {
      const nextPeer = headings.slice(index + 1).find((candidate) => candidate.level <= heading.level);
      return {
        ...heading,
        endLine: Math.max(heading.startLine, (nextPeer?.startLine ?? documentEndLine + 1) - 1)
      };
    })
  };
}

function decorateTerminalMarkdownSourceLines(tokens: import("markdown-it").Token[], offset: number): void {
  for (const token of tokens) {
    if (token.map) {
      token.attrSet("data-source-start-line", String(token.map[0] + 1 + offset));
      token.attrSet("data-source-end-line", String(token.map[1] + offset));
    }
    if (token.children) decorateTerminalMarkdownSourceLines(token.children, offset);
  }
}

export function renderTerminalMarkdownErrorDocument(message: string): string {
  return `<!DOCTYPE html><html><body style="background:#0f1115;color:#f38ba8;font-family:monospace;padding:1.5em 2ch">${escapeHtml(message)}</body></html>`;
}

function splitDocument(source: string): { title: string; markdown: string } {
  const lines = source.replace(/\r\n?/g, "\n").split("\n");
  const titleMatch = /^# (.+)$/.exec(lines[0] ?? "");
  if (!titleMatch) throw new Error("Terminal Markdown must start with a level-one title");
  return {
    title: titleMatch[1],
    markdown: lines.slice(1).join("\n")
  };
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

import type {
  Env,
  MarkdownIt,
  StateCore,
  Token
} from 'markdown-it';

export interface TerminalSidenote {
  id: string;
  markdown: string;
  html: string;
}

export interface TerminalSidenoteEnvironment extends Env {
  sidenotes: ReadonlyMap<string, TerminalSidenote>;
  sidenoteReferenceCounts: Map<string, number>;
}

interface SidenoteDefinition {
  id: string;
  markdown: string;
}

export function installTerminalSidenotes(markdown: MarkdownIt): void {
  markdown.core.ruler.after('inline', 'terminal_sidenote_refs', transformSidenoteReferences);
  markdown.renderer.rules.terminal_sidenote_ref = renderSidenoteReference;
}

export function extractTerminalSidenotes(markdown: string): {
  markdown: string;
  definitions: SidenoteDefinition[];
} {
  const lines = markdown.replace(/\r\n?/g, '\n').split('\n');
  const sectionIndexes = lines
    .map((line, index) => (line.trim() === '# Sidenotes' ? index : -1))
    .filter((index) => index >= 0);
  if (sectionIndexes.length === 0) return { markdown, definitions: [] };
  if (sectionIndexes.length > 1) {
    throw new Error('Terminal Markdown may only contain one # Sidenotes section');
  }

  const sectionIndex = sectionIndexes[0];
  const definitions: Array<{ id: string; lines: string[] }> = [];
  const ids = new Set<string>();
  let current: { id: string; lines: string[] } | null = null;

  for (const line of lines.slice(sectionIndex + 1)) {
    const match = /^\[(\d+)\]\s+(.+)$/.exec(line);
    if (match) {
      const id = String(Number(match[1]));
      if (id === '0') throw new Error('Sidenote identifiers must be positive integers');
      if (ids.has(id)) throw new Error(`Duplicate sidenote definition: ${id}`);
      ids.add(id);
      current = { id, lines: [match[2]] };
      definitions.push(current);
      continue;
    }
    if (!current) {
      if (line.trim()) {
        throw new Error('Sidenote content must begin with a numbered definition');
      }
      continue;
    }
    current.lines.push(line);
  }

  return {
    markdown: lines.slice(0, sectionIndex).join('\n').trimEnd(),
    definitions: definitions.map(({ id, lines: definitionLines }) => {
      const definition = definitionLines.join('\n').trim();
      if (!definition) throw new Error(`Sidenote ${id} is empty`);
      return { id, markdown: definition };
    }),
  };
}

export function renderTerminalSidenoteRail(
  sidenotes: readonly TerminalSidenote[],
): string {
  if (sidenotes.length === 0) return '';
  const cards = sidenotes.map((sidenote) => `
    <li
      class="terminal-sidenote-card"
      id="terminal-sidenote-card-${sidenote.id}"
      data-sidenote-card="${sidenote.id}"
    >
      <span class="terminal-sidenote-number" aria-hidden="true">${sidenote.id}</span>
      <div class="terminal-sidenote-copy">${sidenote.html}</div>
    </li>`).join('');
  return `<aside
  class="terminal-sidenotes"
  data-terminal-sidenotes
  data-cms-static-ui
  aria-label="Sidenotes"
>
  <div class="terminal-sidenotes-heading">sidenotes</div>
  <ol>${cards}
  </ol>
</aside>`;
}

export function terminalSidenoteController(): string {
  return `<script>
(() => {
  const rail = document.querySelector('[data-terminal-sidenotes]');
  if (!rail) return;
  const refs = Array.from(document.querySelectorAll('[data-sidenote-ref]'));
  const cards = Array.from(rail.querySelectorAll('[data-sidenote-card]'));
  const inlineMode = matchMedia('(max-width: 1100px)');
  let pinnedId = null;

  const activate = (id) => {
    cards.forEach((card) => card.classList.toggle(
      'is-active',
      id !== null && card.dataset.sidenoteCard === id
    ));
    refs.forEach((ref) => ref.classList.toggle(
      'is-active',
      id !== null && ref.dataset.sidenoteRef === id
    ));
  };

  const closeInlineNotes = (except) => {
    document.querySelectorAll('[data-sidenote-inline]').forEach((note) => {
      if (note === except) return;
      note.hidden = true;
    });
    refs.forEach((ref) => {
      const inlineId = ref.getAttribute('data-sidenote-inline-target');
      ref.setAttribute(
        'aria-expanded',
        String(Boolean(inlineId && !document.getElementById(inlineId)?.hidden))
      );
    });
  };

  refs.forEach((ref) => {
    const id = ref.dataset.sidenoteRef;
    ref.addEventListener('mouseenter', () => {
      if (!inlineMode.matches) activate(id);
    });
    ref.addEventListener('mouseleave', () => {
      if (!inlineMode.matches) activate(pinnedId);
    });
    ref.addEventListener('focus', () => {
      if (!inlineMode.matches) activate(id);
    });
    ref.addEventListener('blur', () => {
      if (!inlineMode.matches) activate(pinnedId);
    });
    ref.addEventListener('click', () => {
      if (inlineMode.matches) {
        const inlineId = ref.getAttribute('data-sidenote-inline-target');
        const note = inlineId ? document.getElementById(inlineId) : null;
        if (!note) return;
        const opening = note.hidden;
        closeInlineNotes(note);
        note.hidden = !opening;
        ref.setAttribute('aria-expanded', String(opening));
        return;
      }
      pinnedId = pinnedId === id ? null : id;
      activate(pinnedId);
      if (pinnedId) {
        rail.querySelector('[data-sidenote-card="' + pinnedId + '"]')
          ?.scrollIntoView({ block: 'nearest' });
      }
    });
  });

  inlineMode.addEventListener('change', () => {
    pinnedId = null;
    activate(null);
    closeInlineNotes(null);
  });
})();
</script>`;
}

function transformSidenoteReferences(state: StateCore): void {
  for (const blockToken of state.tokens) {
    if (blockToken.type !== 'inline' || !blockToken.children) continue;
    const transformed: Token[] = [];
    let linkDepth = 0;

    for (const token of blockToken.children) {
      if (token.type === 'link_open') linkDepth += 1;
      if (token.type !== 'text' || linkDepth > 0) {
        transformed.push(token);
      } else {
        transformed.push(...splitSidenoteReferences(state, token));
      }
      if (token.type === 'link_close') linkDepth -= 1;
    }
    blockToken.children = transformed;
  }
}

function splitSidenoteReferences(state: StateCore, token: Token): Token[] {
  const pattern = /\((\d+)\)\[footer\]/g;
  const split: Token[] = [];
  let cursor = 0;

  for (const match of token.content.matchAll(pattern)) {
    const index = match.index ?? 0;
    if (index > cursor) {
      const text = new state.Token('text', '', 0);
      text.content = token.content.slice(cursor, index);
      split.push(text);
    }
    const reference = new state.Token('terminal_sidenote_ref', '', 0);
    reference.meta = { id: String(Number(match[1])) };
    split.push(reference);
    cursor = index + match[0].length;
  }
  if (split.length === 0) return [token];
  if (cursor < token.content.length) {
    const text = new state.Token('text', '', 0);
    text.content = token.content.slice(cursor);
    split.push(text);
  }
  return split;
}

function renderSidenoteReference(
  tokens: Token[],
  index: number,
  _options: unknown,
  environment: Env | undefined,
): string {
  const terminalEnvironment = environment as TerminalSidenoteEnvironment;
  const id = String(tokens[index].meta?.id ?? '');
  const sidenote = terminalEnvironment.sidenotes.get(id);
  if (!sidenote) throw new Error(`Missing sidenote definition: ${id}`);
  const count = (terminalEnvironment.sidenoteReferenceCounts.get(id) ?? 0) + 1;
  terminalEnvironment.sidenoteReferenceCounts.set(id, count);
  const inlineId = `terminal-sidenote-inline-${id}-${count}`;
  const cardId = `terminal-sidenote-card-${id}`;

  return `<sup class="terminal-sidenote-marker">
  <button
    type="button"
    class="terminal-sidenote-ref"
    data-sidenote-ref="${id}"
    data-sidenote-inline-target="${inlineId}"
    aria-label="Sidenote ${id}"
    aria-controls="${cardId} ${inlineId}"
    aria-describedby="${cardId}"
    aria-expanded="false"
  >${id}</button>
</sup><span
  class="terminal-sidenote-inline"
  id="${inlineId}"
  data-sidenote-inline="${id}"
  hidden
><span class="terminal-sidenote-inline-number" aria-hidden="true">${id}</span>${sidenote.html}</span>`;
}

import type { MarkdownIt, Token } from "markdown-it";

// Codex's terminal renderer uses the Catppuccin Mocha token palette.
const SHIKI_THEME = "catppuccin-mocha";
const MAX_HIGHLIGHT_BYTES = 512 * 1024;
const MAX_HIGHLIGHT_LINES = 10_000;
const CACHE_LIMIT = 80;

const LANGUAGE_ALIASES: Record<string, string> = {
  "c-sharp": "csharp",
  csharp: "csharp",
  cxx: "cpp",
  golang: "go",
  js: "javascript",
  py: "python",
  python3: "python",
  rs: "rust",
  sh: "bash",
  shell: "bash",
  ts: "typescript"
};

const highlightCache = new Map<string, Promise<string | null>>();

export function installTerminalCodeRenderer(markdown: MarkdownIt): void {
  const fallback = markdown.renderer.rules.fence;
  if (!fallback) throw new Error("markdown-it fence renderer is unavailable");
  markdown.renderer.rules.fence = (tokens, index, options, environment, renderer) => {
    const highlighted = tokens[index].meta?.terminalHighlightedHtml;
    return typeof highlighted === "string"
      ? `<div class="terminal-code-block"${renderer.renderAttrs(tokens[index])}>${highlighted}</div>\n`
      : fallback(tokens, index, options, environment, renderer);
  };
}

export async function highlightTerminalMarkdownFences(tokens: Token[]): Promise<void> {
  await Promise.all(tokens.filter((token) => token.type === "fence").map(async (token) => {
    const language = requestedLanguage(token.info);
    if (!language || exceedsLimits(token.content)) return;
    const html = await highlightedCode(token.content, language);
    if (html) token.meta = { ...token.meta, terminalHighlightedHtml: html };
  }));
}

function requestedLanguage(info: string): string | null {
  const requested = info.trim().toLowerCase().split(/[\s,]/, 1)[0];
  if (!requested) return null;
  return LANGUAGE_ALIASES[requested] ?? requested;
}

function exceedsLimits(code: string): boolean {
  return code.length > MAX_HIGHLIGHT_BYTES || code.split("\n").length > MAX_HIGHLIGHT_LINES;
}

function highlightedCode(code: string, language: string): Promise<string | null> {
  const key = `${SHIKI_THEME}\0${language}\0${code}`;
  const cached = highlightCache.get(key);
  if (cached) return cached;
  const pending = import("shiki").then(({ bundledLanguagesInfo, codeToHtml }) => {
    const bundledLanguage = bundledLanguagesInfo.find((entry) => (
      entry.id === language || entry.aliases?.includes(language)
    ));
    if (!bundledLanguage) return null;
    return codeToHtml(code, { lang: bundledLanguage.id, theme: SHIKI_THEME });
  })
    .catch(() => null);
  highlightCache.set(key, pending);
  if (highlightCache.size > CACHE_LIMIT) {
    const oldest = highlightCache.keys().next().value;
    if (oldest !== undefined) highlightCache.delete(oldest);
  }
  return pending;
}

import type { Token } from 'markdown-it';

export interface TerminalMarkdownHeading {
  id: string;
  label: string;
  level: 2 | 3 | 4;
  startLine: number;
}

export interface TerminalMarkdownSection extends TerminalMarkdownHeading {
  endLine: number;
}

export interface TerminalMarkdownOutline {
  title: string;
  sections: TerminalMarkdownSection[];
}

export function decorateTerminalMarkdownHeadings(
  tokens: Token[],
): TerminalMarkdownHeading[] {
  const headings: TerminalMarkdownHeading[] = [];
  const slugCounts = new Map<string, number>();

  for (let index = 0; index < tokens.length - 1; index += 1) {
    const opening = tokens[index];
    const level = headingLevel(opening);
    if (!level) continue;

    const inline = tokens[index + 1];
    if (inline.type !== 'inline') continue;
    const label = inlineText(inline);
    const base = slugifyHeading(label);
    const count = (slugCounts.get(base) ?? 0) + 1;
    slugCounts.set(base, count);
    const id = count === 1 ? base : `${base}-${count}`;

    opening.attrSet('id', id);
    opening.attrSet('tabindex', '-1');
    headings.push({
      id,
      label,
      level,
      startLine: opening.map ? opening.map[0] + 2 : 1
    });
  }

  return headings;
}

export function renderTerminalMarkdownToc(
  headings: readonly TerminalMarkdownHeading[],
): string {
  if (headings.length === 0) return '';
  const links = headings.map(({ id, label, level }) => `
      <li>
        <a class="terminal-toc-link is-level-${level}" href="#${escapeAttribute(id)}">
          ${escapeHtml(label)}
        </a>
      </li>`).join('');

  return `<nav class="terminal-toc" data-terminal-toc data-cms-static-ui aria-label="Table of contents">
  <div class="terminal-toc-track" aria-hidden="true">
    <span class="terminal-toc-progress"></span>
  </div>
  <div class="terminal-toc-content">
    <div class="terminal-toc-heading">contents</div>
    <ol>${links}
    </ol>
  </div>
</nav>`;
}

function headingLevel(token: Token): TerminalMarkdownHeading['level'] | null {
  if (token.type !== 'heading_open') return null;
  if (token.tag === 'h2') return 2;
  if (token.tag === 'h3') return 3;
  if (token.tag === 'h4') return 4;
  return null;
}

function inlineText(token: Token): string {
  const text = (token.children ?? []).map((child) => {
    if (child.type === 'text' || child.type === 'code_inline' || child.type === 'image') {
      return child.content;
    }
    if (child.type === 'softbreak' || child.type === 'hardbreak') return ' ';
    return '';
  }).join('');
  return text.replace(/\s+/g, ' ').trim() || 'Section';
}

function slugifyHeading(label: string): string {
  const slug = label
    .normalize('NFKD')
    .replace(/\p{Mark}/gu, '')
    .toLowerCase()
    .replace(/[^\p{Letter}\p{Number}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
  return slug || 'section';
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function escapeAttribute(value: string): string {
  return escapeHtml(value).replace(/'/g, '&#39;');
}

import { memo, useEffect, useState } from 'react';
import type { CodeRepoService } from '../../../domain/core/source/codeRepoService';
import type { RepositoryDirectoryListing } from '../../../domain/core/records/domain';

// Listings are shared, but subscriptions and expansion state belong to each explorer.
const serviceListings = new WeakMap<CodeRepoService, Map<string, Promise<RepositoryDirectoryListing>>>();
function cache(service: CodeRepoService) {
  let entries = serviceListings.get(service);
  if (!entries) { entries = new Map(); serviceListings.set(service, entries); }
  return entries;
}
function load(service: CodeRepoService, projectId: string, directory: string, sourceId?: string) {
  const listings = cache(service);
  const key = JSON.stringify([projectId, sourceId, directory]);
  let request = listings.get(key);
  if (!request) {
    request = service.listDirectory({ projectId, sourceId: sourceId ?? '' }, directory).then(entries => ({ directory, entries: entries.map(entry => ({ ...entry, name: entry.path.split('/').at(-1)! })) }));
    listings.set(key, request);
    if (listings.size > 256) listings.delete(listings.keys().next().value!);
    void request.catch(() => { if (listings.get(key) === request) listings.delete(key); });
  }
  return request;
}
function Directory(props: { codeRepo: CodeRepoService; projectId: string; sourceId?: string; directory: string; selected: string; onOpen: (path: string) => void; generation: number }) {
  const { codeRepo } = props;
  const [listing, setListing] = useState<RepositoryDirectoryListing>();
  const [error, setError] = useState('');
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    let active = true;
    setError(''); setListing(undefined);
    void load(codeRepo, props.projectId, props.directory, props.sourceId).then(value => { if (active) setListing(value); }, error => { if (active) setError(String(error.message ?? error)); });
    return () => { active = false; };
  }, [codeRepo, props.projectId, props.sourceId, props.directory, props.generation, attempt]);
  if (error) return <div role="alert">{error} <button onClick={() => setAttempt(n => n + 1)}>Retry directory</button></div>;
  if (!listing) return <span role="status">Loading files…</span>;
  return <ul className="repository-file-list">
    {listing.entries.map(entry => <li key={entry.path}>
      {entry.kind === 'directory' ? <>
        <button type="button" aria-expanded={expanded.has(entry.path)} data-directory={entry.path} onClick={() => setExpanded(current => {
          const next = new Set(current); if (next.has(entry.path)) next.delete(entry.path); else next.add(entry.path); return next;
        })}>{expanded.has(entry.path) ? '▾' : '▸'} {entry.name}/</button>
        {expanded.has(entry.path) && <Directory {...props} directory={entry.path} />}
      </> : <button type="button" data-repository-file={entry.path} aria-current={props.selected === entry.path ? 'page' : undefined}
        title={entry.path} onClick={() => props.onOpen(entry.path)}>{entry.name}</button>}
    </li>)}
    {!listing.entries.length && <li>Empty directory</li>}
  </ul>;
}
export const RepositoryFileExplorer = memo(function RepositoryFileExplorer(props: { codeRepo: CodeRepoService; projectId: string; sourceId?: string; selected: string; onOpen: (path: string) => void }) {
  const { codeRepo } = props;
  const listings = cache(codeRepo);
  const [generation, setGeneration] = useState(0);
  return <aside className="repository-file-explorer" aria-label="Repository files" onKeyDown={event => {
    if (!(event.target instanceof HTMLButtonElement)) return;
    const buttons = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button[data-directory], button[data-repository-file]')];
    const index = buttons.indexOf(event.target);
    if (index < 0) return;
    const next = event.key === 'ArrowDown' ? buttons[index + 1] : event.key === 'ArrowUp' ? buttons[index - 1]
      : event.key === 'Home' ? buttons[0] : event.key === 'End' ? buttons.at(-1) : undefined;
    if (next) { event.preventDefault(); event.stopPropagation(); next.focus(); }
    else if (event.key === 'ArrowRight' && event.target.dataset.directory && event.target.getAttribute('aria-expanded') === 'false') {
      event.preventDefault(); event.stopPropagation(); event.target.click();
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault(); event.stopPropagation();
      if (event.target.getAttribute('aria-expanded') === 'true') event.target.click();
      else event.target.closest('ul')?.parentElement?.querySelector<HTMLButtonElement>(':scope > button')?.focus();
    }
  }}>
    <button type="button" onClick={() => {
      for (const key of listings.keys()) if (JSON.parse(key)[0] === props.projectId) listings.delete(key);
      setGeneration(n => n + 1);
    }}>Refresh files</button>
    <Directory {...props} directory="" generation={generation} />
  </aside>;
});

